def _apply_dpi_awareness():
    """Per-monitor DPI awareness (standalone start only: in TAB mode the host
    process owns this setting)."""
    if sys.platform != 'win32':
        return
    try:
        try:
            _ct.windll.shcore.SetProcessDpiAwareness(2)
        except Exception:
            _ct.windll.user32.SetProcessDPIAware()
    except Exception:
        pass


def _apply_tk_scaling(_root):
    """Aligne l'unite 'point' de Tk sur le DPI reel de l'ecran."""
    try:
        _root.tk.call('tk', 'scaling', _root.winfo_fpixels('1i') / 72.0)
    except Exception:
        return None
    return None


def _default_data_root():
    """%LOCALAPPDATA% on Windows; a per-user folder elsewhere (never the CWD)."""
    base = os.environ.get('LOCALAPPDATA')
    if not base:
        base = os.path.join(os.path.expanduser('~'), '.local', 'share')
    return base


