def _resource(nom):
    """Chemin d'une ressource embarquee.

    Depuis l'exe PyInstaller, les donnees sont extraites dans sys._MEIPASS,
    qui est DEJA le dossier : y appliquer dirname() renvoyait le dossier
    parent, et la ressource n'etait jamais trouvee.
    """
    base = getattr(sys, '_MEIPASS', None)
    if base is None:
        base = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(base, nom)


