_SPIN_RE = re.compile('\\{([^{}]*)\\}')


def _spin(text):
    """Developpe la syntaxe spintax `{a|b|c}` (imbrication supportee).

    Le regex ne matche que les accolades SANS accolade interne, donc les
    groupes les plus profonds sont resolus en premier, puis leurs parents.
    Le compteur de tours borne les cas pathologiques (accolade non fermee)."""
    out = text or ''
    for _ in range(20):
        m = _SPIN_RE.search(out)
        if not m:
            break
        choices = [c.strip() for c in m.group(1).split('|')]
        out = out[:m.start()] + random.choice(choices) + out[m.end():]
    return out


def _utcnow():
    """Maintenant en UTC, sans fuseau (date *naive*)."""
    return datetime.now(timezone.utc).replace(tzinfo=None)


def _get_playwright_driver():
    """Retourne (driver_executable, driver_cli, env) quelle que soit la forme du packaging.

    Playwright <= 1.39 (the only versions available for Python 3.7) returns a
    single path to playwright.cmd/.sh; newer versions return (node, cli.js).
    driver_cli is None for the single-executable form.
    """
    if compute_driver_executable is None:
        return (None, None, None)
    try:
        res = compute_driver_executable()
        env = get_driver_env() if get_driver_env is not None else dict(os.environ)
        if isinstance(res, (tuple, list)):
            return (str(res[0]), str(res[1]), env)
        return (str(res), None, env)
    except Exception:
        return (None, None, None)


def _playwright_install_cmd():
    """Command line that installs Chromium for the Playwright in use."""
    driver_exec, driver_cli, env = _get_playwright_driver()
    if driver_exec and os.path.isfile(driver_exec):
        if driver_cli:
            return ([driver_exec, driver_cli, 'install', 'chromium'], env)
        return ([driver_exec, 'install', 'chromium'], env)
    return ([sys.executable, '-m', 'playwright', 'install', 'chromium'], None)


def _chromium_is_installed():
    """Verifie si le Chromium attendu par Playwright est present.

    Asks Playwright itself for the exact executable it will launch (a
    Chromium left over from another Playwright version does not count).
    Falls back to scanning PLAYWRIGHT_BROWSERS_PATH.
    """
    ok, _detail = _chromium_status()
    return ok


def _chromium_status():
    """(installed, detail) - detail is the executable path or the error."""
    if sync_playwright is None:
        return (False, 'Playwright n\'est pas installe (%s)' % PLAYWRIGHT_PIP_CMD)
    try:
        with sync_playwright() as p:
            exe = p.chromium.executable_path
        if exe and os.path.exists(exe):
            return (True, exe)
        return (False, 'Chromium introuvable : %s' % exe)
    except Exception as e:
        # Driver could not start: fall back to a filesystem scan.
        base = os.environ.get('PLAYWRIGHT_BROWSERS_PATH') or os.path.join(_default_data_root(), 'ms-playwright')
        if os.path.isdir(base):
            hits = _glob.glob(os.path.join(base, 'chromium*', '**', 'chrome.exe'), recursive=True)
            hits += _glob.glob(os.path.join(base, 'chromium*', '**', 'chrome'), recursive=True)
            if hits:
                return (True, hits[0])
        return (False, 'Verification impossible : %s' % e)


def _is_missing_browser_error(exc):
    """True when the error means Playwright or its Chromium is not installed."""
    if sync_playwright is None:
        return True
    low = str(exc).lower()
    return ("executable doesn't exist" in low) or ('playwright install' in low)


def _browser_error_text(exc):
    """Human readable explanation for a Playwright launch/automation error."""
    msg = str(exc) or exc.__class__.__name__
    low = msg.lower()
    if sync_playwright is None:
        return ('Playwright n\'est pas installe pour ce Python (%s).\n'
                'Installez-le avec :\n    %s\n    %s' % (sys.executable, PLAYWRIGHT_PIP_CMD, PLAYWRIGHT_INSTALL_CMD))
    if "executable doesn't exist" in low or 'playwright install' in low or 'browsertype.launch' in low and 'exist' in low:
        return ('Chromium pour Playwright est introuvable.\n'
                'Installez-le avec :\n    %s\n\nDetail : %s' % (PLAYWRIGHT_INSTALL_CMD, msg.strip().splitlines()[0][:300]))
    if 'user data directory is already in use' in low or 'processsingleton' in low or 'profile appears to be in use' in low:
        return ('Le profil Chrome est deja utilise par une autre fenetre/processus.\n'
                'Fermez le navigateur de ce compte puis reessayez.\n\nDetail : %s' % msg.strip()[:300])
    return msg.strip()[:600]


def auto_install_playwright():
    """Installation silencieuse en tache de fond."""
    def _do():
        try:
            cmd, env = _playwright_install_cmd()
            subprocess.run(cmd, env=env, creationflags=_NO_WINDOW, check=False)
        except Exception:
            traceback.print_exc()
    threading.Thread(target=_do, daemon=True, name='pw-autoinstall').start()


def _ensure_psutil():
    """Installe psutil en tache de fond s'il manque - jamais bloquant.

    psutil n'est PAS obligatoire : sans lui, le chien de garde retrouve le
    processus fige via PowerShell (~2 s au lieu de ~0,1 s). On tente donc
    l'installation en silence, sans jamais retarder l'ouverture de l'app ni
    afficher quoi que ce soit en cas d'echec (machine hors ligne, pip absent,
    droits insuffisants...). Une tentative au plus par semaine.
    """
    def _do():
        try:
            __import__('psutil')
            return
        except ImportError:
            pass
        if getattr(sys, 'frozen', False):
            return
        mark = os.path.join(SESSION_BASE, 'psutil_try.txt')
        try:
            os.makedirs(SESSION_BASE, exist_ok=True)
            if os.path.exists(mark) and time.time() - os.path.getmtime(mark) < 604800:
                return
            with open(mark, 'w') as f:
                f.write(str(int(time.time())))
        except Exception:
            pass
        try:
            base = [sys.executable, '-m', 'pip', 'install', '--quiet', '--disable-pip-version-check', 'psutil']
            for cmd in [base, base + ['--user']]:
                r = subprocess.run(cmd, creationflags=_NO_WINDOW, capture_output=True, timeout=180)
                if r.returncode == 0:
                    return
        except Exception:
            return
    threading.Thread(target=_do, daemon=True, name='psutil-install').start()


def install_playwright_with_ui(master, on_done=None, modal=True):
    """Fenetre d'installation de Chromium (original startup installer).

    Originally a blocking Tk() window shown before the app.  It is now a
    Toplevel of `master` (a single Tk root, no nested mainloop) and is only
    shown when the Chromium expected by Playwright is missing.  On failure it
    shows the exact manual command.  on_done(success) is called at the end.
    """
    F = 'Segoe UI'
    win = _tk.Toplevel(master)
    win.overrideredirect(True)
    win.configure(bg='#0f172a')
    sw, sh = (win.winfo_screenwidth(), win.winfo_screenheight())
    W, H = (560, 320)
    win.geometry('%dx%d+%d+%d' % (W, H, (sw - W) // 2, (sh - H) // 2))
    win.lift()
    try:
        win.attributes('-topmost', True)
    except Exception:
        pass
    _tk.Frame(win, bg='#f97316', height=3).pack(fill=_tk.X)
    body = _tk.Frame(win, bg='#0f172a')
    body.pack(fill=_tk.BOTH, expand=True, padx=2, pady=2)
    _tk.Frame(body, bg='#0f172a', height=24).pack()
    try:
        _logo_i = _PI.open(LOGO_PATH).convert('RGBA').resize((72, 72), _PI.LANCZOS)
        _logo_ph = _ITK.PhotoImage(_logo_i, master=win)
        lbl_logo = _tk.Label(body, image=_logo_ph, bg='#0f172a')
        lbl_logo._img = _logo_ph
        lbl_logo.pack()
    except Exception:
        _tk.Label(body, text='\u25a6', font=(F, 32), bg='#0f172a', fg='#f97316').pack()
    _tk.Frame(body, bg='#0f172a', height=10).pack()
    _tk.Label(body, text='AutoPoster Pro', font=(F, 15, 'bold'), bg='#0f172a', fg='#f1f5f9').pack()
    _tk.Label(body, text='Installation de Chromium (Playwright) en cours\u2026', font=(F, 9), bg='#0f172a', fg='#94a3b8').pack(pady=(2, 0))
    _tk.Frame(body, bg='#0f172a', height=18).pack()
    bar_outer = _tk.Frame(body, bg='#1e293b', height=6)
    bar_outer.pack(fill=_tk.X, padx=60)
    bar_outer.pack_propagate(False)
    bar_inner = _tk.Frame(bar_outer, bg='#f97316', height=6, width=0)
    bar_inner.place(x=0, y=0, height=6, width=0)
    bar_total = W - 120
    _tk.Frame(body, bg='#0f172a', height=8).pack()
    status_lbl = _tk.Label(body, text='Initialisation du navigateur\u2026', font=(F, 9), bg='#0f172a', fg='#64748b', wraplength=W - 60, justify='center')
    status_lbl.pack()
    btn_row = _tk.Frame(body, bg='#0f172a')
    _tk.Frame(win, bg='#f97316', height=3).pack(side=_tk.BOTTOM, fill=_tk.X)
    done_event = threading.Event()
    result = [False]
    error_msg = ['']
    finished = [False]
    messages = ['T\u00e9l\u00e9chargement de Chromium\u2026', 'Installation des composants\u2026', 'Configuration du navigateur\u2026', 'Finalisation\u2026']
    msg_idx = [0]
    spacer = [None]

    def _close(success):
        if finished[0]:
            return
        finished[0] = True
        try:
            if modal:
                win.grab_release()
        except Exception:
            pass
        try:
            win.destroy()
        except Exception:
            pass
        if on_done is not None:
            try:
                on_done(success)
            except Exception:
                traceback.print_exc()

    def _reset_progress():
        done_event.clear()
        result[0] = False
        error_msg[0] = ''
        msg_idx[0] = 0
        bar_inner.config(bg='#f97316')
        bar_inner.place(x=0, y=0, height=6, width=0)
        status_lbl.config(fg='#64748b')
        btn_row.pack_forget()
        if spacer[0] is not None:
            spacer[0].destroy()
            spacer[0] = None

    def _retry():
        _reset_progress()
        win.after(200, _pulse)
        threading.Thread(target=_install_thread, daemon=True, name='pw-install').start()

    def _continue():
        _close(False)

    _tk.Button(btn_row, text='R\u00e9essayer', font=(F, 9, 'bold'), bg='#f97316', fg='white', activebackground='#ea6a0a', activeforeground='white', relief='flat', cursor='hand2', padx=16, pady=6, bd=0, command=_retry).pack(side=_tk.LEFT, padx=(0, 8))
    _tk.Button(btn_row, text='Continuer sans navigateur', font=(F, 9, 'bold'), bg='#334155', fg='white', activebackground='#1e293b', activeforeground='white', relief='flat', cursor='hand2', padx=16, pady=6, bd=0, command=_continue).pack(side=_tk.LEFT)

    def _pulse():
        if finished[0]:
            return
        if done_event.is_set():
            if result[0]:
                bar_inner.place(x=0, y=0, height=6, width=bar_total)
                status_lbl.config(text='\u2705 Installation termin\u00e9e !', fg='#16a34a')
                win.after(900, lambda: _close(True))
                return
            bar_inner.config(bg='#ef4444')
            detail = ' (%s)' % error_msg[0] if error_msg[0] else ''
            status_lbl.config(text='\u274c \u00c9chec de l\'installation de Chromium%s\n'
                                   'Installez-le manuellement puis relancez :\n%s' % (detail, PLAYWRIGHT_INSTALL_CMD),
                              fg='#ef4444')
            spacer[0] = _tk.Frame(body, bg='#0f172a', height=10)
            spacer[0].pack()
            btn_row.pack()
            return
        cur_w = bar_inner.winfo_width()
        target = int(bar_total * 0.9)
        if cur_w < target:
            step = max(1, (target - cur_w) // 20)
            bar_inner.place(x=0, y=0, height=6, width=min(cur_w + step, target))
        if msg_idx[0] < len(messages):
            status_lbl.config(text=messages[msg_idx[0]])
            msg_idx[0] = (msg_idx[0] + 1) % len(messages)
        win.after(600, _pulse)

    def _install_thread():
        try:
            cmd, env = _playwright_install_cmd()
            proc = subprocess.run(cmd, env=env, creationflags=_NO_WINDOW, check=False, capture_output=True, universal_newlines=True)
            ok_now, detail = _chromium_status()
            if proc.returncode == 0 and ok_now:
                result[0] = True
            else:
                result[0] = False
                if proc.returncode != 0:
                    raw = proc.stderr or proc.stdout or 'code retour %s' % proc.returncode
                else:
                    raw = 'Chromium introuvable apr\u00e8s installation (%s)' % detail
                lines = raw.strip().splitlines()
                error_msg[0] = (lines[-1] if lines else raw)[:150]
        except Exception as e:
            result[0] = False
            error_msg[0] = str(e)[:150]
        finally:
            done_event.set()

    if modal:
        try:
            win.grab_set()
        except Exception:
            pass
    win.after(200, _pulse)
    threading.Thread(target=_install_thread, daemon=True, name='pw-install').start()
    return win


