def _kill_pid(pid):
    """Kill a process (taskkill on Windows, SIGKILL elsewhere)."""
    try:
        if psutil is not None:
            psutil.Process(pid).kill()
            return True
    except Exception:
        pass
    try:
        if sys.platform == 'win32':
            subprocess.run(['taskkill', '/F', '/T', '/PID', str(pid)], capture_output=True, timeout=15, creationflags=_NO_WINDOW)
        else:
            import signal as _signal
            os.kill(pid, _signal.SIGKILL)
        return True
    except Exception:
        return False


class _AfterTrackerMixin(object):
    """Mixin for the application's root widget (Tk root or TAB container).

    * every after() job is tracked so teardown() can cancel them all;
    * after() called from a worker thread never touches Tcl: the callback is
      handed to the application's UI queue and executed on the Tk thread.
    The original code calls self.root.after(0, ...) from worker threads in
    many places; this keeps all those call sites valid and thread-safe.
    """
    _tracker_ready = False

    def _tracker_init(self):
        self._tracked_after = set()
        self._tracker_ui_ident = threading.get_ident()
        self._cross_thread_sink = None
        self._tracker_ready = True

    def after(self, ms, func=None, *args):
        if func is None or not self._tracker_ready:
            return super(_AfterTrackerMixin, self).after(ms, func, *args)
        if threading.get_ident() != self._tracker_ui_ident:
            sink = self._cross_thread_sink
            if sink is not None:
                sink(ms, func, args)
                return None
        holder = []

        def _tracked_cb(*a):
            try:
                self._tracked_after.discard(holder[0] if holder else None)
            except Exception:
                pass
            return func(*a)
        aid = super(_AfterTrackerMixin, self).after(ms, _tracked_cb, *args)
        holder.append(aid)
        self._tracked_after.add(aid)
        return aid

    def after_idle(self, func, *args):
        return self.after(1, func, *args)

    def after_cancel(self, id):
        if id is None:
            return None
        try:
            self._tracked_after.discard(id)
        except Exception:
            pass
        return super(_AfterTrackerMixin, self).after_cancel(id)

    def cancel_all_after(self):
        for aid in list(getattr(self, '_tracked_after', ())):
            try:
                super(_AfterTrackerMixin, self).after_cancel(aid)
            except Exception:
                pass
        try:
            self._tracked_after.clear()
        except Exception:
            pass


class _AppTk(_AfterTrackerMixin, tk.Tk):
    """Standalone root window."""

    def __init__(self, *a, **kw):
        tk.Tk.__init__(self, *a, **kw)
        self._tracker_init()


if TkinterDnD is not None:
    class _AppDnDTk(_AfterTrackerMixin, TkinterDnD.Tk):
        """Standalone root window with drag & drop support (tkinterdnd2)."""

        def __init__(self, *a, **kw):
            TkinterDnD.Tk.__init__(self, *a, **kw)
            self._tracker_init()
else:
    _AppDnDTk = None


