    # ------------------------------------------------------------------
    # Thread-safe UI dispatch and lifecycle (standalone + TAB mode)
    # ------------------------------------------------------------------
    def _on_ui_thread(self):
        return threading.get_ident() == self._ui_thread_id

    def _post_ui(self, ms, func, args=()):
        """Queue func(*args) to run on the Tk thread (after `ms` ms)."""
        if self._closing:
            return
        self._ui_queue.put((ms, func, tuple(args)))

    def _call_ui(self, func, *args):
        """Run func now if on the Tk thread, otherwise marshal it there."""
        if self._on_ui_thread():
            return func(*args)
        self._post_ui(0, func, args)
        return None

    def _ui_pump(self):
        """Executes the callbacks queued by worker threads (Tk thread only)."""
        self._ui_pump_job = None
        if self._closing:
            return
        for _ in range(500):
            try:
                ms, func, args = self._ui_queue.get_nowait()
            except queue.Empty:
                break
            try:
                if ms and ms > 0:
                    self.root.after(ms, func, *args)
                else:
                    func(*args)
            except tk.TclError:
                pass
            except Exception:
                traceback.print_exc()
        try:
            self._ui_pump_job = self.root.after(30, self._ui_pump)
        except Exception:
            self._ui_pump_job = None

    def _start_thread(self, target, args=(), name=None):
        """Start a daemon worker thread that teardown() knows about."""
        th = threading.Thread(target=self._thread_wrapper, args=(target, args), name=name or getattr(target, '__name__', 'worker'), daemon=True)
        with self._threads_lock:
            self._threads = [t for t in getattr(self, '_threads', []) if t.is_alive()]
            self._threads.append(th)
        th.start()
        return th

    def _thread_wrapper(self, target, args):
        try:
            target(*args)
        except Exception as e:
            traceback.print_exc()
            if not self._closing:
                try:
                    self.log('\u274c Erreur interne (%s) : %s' % (getattr(target, '__name__', 'thread'), e))
                except Exception:
                    pass

    def _note_profile_launch(self, user_data_dir):
        """Remember profile dirs we launched Chromium on (for teardown)."""
        try:
            with self._live_ctx_lock:
                self._launched_dirs.add(os.path.normpath(user_data_dir))
        except Exception:
            pass

    def _browser_error(self, where, exc, popup=False):
        """Clear, visible explanation of a Playwright failure (never silent)."""
        text = _browser_error_text(exc)
        try:
            traceback.print_exc()
        except Exception:
            pass
        self.log('\u274c %s : %s' % (where, text.splitlines()[0] if text else exc))
        low = text.lower()
        if popup or 'playwright install' in low or 'pip install playwright' in low:
            key = 'chromium' if 'playwright install' in low else 'playwright'
            if key not in getattr(self, '_browser_error_shown', set()):
                self._browser_error_shown = getattr(self, '_browser_error_shown', set()) | {key}
                self._call_ui(self._show_error_dialog, 'Navigateur Playwright', text)

    def _show_error_dialog(self, title, text):
        if self._closing:
            return
        try:
            messagebox.showerror(title, text, parent=self.root.winfo_toplevel())
        except Exception:
            print('[autoV2] %s: %s' % (title, text), file=sys.stderr)


    def _notify(self, title, message, kind='info'):
        """Non-modal user feedback: one line into the host log and a toast.

        This is where routed messagebox.showinfo/showwarning/showerror calls
        land in TAB mode (spec §5).  The full text goes to the log (nothing is
        lost); the toast is the glanceable part.
        """
        msg = str(message or '')
        ttl = str(title or '')
        line = (ttl + ' : ' + msg) if ttl else msg
        try:
            self.log(line.replace(chr(10), '  '))
        except Exception:
            pass
        kmap = {'info': 'info', 'warn': 'warn', 'warning': 'warn',
                'error': 'err', 'err': 'err'}
        try:
            self.show_toast(msg or ttl, kmap.get(kind, 'info'))
        except Exception:
            pass

    def _require_playwright(self, where=''):
        """True when the Playwright package is importable; otherwise explain."""
        if sync_playwright is not None:
            return True
        self._browser_error(where or 'Playwright', RuntimeError('playwright missing'), popup=True)
        return False

    def teardown(self):
        """Stop every worker, close every browser, cancel every Tk job."""
        if self._teardown_done:
            return
        self._teardown_done = True
        self._closing = True
        self._shutdown_evt.set()
        # Stop all activities (flags checked by the worker loops).
        self.is_running = False
        self._paused = False
        for attr in ('_jg_running', '_lk_running', '_cm_running', '_sc_running', '_sc_test_running'):
            try:
                setattr(self, attr, False)
            except Exception:
                pass
        try:
            self._wd_stop_evt.set()
        except Exception:
            pass
        for attr in ('_stop_evt', '_cm_stop_evt', '_sc_stop_evt'):
            ev = getattr(self, attr, None)
            if ev is not None:
                try:
                    ev.set()
                except Exception:
                    pass
        # Graceful stop: the worker loops check the flags above and leave their
        # `with sync_playwright()` blocks, which closes their browsers.
        # Playwright objects are bound to their own thread, so they are never
        # closed from here.  Never block the UI for long.
        deadline = time.time() + 2.5
        with self._threads_lock:
            threads = [t for t in getattr(self, '_threads', []) if t is not threading.current_thread()]
        wd = getattr(self, '_wd_thread', None)
        if wd is not None:
            threads.append(wd)
        for th in threads:
            left = deadline - time.time()
            if left <= 0:
                break
            try:
                th.join(timeout=min(left, 1.0))
            except Exception:
                pass
        # Hard stop: browsers still running on one of our profiles are killed
        # in the background (psutil, or PowerShell on Windows without psutil).
        with self._live_ctx_lock:
            dirs = list(self._launched_dirs)
        if dirs and any(th.is_alive() for th in threads):
            threading.Thread(target=self._kill_profile_dirs, args=(dirs,), daemon=True, name='teardown-kill').start()
        # Cancel scheduled Tk callbacks and our global bindings.
        try:
            if self._ui_pump_job is not None:
                self.root.after_cancel(self._ui_pump_job)
        except Exception:
            pass
        cancel_all = getattr(self.root, 'cancel_all_after', None)
        if callable(cancel_all):
            cancel_all()
        self._unbind_wheel()
        try:
            self._save_account_config()
        except Exception:
            pass
        if globals().get('_CURRENT_APP') is self:
            globals()['_CURRENT_APP'] = None


    def _kill_profile_dirs(self, dirs):
        """Kill the Chromium processes whose command line cites one of `dirs`."""
        for udd in dirs:
            try:
                for pid in self._wd_find_pids(udd):
                    _kill_pid(pid)
            except Exception:
                pass

    def _bind_wheel(self, canvas):
        """Mouse-wheel scrolling limited to this application's widgets.

        The original used canvas.bind_all(), which in TAB mode would hijack
        the wheel for the whole host application.  Here the handler is added
        (add='+') and ignores events for widgets outside our tree.
        """
        prefix = str(self.root)

        def _on_wheel(e):
            try:
                w = str(e.widget)
            except Exception:
                return None
            if prefix != '.' and not (w == prefix or w.startswith(prefix + '.')):
                return None
            if isinstance(e.widget, (tk.Text, tk.Listbox)) or w.endswith('!scrolledtext') or '!scrolledtext' in w.rsplit('.', 1)[-1]:
                return None
            try:
                canvas.yview_scroll(int(-1 * (e.delta / 120)) or (-1 if e.delta > 0 else 1), 'units')
            except Exception:
                return None
            return None
        try:
            self._wheel_funcid = self.root.bind_all('<MouseWheel>', _on_wheel, add='+')
        except Exception:
            self._wheel_funcid = None

    def _unbind_wheel(self):
        fid = self._wheel_funcid
        self._wheel_funcid = None
        if not fid:
            return
        try:
            script = self.root.tk.call('bind', 'all', '<MouseWheel>')
            keep = '\n'.join(l for l in str(script).split('\n') if fid not in l)
            self.root.tk.call('bind', 'all', '<MouseWheel>', keep)
            self.root.deletecommand(fid)
        except Exception:
            pass

    @staticmethod
    def _rrect(cv, x1, y1, x2, y2, r, **kw):
        pts = [x1 + r, y1, x2 - r, y1, x2, y1 + r, x2, y2 - r, x2 - r, y2, x1 + r, y2, x1, y2 - r, x1, y1 + r]
        cv.create_polygon(pts, smooth=True, **kw)
    @staticmethod
    def _glow_rrect(cv, x1, y1, x2, y2, r, fill, rings=()):
        """Rect arrondi. Modele A : les anneaux de glow sont ignores (aplats seuls)."""
        for col, pad in []:
            rg = max(r - pad // 2, 4)
            pts = [x1 - pad + rg, y1 - pad, x2 + pad - rg, y1 - pad, x2 + pad, y1 - pad + rg, x2 + pad, y2 + pad - rg, x2 + pad - rg, y2 + pad, x1 - pad, y2 + pad - rg, x1 - pad, y1 - pad + rg]
            cv.create_polygon(pts, smooth=True, fill=col, outline='')
        pts = [x1 + r, y1, x2 - r, y1, x2, y1 + r, x2, y2 - r, x2 - r, y2, x1 + r, y2, x1, y2 - r, x1, y1 + r]
        cv.create_polygon(pts, smooth=True, fill=fill, outline='')
    def _apply_rounded_window(self):
        if not self._standalone or sys.platform != 'win32':
            return None
        try:
            hwnd = ctypes.windll.user32.GetParent(self.root.winfo_id())
            if not hwnd:
                hwnd = int(self.root.frame(), 16)
            ctypes.windll.dwmapi.DwmSetWindowAttribute(hwnd, 33, ctypes.byref(ctypes.c_int(2)), ctypes.sizeof(ctypes.c_int))
        except Exception:
            return None
    def _apply_appwindow_style(self):
        """Applique WS_EX_APPWINDOW pour forcer l\'icône dans la barre des tâches."""
        if not self._standalone or sys.platform != 'win32':
            return None
        try:
            hwnd = ctypes.windll.user32.GetParent(self.root.winfo_id())
            if not hwnd:
                hwnd = int(self.root.frame(), 16)
            style = ctypes.windll.user32.GetWindowLongW(hwnd, (-20))
            style = style & (-129) | 262144
            ctypes.windll.user32.SetWindowLongW(hwnd, (-20), style)
        except Exception:
            return None
    def _fix_taskbar_visibility(self):
        """Force l\'icône dans la barre des tâches au démarrage."""
        if getattr(self, '_taskbar_fixed', False) or not self._standalone:
            return
        else:
            self._apply_appwindow_style()
            self.root.withdraw()
            self.root.after(120, self._taskbar_show)
    def _taskbar_show(self):
        self.root.deiconify()
        self._taskbar_fixed = True
    def create_widgets(self):
        F = 'Segoe UI'
        self.root.configure(bg=C['bg'])
        def _blink():
            if self._closing:
                return
            try:
                self._blink_state = not self._blink_state
                self._conn_blink = not self._conn_blink
                for ref in self._blink_refs:
                    try:
                        ref['w'].config(fg=ref['on'] if self._blink_state else ref['off'])
                    except Exception:
                        pass
                for sid, acc in list(self.accounts.items()):
                    if not acc.get('connecting'):
                        continue
                    fn = self._account_redraw.get(sid)
                    if callable(fn):
                        try:
                            fn()
                        except Exception:
                            pass
                self._refresh_statusbar()
            except Exception:
                pass
            self.root.after(800, _blink)
        self.root.after(800, _blink)
        def section_title(parent, text, pady_top=22):
            f = tk.Frame(parent, bg=C['bg'])
            f.pack(fill=tk.X, padx=28, pady=(pady_top, 10))
            tk.Label(f, text=text, font=(F, 11, 'bold'), bg=C['bg'], fg=C['accent_lt']).pack(side=tk.LEFT)
            line_f = tk.Frame(f, bg=C['bg'])
            line_f.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(12, 0))
            tk.Frame(line_f, bg=C['accent'], height=1).pack(fill=tk.X)
            tk.Frame(line_f, bg=C['g_ind_1'], height=1).pack(fill=tk.X)
        def styled_entry(parent, var, width=None, small=False):
            outer = tk.Frame(parent, bg=C['border'], padx=1, pady=1)
            inner = tk.Frame(outer, bg=C['surface2'])
            inner.pack(fill=tk.BOTH, expand=True)
            kw = dict(font=(F, 10), bg=C['surface2'], fg=C['text'], insertbackground=C['accent'], relief='flat', bd=8, highlightthickness=0)
            if width:
                kw['width'] = width
