        tk.Frame(self.root, bg=C['border2'], height=1).pack(fill=tk.X)
        _E = 6
        _C = 16
        _MIN_W, _MIN_H = (900, 620)
        self._resize_handles = []
        def _make_edge(cursor, relx, rely, anchor, pw, ph, relw=0, relh=0, dx_fn=None, dy_fn=None, dw_fn=None, dh_fn=None):
            try:
                h = tk.Frame(self.root, bg=C['bg'], cursor=cursor)
            except tk.TclError:
                # Some resize cursors are Windows-only; fall back cleanly.
                h = tk.Frame(self.root, bg=C['bg'])
            h.place(relx=relx, rely=rely, anchor=anchor, relwidth=relw, relheight=relh, width=pw, height=ph)
            h.rs = {'rx': 0, 'ry': 0, 'x': 0, 'y': 0, 'w': 0, 'h': 0}
            self._resize_handles.append(h)
            def _press(e):
                h.rs['rx'] = e.x_root
                h.rs['ry'] = e.y_root
                h.rs['x'] = self.root.winfo_x()
                h.rs['y'] = self.root.winfo_y()
                h.rs['w'] = self.root.winfo_width()
                h.rs['h'] = self.root.winfo_height()
            def _drag(e):
                dx = e.x_root - h.rs['rx']
                dy = e.y_root - h.rs['ry']
                nx = h.rs['x'] + (dx_fn(dx, dy) if dx_fn else 0)
                ny = h.rs['y'] + (dy_fn(dx, dy) if dy_fn else 0)
                nw = max(_MIN_W, h.rs['w'] + (dw_fn(dx, dy) if dw_fn else 0))
                nh = max(_MIN_H, h.rs['h'] + (dh_fn(dx, dy) if dh_fn else 0))
                if dx_fn and nw == _MIN_W and (dx_fn(1, 0) < 0):
                    nx = h.rs['x'] + h.rs['w'] - _MIN_W
                if dy_fn and nh == _MIN_H and (dy_fn(0, 1) < 0):
                    ny = h.rs['y'] + h.rs['h'] - _MIN_H
                self.root.geometry('%dx%d+%d+%d' % (nw, nh, nx, ny))
            h.bind('<ButtonPress-1>', _press)
            h.bind('<B1-Motion>', _drag)
            return h
        if self._standalone:
            _make_edge('size_ns', 0, 0, 'nw', 0, _E, relw=1, dy_fn=lambda dx, dy: dy, dh_fn=lambda dx, dy: -dy)
            _make_edge('size_ns', 0, 1, 'sw', 0, _E, relw=1, dh_fn=lambda dx, dy: dy)
            _make_edge('size_we', 0, 0, 'nw', _E, 0, relh=1, dx_fn=lambda dx, dy: dx, dw_fn=lambda dx, dy: -dx)
            _make_edge('size_we', 1, 0, 'ne', _E, 0, relh=1, dw_fn=lambda dx, dy: dx)
            _make_edge('size_nw_se', 0, 0, 'nw', _C, _C, dx_fn=lambda dx, dy: dx, dy_fn=lambda dx, dy: dy, dw_fn=lambda dx, dy: -dx, dh_fn=lambda dx, dy: -dy)
            _make_edge('size_ne_sw', 1, 0, 'ne', _C, _C, dy_fn=lambda dx, dy: dy, dw_fn=lambda dx, dy: dx, dh_fn=lambda dx, dy: -dy)
