        Ws, Hs = (190, 44)
        def _make_sb_btn(parent, text, icon, bg_c, bg_h, glow_r, cmd, enabled=True, width=190, fg='white'):
            cv_b = tk.Canvas(parent, width=width, height=Hs, bg=C['surface'], highlightthickness=0, cursor='hand2' if enabled else 'arrow')
            cv_b._enabled = enabled
            def _draw(state):
                cv_b.delete('all')
                if not cv_b._enabled:
                    self._rrect(cv_b, 0, 0, width, Hs, 8, fill=C['surface2'], outline='')
                    cv_b.create_text(width // 2, Hs // 2, text=f'{icon}  {text}', font=(F, 9, 'bold'), fill=C['text3'])
                else:
                    fill = bg_h if state == 'hover' else bg_c
                    rings = glow_r if state != 'hover' else []
                    self._glow_rrect(cv_b, 0, 0, width, Hs, 8, fill, rings=rings)
                    cv_b.create_text(width // 2, Hs // 2, text=f'{icon}  {text}', font=(F, 9, 'bold'), fill=fg)
            _draw('idle')
            if enabled:
                cv_b.bind('<Enter>', lambda e: _draw('hover'))
                cv_b.bind('<Leave>', lambda e: _draw('idle'))
                cv_b.bind('<Button-1>', lambda e: cmd())
            cv_b._draw_fn = _draw
            return cv_b
