        def _proxy_import():
            path = filedialog.askopenfilename(title='Importer liste de proxys', filetypes=[('Fichiers texte', '*.txt'), ('Tous', '*.*')])
            if not path:
                return
            else:
                try:
                    with open(path, encoding='utf-8', errors='ignore') as _f:
                        lines = [l.strip() for l in _f if l.strip() and (not l.startswith('#'))]
                    parsed = []
                    for ln in lines:
                        p = _parse_proxy_line(ln)
                        if p:
                            parsed.append(p)
                    if not parsed:
                        messagebox.showwarning('Proxys', 'Aucun proxy valide trouvé dans le fichier.')
                        return
                    else:
                        self.proxys_list = parsed
                        self.proxy_enabled_var.set(True)
                        _proxy_refresh()
                        self.log(f'🌐 {len(parsed)} proxy(s) importé(s) depuis {os.path.basename(path)}')
                except Exception as ex:
                    messagebox.showerror('Erreur', str(ex))
        def _proxy_clear():
            self.proxys_list = []
            self.proxy_enabled_var.set(False)
            _proxy_refresh()
            self.log('🌐 Liste de proxys effacée.')
        def _parse_proxy_line(raw):
            """Parse une ligne de proxy en dict {server, username, password}."""
            raw = raw.strip()
            if not raw:
                return
            else:
                if raw.startswith(('http://', 'https://', 'socks4://', 'socks5://')):
                    try:
                        u = urlparse(raw)
                        server = f'{u.scheme}://{u.hostname}:{u.port}'
                        return {'server': server, 'username': u.username or None, 'password': u.password or None}
                    except Exception:
                        return {'server': raw, 'username': None, 'password': None}
                else:
                    parts = raw.split(':')
                    if len(parts) == 4:
                        ip, port, user, pwd = parts
                        return {'server': f'http://{ip}:{port}', 'username': user or None, 'password': pwd or None}
                    else:
                        if len(parts) == 2:
                            ip, port = parts
                            if port.isdigit():
                                return {'server': f'http://{ip}:{port}', 'username': None, 'password': None}
