        def _update_ram():
            if self._closing:
                return
            try:
                class _MEMSTATUS(ctypes.Structure):
                    _fields_ = [('dwLength', ctypes.c_ulong), ('dwMemoryLoad', ctypes.c_ulong), ('ullTotalPhys', ctypes.c_ulonglong), ('ullAvailPhys', ctypes.c_ulonglong), ('ullTotalPageFile', ctypes.c_ulonglong), ('ullAvailPageFile', ctypes.c_ulonglong), ('ullTotalVirtual', ctypes.c_ulonglong), ('ullAvailVirtual', ctypes.c_ulonglong), ('ullAvailExtendedVirtual', ctypes.c_ulonglong)]
                ms = _MEMSTATUS()
                ms.dwLength = ctypes.sizeof(ms)
                ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(ms))
                total_kb = ms.ullTotalPhys // 1024
                free_kb = ms.ullAvailPhys // 1024
                used_mb = (total_kb - free_kb) // 1024
                total_mb = total_kb // 1024
                pct = (total_kb - free_kb) / total_kb * 100
                color = C['danger'] if pct > 85 else C['warning'] if pct > 65 else C['success']
                self._ram_lbl.config(text=f'RAM système : {used_mb} Mo / {total_mb} Mo  ({pct:.0f}%)', fg=color)
            except Exception:
                self._ram_lbl.config(text='')
            self.root.after(5000, _update_ram)
