        def _add_slot():
            s = self._sched_start_var.get().strip()
            e = self._sched_end_var.get().strip()
            if not re.match('^\\d{1,2}:\\d{2}$', s) or not re.match('^\\d{1,2}:\\d{2}$', e):
                messagebox.showerror('Horaire invalide', 'Format attendu : HH:MM  (ex: 02:00)')
                return
            else:
                self.schedule_slots.append({'start': s, 'end': e})
                _refresh_list()
        def _refresh_list():
            for w in self._sched_list_frame.winfo_children():
                w.destroy()
            if not self.schedule_slots:
                tk.Label(self._sched_list_frame, text='Aucun horaire — travail continu', font=(F, 9), bg=C['surface'], fg=C['text3']).pack(anchor='w')
                return
            else:
                for idx, sl in enumerate(self.schedule_slots):
                    row = tk.Frame(self._sched_list_frame, bg=C['surface2'])
                    row.pack(fill=tk.X, pady=2, padx=0)
                    tk.Label(row, text=f"  {sl['start']}  →  {sl['end']}", font=(F, 9, 'bold'), bg=C['surface2'], fg=C['info'], width=18, anchor='w').pack(side=tk.LEFT, padx=6, pady=5)
                    def _del(ii=idx):
                        self.schedule_slots.pop(ii)
                        _refresh_list()
                    tk.Button(row, text='✕', font=(F, 9), bg=C['surface2'], fg=C['danger'], relief='flat', bd=0, activebackground=C['surface2'], activeforeground=C['danger2'], cursor='hand2', command=_del).pack(side=tk.RIGHT, padx=8)
