        tk.Label(rj_opts, text='Délai entre chaque action (s) :', font=(F, 9), bg=C['surface'], fg=C['text2']).pack(side=tk.LEFT)
        tk.Spinbox(rj_opts, from_=2, to=60, textvariable=self._jg_delay_var, font=(F, 9), width=5, bg=C['surface2'], fg=C['text'], relief='flat', bd=4, buttonbackground=C['surface3']).pack(side=tk.LEFT, padx=(6, 16))
        def _rj_import():
            path = filedialog.askopenfilename(title='Importer URLs depuis TXT', filetypes=[('Fichiers texte', '*.txt'), ('Tous', '*.*')])
            if not path:
                return
            else:
                try:
                    with open(path, encoding='utf-8', errors='ignore') as f:
                        lines = [l.strip() for l in f if l.strip() and 'facebook.com' in l.lower()]
                    self._jg_text.delete('1.0', tk.END)
                    self._jg_text.insert(tk.END, '\n'.join(lines))
                except Exception as ex:
                    messagebox.showerror('Erreur', str(ex))
        _mini_btn(rj_opts, '📂 Importer TXT', _rj_import)
        rj_btns = tk.Frame(rj_body, bg=C['surface'])
        rj_btns.pack(fill=tk.X, pady=(10, 0))
        def _rj_start():
            if self._jg_running:
                return
            else:
                raw = self._jg_text.get('1.0', tk.END).strip()
                urls = [l.strip() for l in raw.splitlines() if l.strip().startswith(('http://', 'https://'))]
                if not urls:
                    messagebox.showerror('Erreur', 'Aucune URL valide détectée.')
                    return
                else:
                    slots = [sid for sid, a in self.accounts.items() if a['connected'] and a.get('post_active', True)]
                    if not slots:
                        messagebox.showerror('Erreur', 'Aucun compte connecté et actif.')
                        return
                    else:
                        if not self._require_playwright('Rejoindre les groupes'):
                            return
                        try:
                            delay = int(self._jg_delay_var.get())
                        except Exception:
                            delay = 5
                        self._jg_running = True
                        _rj_start_btn.config(state='disabled', text='En cours…')
                        self._start_thread(self._join_groups_thread, (slots, urls, delay))
        def _rj_stop():
            self._jg_running = False
        _rj_start_btn = tk.Button(rj_btns, text='▶ Rejoindre les groupes', font=(F, 9, 'bold'), bg=C['success'], fg='white', activebackground='#15803d', activeforeground='white', relief='flat', cursor='hand2', padx=14, pady=6, bd=0, command=_rj_start)
