    def _fit_journal(self, dispo=None):
        """Le journal occupe toute la hauteur visible.

        On agit sur le nombre de lignes du widget texte, pas sur la
        hauteur de la fenetre du canvas : c'est la hauteur *demandee* qui
        pilote la mise en page, donc la seule qui donne un resultat
        stable. Le reste de la vue (titre, entete, marges) est mesure
        plutot qu'estime, pour rester juste si la vue evolue."""
        if getattr(self, '_current_section', None) != 'journal':
            return
        try:
            if dispo is None:
                dispo = self._body_canvas.winfo_height()
            if not dispo or dispo < 160:
                return
            sec = self._sections.get('journal')
            if sec is None or self.log_area is None:
                return
            autre = getattr(self, '_journal_habillage', None)
            if autre is None:
                mesure = sec.winfo_reqheight() - self.log_area.winfo_reqheight()
                autre = mesure if 40 <= mesure <= 400 else 170
                self._journal_habillage = autre
            lh = _tkfont.Font(font=self.log_area['font']).metrics('linespace') or 15
            n = max(8, int((dispo - autre - 10) / max(1, lh)))
            if int(self.log_area['height']) != n:
                self.log_area.config(height=n)
        except Exception:
            return None
    def show_section(self, name):
        """Affiche la vue `name` et masque les autres."""
        F = 'Segoe UI'
        if name not in self._sections:
            return
        else:
            for n, frame in self._sections.items():
                if n == name:
                    frame.pack(fill=tk.BOTH, expand=True)
                else:
                    frame.pack_forget()
            for n, b in self._nav_btns.items():
                active = n == name
                b.config(bg=C['surface2'] if active else C['surface'], fg=C['accent'] if active else C['text2'], font=(F, 9, 'bold') if active else (F, 9))
                bar = self._nav_bars.get(n)
                if bar:
                    bar.config(bg=C['accent'] if active else C['surface'])
            self._current_section = name
            try:
                self.root.update_idletasks()
                self._fit_journal()
                self.root.update_idletasks()
                self._fit_body()
                self._body_canvas.configure(scrollregion=self._body_canvas.bbox('all'))
                self._body_canvas.yview_moveto(0)
            except Exception:
                return None
    def _refresh_statusbar(self):
        try:
            n = sum((1 for a in self.accounts.values() if a.get('connected')))
            self._sb_conn.config(text=f'● {n} connecté(s)', fg=C['success'] if n else C['text3'])
            reste = max(0, self._post_total - self._post_count)
            self._sb_queue.config(text=f'file {reste}' if self.is_running else f'file {reste}', fg=C['accent'] if self.is_running else C['text3'])
            if self.wd_enabled_var.get():
                self._sb_wd.config(text=f'chien de garde {self.wd_timeout_var.get()} s', fg=C['text2'])
            else:
                self._sb_wd.config(text='chien de garde inactif', fg=C['text3'])
            self._sb_clock.config(text=datetime.now().strftime('%H:%M:%S'))
        except Exception:
            return None
    def toggle_theme(self):
        if _CURRENT_THEME[0] == 'light':
            _CURRENT_THEME[0] = 'dark'
            C.update(C_DARK)
            icon = '☀'
        else:
            _CURRENT_THEME[0] = 'light'
            C.update(C_LIGHT)
            icon = '🌙'
        if self._theme_btn_lbl:
            self._theme_btn_lbl.config(text=icon)
        self._theme_walk(self.root)
        self.root.configure(bg=C['bg'])
        self._redraw_all_canvases()
    def _redraw_all_canvases(self):
        """Les elements peints sur Canvas ne suivent pas _theme_walk : on les repeint."""
        for fn in list(self._account_redraw.values()):
            try:
                fn()
            except Exception:
                pass
        for w in [getattr(self, 'start_btn', None), getattr(self, 'pause_btn', None), getattr(self, 'stop_btn', None), getattr(self, 'force_stop_btn', None)]:
            fn = getattr(w, '_draw_fn', None)
            if callable(fn):
                try:
                    fn('idle')
                except Exception:
                    pass
        if callable(self._connect_sel_draw):
            try:
                self._connect_sel_draw()
            except Exception:
                return None
    def _theme_walk(self, widget):
        wclass = widget.winfo_class()
        try:
            if wclass in ['Frame', 'Labelframe']:
                bg = widget.cget('bg')
                new_bg = self._remap_color(bg)
                widget.config(bg=new_bg)
            else:
                if wclass == 'Label':
                    bg = self._remap_color(widget.cget('bg'))
                    fg = self._remap_color(widget.cget('fg'))
                    widget.config(bg=bg, fg=fg)
                else:
                    if wclass == 'Button':
                        bg = self._remap_color(widget.cget('bg'))
                        fg = self._remap_color(widget.cget('fg'))
                        widget.config(bg=bg, fg=fg)
                    else:
                        if wclass == 'Entry':
                            bg = self._remap_color(widget.cget('bg'))
                            fg = self._remap_color(widget.cget('fg'))
                            widget.config(bg=bg, fg=fg)
                        else:
                            if wclass in ['Checkbutton', 'Radiobutton']:
                                bg = self._remap_color(widget.cget('bg'))
                                fg = self._remap_color(widget.cget('fg'))
                                widget.config(bg=bg, fg=fg, selectcolor=C['surface2'], activebackground=C['surface'])
                            else:
                                if wclass == 'Text':
                                    widget.config(bg=C['surface2'], fg=C['text'])
                                else:
                                    if wclass == 'Canvas':
                                        widget.config(bg=self._remap_color(widget.cget('bg')))
        except Exception:
            pass
        for child in widget.winfo_children():
            self._theme_walk(child)
    _LIGHT_TO_KEY = None
    _DARK_TO_KEY = None
    def _remap_color(self, col):
        if self.__class__._LIGHT_TO_KEY is None:
            # first key wins (e.g. 'accent' before 'purple', which share a value)
            self.__class__._LIGHT_TO_KEY = {v: k for k, v in reversed(list(C_LIGHT.items()))}
            self.__class__._DARK_TO_KEY = {v: k for k, v in reversed(list(C_DARK.items()))}
        col = (col or '').lower()
        if _CURRENT_THEME[0] == 'dark':
            key = self.__class__._LIGHT_TO_KEY.get(col)
            if key and key in C_DARK:
                return C_DARK[key]
            else:
                return col
        else:
            key = self.__class__._DARK_TO_KEY.get(col)
            if key and key in C_LIGHT:
                return C_LIGHT[key]
            else:
                return col
    def _close_app(self):
        """Close button of the custom title bar (standalone window)."""
        try:
            self.teardown()
        finally:
            if self._standalone:
                try:
                    self.root.destroy()
                except Exception:
                    pass

    def toggle_mini_mode(self):
        if not self._standalone:
            return
        if not self._mini_mode:
            self._full_geometry = self.root.geometry()
            self._mini_mode = True
            self._mini_btn_lbl.config(text='⊞')
            self.root.geometry('480x360')
        else:
            self._mini_mode = False
            self._mini_btn_lbl.config(text='⊟')
            self.root.geometry(self._full_geometry)
    ROW_H = 34
    ROW_MINW = 660
    def _row_zones(self, W):
        """Renvoie {nom: (x1, x2)} pour une rangee de largeur W."""
        W = max(int(W), self.ROW_MINW)
        z = {}
        x = W - 6
        for name, w in [('act2', 96), ('act1', 62), ('page', 128), ('post', 62), ('stat', 118)]:
            z[name] = (x - w, x)
            x -= w + 1
        z['cb'] = (10, 34)
        z['num'] = (38, 64)
        z['name'] = (70, max(150, x - 10))
        return (W, z)
    def _draw_accounts_header(self):
        """Ligne d\'en-tete : rappelle ce que contient chaque colonne."""
        cv = getattr(self, '_acc_head_cv', None)
        if cv is None:
            return
        else:
            F = 'Segoe UI'
            W, z = self._row_zones(cv.winfo_width())
            cv.delete('all')
            cv.create_rectangle(0, 0, W, 22, fill=C['surface2'], outline='')
            cv.create_line(0, 21, W, 21, fill=C['border'], width=1)
            def lbl(zone, text, anchor='w'):
                x1, x2 = z[zone]
                x = x1 if anchor == 'w' else (x1 + x2) // 2
                cv.create_text(x, 11, text=text, anchor=anchor, font=(F, 9), fill=C['text3'])
            lbl('num', 'N°')
            lbl('name', 'Compte')
            lbl('stat', 'État')
            lbl('post', 'Publie', 'center')
            lbl('page', 'Publier en tant que', 'center')
            lbl('act2', 'Action', 'center')
    def _add_account_widget(self, i):
        F = 'Segoe UI'
        F2 = 'Segoe UI Semibold'
        H = self.ROW_H
        cv = tk.Canvas(self.accounts_frame, height=H, bg=C['bg'], highlightthickness=0)
        cv.grid(row=i - 1, column=0, sticky='ew', pady=0)
        cv._hover = None
        def _redraw():
            acc = self.accounts[i]
            conn = acc['connected']
            conn_ing = acc.get('connecting', False)
            needs_lgn = acc.get('needs_login', False) and (not conn) and (not conn_ing)
            sel = acc.get('selected', False)
            post = acc.get('post_active', True)
            pages_list = acc.get('pages', [])
            pa = acc.get('post_as', 'profile')
            refreshing_p = acc.get('refreshing_pages', False)
            pulse = self._conn_blink
            hov = cv._hover
            W, z = self._row_zones(cv.winfo_width())
            cv.delete('all')
            if conn:
                sc = C['success']
            else:
                if conn_ing:
                    sc = C['warning'] if pulse else C['warning2']
                else:
                    if needs_lgn:
                        sc = C['danger']
                    else:
                        if sel:
                            sc = C['accent']
                        else:
                            sc = C['border2']
            row_bg = C['surface2'] if sel and (not conn) else C['surface']
            cv.create_rectangle(0, 0, W, H, fill=row_bg, outline='')
            cv.create_line(0, H - 1, W, H - 1, fill=C['border'], width=1)
            cv.create_rectangle(0, 0, 3, H, fill=sc, outline='')
            def zone_bg(name, fill):
                """Aplat d\'une zone, eclairci si elle est survolee."""
                x1, x2 = z[name]
                cv.create_rectangle(x1, 4, x2, H - 5, fill=fill, outline='')
            mid = H // 2
            cx1, cx2 = z['cb']
            if hov == 'cb' and (not conn) and (not conn_ing):
                        cv.create_rectangle(cx1, 4, cx2, H - 5, fill=C['surface3'], outline='')
            bx = cx1 + 5
            if conn:
                cv.create_rectangle(bx, mid - 7, bx + 14, mid + 7, fill=C['success'], outline='')
                cv.create_text(bx + 7, mid, text='✓', font=(F, 9, 'bold'), fill=C['bg'])
            else:
                if sel:
                    cv.create_rectangle(bx, mid - 7, bx + 14, mid + 7, fill=C['accent'], outline='')
                    cv.create_text(bx + 7, mid, text='✓', font=(F, 9, 'bold'), fill=C['bg'])
                else:
                    cv.create_rectangle(bx, mid - 7, bx + 14, mid + 7, fill=C['surface2'], outline=C['border2'])
            cv.create_text(z['num'][0], mid, text=f'{i:02d}', anchor='w', font=('Consolas', 9), fill=C['text3'])
            nx1, nx2 = z['name']
            cname = acc.get('custom_name', '') or acc.get('name', '')
            maxch = max(8, (nx2 - nx1) // 8)
            disp = cname or f'Compte {i:02d}'
            if len(disp) > maxch:
                disp = disp[:maxch - 1] + '…'
            name_col = C['text'] if conn or sel else C['text2']
            cv.create_text(nx1, mid, text=disp, anchor='w', font=(F2, 9), fill=name_col)
            if conn_ing:
                s_col, s_txt = (C['warning'], 'CONNEXION')
            else:
                if conn:
                    s_col, s_txt = (C['success'], 'EN LIGNE')
                else:
                    if needs_lgn:
                        s_col, s_txt = (C['danger'], '2FA REQUIS')
                    else:
                        if sel:
                            s_col, s_txt = (C['accent'], 'SÉLECTIONNÉ')
                        else:
                            s_col, s_txt = (C['text3'], 'LIBRE')
            cv.create_text(z['stat'][0], mid, text=s_txt, anchor='w', font=('Consolas', 9), fill=s_col)
            if conn:
                px1, px2 = z['post']
                p_fill = C['success_d'] if post else C['surface2']
                if hov == 'post':
                    p_fill = C['surface3']
                cv.create_rectangle(px1, 7, px2, H - 8, fill=p_fill, outline=C['border'])
                cv.create_text((px1 + px2) // 2, mid, text='POST' if post else 'OFF', font=('Consolas', 9), fill=C['success'] if post else C['text3'])
                gx1, gx2 = z['page']
                rf_x = gx2 - 22
                zone_bg('page', C['surface3'] if hov == 'page' else C['surface2'])
                if pa == 'profile' or not pages_list:
                    p_label, p_tc = ('Profil', C['text2'])
                else:
                    idx = max(0, min(int(pa), len(pages_list) - 1))
                    pname = pages_list[idx].get('name', 'Page')
                    p_label = pname[:11] + '…' if len(pname) > 11 else pname
                    p_tc = C['text']
                if pages_list:
                    cv.create_text(gx1 + 8, mid, text='‹', anchor='w', font=(F, 9), fill=C['text3'])
                    cv.create_text(rf_x - 8, mid, text='›', anchor='e', font=(F, 9), fill=C['text3'])
                cv.create_text((gx1 + rf_x) // 2, mid, text=p_label, font=(F, 9), fill=p_tc)
                cv.create_line(rf_x, 4, rf_x, H - 5, fill=C['border'], width=1)
                cv.create_text((rf_x + gx2) // 2, mid, text='↻', font=(F, 9, 'bold'), fill=C['warning'] if refreshing_p else C['text3'])
            a1x1, a1x2 = z['act1']
            a2x1, a2x2 = z['act2']
            if conn_ing:
                bar_w = int((a2x2 - a1x1) * (0.7 if pulse else 0.35))
                cv.create_rectangle(a1x1, mid - 2, a1x1 + bar_w, mid + 2, fill=C['warning'], outline='')
            else:
                if conn:
                    zone_bg('act1', C['surface3'] if hov == 'act1' else C['surface2'])
                    cv.create_text((a1x1 + a1x2) // 2, mid, text='WEB', font=('Consolas', 9), fill=C['info'])
                    zone_bg('act2', C['surface3'] if hov == 'act2' else C['surface2'])
                    cv.create_text((a2x1 + a2x2) // 2, mid, text='Déconnecter', font=(F, 9), fill=C['text2'])
                else:
                    zone_bg('act1', C['surface3'] if hov == 'act1' else C['surface2'])
                    cv.create_text((a1x1 + a1x2) // 2, mid, text='COOKIE', font=('Consolas', 9), fill=C['text3'])
                    if hov == 'act2':
                        zone_bg('act2', C['accent'])
                        cv.create_text((a2x1 + a2x2) // 2, mid, text='Se connecter', font=(F, 9, 'bold'), fill=C['bg'])
                    else:
                        zone_bg('act2', C['surface2'])
                        cv.create_text((a2x1 + a2x2) // 2, mid, text='Se connecter', font=(F, 9), fill=C['text2'])
        def _zone_at(x, y):
            acc = self.accounts[i]
            conn = acc['connected']
            ing = acc.get('connecting', False)
            W, z = self._row_zones(cv.winfo_width())
            for name in ['cb', 'name', 'stat', 'post', 'page', 'act1', 'act2']:
                x1, x2 = z[name]
                if x1 <= x <= x2:
                        if name == 'cb' and (conn or ing):
                            return None
                        else:
                            if name in ('post', 'page') and (not conn):
                                return
                            else:
                                if name in ('act1', 'act2') and ing:
                                    return
                                else:
                                    if name == 'stat':
                                        return
                                    else:
                                        return name
        def _on_click(event):
            acc = self.accounts[i]
            zone = _zone_at(event.x, event.y)
            if zone is None:
                return
            else:
                W, z = self._row_zones(cv.winfo_width())
                if zone == 'cb':
                    acc['selected'] = not acc.get('selected', False)
                    _redraw()
                    self._refresh_connect_btn()
                else:
                    if zone == 'post':
                        with self._accounts_lock:
                            acc['post_active'] = not acc.get('post_active', True)
                        _redraw()
                    else:
                        if zone == 'page':
                            pages_l = acc.get('pages', [])
                            gx1, gx2 = z['page']
                            rf_x = gx2 - 22
                            if event.x >= rf_x:
                                if not acc.get('refreshing_pages') and self._require_playwright('Recherche des pages'):
                                    self._start_thread(self._refresh_pages_thread, (i,), name='refresh-pages-%d' % i)
                                return None
                            else:
                                if not pages_l:
                                    return
                                else:
                                    go_back = event.x < (gx1 + rf_x) // 2
                                    pa = acc.get('post_as', 'profile')
                                    if pa == 'profile':
                                        acc['post_as'] = len(pages_l) - 1 if go_back else 0
                                    else:
                                        idx = max(0, min(int(pa), len(pages_l) - 1))
                                        if go_back:
                                            acc['post_as'] = 'profile' if idx == 0 else idx - 1
                                        else:
                                            acc['post_as'] = 'profile' if idx >= len(pages_l) - 1 else idx + 1
                                    _redraw()
                        else:
                            if zone == 'act1':
                                if acc['connected']:
                                    self._start_thread(self._open_account_browser, (i,), name='browser-%d' % i)
                                else:
                                    self.root.after(0, lambda s=i: self._show_cookie_dialog(s))
                            else:
                                if zone == 'act2':
                                    if acc['connected']:
                                        with self._accounts_lock:
                                            acc.update(connected=False, post_active=True, pages=[], post_as='profile')
                                        _redraw()
                                        self._refresh_account_header()
                                    else:
                                        self.connect_account(i)
        def _on_double(event):
            if _zone_at(event.x, event.y) == 'name':
                self.root.after(0, lambda s=i: self._rename_account_popup(s))
        cv.bind('<Double-Button-1>', _on_double)
        def _press_drag(event):
            if getattr(self, 'is_running', False):
                return
            else:
                self._drag_src = i
                self._drag_active = False
                self._drag_over = None
                self._drag_start = (event.x_root, event.y_root)
        def _motion_drag(event):
            if self._drag_src != i:
                return
            else:
                dx = event.x_root - self._drag_start[0]
                dy = event.y_root - self._drag_start[1]
                if not self._drag_active and (abs(dx) > 6 or abs(dy) > 6):
                        self._drag_active = True
                        cv.config(cursor='fleur')
                if self._drag_active:
                    self._update_drag_highlight(event.x_root, event.y_root)
        def _release_drag(event):
            if self._drag_active and self._drag_src is not None:
                target = self._find_slot_at(event.x_root, event.y_root)
                self._clear_drag_highlight()
                src = self._drag_src
                self._drag_active = False
                self._drag_src = None
                cv.config(cursor='arrow')
                if target and target != src:
                        self.root.after(0, lambda s=src, t=target: self._swap_accounts(s, t))
            else:
                self._drag_active = False
                self._drag_src = None
                _on_click(event)
        cv.bind('<ButtonPress-1>', _press_drag)
        cv.bind('<B1-Motion>', _motion_drag)
        cv.bind('<ButtonRelease-1>', _release_drag)
        def _on_motion(e):
            if self._drag_active:
                return
            else:
                zone = _zone_at(e.x, e.y)
                if zone != cv._hover:
                    cv._hover = zone
                    _redraw()
                cv.config(cursor='hand2' if zone else 'arrow')
        def _on_leave(e):
            if cv._hover is not None:
                cv._hover = None
                _redraw()
        cv.bind('<Motion>', _on_motion)
        cv.bind('<Leave>', _on_leave)
        cv.bind('<Configure>', lambda e: _redraw())
        self.account_canvases[i] = cv
        self._account_redraw[i] = _redraw
        _redraw()
    def _place_add_button(self):
        n = len(self.accounts)
        self.add_account_btn.grid(row=n, column=0, sticky='ew', pady=(6, 0))
    def add_new_account(self):
        i = self.next_account_id
        self.next_account_id += 1
        with self._accounts_lock:
            self.accounts[i] = {'connected': False, 'connecting': False, 'selected': False, 'post_active': True, 'name': '', 'custom_name': '', 'pages': [], 'post_as': 'profile', 'user_data_dir': os.path.join(SESSION_BASE, f'Account_{i}')}
        self._add_account_widget(i)
        self._place_add_button()
    @property
    def _ACCOUNT_CFG(self):
        # computed on access so that a relocated SESSION_BASE is honoured
        return os.path.join(SESSION_BASE, 'account_config.json')

    @staticmethod
    def _safe_profile_dirname(rel_dir):
        """A saved profile folder must be a plain name inside SESSION_BASE."""
        rel_dir = str(rel_dir or '').strip()
        if not rel_dir or rel_dir in ('.', '..') or os.path.basename(rel_dir) != rel_dir or '/' in rel_dir or '\\' in rel_dir or ':' in rel_dir:
            return None
        return rel_dir
    def _load_account_config(self):
        try:
            with open(self._ACCOUNT_CFG, encoding='utf-8') as f:
                cfg = json.load(f)
        except FileNotFoundError:
            return None
        except Exception as e:
            print('[autoV2] account_config.json illisible : %s' % e, file=sys.stderr)
            return None
        try:
            for sid_str, cname in (cfg.get('custom_names') or {}).items():
                sid = int(sid_str)
                if sid in self.accounts:
                    self.accounts[sid]['custom_name'] = str(cname or '')
            for sid_str, rel_dir in (cfg.get('slot_dirs') or {}).items():
                sid = int(sid_str)
                rel_dir = self._safe_profile_dirname(rel_dir)
                if sid in self.accounts and rel_dir:
                    self.accounts[sid]['user_data_dir'] = os.path.join(SESSION_BASE, rel_dir)
            for sid_str, post_as in (cfg.get('post_as') or {}).items():
                sid = int(sid_str)
                if sid in self.accounts:
                    self.accounts[sid]['post_as'] = post_as
            for sid_str, pages in (cfg.get('pages') or {}).items():
                sid = int(sid_str)
                if sid in self.accounts and isinstance(pages, list):
                    self.accounts[sid]['pages'] = pages
        except Exception:
            traceback.print_exc()
            return None
    def _save_account_config(self):
        """Persist names / profile folders / post-as choice / pages.

        (The decompiled version replaced self.accounts with a dict of names
        and shifted every key by one; rebuilt from _load_account_config.)"""
        try:
            os.makedirs(SESSION_BASE, exist_ok=True)
            with self._accounts_lock:
                items = [(sid, dict(a)) for sid, a in self.accounts.items()]
            cfg = {'custom_names': {str(sid): a.get('custom_name', '') for sid, a in items},
                   'slot_dirs': {str(sid): os.path.basename(a['user_data_dir']) for sid, a in items},
                   'post_as': {str(sid): a.get('post_as', 'profile') for sid, a in items},
                   'pages': {str(sid): a.get('pages', []) for sid, a in items}}
            tmp = self._ACCOUNT_CFG + '.tmp'
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump(cfg, f, ensure_ascii=False, indent=2)
            os.replace(tmp, self._ACCOUNT_CFG)
        except Exception:
            traceback.print_exc()
            return
    def _rename_account_popup(self, slot_id):
        acc = self.accounts.get(slot_id)
        if acc is None:
            return
        else:
            current = acc.get('custom_name', '') or acc.get('name', '') or f'Compte {slot_id:02d}'
            dlg = tk.Toplevel(self.root)
            dlg.title('Renommer le compte')
            dlg.resizable(False, False)
            dlg.configure(bg=C['surface'])
            try:
                dlg.transient(self.root.winfo_toplevel())
            except Exception:
                pass
            dlg.grab_set()
            self.root.update_idletasks()
            rx = self.root.winfo_rootx() + self.root.winfo_width() // 2 - 160
            ry = self.root.winfo_rooty() + self.root.winfo_height() // 2 - 60
            dlg.geometry(f'320x120+{rx}+{ry}')
            tk.Label(dlg, text=f'Nom du compte {slot_id:02d}', font=('Segoe UI Semibold', 10), bg=C['surface'], fg=C['text']).pack(pady=(14, 4))
            var = tk.StringVar(value=current)
            ent = tk.Entry(dlg, textvariable=var, font=('Segoe UI', 10), bg=C['surface2'], fg=C['text'], insertbackground=C['text'], relief='flat', bd=4, width=28)
            ent.pack()
            ent.select_range(0, tk.END)
            ent.focus_set()
            def _confirm(event=None):
                name = var.get().strip()[:30]
                self.accounts[slot_id]['custom_name'] = name
                fn = self._account_redraw.get(slot_id)
                if callable(fn):
                    fn()
                self._save_account_config()
                dlg.destroy()
            ent.bind('<Return>', _confirm)
            ent.bind('<Escape>', lambda e: dlg.destroy())
            btn_row = tk.Frame(dlg, bg=C['surface'])
            btn_row.pack(pady=8)
            tk.Button(btn_row, text='Annuler', font=('Segoe UI', 9), bg=C['surface2'], fg=C['text2'], relief='flat', bd=0, padx=12, pady=4, cursor='hand2', command=dlg.destroy).pack(side=tk.LEFT, padx=6)
            tk.Button(btn_row, text='Enregistrer', font=('Segoe UI', 9, 'bold'), bg=C['accent'], fg='white', relief='flat', bd=0, padx=12, pady=4, cursor='hand2', command=_confirm).pack(side=tk.LEFT, padx=6)
    def _find_slot_at(self, x_root, y_root):
        """Slot dont la rangee contient le point ecran (x_root, y_root)."""
        for slot_id, cv in list(self.account_canvases.items()):
            try:
                cx = cv.winfo_rootx()
                cy = cv.winfo_rooty()
                cw = cv.winfo_width()
                ch = cv.winfo_height()
                if cx <= x_root <= cx + cw and cy <= y_root <= cy + ch:
                    return slot_id
            except Exception:
                continue
        return None
    def _update_drag_highlight(self, x_root, y_root):
        target = self._find_slot_at(x_root, y_root)
        if target == self._drag_over:
            return
        else:
            if self._drag_over and self._drag_over in self.account_canvases:
                    self.account_canvases[self._drag_over].config(highlightthickness=0)
            self._drag_over = target
            if target and target != self._drag_src and (target in self.account_canvases):
                        self.account_canvases[target].config(highlightthickness=2, highlightbackground=C['accent'])
    def _clear_drag_highlight(self):
        if self._drag_over and self._drag_over in self.account_canvases:
            try:
                self.account_canvases[self._drag_over].config(highlightthickness=0)
            except Exception:
                pass
        self._drag_over = None
    def _swap_accounts(self, src, dst):
        if src not in self.accounts or dst not in self.accounts:
            return None
        else:
            with self._accounts_lock:
                self.accounts[src], self.accounts[dst] = (self.accounts[dst], self.accounts[src])
            for sid in [src, dst]:
                fn = self._account_redraw.get(sid)
                if callable(fn):
                    fn()
            self._refresh_account_header()
            self._save_account_config()
    def update_account_ui(self, slot_id):
        fn = self._account_redraw.get(slot_id)
        if callable(fn):
            self.root.after(0, fn)
        self.root.after(0, self._refresh_account_header)
        self.root.after(0, self._refresh_connect_btn)
    def _refresh_account_header(self):
        try:
            count = sum((1 for a in self.accounts.values() if a['connected']))
            self._acc_count_lbl.config(text=f'{count} connecté(s)', fg=C['success'] if count > 0 else C['text2'])
        except Exception:
            return
    def _refresh_connect_btn(self):
        if callable(self._connect_sel_draw):
            try:
                self._connect_sel_draw()
            except Exception:
                return None
    def select_all(self, value: bool):
        with self._accounts_lock:
            for acc in self.accounts.values():
                if not acc['connected'] and (not acc.get('connecting')):
                        acc['selected'] = value
        for fn in self._account_redraw.values():
            if callable(fn):
                fn()
        self._refresh_connect_btn()
    def select_range(self):
        """Coche les slots de la plage saisie, bornes incluses, et décoche le reste.\n\n        Même règle de sécurité que `select_all` : un compte déjà connecté ou\n        en cours de connexion n\'est jamais modifié.\n        """
        def _lire(var, defaut):
            try:
                return int(str(var.get()).strip())
            except Exception:
                return defaut
        slots = sorted(self.accounts.keys())
        if not slots:
            return
        else:
            lo = _lire(self._range_from_var, slots[0])
            hi = _lire(self._range_to_var, slots[(-1)])
            if lo > hi:
                lo, hi = (hi, lo)
            lo = max(lo, slots[0])
            hi = min(hi, slots[(-1)])
            if lo > hi:
                self.show_toast(f'Aucun compte entre {lo} et {hi}.', 'warn')
                return
            else:
                self._range_from_var.set(str(lo))
                self._range_to_var.set(str(hi))
                coches = verrouilles = 0
                with self._accounts_lock:
                    for sid, acc in self.accounts.items():
                        dans = lo <= sid <= hi
                        if acc['connected'] or acc.get('connecting'):
                            if dans:
                                verrouilles += 1
                            continue
                        else:
                            acc['selected'] = dans
                            if dans:
                                coches += 1
                for fn in self._account_redraw.values():
                    if not callable(fn):
                        continue
                    else:
                        fn()
                self._refresh_connect_btn()
                msg = f'Plage {lo:02d}–{hi:02d} : {coches} compte(s) coché(s)'
                if verrouilles:
                    msg += f', {verrouilles} déjà connecté(s)'
                self.log(f'☑ {msg}')
                self.show_toast(msg, 'info' if coches else 'warn')
    def set_post_active_all(self, value: bool):
        with self._accounts_lock:
            for acc in self.accounts.values():
                if acc['connected']:
                    acc['post_active'] = value
        for fn in self._account_redraw.values():
            if callable(fn):
                fn()
    def connect_selected_accounts(self):
        targets = [sid for sid, a in self.accounts.items() if a.get('selected') and (not a['connected']) and (not a.get('connecting'))]
        if not targets:
            return
        if not self._require_playwright('Connexion'):
            return
        else:
            need_session_check = []
            n_expired = 0
            n_virgin = 0
            for sid in targets:
                acc = self.accounts[sid]
                result = self._read_sqlite_session(acc['user_data_dir'])
                with self._accounts_lock:
                    if result is True:
                        need_session_check.append(sid)
                        acc.update(connecting=True)
                    else:
                        if result is False:
                            acc.update(connected=False, connecting=False, needs_login=True, selected=False)
                        else:
                            acc.update(connected=False, connecting=False, needs_login=False, selected=False)
                self.root.after(0, lambda s=sid: self.update_account_ui(s))
                if result is False:
                    n_expired += 1
                else:
                    if result is None:
                        n_virgin += 1
            if n_expired:
                self.log(f'⚠ {n_expired} compte(s) avec session expirée — cliquez manuellement sur \'Se connecter\' pour les relancer.')
            if n_virgin:
                self.log(f'⏭ {n_virgin} slot(s) vierge(s) ignoré(s) — connectez-les manuellement via 🍪 Cookies ou \'Se connecter\'.')
            if need_session_check:
                self.log(f'🔌 {len(need_session_check)} compte(s) avec session valide — connexion en cours…')
                self._start_thread(self._check_sessions_sequential, (need_session_check,))
    def connect_account(self, slot_id):
        acc = self.accounts[slot_id]
        if not self._require_playwright('Connexion'):
            return
        if acc.get('needs_login'):
            with self._accounts_lock:
                acc.update(connecting=True, needs_login=False)
            self.root.after(0, lambda s=slot_id: self.update_account_ui(s))
            self.log(f'🔑 Compte {slot_id} : ouverture du navigateur pour login…')
            self._start_thread(self._open_login_window, (slot_id,))
            return
        else:
            os.makedirs(acc['user_data_dir'], exist_ok=True)
            sqlite_result = self._read_sqlite_session(acc['user_data_dir'])
            if sqlite_result is None or sqlite_result is False:
                with self._accounts_lock:
                    acc.update(connecting=True, needs_login=False)
                self.root.after(0, lambda s=slot_id: self.update_account_ui(s))
                self.log(f'🔑 Compte {slot_id} : ouverture du navigateur pour login…')
                self._start_thread(self._open_login_window, (slot_id,))
            else:
                with self._accounts_lock:
                    acc.update(connecting=True)
                self.root.after(0, lambda s=slot_id: self.update_account_ui(s))
                self._start_thread(self._check_sessions_sequential, ([slot_id],))
    _ARGS_HEADLESS = ['--disable-blink-features=AutomationControlled', '--disable-gpu', '--no-sandbox', '--disable-dev-shm-usage', '--disable-extensions', '--disable-default-apps', '--mute-audio', '--blink-settings=imagesEnabled=false', '--disable-background-networking', '--disable-sync', '--disable-translate', '--no-first-run', '--disable-background-timer-throttling', '--disable-backgrounding-occluded-windows', '--disable-renderer-backgrounding', '--js-flags=--max-old-space-size=48']
    _ARGS_VISIBLE = ['--disable-blink-features=AutomationControlled', '--disable-background-timer-throttling', '--disable-backgrounding-occluded-windows', '--disable-renderer-backgrounding', '--disable-dev-shm-usage', '--js-flags=--max-old-space-size=128', '--window-position=120,60', '--window-size=1100,680']
    _ARGS_SCRAPE = ['--disable-blink-features=AutomationControlled', '--disable-gpu', '--no-sandbox', '--disable-dev-shm-usage', '--disable-default-apps', '--mute-audio', '--disable-background-networking', '--disable-sync', '--disable-translate', '--no-first-run', '--disable-background-timer-throttling', '--disable-backgrounding-occluded-windows', '--disable-renderer-backgrounding']
    _ARGS_POST = ['--disable-blink-features=AutomationControlled', '--disable-background-timer-throttling', '--disable-backgrounding-occluded-windows', '--disable-renderer-backgrounding', '--disable-dev-shm-usage', '--js-flags=--max-old-space-size=128', '--window-size=1100,680']
    _ARGS_POST_HEADLESS = ['--disable-blink-features=AutomationControlled', '--disable-background-timer-throttling', '--disable-backgrounding-occluded-windows', '--disable-renderer-backgrounding', '--disable-dev-shm-usage', '--disable-gpu', '--no-sandbox', '--js-flags=--max-old-space-size=128']
    _PAGE_EXCLUSIONS = {'sign up', 'go to feed', 'paramètres', 'help', 'aide', 'all pages', 'facebook', 'accueil', 'inscription', 'most recent', 'publicités', 'messenger', 'ads manager', 'toutes les pages', 'créer une page', 'fil de vos pages', 'login', 'connexion', 'plus récent', 'instagram', 'invitations', 'login', 'help'}
    def _refresh_pages_thread(self, slot_id):
        """Relance la detection de pages pour un compte connecte."""
        acc = self.accounts[slot_id]
        if not acc.get('connected'):
            return
        acc['refreshing_pages'] = True
        self.root.after(0, lambda s=slot_id: self.update_account_ui(s))
        self.log(f'🔍 Recherche pages — Compte {slot_id}…')
        try:
            os.makedirs(acc['user_data_dir'], exist_ok=True)
            with sync_playwright() as p:
                ctx = self._launch_ctx(p, acc['user_data_dir'], headless=True, extra_args=self._ARGS_HEADLESS, sid=slot_id)
                try:
                    page = ctx.pages[0] if ctx.pages else ctx.new_page()
                    pages_list = self._fetch_pages(page)
                    with self._accounts_lock:
                        acc.update(pages=pages_list)
                        if acc.get('post_as') not in ('profile', None):
                            try:
                                if int(acc['post_as']) >= len(pages_list):
                                    acc['post_as'] = 'profile'
                            except Exception:
                                acc['post_as'] = 'profile'
                    if pages_list:
                        self.log(f'📄 Compte {slot_id} — {len(pages_list)} page(s) : ' + ', '.join((pg['name'] for pg in pages_list)))
                    else:
                        self.log(f'⚠️ Compte {slot_id} — aucune page gérée trouvée.')
                finally:
                    try:
                        ctx.close()
                    except Exception:
                        pass
            self.root.after(0, self._save_account_config)
        except Exception as e:
            self._browser_error(f'Compte {slot_id} (rafraîchir pages)', e)
        finally:
            acc['refreshing_pages'] = False
            self.root.after(0, lambda s=slot_id: self.update_account_ui(s))
    def _fetch_pages(self, page_obj):
        """Recupere les Pages Facebook gerees — 3 strategies avec extraction JS."""
        excl = FacebookMultiPosterApp._PAGE_EXCLUSIONS
        _bad = ['/settings', '/help', '/login', '/create', '/ads', '/notifications', 'facebook.com/?', 'facebook.com/home', '/privacy', '/terms', '/people', '/groups/feed', '/events', '/marketplace', '/watch', '/reels', '/gaming', '/fundraisers', '/saved', '/climate']
        def _js_extract(po):
            try:
                return po.evaluate('() => {\n    const out = [], seen = new Set();\n    const bad = [\'/settings\',\'/help\',\'/login\',\'/create\',\'/ads\',\'/notifications\',\n                 \'home.php\',\'/privacy\',\'/terms\',\'/people\',\'/groups/feed\',\n                 \'/events\',\'/marketplace\',\'/watch\',\'/reels\',\'/gaming\'];\n    const main = document.querySelector(\'[role=\"main\"]\') || document.body;\n    main.querySelectorAll(\'a[href]\').forEach(a => {\n        const h = a.href || \'\';\n        if (!h.includes(\'facebook.com\')) return;\n        if (bad.some(b => h.includes(b))) return;\n        if (!/\\/p\\/[^/?#]+/.test(h) &&\n            !/facebook\\.com\\/[A-Za-z0-9._-]{3,60}\\/?$/.test(h)) return;\n        const t = (a.innerText || a.textContent || \'\').trim().split(\'\\n\')[0].trim();\n        if (!t || t.length < 2 || t.length > 80 || seen.has(t)) return;\n        seen.add(t);\n        out.push({name: t, url: h});\n    });\n    return out;\n}') or []
            except Exception:
                return []
        def _filter(raw):
            seen, out = (set(), [])
            for it in raw or []:
                n, u = ((it.get('name') or '').strip(), it.get('url') or '')
                if not n or n.lower() in excl or n in seen:
                    continue
                if any((p in u for p in _bad)):
                    continue
                seen.add(n)
                out.append({'name': n, 'url': u})
            return out[:8]
        # Strategie 1 : gestionnaire de pages
        try:
            page_obj.goto('https://www.facebook.com/pages/manage/', wait_until='domcontentloaded', timeout=14000)
            try:
                page_obj.wait_for_selector('[role=\"main\"] a[href*=\"/p/\"], [role=\"main\"] [role=\"article\"] a', timeout=7000)
            except Exception:
                time.sleep(3)
            pages = _filter(_js_extract(page_obj))
            if pages:
                return pages
        except Exception as e:
            self.log(f'  ⚠️ Récupération pages — stratégie 1 (pages/manage) échouée : {e}')
        # Strategie 2 : site mobile
        try:
            page_obj.goto('https://m.facebook.com/pages/?category=my_pages', wait_until='domcontentloaded', timeout=12000)
            time.sleep(2)
            raw = page_obj.evaluate('() => {\n    const out = [], seen = new Set();\n    document.querySelectorAll(\'a[href]\').forEach(a => {\n        const h = a.href || \'\';\n        if (!h.includes(\'facebook.com\')) return;\n        if (h.includes(\'/create\') || h.includes(\'/help\') || h.includes(\'category=\')) return;\n        if (!h.includes(\'/pages/\') && !h.includes(\'/pg/\')) return;\n        const t = (a.innerText || \'\').trim().split(\'\\n\')[0].trim();\n        if (!t || t.length < 2 || t.length > 80 || seen.has(t)) return;\n        seen.add(t);\n        out.push({name: t, url: h});\n    });\n    return out;\n}') or []
            pages = _filter(raw)
            if pages:
                return pages
        except Exception as e:
            self.log(f'  ⚠️ Récupération pages — stratégie 2 (mobile) échouée : {e}')
        # Strategie 3 : raccourcis du fil principal
        try:
            page_obj.goto('https://www.facebook.com/', wait_until='domcontentloaded', timeout=10000)
            time.sleep(2)
            seen, pages = (set(), [])
            for sel in ['nav a[href*=\"/pages/\"] span[dir=\"auto\"]', 'a[href*=\"/pages/\"] span[dir=\"auto\"]']:
                try:
                    for el in page_obj.locator(sel).all()[:30]:
                        try:
                            txt = el.inner_text(timeout=500).strip()
                            if not txt or txt.lower() in excl or txt in seen:
                                continue
                            try:
                                href = el.locator('xpath=ancestor::a[1]').get_attribute('href', timeout=500) or ''
                            except Exception:
                                href = ''
                            if not any((p in href for p in _bad)):
                                seen.add(txt)
                                pages.append({'name': txt, 'url': href})
                        except Exception:
                            pass
                except Exception:
                    pass
                if pages:
                    return pages[:8]
        except Exception as e:
            self.log(f'  ⚠️ Récupération pages — stratégie 3 (fil principal) échouée : {e}')
        self.log('  ⚠️ Récupération pages — les 3 stratégies ont échoué, aucune page détectée.')
        return []
    @staticmethod
    def _read_sqlite_session(user_data_dir):
        """Lit le SQLite Chromium sans lancer de navigateur.
        Returns True (c_user trouve) / False (absent) / None (pas de fichier)."""
        for rel in [('Default', 'Network', 'Cookies'), ('Default', 'Cookies')]:
            path = os.path.join(user_data_dir, *rel)
            if not os.path.isfile(path):
                continue
            tmp = path + '.~check'
            try:
                shutil.copy2(path, tmp)
                con = sqlite3.connect(tmp)
                try:
                    cur = con.cursor()
                    cur.execute("SELECT COUNT(*) FROM cookies WHERE host_key LIKE '%facebook.com%' AND name='c_user'")
                    found = cur.fetchone()[0] > 0
                    return found
                finally:
                    con.close()
                    try:
                        os.unlink(tmp)
                    except Exception:
                        pass
            except Exception:
                continue
        return None
    def _check_sessions_sequential(self, slot_ids):
        """Connexion en 2 phases : SQLite instantane puis Playwright sequentiel pour les noms."""
        with _CONNECT_LOCK:
            need_name = []
            for sid in slot_ids:
                acc = self.accounts[sid]
                os.makedirs(acc['user_data_dir'], exist_ok=True)
                result = self._read_sqlite_session(acc['user_data_dir'])
                with self._accounts_lock:
                    if result is True:
                        acc.update(connected=True, connecting=False, needs_login=False, post_active=True)
                        need_name.append(sid)
                    elif result is False:
                        acc.update(connected=False, connecting=False, needs_login=True)
                    else:
                        acc.update(connected=False, connecting=False, needs_login=False, selected=False)
                if result is False:
                    self.log(f'🔑 Compte {sid} : login requis')
                elif result is None:
                    self.log(f'⏭ Compte {sid} : slot vierge — ignoré')
            for sid in slot_ids:
                self.root.after(0, lambda s=sid: self.update_account_ui(s))
            if need_name:
                self.log(f'⚡ {len(need_name)} session(s) détectée(s) — récupération noms…')
            to_process = [(sid, 'name') for sid in need_name]
            if not to_process:
                return
            try:
                with sync_playwright() as pw:
                    for sid, mode in to_process:
                        if self._closing:
                            break
                        acc = self.accounts[sid]
                        name = ''
                        try:
                            ctx = self._launch_ctx(pw, acc['user_data_dir'], headless=True, extra_args=self._ARGS_HEADLESS, sid=sid)
                            try:
                                fb_cookies = ctx.cookies('https://www.facebook.com')
                                c_user_c = next((c for c in fb_cookies if c['name'] == 'c_user'), None)
                                if c_user_c:
                                    try:
                                        pg = ctx.new_page()
                                        pg.goto(f"https://web.facebook.com/profile.php?id={c_user_c['value']}", wait_until='domcontentloaded', timeout=9000)
                                        name = pg.locator('h1').first.inner_text(timeout=4000).strip()
                                    except Exception:
                                        pass
                                    with self._accounts_lock:
                                        acc.update(connected=True, connecting=False, needs_login=False, post_active=True, name=name)
                                    self.log(f'✅ Compte {sid}' + (f' — {name}' if name else ''))
                                else:
                                    with self._accounts_lock:
                                        acc.update(connected=False, connecting=False, needs_login=True, name='')
                                    self.log(f'🔑 Compte {sid} : session expirée')
                            finally:
                                try:
                                    ctx.close()
                                except Exception:
                                    pass
                        except Exception as e:
                            self._browser_error(f'Compte {sid}', e)
                            with self._accounts_lock:
                                acc.update(connected=False, connecting=False)
                            if _is_missing_browser_error(e):
                                self.root.after(0, lambda s=sid: self.update_account_ui(s))
                                raise
                        self.root.after(0, lambda s=sid: self.update_account_ui(s))
            except Exception as e:
                if not _is_missing_browser_error(e):
                    self._browser_error('Playwright', e)
                for sid, _ in to_process:
                    with self._accounts_lock:
                        was_connecting = self.accounts[sid].get('connecting')
                        if _is_missing_browser_error(e):
                            # Chromium absent : the SQLite pre-check cannot be confirmed
                            self.accounts[sid].update(connected=False)
                            was_connecting = True
                        if was_connecting:
                            self.accounts[sid].update(connecting=False)
                    if was_connecting:
                        self.root.after(0, lambda s=sid: self.update_account_ui(s))
    def _open_login_window(self, slot_id):
        """Phase 2 — navigateur visible pour login manuel (declenche explicitement).

        Le navigateur reste ouvert jusqu'a ce que l'utilisateur le ferme ; la
        connexion est detectee des que le cookie c_user apparait."""
        acc = self.accounts[slot_id]
        os.makedirs(acc['user_data_dir'], exist_ok=True)
        logged_in = False
        try:
            with _VISIBLE_LOCK:
                with sync_playwright() as p:
                    ctx = self._launch_ctx(p, acc['user_data_dir'], headless=False, extra_args=self._ARGS_VISIBLE, sid=slot_id, viewport={'width': 1280, 'height': 720})
                    try:
                        page = ctx.pages[0] if ctx.pages else ctx.new_page()
                        try:
                            page.goto('https://web.facebook.com/', wait_until='domcontentloaded', timeout=15000)
                        except Exception:
                            pass
                        while not self._closing:
                            try:
                                fb_c = ctx.cookies('https://www.facebook.com')
                                if any((c.get('name') == 'c_user' for c in fb_c)) and (not logged_in):
                                    logged_in = True
                                    name, pages_list = ('', [])
                                    try:
                                        uid = next((c['value'] for c in fb_c if c['name'] == 'c_user'))
                                        page.goto(f'https://web.facebook.com/profile.php?id={uid}', wait_until='domcontentloaded', timeout=10000)
                                        name = page.locator('h1').first.inner_text(timeout=5000).strip()
                                        pages_list = self._fetch_pages(page)
                                    except Exception:
                                        pass
                                    with self._accounts_lock:
                                        acc.update(connected=True, connecting=False, needs_login=False, post_active=True, name=name, pages=pages_list)
                                    self.log(f'✅ Compte {slot_id} connecté !' + (f' ({name})' if name else '') + (f' · {len(pages_list)} page(s)' if pages_list else ''))
                                    self.root.after(0, lambda s=slot_id: self.update_account_ui(s))
                                    self.root.after(0, self._save_account_config)
                                if not ctx.pages:
                                    break
                            except Exception:
                                break
                            time.sleep(1)
                    finally:
                        try:
                            ctx.close()
                        except Exception:
                            pass
            if not logged_in:
                with self._accounts_lock:
                    acc.update(connecting=False)
                self.log(f'⚠️ Compte {slot_id} : login non détecté.')
            self.root.after(0, lambda s=slot_id: self.update_account_ui(s))
        except Exception as e:
            self._browser_error(f'Compte {slot_id} (login)', e)
            with self._accounts_lock:
                acc.update(connected=False, connecting=False, needs_login=True)
            self.root.after(0, lambda s=slot_id: self.update_account_ui(s))
    @staticmethod
    def _parse_cookie_string(raw):
        """Parse les cookies : JSON array ou 'name=value; name2=value2'.

        Formats supportes :
        - JSON : [{"name":"c_user","value":"123",...}, ...]  (Cookie-Editor)
        - Netscape : lignes tab-separees a 7 champs (format wget/curl)
        - Inline : c_user=123; xs=abc; datr=xyz; ...

        Les valeurs ne sont jamais decodees URL.
        """
        raw = (raw or '').strip()
        if not raw:
            return []
        if raw.startswith('['):
            try:
                items = json.loads(raw)
                if isinstance(items, list):
                    return [{'name': c['name'], 'value': str(c.get('value', ''))} for c in items if isinstance(c, dict) and c.get('name')]
            except Exception:
                pass
        if '\t' in raw:
            cookies = []
            for line in raw.splitlines():
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                parts = line.split('\t')
                if len(parts) == 7:
                    name, value = (parts[5].strip(), parts[6].strip())
                    if name:
                        cookies.append({'name': name, 'value': value})
            if cookies:
                return cookies
        cookies = []
        for part in raw.split(';'):
            part = part.strip()
            if not part or '=' not in part:
                continue
            name, _, value = part.partition('=')
            name = name.strip()
            value = value.strip()
            if not name:
                continue
            cookies.append({'name': name, 'value': value})
        return cookies
