        tk.Label(info, text='Format : collez la chaîne brute  (ex: c_user=123; xs=abc; datr=xyz; ...)', font=('Consolas', 9), bg=C['surface2'], fg=C['text3']).pack(anchor='w', pady=(2, 0))
        txt_outer = tk.Frame(body_f, bg=C['border'], padx=1, pady=1)
        txt_outer.pack(fill=tk.BOTH, expand=True)
        txt_inner = tk.Frame(txt_outer, bg=C['surface2'])
        txt_inner.pack(fill=tk.BOTH, expand=True)
        txt = tk.Text(txt_inner, font=('Consolas', 9), bg=C['surface2'], fg=C['text'], relief='flat', bd=8, height=5, wrap=tk.WORD, insertbackground=C['accent'], selectbackground=C['accent_lt'])
        txt.pack(fill=tk.BOTH, expand=True)
