        txt.bind('<FocusIn>', lambda e: txt_outer.config(bg=C['accent']))
        txt.bind('<FocusOut>', lambda e: txt_outer.config(bg=C['border']))
        btn_row = tk.Frame(dlg, bg=C['surface'], padx=24, pady=14)
        btn_row.pack(fill=tk.X, side=tk.BOTTOM)
        tk.Frame(dlg, bg=C['border2'], height=1).pack(fill=tk.X, side=tk.BOTTOM)
        def _validate():
            raw = txt.get('1.0', tk.END).strip()
            if not raw:
                messagebox.showwarning('Cookies vides', 'Collez vos cookies Facebook dans le champ.')
                return
            else:
                missing = [k for k in ['c_user', 'xs'] if k not in raw]
                if missing:
                    messagebox.showwarning('Cookies manquants', f"Cookies critiques absents : {', '.join(missing)}\n\nCopiez TOUS les cookies du domaine facebook.com\n(Cookie-Editor → Export → coller ici).")
