        cancel_btn = tk.Button(btn_row, text='Annuler', font=(F, 9), bg=C['surface3'], fg=C['text2'], activebackground=C['danger'], activeforeground='white', relief='flat', bd=0, padx=18, pady=8, cursor='hand2', command=dlg.destroy)
