        sty.configure('FB.Vertical.TScrollbar', background=C['surface3'],
                      troughcolor=C['surface'], bordercolor=C['surface'], arrowcolor=C['text2'])
        sty.map('FB.Vertical.TScrollbar',
                background=[('active', C['accent2']), ('!active', C['surface3'])])
        sty.configure('SC.TCombobox', fieldbackground=C['surface2'], background=C['surface2'],
                      foreground=C['text'], arrowcolor=C['text2'], bordercolor=C['border'],
                      selectbackground=C['surface2'], selectforeground=C['text'])
        sty.map('SC.TCombobox',
                fieldbackground=[('readonly', C['surface2'])],
                foreground=[('readonly', C['text'])],
                selectbackground=[('readonly', C['surface2'])],
                selectforeground=[('readonly', C['text'])],
                background=[('active', C['surface3']), ('readonly', C['surface2'])])
