def _ui_recolor_plain(self, remap):
    """Spinbox / Scrollbar / Button rings: not handled by _theme_walk."""
    import tkinter as _tk
    for w in _ui_walk(self.root):
        try:
            if isinstance(w, _tk.Spinbox):
                opts = {}
                for o in ('bg', 'fg', 'buttonbackground', 'insertbackground'):
                    v = str(w.cget(o))
                    nv = remap(v) if remap else v
                    if nv != v:
                        opts[o] = nv
                if opts:
                    _ui_raw_conf(w, **opts)
            elif isinstance(w, _tk.Scrollbar):
                _ui_raw_conf(w, bg=C['surface3'], troughcolor=C['surface2'],
                             activebackground=C['border2'], highlightthickness=0, bd=0)
            elif isinstance(w, _tk.Button):
                _ui_raw_conf(w, highlightbackground=C['border'], highlightcolor=C['accent'])
        except Exception:
            pass


