from collections import OrderedDict as _UIOrderedDict


def _ui_flat(a):
    out = []
    for x in a:
        if isinstance(x, (tuple, list)):
            out.extend(x)
        else:
            out.append(x)
    return out


def _sd_rbox(x0, y0, x1, y1, r):
    cx, cy = (x0 + x1) / 2.0, (y0 + y1) / 2.0
    hx, hy = (x1 - x0) / 2.0 - r, (y1 - y0) / 2.0 - r

    def f(x, y):
        qx = abs(x - cx) - hx
        qy = abs(y - cy) - hy
        ox = qx if qx > 0 else 0.0
        oy = qy if qy > 0 else 0.0
        ins = qx if qx > qy else qy
        ins = ins if ins < 0 else 0.0
        return _ui_math.hypot(ox, oy) + ins - r
    return f


def _ui_render_button(W, H, r, top, bottom=None, shadow=False):
    """Anti-aliased rounded button face (optional vertical gradient/shadow)."""
    cv = _UICanvas(W, H)
    t = _ui_hex(top)
    b = _ui_hex(bottom) if bottom else t
    yb = H - (3 if shadow else 0)
    if shadow:
        cv.paint(_sd_rbox(1.0, 3.0, W - 1.0, H - 0.3, r), (15, 23, 42), 0.18)
    if bottom:
        col = lambda x, y: _ui_mix(t, b, max(0.0, min(1.0, y / max(1.0, float(yb)))))
    else:
        col = t
    cv.paint(_sd_rbox(0.5, 0.5, W - 0.5, yb - 0.5, r), col)
    return cv.png()


def _ui_btn_img(w, W, H, fill):
    f = str(fill).lower()
    if f == C['surface2'].lower():          # disabled: soft grey like btn.png
        f = '#%02x%02x%02x' % tuple(int(v) for v in _ui_mix(_ui_hex(C['surface2']), _ui_hex(C['surface3']), 0.55))
    r = min(12, H // 2)
    return _ui_photo(w, ('btn', W, H, r, f), lambda: _ui_render_button(W, H, r, f))


def _ui_install_hooks_v3():
    import tkinter as _tk
    if getattr(_tk.Canvas, '_ui_poly_hooked', False):
        return
    o_cp = _tk.Canvas.create_polygon

    def create_polygon(self, *a, **kw):
        # the app's rounded buttons are 8-point smoothed polygons, which Tk
        # draws as lumpy blobs; draw a true anti-aliased rounded rect instead
        try:
            if getattr(self, '_ui_smooth_btn', False) and kw.get('smooth'):
                co = _ui_flat(a)
                fill = kw.get('fill') or ''
                if len(co) == 16 and fill:
                    xs, ys = co[0::2], co[1::2]
                    x0, y0 = min(xs), min(ys)
                    W, H = int(round(max(xs) - x0)), int(round(max(ys) - y0))
                    if W > 10 and H > 10:
                        return self.create_image(int(x0), int(y0), anchor='nw',
                                                 image=_ui_btn_img(self, W, H, fill))
        except Exception:
            pass
        return o_cp(self, *a, **kw)
    _tk.Canvas.create_polygon = create_polygon
    _tk.Canvas._ui_poly_hooked = True


_ui_install_hooks_v3()


# ------------------------------------------ Configuration panels (d0)
_UI_BROWSER_ROWS = ('Navigateurs cachés', 'Variation humaine', 'Posts Anonymes',
                    'Navigateurs simultanés', 'Chien de garde')
_UI_TOR_ROWS = ('Réseau Tor', 'Proxys par compte')


def _ui_title(parent, src):
    """Section heading identical to the app's own (label + accent rule)."""
    import tkinter as _tk
    F = 'Segoe UI'
    f = _tk.Frame(parent, bg=C['bg'])
    _tk.Label(f, text=src, font=(F, 11, 'bold'), bg=C['bg'], fg=C['accent_lt']).pack(side=_tk.LEFT)
    lf = _tk.Frame(f, bg=C['bg'])
    lf.pack(side=_tk.LEFT, fill=_tk.X, expand=True, padx=(12, 0))
    _tk.Frame(lf, bg=C['accent'], height=1).pack(fill=_tk.X)
    _tk.Frame(lf, bg=C['g_ind_1'], height=1).pack(fill=_tk.X)
    return f


def _ui_build_config3(self):
    """Split the campaign form into three cards — Configuration, Browser
    settings, Tor & proxies — by re-homing the existing row widgets with
    grid(in_=card). Nothing is re-created, so every variable, command and
    reference the app holds keeps working."""
    import tkinter as _tk
    S = self._sections.get('campagne')
    if S is None:
        return False
    cfg_inner = None
    for w in _ui_walk(S):
        try:
            if w.winfo_class() == 'Frame' and any(
                    getattr(s, '_i18n_src', None) == 'Cible' for s in w.grid_slaves()):
                cfg_inner = w
                break
        except Exception:
            pass
    if cfg_inner is None:
        return False
    cfg_card = cfg_inner.master
    kids = S.pack_slaves()
    if cfg_card.master is not S or cfg_card not in kids:
        return False
    i = kids.index(cfg_card)
    after = kids[i + 1:]
    if i < 1 or len(after) < 2:
        return False
    t_cfg, t_wm, wm_card = kids[i - 1], after[0], after[1]

    # group the form's grid rows: a labelled row + the unlabelled rows under it
    rows = {}
    for idx, s in enumerate(reversed(cfg_inner.grid_slaves())):
        gi = s.grid_info()
        try:
            r, c, sp = int(gi['row']), int(gi['column']), int(gi.get('columnspan', 1))
        except Exception:
            return False
        rows.setdefault(r, []).append((c, sp, idx, s, gi))

    def label_of(r):
        for c, sp, idx, s, gi in rows[r]:
            if c == 0 and sp == 1 and s.winfo_class() == 'Label':
                return getattr(s, '_i18n_src', None) or '?'
        return None
    groups, cur = [], None
    ram = getattr(self, '_ram_lbl', None)
    for r in sorted(rows):
        lab = label_of(r)
        items = rows[r]
        if lab is not None:
            cur = [lab, [r]]
            groups.append(cur)
        elif any(sp == 2 for c, sp, idx, s, gi in items):
            groups.append(['__span__', [r]])
            cur = None
        elif ram is not None and any(s is ram for c, sp, idx, s, gi in items):
            groups.append(['__ram__', [r]])
            cur = None
        elif cur is not None:
            cur[1].append(r)
        else:
            groups.append(['__misc__', [r]])
    cfg_g, br_g, tor_g, span_g = [], {}, [], []
    for g in groups:
        if g[0] in _UI_BROWSER_ROWS:
            br_g[g[0]] = g
        elif g[0] in _UI_TOR_ROWS or g[0] == '__ram__':
            tor_g.append(g)
        elif g[0] == '__span__':
            span_g.append(g)
        else:
            cfg_g.append(g)
    if not br_g or not tor_g:
        return False
    # the drag & drop hint belongs right under the CSV files field
    ci = next((k for k, g in enumerate(cfg_g) if g[0] == 'Fichiers CSV / XLSX'), None)
    for g in span_g:
        if ci is None:
            cfg_g.append(g)
        else:
            ci += 1
            cfg_g.insert(ci, g)
    br_list = [br_g[k] for k in _UI_BROWSER_ROWS if k in br_g]

    def mkpanel():
        p = _tk.Frame(cfg_inner, bg=C['surface'], padx=20, pady=16, highlightthickness=1,
                      highlightbackground=C['border'], highlightcolor=C['border'])
        p.columnconfigure(0, weight=1)
        p.columnconfigure(1, weight=0)
        return p

    moved = []

    def fill(panel, glist):
        r = 0
        for g in glist:
            for rn in g[1]:
                items = sorted(rows[rn], key=lambda t: ((0 if t[0] == 0 and t[1] == 1
                                                         else (1 if t[0] == 0 else 2)), t[2]))
                for c, sp, idx, s, gi in items:
                    if c == 0 and sp == 1:
                        s.grid(in_=panel, row=r, column=0, columnspan=2, sticky='w',
                               padx=0, pady=((14 if r else 0), 5))
                    elif c == 0:
                        s.grid(in_=panel, row=r, column=0, columnspan=2, padx=0,
                               pady=(10, 2), sticky=(gi.get('sticky') or 'we'))
                    else:
                        s.grid(in_=panel, row=r, column=0, columnspan=2, padx=0,
                               pady=(0, 2), sticky=(gi.get('sticky') or 'w'))
                    moved.append(s)
                    r += 1
    p_cfg, p_br, p_tor = mkpanel(), mkpanel(), mkpanel()
    fill(p_cfg, cfg_g)
    fill(p_br, br_list)
    fill(p_tor, tor_g)
    for s in moved:                  # rows must sit above their new card
        try:
            s.lift()
        except Exception:
            pass
    # compact proxy-format help so the Tor card stays short (as in d0)
    for s in moved:
        for w in _ui_walk(s):
            try:
                if (w.winfo_class() == 'Label'
                        and str(getattr(w, '_i18n_src', '') or '').startswith('Formats accept')):
                    w.configure(font=('Consolas', 8), padx=8, pady=6)
            except Exception:
                pass
    t_br = _ui_title(cfg_inner, 'Paramètres des navigateurs')
    t_tor = _ui_title(cfg_inner, 'Réseau Tor & proxys')
    # the old card + inner frame become an invisible full-size canvas
    cfg_card.pack_forget()
    cfg_card.place(x=0, y=0, relwidth=1, relheight=1)
    _ui_raw_conf(cfg_card, bg=C['bg'], highlightthickness=0, bd=0)
    cfg_inner.pack_forget()
    cfg_inner.place(x=0, y=0, relwidth=1, relheight=1)
    _ui_raw_conf(cfg_inner, bg=C['bg'], padx=0, pady=0, bd=0, highlightthickness=0)
    cfg_inner.columnconfigure(0, weight=0, minsize=0)
    cfg_inner.columnconfigure(1, weight=0, minsize=0)
    for w in (t_cfg, t_wm, wm_card):
        w.pack_forget()
        w.lift()
    _ui_raw_conf(wm_card, highlightthickness=1, highlightbackground=C['border'],
                 highlightcolor=C['border'])
    self._ui_cfg3 = {'blocks': _UIOrderedDict([('cfg', (t_cfg, p_cfg)), ('wm', (t_wm, wm_card)),
                                                ('tor', (t_tor, p_tor)), ('br', (t_br, p_br))])}
    self._ui_cfg3_cards = [p_cfg, p_br, p_tor, wm_card]
    for p in self._ui_cfg3_cards:
        try:
            p.bind('<Configure>', lambda e: self._ui_request_relayout(), add='+')
        except Exception:
            pass
    return True


# ------------------------------------------- sidebar: btn.png + links
_UI_LINKS = (('Site des bons plans', 'https://mavelylink.com/', '\u2197'),
             ('Acheter une licence', 'https://mavlink.click/', '\u2605'))


def _ui_open_url(url):
    try:
        import webbrowser
        if webbrowser.open_new_tab(url):
            return True
    except Exception:
        pass
    try:
        if sys.platform == 'win32':
            os.startfile(url)
            return True
    except Exception:
        pass
    return False


def _ui_install_links(self):
    """'Site For Deals' / 'Buy License' at the bottom of the sidebar."""
    import tkinter as _tk
    try:
        sidebar = self.start_btn.master.master.master     # sb_btn_f > action_bot > sidebar
        if int(sidebar.cget('width')) < 150:
            return
    except Exception:
        return
    F = 'Segoe UI'
    box = _tk.Frame(sidebar, bg=C['surface'], padx=16)
    box.pack(side=_tk.BOTTOM, fill=_tk.X, pady=(0, 14))
    self._ui_links = []
    W, H = 190, 44
    for src, url, icon in _UI_LINKS:
        cv = _tk.Canvas(box, width=W, height=H, bg=C['surface'], highlightthickness=0,
                        cursor='hand2')
        cv.pack(pady=(0, 8))

        def draw(state='idle', cv=cv, src=src, icon=icon):
            try:
                cv.delete('all')
                top, bot = '#7c3aed', '#6d28d9'
                if state == 'hover':
                    top, bot = '#6d28d9', '#5b21b6'
                img = _ui_photo(cv, ('link', W, H, top, bot, state),
                                lambda: _ui_render_button(W, H, 12, top, bot, shadow=True))
                cv.create_image(0, 0, anchor='nw', image=img)
                cv.create_text(W // 2, (H - 3) // 2, text='%s  %s' % (icon, _TR(src)),
                               font=(F, 10, 'bold'), fill='white')
            except Exception:
                pass
        cv.bind('<Enter>', lambda e, d=draw: d('hover'))
        cv.bind('<Leave>', lambda e, d=draw: d('idle'))
        cv.bind('<Button-1>', lambda e, u=url: _ui_open_url(u))
        cv._ui_draw = draw
        cv._ui_url = url
        draw()
        self._ui_links.append(cv)


def _ui_redraw_links(self):
    for cv in getattr(self, '_ui_links', []) or []:
        try:
            cv._ui_draw()
        except Exception:
            pass


FacebookMultiPosterApp._ui_redraw_links = _ui_redraw_links


