def _ui_render_dropdown(S, up=False):
    """Blue rounded square with a white outlined triangle (user's icon)."""
    cv = _UICanvas(S, S)
    top, bot = (28, 145, 249), (16, 69, 217)
    cv.paint(_sd_rbox(0.5, 0.5, S - 0.5, S - 0.5, S * 0.2),
             lambda x, y: _ui_mix(top, bot, max(0.0, min(1.0, y / float(S)))))
    yt, yb = (0.34 * S, 0.72 * S) if not up else (0.66 * S, 0.28 * S)
    a, b, c = (0.21 * S, yt), (0.79 * S, yt), (0.5 * S, yb)
    h = max(0.7, S * 0.03)
    cv.paint(_sd_union(_sd_capsule(a[0], a[1], b[0], b[1], h),
                       _sd_capsule(b[0], b[1], c[0], c[1], h),
                       _sd_capsule(c[0], c[1], a[0], a[1], h)), (255, 255, 255))
    return cv.png()


def _ui_render_openlist(S, grey=False):
    """Green square with an outward arrow (user's open-list icon)."""
    cv = _UICanvas(S, S)
    k = S / 29.0
    edge, fill, col = ((62, 173, 1), (84, 236, 0), (48, 135, 1)) if not grey else \
        ((170, 176, 186), (214, 218, 225), (150, 156, 166))
    cv.paint(_sd_rbox(0.5 * k, 3.5 * k, 24.5 * k, 28.5 * k, 1.4 * k), edge)
    cv.paint(_sd_rbox(2.0 * k, 5.0 * k, 23.0 * k, 27.0 * k, 0.8 * k), fill)
    h = max(0.8, 1.1 * k)
    cv.paint(_sd_union(_sd_capsule(12.5 * k, 16.0 * k, 27.0 * k, 2.0 * k, h),
                       _sd_capsule(27.0 * k, 2.0 * k, 19.5 * k, 2.0 * k, h),
                       _sd_capsule(27.0 * k, 2.0 * k, 27.0 * k, 9.5 * k, h)), col)
    return cv.png()


def _ui_icon(w, kind, base, up=False):
    S = max(10, int(round(base * _UI_ZOOM[0])))
    if kind == 'dropdown':
        return _ui_photo(w, ('dd', S, up), lambda: _ui_render_dropdown(S, up))
    if kind == 'openbrowser':
        return _ui_photo(w, ('ob', S), lambda: _ui_render_openbrowser(S))
    if kind == 'openlist_off':
        return _ui_photo(w, ('olx', S), lambda: _ui_render_openlist(S, grey=True))
    return _ui_photo(w, ('ol', S), lambda: _ui_render_openlist(S))


def _ui_refresh_icons(self):
    for lab, kind, base, upf in list(getattr(self, '_ui_icon_widgets', []) or []):
        try:
            _ui_raw_conf(lab, image=_ui_icon(lab, kind, base, upf() if upf else False))
        except Exception:
            pass


FacebookMultiPosterApp._ui_refresh_icons = _ui_refresh_icons


def _ui_add_icon(self, lab, kind, base, upf=None):
    if not hasattr(self, '_ui_icon_widgets'):
        self._ui_icon_widgets = []
    self._ui_icon_widgets.append((lab, kind, base, upf))


# ------------------------------------------------ Browser settings (p1)
_UI_BR_LEFT = ('Navigateurs cachés', '__grid__', 'Navigateurs simultanés')
_UI_BR_RIGHT = ('Variation humaine', 'Chien de garde', 'Posts Anonymes')


def _ui_build_br_columns(self):
    import tkinter as _tk
    c3 = self._ui_cfg3
    p_br = c3['blocks']['br'][1]
    groups, cur = {}, None
    for w in sorted(p_br.grid_slaves(), key=lambda x: int(x.grid_info()['row'])):
        src = getattr(w, '_i18n_src', None) if w.winfo_class() == 'Label' else None
        if src in _UI_BROWSER_ROWS:
            cur = groups.setdefault(src, [])
        if cur is not None:
            cur.append(w)
    cols = []
    for keys in (_UI_BR_LEFT, _UI_BR_RIGHT):
        col = _tk.Frame(p_br, bg=C['surface'])
        col.columnconfigure(0, weight=1)
        r = 0
        for k in keys:
            if k == '__grid__':                  # slot for "Visible Browsers Grid Tabs"
                c3['br_grid_slot'] = (col, r)
                r += 3
                continue
            for i, w in enumerate(groups.get(k, [])):
                st = w.grid_info().get('sticky') or 'w'
                if i == 0:
                    w.grid(in_=col, row=r, column=0, columnspan=1, sticky='w', padx=0,
                           pady=((14 if r else 0), 5))
                else:
                    w.grid(in_=col, row=r, column=0, columnspan=1, sticky=st, padx=0, pady=(0, 2))
                r += 1
        cols.append(col)
    c3['br_cols'] = tuple(cols)
    c3['br_two'] = None
    _ui_br_arrange(self, True)


def _ui_br_arrange(self, two):
    c3 = getattr(self, '_ui_cfg3', None) or {}
    cols = c3.get('br_cols')
    if not cols or c3.get('br_two') == two:
        return
    p_br = c3['blocks']['br'][1]
    left, right = cols
    if two:
        left.grid(row=0, column=0, columnspan=1, sticky='nwe', padx=(0, 22), pady=0)
        right.grid(row=0, column=1, columnspan=1, sticky='nwe', padx=0, pady=0)
        p_br.columnconfigure(0, weight=1, uniform='ui_br')
        p_br.columnconfigure(1, weight=1, uniform='ui_br')
    else:
        left.grid(row=0, column=0, columnspan=2, sticky='nwe', padx=0, pady=0)
        right.grid(row=1, column=0, columnspan=2, sticky='nwe', padx=0, pady=(14, 0))
        p_br.columnconfigure(0, weight=1, uniform='')
        p_br.columnconfigure(1, weight=0, uniform='')
    c3['br_two'] = two


# ------------------------------------------------ Tor card dropdown (p1)
def _ui_build_tor_toggle(self):
    import tkinter as _tk
    F = 'Segoe UI'
    c3 = self._ui_cfg3
    p_tor = c3['blocks']['tor'][1]
    slaves = sorted(p_tor.grid_slaves(), key=lambda x: int(x.grid_info()['row']))
    head = next((w for w in slaves if getattr(w, '_i18n_src', None) == 'Réseau Tor'), None)
    if head is None:
        return
    body = [w for w in slaves if w is not head]
    hdr = _tk.Frame(p_tor, bg=C['surface'])
    head.grid_forget()
    hdr.grid(row=0, column=0, columnspan=2, sticky='we')
    head.pack(in_=hdr, side=_tk.LEFT)
    head.lift()
    pills = []
    for txt, var in (('TOR', getattr(self, 'tor_var', None)),
                     ('PROXY', getattr(self, 'proxy_enabled_var', None))):
        pl = _tk.Label(hdr, text=txt, font=(F, 7, 'bold'), padx=5, pady=1,
                       bg=C['surface3'], fg=C['text3'])
        pl._i18n_src = None
        pl.pack(side=_tk.LEFT, padx=(8, 0))
        pills.append((pl, var))
    icon = _tk.Label(hdr, bg=C['surface'], cursor='hand2', bd=0)
    icon.pack(side=_tk.RIGHT)
    first = body[0] if body else None
    if first is not None:
        try:
            first.grid_configure(pady=(10, 2))
        except Exception:
            pass
    c3['tor'] = {'hdr': hdr, 'head': head, 'body': body, 'icon': icon,
                 'pills': pills, 'open': True}
    _ui_add_icon(self, icon, 'dropdown', 30, lambda: bool(c3['tor']['open']))

    def refresh_pills(*_a):
        for pl, var in pills:
            try:
                on = bool(var.get()) if var is not None else False
                _ui_raw_conf(pl, bg=(C['success'] if on else C['surface3']),
                             fg=('white' if on else C['text3']))
            except Exception:
                pass
    c3['tor']['refresh'] = refresh_pills
    for _pl, var in pills:
        try:
            var.trace_add('write', refresh_pills)
        except Exception:
            pass
    refresh_pills()
    for w in (icon, head, hdr):
        w.bind('<Button-1>', lambda e: self._ui_tor_toggle())
    head.configure(cursor='hand2')
    self._ui_tor_toggle(False)


def _ui_tor_toggle(self, open_=None):
    c3 = getattr(self, '_ui_cfg3', None) or {}
    t = c3.get('tor')
    if not t:
        return
    st = (not t['open']) if open_ is None else bool(open_)
    if st == t['open'] and open_ is not None:
        pass
    t['open'] = st
    for w in t['body']:
        try:
            if st:
                w.grid()
            else:
                w.grid_remove()
        except Exception:
            pass
    try:
        _ui_raw_conf(t['icon'], image=_ui_icon(t['icon'], 'dropdown', 30, st))
    except Exception:
        pass
    try:
        self._ui_request_relayout(force=True)
    except Exception:
        pass


FacebookMultiPosterApp._ui_tor_toggle = _ui_tor_toggle


# ------------------------------------------ Configuration arrangement (p1)
#   [Configuration + Watermark] [ Browser settings (2 inner columns) ]
#                               [ Tor & proxies ] [ Working hours   ]
#                               [ Facebook accounts                 ]
_TAB_LAYOUT['config']['mid_share'] = 0.5


def _ui_layout_config3(self, spec, body_w):
    S = self._sections['campagne']
    H = self._sections['horaires']
    A = self._sections['comptes']
    m = _UI_M
    rest = max(spec['right_min'], int(body_w * spec['right_share']))
    lw = body_w - rest
    three = lw >= spec['left_min']
    blocks = self._ui_cfg3['blocks']
    if three:
        mw = int(rest * spec['mid_share'])
        rw = rest - mw
        where = {'cfg': (0, lw), 'wm': (0, lw), 'br': (lw, rest), 'tor': (lw, mw)}
        hx, hw = lw + mw, rw
    else:
        where = dict((k, (0, body_w)) for k in blocks)
        hx, hw = 0, body_w
    _ui_br_arrange(self, (where['br'][1] - 2 * m - 42) >= 600)

    def put_block(name, x, y, w):
        t, p = blocks[name]
        th = t.winfo_reqheight()
        t.place(x=x + m, y=y + 22, width=max(10, w - 2 * m))
        p.place(x=x + m, y=y + 22 + th + 10, width=max(10, w - 2 * m))
        return 22 + th + 10 + p.winfo_reqheight() + 10

    S.place(x=0, y=0, width=body_w, height=max(10, S.winfo_height()))
    for name in blocks:
        put_block(name, where[name][0], 0, where[name][1])
    H.place(x=hx, y=0, width=hw)
    A.place(x=(lw if three else 0), y=0, width=(rest if three else body_w))
    _ui_fit_boxes(self, [H, A] + [p for (_t, p) in blocks.values()])
    if three:
        yl = put_block('cfg', 0, 0, lw)
        yl += put_block('wm', 0, yl, lw)
        yb = put_block('br', lw, 0, rest)
        ht = put_block('tor', lw, yb, mw)
        H.place(x=hx, y=yb, width=hw)
        ya = yb + max(ht, H.winfo_reqheight() + _GRID_GAP)
        A.place(x=lw, y=ya, width=rest)
        total = max(yl, ya + A.winfo_reqheight())
    else:
        y = 0
        A.place(x=0, y=y, width=body_w)
        y += A.winfo_reqheight() + _GRID_GAP
        H.place(x=0, y=y, width=body_w)
        y += H.winfo_reqheight() + _GRID_GAP
        for name in ('cfg', 'br', 'tor', 'wm'):
            y += put_block(name, 0, y, body_w)
        total = y
    S.place(x=0, y=0, width=body_w, height=max(10, total))
    for w in (H, A):
        try:
            w.lift()
        except Exception:
            pass
    self._ui_two_cols = three
    return total


# ---------------------------------------- Automatic mode rows (p2)
def _ui_row_card(sec):
    """The main card of a section (last packed child painted as a card)."""
    try:
        cards = [c for c in sec.pack_slaves()
                 if c.winfo_class() == 'Frame' and (c.cget('bg') or '').lower() == C['surface'].lower()]
        return cards[-1] if cards else None
    except Exception:
        return None


def _ui_layout_rows(self, spec, body_w):
    lmin, rmin = spec['min']
    two = body_w >= lmin + rmin
    lw = max(lmin, int(body_w * spec['ratio'])) if two else body_w
    rw = body_w - lw if two else body_w
    secs = dict(_ui_sections_of(self, self._current_tab))
    for n, fr in secs.items():                 # cards stretch to the row height
        card = _ui_row_card(fr)
        if card is not None and not getattr(card, '_ui_stretch', False):
            try:
                card.pack_configure(fill='both', expand=True)
                card._ui_stretch = True
            except Exception:
                pass
    for n, fr in secs.items():
        fr.place(x=0, y=0, width=(lw if two else body_w), height='')
    for (ln, rn) in spec['rows']:
        if two and rn in secs:
            secs[rn].place(x=lw, y=0, width=rw, height='')
    _ui_fit_boxes(self, list(secs.values()))
    y = 0
    if two:
        for (ln, rn) in spec['rows']:
            h = max([secs[n].winfo_reqheight() for n in (ln, rn) if n in secs] or [0])
            if ln in secs:
                secs[ln].place(x=0, y=y, width=lw, height=h)
            if rn in secs:
                secs[rn].place(x=lw, y=y, width=rw, height=h)
            y += h + _GRID_GAP
    else:
        for n in spec['sections']:
            if n in secs:
                secs[n].place(x=0, y=y, width=body_w, height='')
                y += secs[n].winfo_reqheight() + _GRID_GAP
    self._ui_two_cols = two
    return y


# --------------------------------------------- open-list editor (p2)
def _ui_close_editor(self):
    ed = getattr(self, '_ui_editor', None)
    self._ui_editor = None
    if ed is not None:
        try:
            ed.destroy()
        except Exception:
            pass


def _ui_find(root, pred):
    for w in _ui_walk(root):
        try:
            if pred(w):
                return w
        except Exception:
            pass
    return None


def _ui_invoke(btn):
    """Press one of the app's buttons even while its section is locked
    (internal housekeeping only); the lock is restored right after."""
    st = str(btn.cget('state'))
    if st == 'disabled':
        btn.configure(state='normal')
    try:
        return btn.invoke()
    finally:
        if st == 'disabled':
            try:
                btn.configure(state='disabled')
            except Exception:
                pass


def _ui_invoke_row_delete(list_frame):
    """Press the app's own ✕ button on the first row of a list."""
    for row in list_frame.winfo_children():
        for b in row.winfo_children():
            try:
                if b.winfo_class() == 'Button' and str(b.cget('text')).strip() == '✕':
                    _ui_invoke(b)
                    return True
            except Exception:
                pass
    return False


def _ui_apply_urls(self, lines):
    new, skipped = [], 0
    for l in lines:
        u = l.strip()
        if not u:
            continue
        if u.startswith(('http://', 'https://')):
            if u not in new:
                new.append(u)
        else:
            skipped += 1
    t = self._ui_targets.get('urls') or {}
    lst = self.group_urls_list
    if new == lst:
        return skipped
    if not new:
        if lst:
            lst[:] = lst[:1]
            if not _ui_invoke_row_delete(self._url_list_frame):
                lst[:] = []
        return skipped
    lst[:] = new[:-1]
    e = t['entry']
    e.delete(0, 'end')
    e.insert(0, new[-1])
    t['add'].invoke()                      # the app's own "+ Add" path
    return skipped


def _ui_apply_csv(self, lines):
    new, skipped = [], 0
    have = set(self.csv_paths_list)
    for l in lines:
        p = l.strip().strip('"').strip("'").strip('{}')
        if not p:
            continue
        if (p in have or (os.path.isfile(p) and p.lower().endswith(('.csv', '.xlsx')))):
            if p not in new:
                new.append(p)
        else:
            skipped += 1
    t = self._ui_targets.get('csv') or {}
    lst = self.csv_paths_list
    if new == lst:
        return skipped
    if not new:
        if lst:
            lst[:] = lst[:1]
            if not _ui_invoke_row_delete(self._csv_list_frame):
                lst[:] = []                      # no row drawn: clear directly
        return skipped
    lst[:] = new[:-1]
    orig = filedialog.askopenfilename
    try:                                   # the app's own Browse path
        filedialog.askopenfilename = lambda *a, **k: new[-1]
        _ui_invoke(t['browse'])
    finally:
        filedialog.askopenfilename = orig
    return skipped


def _ui_open_editor(self, key):
    """Floating 'paste box' for a list field (links, users, text)."""
    import tkinter as _tk
    t = (getattr(self, '_ui_targets', {}) or {}).get(key)
    if not t:
        return
    if key in ('zip', 'csv') and getattr(self, '_ui_src_parts', None) and _ui_source(self) != key:
        return                                       # this posting source is locked
    self._ui_close_editor()
    F = 'Segoe UI'
    root = self.root
    z = _UI_ZOOM[0]
    card = _tk.Frame(root, bg=C['surface'], highlightthickness=1,
                     highlightbackground=C['border2'], highlightcolor=C['border2'],
                     padx=16, pady=14)
    self._ui_editor = card
    hdr = _tk.Frame(card, bg=C['surface'])
    hdr.pack(fill=_tk.X)
    title = _TR(t['title']).strip().rstrip(':').strip()
    tl = _tk.Label(hdr, text=title, font=(F, 11, 'bold'), bg=C['surface'], fg=C['text'],
                   anchor='w', justify='left')
    tl._i18n_src = None
    tl.pack(side=_tk.LEFT, fill=_tk.X, expand=True)
    x = _tk.Label(hdr, text='✕', font=(F, 11), bg=C['surface'], fg=C['text2'],
                  cursor='hand2', padx=6)
    x._i18n_src = None
    x.pack(side=_tk.RIGHT)
    x.bind('<Button-1>', lambda e: self._ui_close_editor())
    _tk.Label(card, text='Une entrée par ligne — collez vos liens, utilisateurs ou textes',
              font=(F, 9), bg=C['surface'], fg=C['text3'], anchor='w',
              justify='left').pack(fill=_tk.X, pady=(2, 8))
    foot = _tk.Frame(card, bg=C['surface'])          # footer first, pinned
    foot.pack(side=_tk.BOTTOM, fill=_tk.X, pady=(10, 0))  # to the bottom
    tf = _tk.Frame(card, bg=C['border'], padx=1, pady=1)
    tf.pack(fill=_tk.BOTH, expand=True)
    txt = _tk.Text(tf, font=('Consolas', 10), bg=C['surface2'], fg=C['text'],
                   insertbackground=C['accent'], relief='flat', bd=8, wrap='none', undo=True,
                   highlightthickness=0, height=6, width=30)
    sb = _tk.Scrollbar(tf, command=txt.yview)
    txt.configure(yscrollcommand=sb.set)
    sb.pack(side=_tk.RIGHT, fill=_tk.Y)
    txt.pack(side=_tk.LEFT, fill=_tk.BOTH, expand=True)
    status = _tk.Label(foot, text='', font=(F, 9), bg=C['surface'], fg=C['text3'])
    status.pack(side=_tk.LEFT)
    kind = t['kind']
    if kind == 'text':
        init = t['widget'].get('1.0', 'end-1c')
    elif kind == 'urls':
        init = '\n'.join(self.group_urls_list)
    elif kind == 'csv':
        init = '\n'.join(self.csv_paths_list)
    elif kind == 'zip':
        init = '\n'.join(it[0] for it in (getattr(self, '_ui_zip_items', []) or []))
    else:
        init = t['var'].get()
    txt.insert('1.0', init)

    def count(_e=None):
        n = sum(1 for l in txt.get('1.0', 'end-1c').splitlines() if l.strip())
        _ui_raw_conf(status, text=_TR('%d ligne(s)' % n), fg=C['text3'])

    def close(_e=None):
        self._ui_close_editor()
        return 'break'

    def apply(_e=None):
        raw = txt.get('1.0', 'end-1c')
        lines = raw.splitlines()
        skipped = 0
        try:
            if kind == 'text':
                w = t['widget']
                st = str(w.cget('state'))
                if st == 'disabled':
                    w.configure(state='normal')
                w.delete('1.0', 'end')
                w.insert('1.0', '\n'.join(l.rstrip() for l in lines).strip('\n'))
                if st == 'disabled':
                    w.configure(state='disabled')
            elif kind == 'urls':
                skipped = _ui_apply_urls(self, lines)
            elif kind == 'csv':
                skipped = _ui_apply_csv(self, lines)
            elif kind == 'zip':
                skipped = _ui_apply_zip(self, lines)
            else:
                t['var'].set(next((l.strip() for l in lines if l.strip()), ''))
        except Exception:
            skipped = -1
        if skipped:
            msg = _TR('%d ligne(s) ignorée(s)' % max(0, skipped)) if skipped > 0 else '⚠'
            _ui_raw_conf(status, text=msg, fg=C['danger'])
            return 'break'
        self._ui_close_editor()
        return 'break'

    def paste():
        try:
            clip = root.clipboard_get()
        except Exception:
            clip = ''
        if clip:
            txt.insert('insert', clip)
            count()

    def clear():
        txt.delete('1.0', 'end')
        count()
    for label, cmd, bg, fg in (('Appliquer', apply, C['accent'], 'white'),
                               ('Annuler', close, C['surface3'], C['text']),
                               ('Effacer', clear, C['surface3'], C['text']),
                               ('Coller', paste, C['surface3'], C['text'])):
        b = _tk.Button(foot, text=label, font=(F, 9, 'bold'), bg=bg, fg=fg, relief='flat',
                       bd=0, padx=14, pady=6, cursor='hand2', activebackground=C['accent2'],
                       activeforeground='white', command=cmd)
        b.pack(side=_tk.RIGHT, padx=(6, 0))
    txt.bind('<KeyRelease>', count)
    txt.bind('<Escape>', close)
    txt.bind('<Control-Return>', apply)
    card.bind('<Escape>', close)
    count()
    try:
        root.update_idletasks()
        W = min(int(600 * z), max(260, root.winfo_width() - 40))
        H = min(int(420 * z), max(200, root.winfo_height() - 60))
    except Exception:
        W, H = 600, 420
    card.place(relx=0.5, rely=0.5, anchor='center', width=W, height=H)
    card.lift()
    txt.focus_set()
    card._ui_text = txt
    card._ui_apply = apply
    card._ui_status = status
    return card


FacebookMultiPosterApp._ui_close_editor = _ui_close_editor
FacebookMultiPosterApp._ui_open_editor = _ui_open_editor


def _ui_install_list_icons(self):
    """Green open-list icon inside every list / link field."""
    import tkinter as _tk
    self._ui_targets = {}

    def entry_icon(entry, key):
        par = entry.master
        lab = _tk.Label(par, image=_ui_icon(par, 'openlist', 20), bd=0,
                        bg=entry.cget('bg'), cursor='hand2')
        lab.pack(side=_tk.RIGHT, before=entry, padx=(0, 6))
        lab.bind('<Button-1>', lambda e: self._ui_open_editor(key))
        _ui_add_icon(self, lab, 'openlist', 20)
        return lab

    def text_icon(text, key):
        par = text.master
        lab = _tk.Label(par, image=_ui_icon(par, 'openlist', 22), bd=0,
                        bg=text.cget('bg'), cursor='hand2')
        lab.place(in_=text, relx=1.0, rely=1.0, x=-4, y=-4, anchor='se')
        lab.bind('<Button-1>', lambda e: self._ui_open_editor(key))
        _ui_add_icon(self, lab, 'openlist', 22)
        return lab
    # Configuration: group/page URLs
    try:
        mgr = self._url_list_frame.master
        row = mgr.pack_slaves()[0]
        add = _ui_find(row, lambda w: w.winfo_class() == 'Button'
                       and getattr(w, '_i18n_src', None) == '+ Ajouter')
        ent = _ui_find(row, lambda w: w.winfo_class() == 'Entry')
        if add is not None and ent is not None:
            self._ui_targets['urls'] = {'kind': 'urls', 'entry': ent, 'add': add,
                                        'title': 'URLs des groupes/pages'}
            entry_icon(ent, 'urls')
    except Exception:
        pass
    # Configuration: CSV / XLSX files
    try:
        pc = self._ui_cfg3['blocks']['cfg'][1]
        sl = sorted(pc.grid_slaves(), key=lambda x: int(x.grid_info()['row']))
        i = next(k for k, w in enumerate(sl) if getattr(w, '_i18n_src', None) == 'Fichiers CSV / XLSX')
        fr = sl[i + 1]
        br = _ui_find(fr, lambda w: w.winfo_class() == 'Button'
                      and getattr(w, '_i18n_src', None) == 'Parcourir')
        ent = _ui_find(fr, lambda w: w.winfo_class() == 'Entry')
        if br is not None and ent is not None:
            self._ui_targets['csv'] = {'kind': 'csv', 'browse': br, 'entry': ent,
                                       'title': 'Fichiers CSV / XLSX'}
            self._ui_targets['csv']['icon'] = entry_icon(ent, 'csv')
    except Exception:
        pass
    # Automatic mode: the four multi-line lists
    for key, attr, title, lines in (
            ('sc', '_sc_text', 'Groupes à surveiller — une URL par ligne :', 4),
            ('cm', '_cm_text', 'Groupes à commenter — une URL par ligne :', 2),
            ('cmc', '_cm_comments', 'Commentaires — un par ligne :', 2),
            ('jg', '_jg_text', 'URLs des groupes (une par ligne) :', 2)):
        w = getattr(self, attr, None)
        if w is None:
            continue
        try:
            _ui_raw_conf(w, height=lines)         # compact: the editor holds the rest
            self._ui_targets[key] = {'kind': 'text', 'widget': w, 'title': title}
            text_icon(w, key)
        except Exception:
            pass
    # Auto like: group or page URL
    try:
        vname = str(self._lk_url_var)
        ent = _ui_find(self._sections['liker'], lambda w: w.winfo_class() == 'Entry'
                       and str(w.cget('textvariable')) == vname)
        if ent is not None:
            self._ui_targets['lk'] = {'kind': 'entry', 'var': self._lk_url_var,
                                      'title': 'URL du groupe ou de la page :'}
            entry_icon(ent, 'lk')
    except Exception:
        pass


