_ui_orig_post_build_v3 = FacebookMultiPosterApp._ui_post_build


def _ui_post_build4(self):
    _ui_orig_post_build_v3(self)
    if getattr(self, '_ui_cfg3', None):
        try:
            _ui_build_br_columns(self)
        except Exception:
            pass
        try:
            _ui_build_tor_toggle(self)
        except Exception:
            pass
    try:
        _ui_install_list_icons(self)
    except Exception:
        pass
    # any content growth inside a grid-tab section re-flows the grid
    try:
        tag = 'APUIRelayout'
        self.root.bind_class(tag, '<Configure>',
                             lambda e: (globals().get('_CURRENT_APP') is not None
                                        and globals()['_CURRENT_APP']._ui_request_relayout()),
                             add='+')
        for n in ('collecte', 'commenter', 'rejoindre', 'liker', 'horaires', 'comptes'):
            sec = self._sections.get(n)
            if sec is None:
                continue
            for w in _ui_walk(sec):
                if w.winfo_class() == 'Frame':
                    tags = w.bindtags()
                    if tag not in tags:
                        w.bindtags(tags + (tag,))
    except Exception:
        pass


