# ======================================================================
# >>> UI v5 — Visible browsers grid (1 → 4×4) · visible commenting ·
#     ZIP import (image + description.txt + comment.txt)
# ======================================================================
import threading as _ui_threading

_UI_GRID = {
    'lock': _ui_threading.Lock(),
    'slots': {},                   # feature -> {user_data_dir: tile index}
    'region': None,                # (x, y, w, h) physical px, refreshed on the Tk thread
    'scale': 1.0,                  # system DPI scale (1.0 = 96 dpi)
    'headless': True,              # cached "Hidden browsers" value (Tk thread)
    'cm_visible': False,           # cached "Browser visible during commenting"
    'on': {'global': False, 'auto': False, 'comment': False},
}
_UI_WIN_FLAGS = ('--window-position=', '--window-size=', '--start-maximized',
                 '--start-fullscreen', '--force-device-scale-factor=')


def _ui_grid_cells(n, region):
    """Tiles for n windows: 1 full · 2 side by side · 3 = 2 + 1 wide ·
    4 = 2×2 … 16 = 4×4. A short last row stretches to the full width."""
    x0, y0, W, H = region
    n = max(1, min(16, int(n)))
    cols = int(_ui_math.ceil(_ui_math.sqrt(n)))
    rows = int(_ui_math.ceil(n / float(cols)))
    cells = []
    for r in range(rows):
        cnt = cols if r < rows - 1 else n - cols * (rows - 1)
        y1 = y0 + (H * r) // rows
        y2 = y0 + (H * (r + 1)) // rows
        for c in range(cnt):
            x1 = x0 + (W * c) // cnt
            x2 = x0 + (W * (c + 1)) // cnt
            cells.append((x1, y1, x2 - x1, y2 - y1))
    return cells


def _ui_grid_feature(caller, app):
    if caller == '_cm_run':
        return 'comment'
    if caller == '_sc_open_ctx':
        return 'auto'
    if caller == '_open_browser_for_slot':
        return 'auto' if getattr(app, '_sc_running', False) else 'post'
    if caller == '_join_groups_thread':
        return 'join'
    if caller == '_auto_like_thread':
        return 'like'
    return 'other'                 # login / manual windows / headless checks


def _ui_grid_on_for(feat):
    on = _UI_GRID['on']
    if feat in ('post', 'join', 'like'):
        return bool(on['global'])
    if feat == 'auto':
        return bool(on['global'] or on['auto'])
    if feat == 'comment':
        return bool(on['global'] or on['comment'])
    return False


def _ui_grid_alloc(app, feat, udd):
    """Pick this browser's tile. Posters use their worker number (poster-N)
    and the parallel count; sequential features take the lowest free tile.
    Beyond 16 (or beyond the planned count) a second grid overlays the first."""
    tname = _ui_threading.current_thread().name or ''
    with _UI_GRID['lock']:
        key = None
        if feat in ('post', 'auto') and tname.startswith('poster-'):
            try:
                idx = max(0, int(tname.split('-', 1)[1]) - 1)
            except Exception:
                idx = 0
            try:
                n = max(1, int(getattr(app, '_wd_charge', 1) or 1))
            except Exception:
                n = 1
        else:
            slots = _UI_GRID['slots'].setdefault(feat, {})
            if udd not in slots:
                used = set(slots.values())
                i = 0
                while i in used:
                    i += 1
                slots[udd] = i
            idx = slots[udd]
            n = max(1, len(slots), idx + 1)
            key = (feat, udd)
        per = max(1, min(16, n))
        pos = idx % per
        region = _UI_GRID['region'] or (0, 0, 1366, 768)
        cell = _ui_grid_cells(per, region)[pos]
        scale = float(_UI_GRID.get('scale') or 1.0)
        # Chrome clamps a forced scale factor below 0.5, so never ask for less
        s = max(0.5, min(max(scale, 0.5), cell[2] / 1300.0))
    return cell, s, key


def _ui_grid_release(key):
    if not key:
        return
    with _UI_GRID['lock']:
        slots = _UI_GRID['slots'].get(key[0]) or {}
        slots.pop(key[1], None)


def _ui_grid_args(extra_args, cell, s):
    """Chrome window flags for a tile. Position/size are in DIPs of the
    forced scale factor, so physical px / s puts the window exactly on
    the tile, and the page keeps its full desktop layout, scaled down."""
    args = [a for a in (extra_args or []) if not str(a).startswith(_UI_WIN_FLAGS)]
    x, y, w, h = cell
    args += ['--window-position=%d,%d' % (int(round(x / s)), int(round(y / s))),
             '--window-size=%d,%d' % (max(300, int(round(w / s))), max(200, int(round(h / s)))),
             '--force-device-scale-factor=%.3f' % s]
    return args


def _ui_win_place(app, udd, rect, timeout=10.0):
    """Windows only: snap this profile's Chrome window exactly onto its tile.
    Physical pixels (the app is DPI-aware); the invisible Win10 resize borders
    are compensated so the visible edges of neighbouring tiles touch.
    Pure Win32 in a short-lived thread — never touches Playwright or Tk."""
    if sys.platform != 'win32':
        return

    def run():
        try:
            import ctypes
            import time as _t
            from ctypes import wintypes
            user32 = ctypes.windll.user32
            try:
                dwm = ctypes.windll.dwmapi
            except Exception:
                dwm = None
            proc = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)
            x, y, w, h = [int(v) for v in rect]
            pids, stable, end = set(), 0, _t.time() + timeout
            while _t.time() < end and stable < 2:
                if not pids:
                    try:
                        pids = set(int(p) for p in (app._wd_find_pids(udd) or []))
                    except Exception:
                        pids = set()
                    if not pids:
                        _t.sleep(0.5)
                        continue
                wins = []

                def cb(hwnd, _lp):
                    try:
                        if not user32.IsWindowVisible(hwnd):
                            return True
                        pid = wintypes.DWORD()
                        user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
                        if pid.value not in pids:
                            return True
                        buf = ctypes.create_unicode_buffer(64)
                        user32.GetClassNameW(hwnd, buf, 64)
                        if buf.value != 'Chrome_WidgetWin_1' or user32.GetWindowTextLengthW(hwnd) == 0:
                            return True
                        wins.append(hwnd)
                    except Exception:
                        pass
                    return True
                user32.EnumWindows(proc(cb), 0)
                if not wins:
                    _t.sleep(0.4)
                    continue
                moved = False
                for hwnd in wins:
                    if user32.IsZoomed(hwnd) or user32.IsIconic(hwnd):
                        user32.ShowWindow(hwnd, 9)                       # SW_RESTORE
                    wr = wintypes.RECT()
                    user32.GetWindowRect(hwnd, ctypes.byref(wr))
                    l = t = r = b = 0
                    if dwm is not None:
                        fb = wintypes.RECT()
                        if dwm.DwmGetWindowAttribute(hwnd, 9, ctypes.byref(fb), ctypes.sizeof(fb)) == 0:
                            l, t = fb.left - wr.left, fb.top - wr.top      # EXTENDED_FRAME_BOUNDS
                            r, b = wr.right - fb.right, wr.bottom - fb.bottom
                    tx, ty, tw, th = x - l, y - t, w + l + r, h + t + b
                    if (abs(wr.left - tx) > 2 or abs(wr.top - ty) > 2
                            or abs(wr.right - wr.left - tw) > 2 or abs(wr.bottom - wr.top - th) > 2):
                        user32.SetWindowPos(hwnd, 0, tx, ty, tw, th, 0x0004 | 0x0010)
                        moved = True
                stable = 0 if moved else stable + 1
                _t.sleep(0.4)
        except Exception:
            pass
    _ui_threading.Thread(target=run, daemon=True, name='grid-place').start()


_ui_orig_launch_ctx = FacebookMultiPosterApp._launch_ctx


def _ui_launch_ctx(self, pw, user_data_dir, headless=None, extra_args=None, sid=None, **extra_kw):
    grid_key, gridded, cell = None, False, None
    try:
        feat = _ui_grid_feature(sys._getframe(1).f_code.co_name, self)
        if feat == 'comment' and _UI_GRID['cm_visible']:
            headless = False                       # "Browser visible during commenting"
        eff = headless if headless is not None else _UI_GRID['headless']
        if feat != 'other' and not eff and _ui_grid_on_for(feat):
            cell, s, grid_key = _ui_grid_alloc(self, feat, user_data_dir)
            extra_args = _ui_grid_args(extra_args, cell, s)
            extra_kw.pop('viewport', None)
            extra_kw['no_viewport'] = True         # window size drives the page
            headless = False
            gridded = True
    except Exception:
        grid_key, gridded = None, False
    ctx = _ui_orig_launch_ctx(self, pw, user_data_dir, headless=headless,
                              extra_args=extra_args, sid=sid, **extra_kw)
    if gridded:
        if grid_key is not None:
            try:
                ctx.on('close', lambda *_a, k=grid_key: _ui_grid_release(k))
            except Exception:
                pass
        _ui_win_place(self, user_data_dir, cell)
    return ctx


FacebookMultiPosterApp._launch_ctx = _ui_launch_ctx


# --------------------------------------------- options file (new switches)
def _ui_opts_path():
    return _ui_pref_path('ui_options.json')


def _ui_opts_load():
    try:
        import json
        with open(_ui_opts_path(), encoding='utf-8') as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


_UI_ZIPOPT_SAVE = lambda self: {}


def _ui_opts_save(self):
    try:
        import json
        d = {'grid_global': bool(self._ui_grid_var.get()),
             'grid_auto': bool(self._sc_grid_var.get()),
             'grid_comment': bool(self._cm_grid_var.get()),
             'cm_visible': bool(self._cm_visible_var.get()),
             'zip_items': [list(it) for it in (getattr(self, '_ui_zip_items', []) or [])]}
        try:
            d.update(_UI_ZIPOPT_SAVE(self))
        except Exception:
            pass
        os.makedirs(os.path.dirname(_ui_opts_path()), exist_ok=True)
        with open(_ui_opts_path(), 'w', encoding='utf-8') as f:
            json.dump(d, f, ensure_ascii=False, indent=1)
    except Exception:
        pass


# ------------------------------------------------ grid switches (Tk side)
def _ui_clone_style(src, kind):
    """Options copied from an existing widget so new ones look identical."""
    keys = {'label': ('font', 'bg', 'fg'),
            'check': ('font', 'bg', 'fg', 'activebackground', 'activeforeground')}[kind]
    out = {}
    for k in keys:
        try:
            out[k] = src.cget(k)
        except Exception:
            pass
    return out


def _ui_find_check(root, var):
    name = str(var)
    return _ui_find(root, lambda w: w.winfo_class() == 'Checkbutton'
                    and str(w.cget('variable')) == name)


def _ui_build_grid_switches(self):
    import tkinter as _tk
    F = 'Segoe UI'
    self._ui_grid_var = _tk.BooleanVar(value=False)
    self._sc_grid_var = _tk.BooleanVar(value=False)
    self._cm_grid_var = _tk.BooleanVar(value=False)
    self._cm_visible_var = _tk.BooleanVar(value=False)
    self._ui_grid_widgets = []                 # (key, var, switch, hint, show, hide)
    head_ref = _ui_find_check(self.root, self.headless_var)
    chk_style = _ui_clone_style(head_ref, 'check') if head_ref is not None else {'font': (F, 9)}
    # 1) Browser settings — right column, under "Simultaneous browsers"
    c3 = getattr(self, '_ui_cfg3', None) or {}
    if c3.get('br_cols'):
        col = c3['br_cols'][1]
        lab_ref = next((w for w in col.grid_slaves() if w.winfo_class() == 'Label'
                        and getattr(w, '_i18n_src', None) in _UI_BROWSER_ROWS), None)
        r = max([int(w.grid_info()['row']) for w in col.grid_slaves()] or [0]) + 1
        if c3.get('br_grid_slot'):
            col, r = c3['br_grid_slot']
        lab = _tk.Label(col, text='Grille des navigateurs visibles',
                        **(_ui_clone_style(lab_ref, 'label') if lab_ref is not None
                           else {'font': (F, 9, 'bold'), 'bg': C['surface'], 'fg': C['text']}))
        lab.grid(row=r, column=0, sticky='w', pady=(14, 5))
        sw = _tk.Checkbutton(col, text='Afficher les navigateurs en grille (1 → 4×4)',
                             variable=self._ui_grid_var, **chk_style)
        sw.grid(row=r + 1, column=0, sticky='w')
        hint = _tk.Label(col, text='Désactivez « Navigateurs cachés » pour utiliser la grille',
                         font=(F, 8), bg=C['surface'], fg=C['warning'], anchor='w', justify='left')
        hint.grid(row=r + 2, column=0, sticky='w', pady=(2, 0))
        self._ui_grid_widgets.append(('global', self._ui_grid_var, sw, hint,
                                      hint.grid, hint.grid_remove))
    # 2) Automatic mode — right under "Browser visible during collection"
    ref = _ui_find_check(self._sections.get('collecte') or self.root, self._sc_visible_var)
    if ref is not None:
        row = ref.master
        new = _tk.Frame(row.master, bg=row.cget('bg'))
        try:
            info = row.pack_info()
            new.pack(after=row, anchor=info.get('anchor', 'w'), fill=info.get('fill', 'none'),
                     pady=(2, 2))
        except Exception:
            new.pack(anchor='w')
        st = _ui_clone_style(ref, 'check')
        sw = _tk.Checkbutton(new, text='Grille des navigateurs visibles',
                             variable=self._sc_grid_var, **st)
        sw.pack(side=_tk.LEFT)
        hint = _tk.Label(new, text='Rendez le navigateur visible pour utiliser la grille',
                         font=(F, 8), bg=row.cget('bg'), fg=C['warning'])
        self._ui_grid_widgets.append(('auto', self._sc_grid_var, sw, hint,
                                      lambda h=hint: h.pack(side=_tk.LEFT, padx=(10, 0)),
                                      hint.pack_forget))
    # 3) Comment on groups — visible + grid, just above the Start/Stop buttons
    cm = self._sections.get('commenter')
    start = _ui_find(cm, lambda w: w.winfo_class() == 'Button'
                     and 'Lancer les commentaires' in str(getattr(w, '_i18n_src', '') or '')) if cm else None
    if start is not None:
        btn_row = start.master
        new = _tk.Frame(btn_row.master, bg=btn_row.master.cget('bg'))
        new.pack(before=btn_row, anchor='w', fill='x', pady=(4, 8))
        cref = _ui_find(cm, lambda w: w.winfo_class() == 'Checkbutton')
        st = _ui_clone_style(cref, 'check') if cref is not None else chk_style
        st['bg'] = new.cget('bg')
        st['activebackground'] = new.cget('bg')
        vis = _tk.Checkbutton(new, text='Navigateur visible pendant les commentaires',
                              variable=self._cm_visible_var, **st)
        vis.pack(side=_tk.LEFT, padx=(0, 14))
        sw = _tk.Checkbutton(new, text='Grille des navigateurs visibles',
                             variable=self._cm_grid_var, **st)
        sw.pack(side=_tk.LEFT)
        hint = _tk.Label(new, text='Rendez le navigateur visible pour utiliser la grille',
                         font=(F, 8), bg=new.cget('bg'), fg=C['warning'])
        self._ui_grid_widgets.append(('comment', self._cm_grid_var, sw, hint,
                                      lambda h=hint: h.pack(side=_tk.LEFT, padx=(10, 0)),
                                      hint.pack_forget))
    # saved state
    o = _ui_opts_load()
    self._ui_grid_var.set(bool(o.get('grid_global', False)))
    self._sc_grid_var.set(bool(o.get('grid_auto', False)))
    self._cm_grid_var.set(bool(o.get('grid_comment', False)))
    self._cm_visible_var.set(bool(o.get('cm_visible', False)))
    for v in (self._ui_grid_var, self._sc_grid_var, self._cm_grid_var, self._cm_visible_var,
              self.headless_var, self._sc_visible_var):
        try:
            v.trace_add('write', lambda *_a: self._ui_grid_sync())
        except Exception:
            pass
    self._ui_grid_sync(save=False)
    self._ui_grid_tick()


def _ui_grid_sync(self, save=True):
    """Enforce: the grid needs visible browsers ("Hidden browsers" OFF, or the
    feature's own visible option ON). Refresh the cache read by workers."""
    if getattr(self, '_ui_grid_syncing', False):
        return
    self._ui_grid_syncing = True
    try:
        try:
            hl = bool(self.headless_var.get())
        except Exception:
            hl = True
        scv = bool(self._sc_visible_var.get())
        cmv = bool(self._cm_visible_var.get())
        allow = {'global': not hl, 'auto': (not hl) or scv, 'comment': (not hl) or cmv}
        for key, var, sw, hint, show, hide in getattr(self, '_ui_grid_widgets', []):
            try:
                if not allow[key]:
                    if var.get():
                        var.set(False)
                    sw.configure(state='disabled')
                    show()
                else:
                    sw.configure(state='normal')
                    hide()
            except Exception:
                pass
        _UI_GRID['headless'] = hl
        _UI_GRID['cm_visible'] = cmv
        _UI_GRID['on'] = {'global': allow['global'] and bool(self._ui_grid_var.get()),
                          'auto': allow['auto'] and bool(self._sc_grid_var.get()),
                          'comment': allow['comment'] and bool(self._cm_grid_var.get())}
        _ui_grid_region_update(self)
        if save:
            _ui_opts_save(self)
    finally:
        self._ui_grid_syncing = False


def _ui_grid_region_update(self):
    """Grid area = the app window below its title bar (like the mockups);
    the whole screen when the window is minimised or very small."""
    try:
        top = self.root.winfo_toplevel()
        try:
            state = top.state()
        except Exception:
            state = 'normal'
        x, y = top.winfo_rootx(), top.winfo_rooty()
        w, h = top.winfo_width(), top.winfo_height()
        hdr = 48
        try:
            tb = self._theme_btn_lbl.master.master
            hdr = max(0, tb.winfo_rooty() + tb.winfo_height() - y)
        except Exception:
            pass
        if state in ('iconic', 'withdrawn') or w < 640 or h < 420:
            x, y, w, h, hdr = 0, 0, top.winfo_screenwidth(), top.winfo_screenheight() - 48, 0
        _UI_GRID['region'] = (int(x), int(y + hdr), int(w), int(max(200, h - hdr)))
        _UI_GRID['scale'] = max(1.0, float(top.winfo_fpixels('1i')) / 96.0)
        _UI_GRID['headless'] = bool(self.headless_var.get())
    except Exception:
        pass


def _ui_grid_tick(self):
    _ui_grid_region_update(self)
    try:
        self._ui_grid_job = self.root.after(1500, self._ui_grid_tick)
    except Exception:
        pass


FacebookMultiPosterApp._ui_grid_sync = _ui_grid_sync
FacebookMultiPosterApp._ui_grid_tick = _ui_grid_tick


# ------------------------------------------------------- ZIP import
_UI_IMG_EXT = ('.png', '.jpg', '.jpeg', '.webp', '.gif', '.bmp')
_UI_DESC_NAMES = ('description.txt', 'desc.txt', 'caption.txt', 'texte.txt', 'text.txt')
_UI_CMT_NAMES = ('comment.txt', 'comments.txt', 'commentaire.txt', 'link.txt', 'lien.txt')


def _ui_txt(data):
    if data[:2] in (b'\xff\xfe', b'\xfe\xff'):
        try:
            return data.decode('utf-16')
        except Exception:
            pass
    for enc in ('utf-8-sig', 'cp1252', 'latin-1'):
        try:
            return data.decode(enc)
        except Exception:
            continue
    return ''


def _ui_natkey(s):
    return [int(t) if t.isdigit() else t.lower() for t in re.split(r'(\d+)', s)]


def _ui_zip_to_csv(zp):
    """One post per folder: image.* + description.txt (+ comment.txt).
    Writes the images and a texte/image/commentaire CSV into the session
    folder, i.e. exactly the format the app's CSV reader already posts
    (image + text, then the comment with the link)."""
    import zipfile
    import hashlib
    import io
    import csv as _csv
    st = os.stat(zp)
    h = hashlib.md5(('%s|%s|%s' % (os.path.abspath(zp), st.st_size, int(st.st_mtime))).encode('utf-8')).hexdigest()[:8]
    stem = re.sub(r'[^A-Za-z0-9_.-]+', '_', os.path.splitext(os.path.basename(zp))[0])[:48] or 'zip'
    base = os.path.join(SESSION_BASE, 'zip_posts')
    out_dir = os.path.join(base, '%s_%s' % (stem, h))
    groups = {}
    with zipfile.ZipFile(zp) as z:
        for info in z.infolist():
            name = info.filename.replace('\\', '/')
            if name.endswith('/') or name.startswith('/') or name.startswith('__MACOSX/'):
                continue
            parts = [p for p in name.split('/') if p]
            if not parts or any(p in ('..', '.') for p in parts) or ':' in parts[0]:
                continue                                  # never write outside
            fn = parts[-1]
            if fn.startswith('.'):
                continue
            g = groups.setdefault('/'.join(parts[:-1]), {})
            low = fn.lower()
            if low.endswith(_UI_IMG_EXT):
                if 'img' not in g or low.startswith('image'):
                    g['img'] = info
            elif low in _UI_DESC_NAMES:
                g['desc'] = info
            elif low in _UI_CMT_NAMES:
                g['cmt'] = info
        rows, skipped = [], 0
        for i, d in enumerate(sorted(groups, key=_ui_natkey)):
            g = groups[d]
            if 'img' not in g:
                if g.get('desc') or g.get('cmt'):
                    skipped += 1
                continue
            pdir = os.path.join(out_dir, '%03d' % (i + 1))
            os.makedirs(pdir, exist_ok=True)
            ext = os.path.splitext(g['img'].filename)[1].lower() or '.png'
            img_path = os.path.join(pdir, 'image' + ext)
            with open(img_path, 'wb') as fh:
                fh.write(z.read(g['img']))
            text = _ui_txt(z.read(g['desc'])).strip() if g.get('desc') else ''
            cmt = _ui_txt(z.read(g['cmt'])).strip() if g.get('cmt') else ''
            rows.append((text, os.path.abspath(img_path), cmt))
    if not rows:
        return None, 0, skipped
    # the app picks ';' when the first 4 KB has at least as many ';' as ','
    for delim in (';', ','):
        buf = io.StringIO()
        w = _csv.writer(buf, delimiter=delim, quoting=_csv.QUOTE_MINIMAL, lineterminator='\n')
        w.writerow(['texte', 'image', 'commentaire'])
        for r in rows:
            w.writerow(r)
        data = buf.getvalue()
        sample = data[:4096]
        picks = ';' if sample.count(';') >= sample.count(',') else ','
        if picks == delim:
            break
    csv_path = os.path.join(base, '%s_%s.csv' % (stem, h))
    os.makedirs(base, exist_ok=True)
    with open(csv_path, 'w', encoding='utf-8-sig', newline='') as fh:
        fh.write(data)
    return csv_path, len(rows), skipped


def _ui_zip_render(self):
    import tkinter as _tk
    F = 'Segoe UI'
    lf = getattr(self, '_ui_zip_list', None)
    if lf is None:
        return
    mf = getattr(self, '_ui_zip_msg_fn', None)
    if mf and getattr(self, '_ui_zip_msg', None) is not None:
        try:
            _ui_raw_conf(self._ui_zip_msg, text=mf[0](), fg=C[mf[1]])
        except Exception:
            pass
    for w in lf.winfo_children():
        w.destroy()
    for zp, csvp, n in list(getattr(self, '_ui_zip_items', []) or []):
        row = _tk.Frame(lf, bg=C['surface'])
        row.pack(fill='x', pady=(2, 0))
        b = _tk.Label(row, text='ZIP', font=(F, 8, 'bold'), bg=C['accent'], fg='white', padx=5)
        b._i18n_src = None
        b.pack(side='left')
        lab = _tk.Label(row, text='%s  ·  %s' % (os.path.basename(zp), _TR('%d publication(s)' % n)),
                        font=(F, 9), bg=C['surface'], fg=C['text'], anchor='w', width=1)
        lab._i18n_src = None
        lab.pack(side='left', fill='x', expand=True, padx=6)
        x = _tk.Button(row, text='✕', font=(F, 9, 'bold'), bg=C['surface'], fg=C['danger'],
                       relief='flat', bd=0, cursor='hand2', activebackground=C['danger_d'],
                       command=lambda z=zp: _ui_zip_remove(self, z))
        x._i18n_src = None
        x.pack(side='right')


def _ui_zip_status(self, text, color_key='text3', fn=None):
    self._ui_zip_msg_fn = (fn, color_key) if fn else None
    lab = getattr(self, '_ui_zip_msg', None)
    if lab is not None:
        try:
            _ui_raw_conf(lab, text=text, fg=C[color_key])
        except Exception:
            pass


def _ui_zip_remove(self, zp):
    items = list(getattr(self, '_ui_zip_items', []) or [])
    keep = [it for it in items if it[0] != zp]
    gone = [it[1] for it in items if it[0] == zp]
    self._ui_zip_items = keep
    try:
        new = [p for p in self.csv_paths_list if p not in gone]
        if new != list(self.csv_paths_list):
            _ui_apply_csv(self, new)
    except Exception:
        pass
    _ui_zip_render(self)
    _ui_zip_status(self, '')
    _ui_opts_save(self)


def _ui_zip_import(self, paths):
    """Convert in a worker thread, then register on the Tk thread."""
    paths = [p for p in paths if p]
    if not paths:
        return
    _ui_zip_status(self, _TR('Importation du ZIP…'), 'text3')

    box = {'res': None}

    def work():                                  # no Tk calls in this thread
        res = []
        for zp in paths:
            try:
                csvp, n, bad = _ui_zip_to_csv(zp)
                res.append((zp, csvp, n, bad, None))
            except Exception as e:
                res.append((zp, None, 0, 0, str(e)))
        box['res'] = res

    def poll():                                  # Tk thread picks up the result
        if box['res'] is None:
            try:
                self.root.after(120, poll)
            except Exception:
                pass
            return
        _ui_zip_finish(self, box['res'])
    _ui_threading.Thread(target=work, daemon=True, name='zip-import').start()
    try:
        self.root.after(120, poll)
    except Exception:
        pass


def _ui_zip_finish(self, res):
    items = list(getattr(self, '_ui_zip_items', []) or [])
    total, errors = 0, []
    add = []
    for zp, csvp, n, bad, err in res:
        if err or not csvp:
            errors.append(os.path.basename(zp))
            continue
        items = [it for it in items if it[0] != zp] + [(zp, csvp, n)]
        add.append(csvp)
        total += n
    self._ui_zip_items = items
    if add and _ui_source(self) is None:
        _ui_set_source(self, 'zip')          # first import picks the ZIP method
    _ui_zip_render(self)
    if errors and not total:
        _ui_zip_status(self, _TR('Aucune publication trouvée dans le ZIP') + ' — ' + ', '.join(errors), 'danger')
    elif errors:
        _ui_zip_status(self, _TR('%d publication(s) importée(s)' % total) + ' · ⚠ ' + ', '.join(errors), 'warning')
    else:
        _ui_zip_status(self, '✓ ' + _TR('%d publication(s) importée(s)' % total), 'success',
                       fn=lambda t=total: '✓ ' + _TR('%d publication(s) importée(s)' % t))
    _ui_opts_save(self)


def _ui_apply_zip(self, lines):
    ok, skipped = [], 0
    for l in lines:
        p = l.strip().strip('"').strip("'").strip('{}')
        if not p:
            continue
        if os.path.isfile(p) and p.lower().endswith('.zip'):
            if p not in ok:
                ok.append(p)
        else:
            skipped += 1
    if ok:
        _ui_zip_import(self, ok)
    return skipped


def _ui_build_zip_row(self):
    """'Zip file from mavelylink' — between Interval and CSV / XLSX files."""
    import tkinter as _tk
    c3 = getattr(self, '_ui_cfg3', None) or {}
    t = (getattr(self, '_ui_targets', {}) or {}).get('csv')
    if not c3 or not t:
        return
    pc = c3['blocks']['cfg'][1]
    sl = sorted(pc.grid_slaves(), key=lambda x: int(x.grid_info()['row']))
    csv_lab = next((w for w in sl if getattr(w, '_i18n_src', None) == 'Fichiers CSV / XLSX'), None)
    if csv_lab is None:
        return
    r0 = int(csv_lab.grid_info()['row'])
    for w in sl:
        rr = int(w.grid_info()['row'])
        if rr >= r0:
            w.grid_configure(row=rr + 4)
    lab_style = _ui_clone_style(csv_lab, 'label')
    head = _tk.Frame(pc, bg=C['surface'])
    head.grid(row=r0, column=0, columnspan=2, sticky='w', pady=((14 if r0 else 0), 5))
    _tk.Label(head, text='Fichier ZIP depuis', **lab_style).pack(side='left')
    link = _tk.Label(head, text='mavelylink', font=lab_style.get('font'), bg=C['surface'],
                     fg=C['info'], cursor='hand2')
    link._i18n_src = None
    link.pack(side='left', padx=(4, 0))
    link.bind('<Button-1>', lambda e: _ui_open_url('https://mavelylink.com/'))
    # entry + browse, styled like the CSV row
    ent_csv, br_csv = t['entry'], t['browse']
    inner_csv = ent_csv.master
    outer_csv = inner_csv.master
    row_csv = outer_csv.master
    row = _tk.Frame(pc, bg=row_csv.cget('bg'))
    row.grid(row=r0 + 1, column=0, columnspan=2, sticky='we', pady=(0, 2))
    outer = _tk.Frame(row, bg=outer_csv.cget('bg'), padx=outer_csv.cget('padx'), pady=outer_csv.cget('pady'))
    inner = _tk.Frame(outer, bg=inner_csv.cget('bg'))
    inner.pack(fill='both', expand=True)
    self._ui_zip_var = _tk.StringVar(value='')
    ent = _tk.Entry(inner, textvariable=self._ui_zip_var)
    for k in ('font', 'bg', 'fg', 'insertbackground', 'relief', 'bd', 'highlightthickness'):
        try:
            ent.configure(**{k: ent_csv.cget(k)})
        except Exception:
            pass
    ent.pack(fill='x', expand=True)
    try:
        oi = outer_csv.pack_info()
        oi.pop('in', None)
        outer.pack(**oi)
    except Exception:
        outer.pack(side='left', fill='x', expand=True)

    def browse():
        try:
            ps = filedialog.askopenfilenames(title='ZIP', filetypes=[('ZIP', '*.zip'), ('*', '*.*')])
        except Exception:
            ps = ()
        ps = [p for p in (ps or ()) if p]
        if ps:
            _ui_zip_import(self, ps)
    bopts = {}
    for k in ('font', 'bg', 'fg', 'relief', 'bd', 'padx', 'pady', 'cursor', 'activebackground',
              'activeforeground', 'highlightthickness'):
        try:
            bopts[k] = br_csv.cget(k)
        except Exception:
            pass
    bt = _tk.Button(row, text='Parcourir', command=browse, **bopts)
    try:
        bi = br_csv.pack_info()
        bi.pop('in', None)
        bt.pack(**bi)
    except Exception:
        bt.pack(side='left', padx=(8, 0))

    def enter(_e=None):
        v = self._ui_zip_var.get().strip()
        if v:
            if _ui_apply_zip(self, [v]) == 0:
                self._ui_zip_var.set('')
            else:
                _ui_zip_status(self, _TR('Aucune publication trouvée dans le ZIP'), 'danger')
    ent.bind('<Return>', enter)
    # open-list icon + paste editor
    self._ui_targets['zip'] = {'kind': 'zip', 'title': 'Fichier ZIP depuis'}
    ic = _tk.Label(inner, image=_ui_icon(inner, 'openlist', 20), bd=0, bg=ent.cget('bg'),
                   cursor='hand2')
    ic.pack(side='right', before=ent, padx=(0, 6))
    ic.bind('<Button-1>', lambda e: self._ui_open_editor('zip'))
    _ui_add_icon(self, ic, 'openlist', 20)
    self._ui_zip_entry, self._ui_zip_browse, self._ui_zip_icon = ent, bt, ic
    self._ui_zip_list = _tk.Frame(pc, bg=C['surface'])
    self._ui_zip_list.grid(row=r0 + 2, column=0, columnspan=2, sticky='we')
    self._ui_zip_msg = _tk.Label(pc, text='', font=('Segoe UI', 8), bg=C['surface'], fg=C['text3'],
                                 anchor='w', justify='left')
    self._ui_zip_msg._i18n_src = None
    self._ui_zip_msg.grid(row=r0 + 3, column=0, columnspan=2, sticky='w')
    # saved ZIP list (only those still loaded as CSV)
    o = _ui_opts_load()
    items = []
    for it in o.get('zip_items') or []:
        try:
            zp, csvp, n = it[0], it[1], int(it[2])
            if os.path.isfile(csvp):
                items.append((zp, csvp, n))
        except Exception:
            pass
    self._ui_zip_items = items
    _ui_zip_render(self)


