# ======================================================================
# >>> UI v6 — comment on the SAME post · ZIP options · rename · open-browser
#     icon · Start/Stop in Configuration · scrollable commenting accounts ·
#     running-tasks panel
# ======================================================================
_UI_PERMA_RX = re.compile(r'/posts/|/permalink/|permalink\.php|story_fbid=|multi_permalinks=')


def _ui_norm(s):
    """Letters/digits only (drops spaces, punctuation, emoji) for matching."""
    return re.sub(r'[\W_]+', '', (s or '').lower())


# In-page capture of the post Facebook just created. The creation request's
# reply carries the new post's id/url; it is kept in sessionStorage so it
# survives the page refresh that follows publishing.
_UI_CAP_JS = r"""(() => {
  if (window.__apCapHooked) return;
  window.__apCapHooked = true;
  window.__apNewPosts = window.__apNewPosts || [];
  const WANT = /(Composer[A-Za-z]*Create|StoryCreate)/;
  const RXU = /groups\\?\/([A-Za-z0-9_.\-]+)\\?\/(?:posts|permalink)\\?\/(\d{5,})/;
  const RXI = /"(?:post_id|legacy_story_hideable_id|top_level_post_id)"\s*:\s*"(\d{5,})"/;
  const bodyText = (b) => {
    try {
      if (!b) return '';
      if (typeof b === 'string') return b;
      if (typeof FormData !== 'undefined' && b instanceof FormData) {
        let s = ''; b.forEach((v, k) => { if (typeof v === 'string') s += k + '=' + v + '&'; }); return s;
      }
      if (typeof URLSearchParams !== 'undefined' && b instanceof URLSearchParams) return b.toString();
    } catch (e) {}
    return '';
  };
  const push = (o) => {
    window.__apNewPosts.push(o);
    try {
      const a = JSON.parse(sessionStorage.getItem('__apNewPost') || '[]');
      a.push(o); sessionStorage.setItem('__apNewPost', JSON.stringify(a.slice(-10)));
    } catch (e) {}
  };
  const grab = (req, text) => {
    try {
      if (!WANT.test(req || '')) return;
      const t = text || '';
      const m = RXU.exec(t);
      if (m) { push({gid: m[1], pid: m[2], t: Date.now()}); return; }
      const i = RXI.exec(t);
      if (i) push({gid: '', pid: i[1], t: Date.now()});
    } catch (e) {}
  };
  try {
    const XO = XMLHttpRequest.prototype.open, XS = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.open = function (m, u) { this.__apU = String(u || ''); return XO.apply(this, arguments); };
    XMLHttpRequest.prototype.send = function (b) {
      try {
        if (/graphql/.test(this.__apU || '')) {
          const req = bodyText(b), x = this;
          x.addEventListener('load', function () { try { grab(req, x.responseText); } catch (e) {} });
        }
      } catch (e) {}
      return XS.apply(this, arguments);
    };
  } catch (e) {}
  try {
    const F = window.fetch;
    if (F) window.fetch = function (input, init) {
      const p = F.apply(this, arguments);
      try {
        const u = typeof input === 'string' ? input : ((input && input.url) || '');
        if (/graphql/.test(u)) {
          const req = bodyText(init && init.body);
          p.then(function (r) { try { r.clone().text().then(function (t) { grab(req, t); }); } catch (e) {} })
           .catch(function () {});
        }
      } catch (e) {}
      return p;
    };
  } catch (e) {}
})();"""

# Find a post by its TEXT, at any element level. Current Facebook marks
# only comments as role="article" (not posts), which is why the old
# "first article" logic landed on a stranger's post via one of its comments.
_UI_FIND_JS = r"""(args) => {
  const needle = args.needle || '';
  const isCommentArt = (a) => {
    if (!a) return false;
    if (a.parentElement && a.parentElement.closest('[role="article"]')) return true;
    const lab = (a.getAttribute('aria-label') || '').toLowerCase();
    return /comment|coment|تعليق|reply|répon|respuest/.test(lab);
  };
  const inComment = (el) => isCommentArt(el.closest('[role="article"]'));
  const norm = s => (s || '').normalize('NFC').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '');
  const RXP = /\/(?:posts|permalink)\/\d+|story_fbid=|multi_permalinks=|permalink\.php/;
  const MSG = '[data-ad-rendering-role="story_message"], [data-ad-comet-preview="message"], [data-ad-preview="message"]';
  document.querySelectorAll('[data-ap-mine]').forEach(e => e.removeAttribute('data-ap-mine'));
  let hit = null;
  const sels = [MSG, 'div[dir="auto"]', 'span[dir="auto"]', 'p', 'div'];
  for (const sel of sels) {
    for (const el of document.querySelectorAll(sel)) {
      if (inComment(el)) continue;                            // skip comments
      const txt = el.innerText || '';
      if (txt.length > 5000) continue;
      if (needle ? norm(txt).includes(needle) : el.matches(MSG)) {
        if (!hit || txt.length < (hit.innerText || '').length) hit = el;
      }
    }
    if (hit) break;
  }
  if (!hit) return {found: false, href: null};
  const base = (hit.innerText || '').length;
  let node = hit, box = hit, href = null;
  for (let i = 0; i < 40 && node && node !== document.body; i++) {
    if (node.matches('[role="feed"], [role="main"]')) break;          // never climb into the feed
    if (node.querySelectorAll(MSG).length > 1) break;                // left our post
    if ((node.innerText || '').length > base + 2500) break;          // a fresh post is short
    box = node;
    for (const a of node.querySelectorAll('a[href]')) {
      if (inComment(a)) continue;                                     // links inside comments
      const h = a.getAttribute('href') || '';
      if (RXP.test(h) && !/comment_id=/.test(h)) { href = a.href; break; }
    }
    if (href) break;
    node = node.parentElement;
  }
  box.setAttribute('data-ap-mine', '1');
  return {found: true, href: href};
}"""

_UI_MARKED_LINK_JS = r"""() => {
  const isCommentArt = (a) => {
    if (!a) return false;
    if (a.parentElement && a.parentElement.closest('[role="article"]')) return true;
    const lab = (a.getAttribute('aria-label') || '').toLowerCase();
    return /comment|coment|تعليق|reply|répon|respuest/.test(lab);
  };
  const inComment = (el) => isCommentArt(el.closest('[role="article"]'));
  const box = document.querySelector('[data-ap-mine="1"]');
  if (!box) return null;
  const RXP = /\/(?:posts|permalink)\/\d+|story_fbid=|multi_permalinks=|permalink\.php/;
  let node = box;
  for (let i = 0; i < 6 && node; i++) {
    for (const a of node.querySelectorAll('a[href]')) {
      if (inComment(a)) continue;
      const h = a.getAttribute('href') || '';
      if (RXP.test(h) && !/comment_id=/.test(h)) return a.href;
    }
    node = node.parentElement;
    if (!node || node.matches('[role="feed"], [role="main"]')) break;
  }
  return null;
}"""


def _ui_cap_install(page):
    try:
        ctx = page.context
        if not getattr(ctx, '_ui_cap_on', False):
            ctx.add_init_script(_UI_CAP_JS)
            try:
                ctx._ui_cap_on = True
            except Exception:
                pass
    except Exception:
        pass
    try:
        page.evaluate(_UI_CAP_JS)
    except Exception:
        pass


def _ui_cap_begin(page):
    try:
        return page.evaluate("() => { try { sessionStorage.removeItem('__apNewPost'); } catch (e) {} "
                             "window.__apNewPosts = []; return Date.now(); }")
    except Exception:
        return None


def _ui_origin_gid(url):
    from urllib.parse import urlsplit
    sp = urlsplit(url or '')
    origin = '%s://%s' % (sp.scheme or 'https', sp.netloc or 'www.facebook.com')
    m = re.search(r'/groups/([^/?#]+)', url or '')
    return origin, (m.group(1) if m else None)


def _ui_cap_permalink(page, task_url, t0):
    """Address of the post just created, from Facebook's own reply."""
    origin, gid0 = _ui_origin_gid(task_url)
    try:
        lst = page.evaluate("() => { let a = []; try { a = JSON.parse(sessionStorage.getItem('__apNewPost') || '[]'); } "
                            "catch (e) {} return a.concat(window.__apNewPosts || []); }") or []
    except Exception:
        lst = []
    if t0:
        lst = [e for e in lst if (e.get('t') or 0) >= t0 - 2000]
    for e in reversed(lst):
        gid, pid = (e.get('gid') or gid0), e.get('pid')
        if gid and pid:
            return '%s/groups/%s/posts/%s/' % (origin, gid, pid)
    try:
        m = re.search(r'multi_permalinks=(\d+)', page.url or '')
        if m and gid0:
            return '%s/groups/%s/posts/%s/' % (origin, gid0, m.group(1))
    except Exception:
        pass
    return None


def _ui_dom_locate(page, needle):
    """Our post's permalink by text (hovering its links if Facebook only
    fills the timestamp address on hover). (found, href)."""
    try:
        res = page.evaluate(_UI_FIND_JS, {'needle': needle}) or {}
    except Exception:
        return False, None
    if not res.get('found'):
        return False, None
    if res.get('href'):
        return True, res['href']
    try:
        links = page.locator('[data-ap-mine="1"] a')
        for k in range(min(links.count(), 14)):
            try:
                links.nth(k).hover(timeout=1500)
            except Exception:
                continue
            h = page.evaluate(_UI_MARKED_LINK_JS)
            if h:
                return True, h
    except Exception:
        pass
    return True, None


def _ui_goto_own_post(app, page, info, sid):
    """Open the post that was just published so the app's own comment
    routine writes on THAT post. 'ok' / 'notfound'."""
    needle = _ui_norm(__import__('unicodedata').normalize('NFC', info.get('texte') or ''))[:32]
    origin, gid = _ui_origin_gid(info.get('group_url') or '')
    try:
        url = page.url or ''
    except Exception:
        url = ''

    def wait_feed():
        try:
            page.wait_for_selector('[role="feed"], [aria-posinset], [data-ad-rendering-role], '
                                   '[data-ad-comet-preview], [role="main"], div[role="article"]',
                                   timeout=8000)
        except Exception:
            pass
        try:
            page.wait_for_timeout(2500)
        except Exception:
            time.sleep(2.5)

    def same(u1, u2):
        return (u1 or '').split('?')[0].rstrip('/') == (u2 or '').split('?')[0].rstrip('/')
    perma = info.get('permalink')                       # 0) captured at publish time
    if perma:
        try:
            if not same(url, perma):
                app.log('  → Lien du post publié récupéré — ouverture du post pour y commenter.')
                page.goto(perma, wait_until='domcontentloaded', timeout=30000)
                wait_feed()
            return 'ok'
        except Exception:
            pass
    if _UI_PERMA_RX.search(url):                        # already on a post page: ours?
        if needle and _ui_dom_locate(page, needle)[0]:
            info['permalink'] = url
            return 'ok'
    views = [None]
    if gid:
        views += ['%s/groups/%s/?sorting_setting=CHRONOLOGICAL' % (origin, gid),
                  '%s/groups/%s/my_posted_content' % (origin, gid)]
    for v in views:
        if v is not None:
            try:
                page.goto(v, wait_until='domcontentloaded', timeout=30000)
            except Exception:
                continue
            wait_feed()
        elif needle:
            try:
                page.evaluate('window.scrollTo(0, 0)')
            except Exception:
                pass
        if not needle and (v is None or not v.endswith('my_posted_content')):
            continue                                    # no text: only "my posts" is safe
        found, href = _ui_dom_locate(page, needle)
        if found and href:
            try:
                from urllib.parse import urljoin
                href = urljoin(origin + '/', href)
                app.log('  → Post publié retrouvé — ouverture de son lien pour y commenter.')
                page.goto(href, wait_until='domcontentloaded', timeout=30000)
                wait_feed()
                info['permalink'] = page.url
                return 'ok'
            except Exception:
                continue
    return 'notfound'


_ui_orig_publish_post = FacebookMultiPosterApp._publish_post


def _ui_publish_post(self, page, task_url, task, sid, post_num, target_type, *a, **kw):
    data = (task or {}).get('data') or {}
    try:
        if not hasattr(self, '_ui_last_pub'):
            self._ui_last_pub = {}
        self._ui_last_pub[sid] = {'texte': data.get('texte') or '', 'group_url': task_url,
                                  'target': target_type}
    except Exception:
        pass
    t0 = None
    try:
        _ui_cap_install(page)
        t0 = _ui_cap_begin(page)
    except Exception:
        pass
    ok = _ui_orig_publish_post(self, page, task_url, task, sid, post_num, target_type, *a, **kw)
    if ok:
        try:
            perma = _ui_cap_permalink(page, task_url, t0)
            if perma:
                self._ui_last_pub[sid]['permalink'] = perma
                self.log('  → Lien du nouveau post : %s' % perma)
        except Exception:
            pass
        try:
            _ui_zip_mark_posted(data)
        except Exception:
            pass
    return ok


_ui_orig_add_comment = FacebookMultiPosterApp._add_comment


def _ui_add_comment(self, page, commentaire, slot_id, post_num, check_existing=False):
    """Comment on the post that was just published — never on another one."""
    info = (getattr(self, '_ui_last_pub', {}) or {}).get(slot_id) or {}
    try:
        state = _ui_goto_own_post(self, page, info, slot_id)
    except Exception:
        state = 'notfound'
    if state != 'ok':
        self.log('  ⚠️ Post %s introuvable dans le groupe (en attente de validation ?) — '
                 'lien non commenté pour ne pas commenter un autre post.' % post_num)
        return False                     # no exception -> no re-post elsewhere
    return _ui_orig_add_comment(self, page, commentaire, slot_id, post_num, check_existing)


FacebookMultiPosterApp._publish_post = _ui_publish_post
FacebookMultiPosterApp._add_comment = _ui_add_comment


# ------------------------------------------------ ZIP options (site.png)
_UI_ZIPOPT = {'mode': 'seq', 'dedup': False, 'irreg': False}   # read by workers
_UI_ZIPMEM_LOCK = _ui_threading.Lock()


def _ui_zip_root():
    return os.path.normcase(os.path.abspath(os.path.join(SESSION_BASE, 'zip_posts')))


def _ui_is_zip_pub(p):
    try:
        img = os.path.normcase(os.path.abspath(p.get('image') or ''))
        return img.startswith(_ui_zip_root() + os.sep)
    except Exception:
        return False


def _ui_zip_key(p):
    import hashlib
    base = _ui_norm(p.get('texte')) + '|' + (p.get('commentaire') or '').strip()
    if base == '|':
        base = os.path.basename(os.path.dirname(p.get('image') or ''))
    return hashlib.md5(base.encode('utf-8')).hexdigest()


def _ui_zip_mem_path():
    return os.path.join(SESSION_BASE, 'zip_posted.json')


def _ui_zip_memory():
    try:
        import json
        with open(_ui_zip_mem_path(), encoding='utf-8') as f:
            return set(json.load(f) or [])
    except Exception:
        return set()


def _ui_zip_mark_posted(data):
    """Remember every ZIP deal that was published (anti-duplicate memory)."""
    if not data or not _ui_is_zip_pub(data):
        return
    import json
    with _UI_ZIPMEM_LOCK:
        mem = _ui_zip_memory()
        mem.add(_ui_zip_key(data))
        try:
            with open(_ui_zip_mem_path(), 'w', encoding='utf-8') as f:
                json.dump(sorted(mem), f)
        except Exception:
            pass


def _ui_zip_order_key(app, p):
    img = os.path.abspath(p.get('image') or '')
    folder = os.path.basename(os.path.dirname(os.path.dirname(img)))
    order = [os.path.splitext(os.path.basename(it[1]))[0]
             for it in (getattr(app, '_ui_zip_items', []) or [])]
    pos = order.index(folder) if folder in order else len(order)
    return (pos, _ui_natkey(img))


_ui_orig_load_publications = FacebookMultiPosterApp.load_publications


def _ui_load_publications(self, *a, **kw):
    """ZIP posts follow the ZIP row's own File mode + anti-duplicate memory;
    CSV / XLSX posts are left exactly as the app loaded them."""
    pubs = _ui_orig_load_publications(self, *a, **kw)
    try:
        slots = [k for k, p in enumerate(pubs) if _ui_is_zip_pub(p)]
        if not slots:
            return pubs
        zp = [pubs[k] for k in slots]
        if _UI_ZIPOPT['dedup']:
            mem = _ui_zip_memory()
            keep = [p for p in zp if _ui_zip_key(p) not in mem]
            if len(keep) < len(zp):
                self.log('♻️ ZIP : %d publication(s) déjà postée(s) ignorée(s) (mémoire anti-doublon).'
                         % (len(zp) - len(keep)))
        else:
            keep = list(zp)
        if _UI_ZIPOPT['mode'] == 'rand':
            random.shuffle(keep)
        else:
            keep.sort(key=lambda p: _ui_zip_order_key(self, p))
        it = iter(keep)
        sset = set(slots)
        out = []
        for k, p in enumerate(pubs):
            if k in sset:
                nxt = next(it, None)
                if nxt is not None:
                    out.append(nxt)
            else:
                out.append(p)
        return out
    except Exception:
        return pubs


_ui_orig_run_automation = FacebookMultiPosterApp.run_automation


def _ui_run_automation(self, group_urls, interval_min, slots, publications, target_type='groupe',
                       interval_max=None, group_mode='rotation', *a, **kw):
    try:
        if _UI_ZIPOPT['irreg'] and any(_ui_is_zip_pub(p) for p in (publications or [])):
            lo = int(interval_min)
            hi = int(interval_max) if interval_max else lo
            nlo = max(1, int(round(lo * 0.5)))
            nhi = max(nlo + 1, int(round(max(hi, lo) * 1.8)))
            self.log('⏱️ Délais irréguliers (ZIP) : pauses aléatoires entre %d et %d min.' % (nlo, nhi))
            interval_min, interval_max = nlo, nhi
    except Exception:
        pass
    return _ui_orig_run_automation(self, group_urls, interval_min, slots, publications,
                                   target_type, interval_max, group_mode, *a, **kw)


FacebookMultiPosterApp.load_publications = _ui_load_publications
FacebookMultiPosterApp.run_automation = _ui_run_automation


def _ui_build_zip_opts(self):
    """File mode + Anti-duplicate memory + Irregular delays under the ZIP list."""
    import tkinter as _tk
    msg = getattr(self, '_ui_zip_msg', None)
    c3 = getattr(self, '_ui_cfg3', None) or {}
    if msg is None or not c3:
        return
    pc = c3['blocks']['cfg'][1]
    r_ins = int(msg.grid_info()['row'])
    for w in pc.grid_slaves():
        rr = int(w.grid_info()['row'])
        if rr >= r_ins:
            w.grid_configure(row=rr + 2)
    mode_lab = _ui_find(self._sections.get('campagne') or pc,
                        lambda w: getattr(w, '_i18n_src', None) == 'Mode fichiers :')
    radios = [w for w in (mode_lab.master.winfo_children() if mode_lab is not None else [])
              if w.winfo_class() == 'Radiobutton']
    self._ui_zip_mode_var = _tk.StringVar(value='seq')
    self._ui_zip_dedup_var = _tk.BooleanVar(value=False)
    self._ui_zip_irreg_var = _tk.BooleanVar(value=False)
    self._ui_csv_mode_row = mode_lab.master if mode_lab is not None else None
    row = _tk.Frame(pc, bg=(mode_lab.master.cget('bg') if mode_lab is not None else C['surface']))
    row.grid(row=r_ins, column=0, columnspan=2, sticky='w', pady=(6, 2))
    self._ui_zip_mode_row = row
    lab = _tk.Label(row, text='Mode fichiers :', **(_ui_clone_style(mode_lab, 'label')
                                                   if mode_lab is not None else {}))
    lab.pack(side='left', padx=(0, 8))
    for val, src in zip(('seq', 'rand'), radios[:2] or []):
        rb = _tk.Radiobutton(row, text=getattr(src, '_i18n_src', None) or src.cget('text'),
                             variable=self._ui_zip_mode_var, value=val,
                             font=src.cget('font'), fg=src.cget('fg'))
        rb.pack(side='left', padx=(0, 8))
    sw_row = _tk.Frame(pc, bg=C['surface'])
    sw_row.grid(row=r_ins + 1, column=0, columnspan=2, sticky='w', pady=(2, 2))
    self._ui_zip_sw_row = sw_row
    ref = _ui_find_check(self.root, self.headless_var)
    st = _ui_clone_style(ref, 'check') if ref is not None else {}
    st['bg'] = C['surface']
    st['activebackground'] = C['surface']
    for text, var in (('Mémoire anti-doublon', self._ui_zip_dedup_var),
                      ('Délais irréguliers', self._ui_zip_irreg_var)):
        _tk.Checkbutton(sw_row, text=text, variable=var, **st).pack(side='left', padx=(0, 14))
    o = _ui_opts_load()
    self._ui_zip_mode_var.set('rand' if o.get('zip_mode') == 'rand' else 'seq')
    self._ui_zip_dedup_var.set(bool(o.get('zip_dedup', False)))
    self._ui_zip_irreg_var.set(bool(o.get('zip_irreg', False)))

    def sync(*_a):
        _UI_ZIPOPT['mode'] = self._ui_zip_mode_var.get()
        _UI_ZIPOPT['dedup'] = bool(self._ui_zip_dedup_var.get())
        _UI_ZIPOPT['irreg'] = bool(self._ui_zip_irreg_var.get())
        _ui_opts_save(self)
    for v in (self._ui_zip_mode_var, self._ui_zip_dedup_var, self._ui_zip_irreg_var):
        v.trace_add('write', sync)
    sync()


def _ui_zipopt_save(self):
    try:
        return {'zip_mode': self._ui_zip_mode_var.get(),
                'zip_dedup': bool(self._ui_zip_dedup_var.get()),
                'zip_irreg': bool(self._ui_zip_irreg_var.get())}
    except Exception:
        return {}


_UI_ZIPOPT_SAVE = _ui_zipopt_save


def _ui_build_cfg_actions(self):
    """'Start Posting' / 'Stop' at the bottom of the Configuration card."""
    import tkinter as _tk
    c3 = getattr(self, '_ui_cfg3', None) or {}
    if not c3:
        return
    pc = c3['blocks']['cfg'][1]
    r = max([int(w.grid_info()['row']) for w in pc.grid_slaves()] or [0]) + 1
    sc = self._sections.get('collecte')
    ref_go = _ui_find(sc, lambda w: w.winfo_class() == 'Button'
                      and 'mode automatique' in str(getattr(w, '_i18n_src', '') or '')) if sc else None
    ref_stop = _ui_find(sc, lambda w: w.winfo_class() == 'Button'
                        and str(getattr(w, '_i18n_src', '') or '').startswith('■')) if sc else None

    def style(ref, bg):
        out = {}
        for k in ('font', 'bg', 'fg', 'relief', 'bd', 'padx', 'pady', 'cursor',
                  'activebackground', 'activeforeground', 'highlightthickness'):
            try:
                out[k] = ref.cget(k)
            except Exception:
                pass
        if not out:
            out = {'bg': bg, 'fg': 'white', 'relief': 'flat', 'bd': 0, 'padx': 14, 'pady': 6,
                   'cursor': 'hand2', 'font': ('Segoe UI', 9, 'bold')}
        return out
    row = _tk.Frame(pc, bg=C['surface'])
    row.grid(row=r, column=0, columnspan=2, sticky='e', pady=(16, 0))
    go = _tk.Button(row, text='▶ Lancer la publication', command=self.start_posting,
                    **style(ref_go, C['success']))
    go.pack(side='left', padx=(0, 8))
    stop = _tk.Button(row, text='■ Arrêter', command=self.stop_posting,
                      **style(ref_stop, C['danger']))
    stop.pack(side='left')
    self._ui_cfg_go, self._ui_cfg_stop = go, stop


