def _ui_render_openbrowser(S):
    """Orange circle with a white 'open' box + arrow (user's icon)."""
    cv = _UICanvas(S, S)
    k = S / 24.0
    top, bot = (251, 156, 38), (236, 118, 6)
    cv.paint(_sd_circle(S / 2.0, S / 2.0, S / 2.0 - 0.4),
             lambda x, y: _ui_mix(top, bot, max(0.0, min(1.0, y / float(S)))))
    h = max(0.75, 0.95 * k)
    segs = [((5.8, 5.8), (12.0, 5.8)), ((5.8, 5.8), (5.8, 17.8)), ((5.8, 17.8), (18.2, 17.8)),
            ((18.2, 17.8), (18.2, 11.6)), ((10.8, 13.2), (18.4, 5.6)), ((18.4, 5.6), (14.0, 5.6)),
            ((18.4, 5.6), (18.4, 10.0))]
    cv.paint(_sd_union(*[_sd_capsule(a[0] * k, a[1] * k, b[0] * k, b[1] * k, h) for a, b in segs]),
             (255, 255, 255))
    return cv.png()


def _ui_open_browser(self, sid):
    try:
        self._start_thread(self._open_account_browser, (sid,), name='browser-%d' % sid)
    except Exception:
        pass


def _ui_rename_open(self, sid):
    """Single click on the name opens the app's own rename box (unless its
    double-click already did)."""
    import tkinter as _tk
    try:
        for w in self.root.winfo_children():
            if isinstance(w, _tk.Toplevel) and w.winfo_exists() and w.winfo_viewable():
                return
    except Exception:
        pass
    self._rename_account_popup(sid)


def _ui_bind_rename(self, cv, sid):
    def press(e):
        cv._ui_press = (e.x, e.y)

    def release(e):
        p = getattr(cv, '_ui_press', None)
        cv._ui_press = None
        if not p or abs(e.x - p[0]) > 4 or abs(e.y - p[1]) > 4:
            return
        try:
            _W, z = self._row_zones(cv.winfo_width())
            x1, x2 = z['name']
        except Exception:
            return
        if x1 <= e.x <= x2:
            self.root.after(320, lambda: _ui_rename_open(self, sid))

    def motion(e):
        try:
            _W, z = self._row_zones(cv.winfo_width())
            x1, x2 = z['name']
            want = 'xterm' if x1 <= e.x <= x2 else ''
            if str(cv.cget('cursor')) != want and (want or getattr(cv, '_ui_cur', False)):
                cv.configure(cursor=want)
                cv._ui_cur = bool(want)
        except Exception:
            pass
    cv.bind('<ButtonPress-1>', press, add='+')
    cv.bind('<ButtonRelease-1>', release, add='+')
    cv.bind('<Motion>', motion, add='+')
    cv._ui_rename = True


def _ui_accounts_sync(self):
    import tkinter as _tk
    af = getattr(self, 'accounts_frame', None)
    cvs = getattr(self, 'account_canvases', None) or {}
    if af is None:
        return
    if not hasattr(self, '_ui_acc_icons'):
        self._ui_acc_icons = {}
        try:
            af.columnconfigure(0, weight=1)
            self._acc_head_cv.pack_configure(padx=(8, 8 + 32))   # header stays aligned
        except Exception:
            pass
    icons = self._ui_acc_icons
    for sid, cv in list(cvs.items()):
        try:
            if not cv.winfo_exists():
                continue
            gi = cv.grid_info()
            if not gi:
                continue
            row = int(gi['row'])
            lab = icons.get(sid)
            if lab is None or not lab.winfo_exists():
                lab = _tk.Label(af, image=_ui_icon(af, 'openbrowser', 22), bg=af.cget('bg'),
                                bd=0, cursor='hand2')
                lab.bind('<Button-1>', lambda e, s=sid: _ui_open_browser(self, s))
                icons[sid] = lab
                _ui_add_icon(self, lab, 'openbrowser', 22)
            li = lab.grid_info()
            if not li or int(li.get('row', -1)) != row:
                lab.grid(row=row, column=1, padx=(6, 0), pady=0)
            if not getattr(cv, '_ui_rename', False):
                _ui_bind_rename(self, cv, sid)
        except Exception:
            continue
    for sid in list(icons):
        cv = cvs.get(sid)
        try:
            alive = cv is not None and cv.winfo_exists() and bool(cv.grid_info())
        except Exception:
            alive = False
        if not alive:
            try:
                icons.pop(sid).destroy()
            except Exception:
                icons.pop(sid, None)


