# --------------------------- commenting accounts: scrollable columns (mode.png)
_UI_CM_ROWS = 6


def _ui_cm_layout(self):
    """Commenting accounts in columns of 6, scrolled left/right (mode.png).
    The app's own frame stays in place and clips the profiles; the scrollbar
    just shifts their positions (no re-parenting, no canvas tricks)."""
    import tkinter as _tk
    cadre = getattr(self, '_cm_acc_frame', None)
    if cadre is None:
        return
    try:
        if not cadre.winfo_exists():
            return
    except Exception:
        return
    host = getattr(self, '_ui_cm_host', None)
    if host is None:
        par = cadre.master
        hsb = _tk.Scrollbar(par, orient='horizontal', command=lambda *a: _ui_cm_scroll(self, *a))
        host = self._ui_cm_host = {'hsb': hsb, 'off': 0, 'kids': [], 'cw': 0, 'colw': 100}

        def wheel(e):
            d = getattr(e, 'delta', 0) or (120 if getattr(e, 'num', 0) == 4 else -120)
            _ui_cm_scroll(self, 'scroll', -1 if d > 0 else 1, 'units')
            return 'break'
        host['wheel'] = wheel
        cadre.bind('<Configure>', lambda e: _ui_cm_place(self), add='+')
        for seq in ('<Shift-MouseWheel>', '<Shift-Button-4>', '<Shift-Button-5>'):
            cadre.bind(seq, wheel)
        try:
            _ui_raw_conf(cadre, padx=0, pady=0, width=1)
        except Exception:
            pass
    kids = [w for w in cadre.winfo_children() if w.winfo_exists()]
    for w in kids:
        if w.winfo_manager() == 'pack':
            w.pack_forget()
        for seq in ('<Shift-MouseWheel>', '<Shift-Button-4>', '<Shift-Button-5>'):
            try:
                w.bind(seq, host['wheel'])
            except Exception:
                pass
    cadre.pack_propagate(False)
    cadre.update_idletasks()
    host['kids'] = kids
    if len(kids) == 1 and kids[0].winfo_class() == 'Label':
        lab = kids[0]
        try:
            _ui_raw_conf(lab, wraplength=max(200, cadre.winfo_width() - 24), justify='left')
        except Exception:
            pass
        host.update(single=True, colw=0, rowh=lab.winfo_reqheight(), cw=0)
        H = lab.winfo_reqheight() + 12
    else:
        colw = max([w.winfo_reqwidth() for w in kids] or [100]) + 26
        rowh = max([w.winfo_reqheight() for w in kids] or [24]) + 2
        ncols = max(1, (len(kids) + _UI_CM_ROWS - 1) // _UI_CM_ROWS)
        host.update(single=False, colw=colw, rowh=rowh, cw=16 + ncols * colw)
        H = 12 + max(1, min(len(kids), _UI_CM_ROWS)) * rowh
    _ui_raw_conf(cadre, height=H)
    _ui_cm_place(self)


def _ui_cm_place(self):
    host = getattr(self, '_ui_cm_host', None)
    cadre = getattr(self, '_cm_acc_frame', None)
    if not host or cadre is None:
        return
    try:
        vw = max(1, cadre.winfo_width())
        cw = host['cw']
        off = max(0, min(host['off'], max(0, cw - vw)))
        host['off'] = off
        if host.get('single'):
            for w in host['kids']:
                w.place(x=8, y=6)
        else:
            for i, w in enumerate(host['kids']):
                if w.winfo_exists():
                    col, r = divmod(i, _UI_CM_ROWS)
                    w.place(x=8 + col * host['colw'] - off, y=6 + r * host['rowh'])
        hsb = host['hsb']
        if cw > vw + 2:
            if not hsb.winfo_manager():
                hsb.pack(after=cadre, fill='x')
            hsb.set(off / float(cw), min(1.0, (off + vw) / float(cw)))
        elif hsb.winfo_manager():
            hsb.pack_forget()
    except Exception:
        pass


def _ui_cm_scroll(self, *args):
    host = getattr(self, '_ui_cm_host', None)
    cadre = getattr(self, '_cm_acc_frame', None)
    if not host or cadre is None or not args:
        return
    vw = max(1, cadre.winfo_width())
    try:
        if args[0] == 'moveto':
            host['off'] = int(float(args[1]) * host['cw'])
        elif args[0] == 'scroll':
            step = host['colw'] if (len(args) < 3 or args[2] == 'units') else vw
            host['off'] = host['off'] + int(args[1]) * step
    except Exception:
        return
    _ui_cm_place(self)


