# ======================================================================
# >>> UI v7 — ZIP / CSV-XLSX source switch · ZIP posts without the CSV
#     list · comment pinned to our post on every attempt · Export
# ======================================================================
def _ui_source(self):
    try:
        if self._ui_src_zip_var.get():
            return 'zip'
        if self._ui_src_csv_var.get():
            return 'csv'
    except Exception:
        pass
    return None


def _ui_set_source(self, src):
    try:
        self._ui_src_zip_var.set(src == 'zip')
        self._ui_src_csv_var.set(src == 'csv')
    except Exception:
        pass


def _ui_read_zip_csv(path):
    import csv as _csv
    out = []
    try:
        with open(path, encoding='utf-8-sig', newline='') as f:
            head = f.readline()
            delim = ';' if head.count(';') >= head.count(',') else ','
            f.seek(0)
            if f.read(1) != '\ufeff':
                f.seek(0)
            for row in _csv.DictReader(f, delimiter=delim):
                row = {(k or '').strip(): (v or '') for k, v in row.items()}
                t = row.get('texte', '').strip()
                img = row.get('image', '').strip()
                if t or img:
                    out.append({'texte': t, 'image': img,
                                'commentaire': row.get('commentaire', '').strip(), 'source': 'csv'})
    except Exception:
        pass
    return out


def _ui_zip_publications(self):
    """ZIP deals straight from the imported ZIPs (no CSV/XLSX list needed)."""
    pubs = []
    for zp, csvp, _n in list(getattr(self, '_ui_zip_items', []) or []):
        for p in _ui_read_zip_csv(csvp):
            if p['image'] and not os.path.isfile(p['image']):
                continue
            pubs.append(p)
    if _UI_ZIPOPT['dedup']:
        mem = _ui_zip_memory()
        keep = [p for p in pubs if _ui_zip_key(p) not in mem]
        if len(keep) < len(pubs):
            self.log('♻️ ZIP : %d publication(s) déjà postée(s) ignorée(s) (mémoire anti-doublon).'
                     % (len(pubs) - len(keep)))
        pubs = keep
    if _UI_ZIPOPT['mode'] == 'rand':
        random.shuffle(pubs)
    try:
        lim = int(self.max_posts_var.get())
        if lim > 0:
            pubs = pubs[:lim]
    except Exception:
        pass
    if pubs:
        self.log('📦 %d publication(s) chargée(s) depuis %d fichier(s) ZIP.'
                 % (len(pubs), len(getattr(self, '_ui_zip_items', []) or [])))
    return pubs


def _ui_load_publications_v7(self, *a, **kw):
    src = _ui_source(self)
    if src == 'zip':
        return _ui_zip_publications(self)
    if src == 'csv':
        pubs = _ui_orig_load_publications(self, *a, **kw)
        return [p for p in pubs if not _ui_is_zip_pub(p)]
    return []


FacebookMultiPosterApp.load_publications = _ui_load_publications_v7

_ui_orig_start_posting = FacebookMultiPosterApp.start_posting


def _ui_start_posting(self, *a, **kw):
    if not getattr(self, 'is_running', False) and not getattr(self, '_sc_running', False):
        src = _ui_source(self)
        if src is None:
            messagebox.showwarning(_TR('Source de publication'),
                                   _TR('Choisissez une source de publication : fichier ZIP ou CSV / XLSX.'))
            return None
        if src == 'zip' and not (getattr(self, '_ui_zip_items', []) or []):
            messagebox.showerror(_TR('Erreur'), _TR('Aucune publication dans les fichiers ZIP.'))
            return None
    return _ui_orig_start_posting(self, *a, **kw)


FacebookMultiPosterApp.start_posting = _ui_start_posting

_ui_orig_add_comment_once = FacebookMultiPosterApp._add_comment_once


def _ui_add_comment_once(self, page, commentaire, slot_id, post_num, *a, **kw):
    """Every attempt starts on OUR post's page (the app would otherwise
    reload the feed and use its first post)."""
    info = (getattr(self, '_ui_last_pub', {}) or {}).get(slot_id) or {}
    perma = info.get('permalink')
    if perma:
        try:
            cur = (page.url or '').split('?')[0].rstrip('/')
            if cur != perma.split('?')[0].rstrip('/'):
                page.goto(perma, wait_until='domcontentloaded', timeout=30000)
                page.wait_for_timeout(2500)
        except Exception:
            pass
    return _ui_orig_add_comment_once(self, page, commentaire, slot_id, post_num, *a, **kw)


FacebookMultiPosterApp._add_comment_once = _ui_add_comment_once


# ------------------------------------------ source switches + lock state
def _ui_build_source_switches(self):
    """A switch on the ZIP and on the CSV / XLSX header. Only one can be ON;
    the other section is locked. None ON = both locked."""
    import tkinter as _tk
    c3 = getattr(self, '_ui_cfg3', None) or {}
    if not c3 or not hasattr(self, '_ui_zip_list'):
        return
    pc = c3['blocks']['cfg'][1]
    self._ui_src_zip_var = _tk.BooleanVar(value=False)
    self._ui_src_csv_var = _tk.BooleanVar(value=False)
    ref = _ui_find_check(self.root, self.headless_var)
    st = _ui_clone_style(ref, 'check') if ref is not None else {}
    st['bg'] = st['activebackground'] = C['surface']
    # ZIP header = my frame (first child is the "Zip file from" label)
    zhead = next((w for w in pc.grid_slaves() if w.winfo_class() == 'Frame'
                  and any(getattr(c, '_i18n_src', None) == 'Fichier ZIP depuis' for c in w.winfo_children())), None)
    csv_lab = next((w for w in pc.grid_slaves() if getattr(w, '_i18n_src', None) == 'Fichiers CSV / XLSX'), None)
    if zhead is None or csv_lab is None:
        return
    zs = _tk.Checkbutton(zhead, text='', variable=self._ui_src_zip_var, **st)
    zs.pack(side='left', before=zhead.winfo_children()[0], padx=(0, 6))
    gi = csv_lab.grid_info()
    chead = _tk.Frame(pc, bg=C['surface'])
    csv_lab.grid_forget()
    chead.grid(row=int(gi['row']), column=0, columnspan=2, sticky='w', pady=gi.get('pady', (14, 5)))
    cs = _tk.Checkbutton(chead, text='', variable=self._ui_src_csv_var, **st)
    cs.pack(side='left', padx=(0, 6))
    csv_lab.pack(in_=chead, side='left')
    csv_lab.lift()
    self._ui_src_switches = (zs, cs)
    # remember the fixed widgets of each section
    t = self._ui_targets
    csv_mode_row = getattr(self, '_ui_csv_mode_row', None)
    if csv_mode_row is None:
        lab = _ui_find(self._sections.get('campagne') or pc,
                       lambda w: getattr(w, '_i18n_src', None) == 'Mode fichiers :'
                       and w.master is not getattr(self, '_ui_zip_mode_row', None))
        csv_mode_row = lab.master if lab is not None else None
    dnd = _ui_find(self._sections.get('campagne') or pc,
                   lambda w: w.winfo_class() == 'Label'
                   and 'Glissez' in str(getattr(w, '_i18n_src', '') or ''))
    self._ui_src_parts = {
        'zip': {'entry': self._ui_zip_entry, 'browse': self._ui_zip_browse,
                'icon': self._ui_zip_icon, 'list': self._ui_zip_list,
                'rows': [getattr(self, '_ui_zip_mode_row', None), getattr(self, '_ui_zip_sw_row', None)]},
        'csv': {'entry': t['csv']['entry'], 'browse': t['csv']['browse'],
                'icon': t['csv'].get('icon'), 'list': self._csv_list_frame,
                'rows': [csv_mode_row], 'dnd': dnd},
    }
    o = _ui_opts_load()
    src = o.get('source', '__unset__')
    if src == '__unset__':                      # first run: keep what was in use
        src = 'csv' if self.csv_paths_list else ('zip' if self._ui_zip_items else None)
    _ui_set_source(self, src if src in ('zip', 'csv') else None)
    state = {'busy': False}

    def on_toggle(which):
        if state['busy']:
            return
        state['busy'] = True
        try:
            if which == 'zip' and self._ui_src_zip_var.get():
                self._ui_src_csv_var.set(False)
            elif which == 'csv' and self._ui_src_csv_var.get():
                self._ui_src_zip_var.set(False)
        finally:
            state['busy'] = False
        _ui_src_apply(self)
        _ui_opts_save(self)
    self._ui_src_zip_var.trace_add('write', lambda *_a: on_toggle('zip'))
    self._ui_src_csv_var.trace_add('write', lambda *_a: on_toggle('csv'))
    _ui_src_apply(self)


def _ui_src_apply(self):
    """Lock every control of the section that is not the active source."""
    parts = getattr(self, '_ui_src_parts', None)
    if not parts:
        return
    src = _ui_source(self)
    for key, p in parts.items():
        on = (src == key)
        st = 'normal' if on else 'disabled'
        for w in (p.get('entry'), p.get('browse')):
            try:
                if w is not None and str(w.cget('state')) != st:
                    w.configure(state=st)
            except Exception:
                pass
        ic = p.get('icon')
        if ic is not None:
            try:
                ic._ui_locked = not on
                _ui_raw_conf(ic, image=_ui_icon(ic, 'openlist' if on else 'openlist_off', 20),
                             cursor=('hand2' if on else 'arrow'))
            except Exception:
                pass
        conts = [p.get('list')] + list(p.get('rows') or [])
        for cont in conts:
            if cont is None:
                continue
            for w in _ui_walk(cont):
                try:
                    if w.winfo_class() in ('Button', 'Radiobutton', 'Checkbutton', 'Entry', 'Spinbox'):
                        if str(w.cget('state')) != st:
                            w.configure(state=st)
                except Exception:
                    pass
        d = p.get('dnd')
        if d is not None:
            try:
                if not hasattr(d, '_ui_fg0'):
                    d._ui_fg0 = d.cget('fg')
                _ui_raw_conf(d, fg=(d._ui_fg0 if on else C['text3']))
            except Exception:
                pass


def _ui_opts_src(self):
    return {'source': _ui_source(self)}


_ui_prev_opts_extra = _UI_ZIPOPT_SAVE
_UI_ZIPOPT_SAVE = lambda self: dict(_ui_prev_opts_extra(self), **_ui_opts_src(self))


def _ui_cleanup_legacy_zip_csv(self):
    """Older builds put the ZIP's generated CSV in the CSV/XLSX list; remove it."""
    try:
        legacy = [p for p in self.csv_paths_list
                  if os.path.normcase(os.path.abspath(p)).startswith(_ui_zip_root() + os.sep)]
        if legacy:
            _ui_apply_csv(self, [p for p in self.csv_paths_list if p not in legacy])
    except Exception:
        pass


# ------------------------------------------------------------- Export
_UI_EXPORT_LOCK = _ui_threading.Lock()


def _ui_export_path():
    return os.path.join(SESSION_BASE, 'sc_collected.json')


def _ui_export_load():
    try:
        import json
        with open(_ui_export_path(), encoding='utf-8') as f:
            d = json.load(f)
        return d if isinstance(d, list) else []
    except Exception:
        return []


def _ui_export_add(pubs):
    """Keep every post Automatic mode collects (text + image), newest last."""
    import json
    if not pubs:
        return
    with _UI_EXPORT_LOCK:
        bag = _ui_export_load()
        seen = set((b.get('texte', ''), os.path.basename(b.get('image', ''))) for b in bag)
        for p in pubs:
            k = ((p.get('texte') or ''), os.path.basename(p.get('image') or ''))
            if k in seen:
                continue
            seen.add(k)
            bag.append({'texte': p.get('texte') or '', 'image': p.get('image') or '',
                        'commentaire': p.get('commentaire') or ''})
        bag = bag[-1000:]
        try:
            os.makedirs(SESSION_BASE, exist_ok=True)
            with open(_ui_export_path(), 'w', encoding='utf-8') as f:
                json.dump(bag, f, ensure_ascii=False)
        except Exception:
            pass


_ui_orig_sc_scrape_group = FacebookMultiPosterApp._sc_scrape_group


def _ui_sc_scrape_group(self, *a, **kw):
    got = _ui_orig_sc_scrape_group(self, *a, **kw)
    try:
        _ui_export_add(got)
    except Exception:
        pass
    return got


FacebookMultiPosterApp._sc_scrape_group = _ui_sc_scrape_group


def _ui_export_items():
    return [b for b in _ui_export_load() if (b.get('texte') or (b.get('image') and os.path.isfile(b['image'])))]


def _ui_slug(s, n=40):
    s = re.sub(r'[^A-Za-z0-9]+', '_', s or '').strip('_')
    return (s[:n] or 'post')


def _ui_export_write(items, path, fmt):
    """ZIP = one folder per post (image + description.txt + comment.txt, the
    same format the ZIP importer reads). CSV / XLSX = texte/image/commentaire
    with the images copied into a folder next to the file (relative paths)."""
    import zipfile
    import shutil
    n = 0
    if fmt == 'zip':
        with zipfile.ZipFile(path, 'w', zipfile.ZIP_DEFLATED) as z:
            for i, it in enumerate(items, 1):
                d = '%03d_%s' % (i, _ui_slug(it.get('texte')))
                img = it.get('image') or ''
                if img and os.path.isfile(img):
                    z.write(img, '%s/image%s' % (d, os.path.splitext(img)[1].lower() or '.jpg'))
                elif not it.get('texte'):
                    continue
                z.writestr('%s/description.txt' % d, (it.get('texte') or '').encode('utf-8'))
                if it.get('commentaire'):
                    z.writestr('%s/comment.txt' % d, it['commentaire'].encode('utf-8'))
                n += 1
        return n
    base = os.path.splitext(path)[0]
    img_dir = base + '_images'
    rows = []
    for i, it in enumerate(items, 1):
        img = it.get('image') or ''
        rel = ''
        if img and os.path.isfile(img):
            os.makedirs(img_dir, exist_ok=True)
            name = '%03d%s' % (i, os.path.splitext(img)[1].lower() or '.jpg')
            shutil.copyfile(img, os.path.join(img_dir, name))
            rel = os.path.basename(img_dir) + '/' + name
        elif not it.get('texte'):
            continue
        rows.append((it.get('texte') or '', rel, it.get('commentaire') or ''))
    if fmt == 'xlsx':
        if openpyxl is None:
            raise RuntimeError('openpyxl')
        wb = openpyxl.Workbook()
        ws = wb.active
        ws.append(['texte', 'image', 'commentaire'])
        for r in rows:
            ws.append(list(r))
        wb.save(path)
    else:
        import csv as _csv
        import io
        for delim in (';', ','):
            buf = io.StringIO()
            w = _csv.writer(buf, delimiter=delim, lineterminator='\n')
            w.writerow(['texte', 'image', 'commentaire'])
            for r in rows:
                w.writerow(r)
            data = buf.getvalue()
            sample = data[:4096]
            if (';' if sample.count(';') >= sample.count(',') else ',') == delim:
                break
        with open(path, 'w', encoding='utf-8-sig', newline='') as f:
            f.write(data)
    return len(rows)


def _ui_export_run(self, fmt):
    items = _ui_export_items()
    if not items:
        messagebox.showinfo(_TR('Exporter'), _TR('Aucune publication collectée pour le moment — lancez le mode automatique.'))
        return
    ext = {'zip': '.zip', 'csv': '.csv', 'xlsx': '.xlsx'}[fmt]
    name = 'autoposter_export_%s%s' % (time.strftime('%Y-%m-%d_%H%M'), ext)
    try:
        path = filedialog.asksaveasfilename(title=_TR('Exporter'), defaultextension=ext, initialfile=name,
                                            filetypes=[(fmt.upper(), '*' + ext)])
    except Exception:
        path = ''
    if not path:
        return
    try:
        n = _ui_export_write(items, path, fmt)
    except Exception as e:
        messagebox.showerror(_TR('Erreur'), '%s\n%s' % (_TR('Export impossible.'), e))
        return
    self.log('💾 %d publication(s) exportée(s) → %s' % (n, path))
    messagebox.showinfo(_TR('Exporter'), '%s\n%s' % (_TR('%d publication(s) exportée(s)' % n), path))


def _ui_export_clear(self):
    if messagebox.askyesno(_TR('Exporter'), _TR('Vider la liste des publications collectées ?')):
        with _UI_EXPORT_LOCK:
            try:
                os.remove(_ui_export_path())
            except Exception:
                pass
        _ui_export_refresh(self)


def _ui_build_export(self):
    import tkinter as _tk
    sc = self._sections.get('collecte')
    go = _ui_find(sc, lambda w: w.winfo_class() == 'Button'
                  and 'mode automatique' in str(getattr(w, '_i18n_src', '') or '')) if sc else None
    if go is None:
        return
    row = go.master
    ref = row.pack_slaves()[-1] if row.pack_slaves() else go
    opts = {}
    for k in ('font', 'relief', 'bd', 'padx', 'pady', 'cursor', 'highlightthickness'):
        try:
            opts[k] = ref.cget(k)
        except Exception:
            pass
    b = _tk.Button(row, text='', bg=C['accent'], fg='white', activebackground=C['accent2'],
                   activeforeground='white', **opts)
    b._i18n_src = None
    b.pack(side='left', padx=(8, 0))

    def menu(_e=None):
        m = _tk.Menu(b, tearoff=0)
        m.add_command(label='ZIP  (image + description.txt + comment.txt)',
                      command=lambda: _ui_export_run(self, 'zip'))
        m.add_command(label='CSV', command=lambda: _ui_export_run(self, 'csv'))
        m.add_command(label='Excel (XLSX)', command=lambda: _ui_export_run(self, 'xlsx'))
        m.add_separator()
        m.add_command(label=_TR('Vider les publications collectées'), command=lambda: _ui_export_clear(self))
        try:
            m.tk_popup(b.winfo_rootx(), b.winfo_rooty() + b.winfo_height())
        finally:
            m.grab_release()
    b.configure(command=menu)
    self._ui_export_btn = b
    _ui_export_refresh(self)


def _ui_export_refresh(self):
    b = getattr(self, '_ui_export_btn', None)
    if b is None:
        return
    n = len(_ui_export_items())
    try:
        _ui_raw_conf(b, text='%s (%d)' % (_TR('⤓ Exporter'), n))
    except Exception:
        pass


