# ======================================================================
# >>> UI v9 — link works with Hidden browsers ON · seconds interval ·
#     three relabelled titles
# ======================================================================
# In headless Chrome the clipboard is unreliable, and the composer often
# opens as a dialog whose <textbox> is momentarily covered (your log:
# "<div …> intercepts pointer events"). This inserts the link with
# beforeinput/execCommand (no clipboard, no fragile click) and confirms it,
# on the post page we already opened at publish time.
_UI_CMT_JS = r"""(args) => {
  const box = args.box, text = args.text;
  if (!box) return false;
  const setNativeCE = (el, val) => {
    el.focus();
    try {
      const sel = window.getSelection(); const r = document.createRange();
      r.selectNodeContents(el); sel.removeAllRanges(); sel.addRange(r);
      document.execCommand('delete', false, null);
    } catch (e) {}
    let okIns = false;
    try { okIns = document.execCommand('insertText', false, val); } catch (e) { okIns = false; }
    if (!okIns || !(el.innerText || '').trim()) {
      try {
        const ev = new InputEvent('beforeinput', {inputType: 'insertText', data: val, bubbles: true, cancelable: true});
        el.dispatchEvent(ev);
      } catch (e) {}
    }
    if (!(el.innerText || '').trim()) {
      el.textContent = val;
      try { el.dispatchEvent(new InputEvent('input', {inputType: 'insertText', data: val, bubbles: true})); } catch (e) {}
    }
    try { el.dispatchEvent(new Event('input', {bubbles: true})); } catch (e) {}
  };
  setNativeCE(box, text);
  return (box.innerText || box.textContent || '').toLowerCase().includes((text || '').toLowerCase().slice(0, 20));
}"""


def _ui_find_comment_box_headless(page, scope):
    sels = ('div[role="dialog"] div[role="textbox"][contenteditable="true"]',
            'div[role="textbox"][contenteditable="true"][aria-label*="comment" i]',
            'div[role="textbox"][contenteditable="true"][aria-label*="commentaire" i]',
            'div[role="textbox"][contenteditable="true"][aria-label*="تعليق"]',
            'form [contenteditable="true"]',
            'div[role="textbox"][contenteditable="true"]',
            '[contenteditable="true"]')
    for root in ([scope, page] if scope is not None and scope is not page else [page]):
        for sel in sels:
            try:
                loc = root.locator(sel)
                n = min(loc.count(), 6)
            except Exception:
                continue
            for k in range(n):
                cb = loc.nth(k)
                try:
                    if cb.is_visible() and cb.bounding_box():
                        return cb
                except Exception:
                    continue
    return None


def _ui_headless_comment(self, page, commentaire, slot_id, post_num):
    """Robust link insertion for headless posting. Returns True on success,
    False to let the app's own routine try, None if we could not act."""
    needle = (commentaire or '').strip().split('\n')[0][:24].lower()
    try:
        page.wait_for_selector('div[role="textbox"][contenteditable="true"], [contenteditable="true"]', timeout=9000)
    except Exception:
        pass
    try:
        page.wait_for_timeout(1200)
    except Exception:
        pass
    cb = _ui_find_comment_box_headless(page, None)
    if cb is None:
        return None
    try:
        cb.scroll_into_view_if_needed(timeout=3000)
    except Exception:
        pass
    for attempt in range(2):
        try:
            handle = cb.element_handle()
            ins = page.evaluate(_UI_CMT_JS, {'box': handle, 'text': commentaire})
        except Exception:
            ins = False
        if not ins:                                   # last resort: real typing
            try:
                cb.click(timeout=3000)
                page.keyboard.press('Control+A')
                page.keyboard.press('Delete')
                cb.type(commentaire, delay=12)
                page.wait_for_timeout(400)
            except Exception:
                pass
        try:
            typed = (cb.inner_text(timeout=1500) or '').lower()
        except Exception:
            typed = ''
        if needle and needle not in typed:
            page.wait_for_timeout(500)
            continue
        try:
            cb.press('Enter')
        except Exception:
            try:
                page.keyboard.press('Enter')
            except Exception:
                pass
        page.wait_for_timeout(3500)
        # confirmed if the box cleared, or the link now shows on the post
        ok_sent = False
        try:
            ok_sent = ((cb.inner_text(timeout=1500) or '').strip() == '')
        except Exception:
            ok_sent = True                            # box detached = submitted
        if not ok_sent and needle:
            try:
                ok_sent = needle in (page.locator('div[role="article"]').first.inner_text(timeout=2500) or '').lower()
            except Exception:
                pass
        if not ok_sent:
            try:
                if self._cm_click_send(cb):
                    page.wait_for_timeout(2500)
                    ok_sent = True
            except Exception:
                pass
        if ok_sent:
            self.log('✅ Commentaire posté — Compte %s · post %s' % (slot_id, post_num))
            return True
        page.wait_for_timeout(500)
    return False


_ui_orig_add_comment_once_v9 = FacebookMultiPosterApp._add_comment_once


def _ui_add_comment_once_v9(self, page, commentaire, slot_id, post_num, attempt=1, check_existing=False):
    # make sure we are on OUR post (captured at publish time), then try the
    # headless-safe insertion first; fall back to the app's own routine
    info = (getattr(self, '_ui_last_pub', {}) or {}).get(slot_id) or {}
    perma = info.get('permalink')
    if perma:
        try:
            cur = (page.url or '').split('?')[0].rstrip('/')
            if cur != perma.split('?')[0].rstrip('/'):
                page.goto(perma, wait_until='domcontentloaded', timeout=30000)
                page.wait_for_timeout(2500)
        except Exception:
            pass
    if perma or bool(re.search(r'/posts/|/permalink/|permalink\.php|story_fbid=', (page.url or ''))):
        try:
            r = _ui_headless_comment(self, page, commentaire, slot_id, post_num)
        except Exception:
            r = None
        if r is True:
            return True
    return _ui_orig_add_comment_once_v9(self, page, commentaire, slot_id, post_num, attempt, check_existing)


FacebookMultiPosterApp._add_comment_once = _ui_add_comment_once_v9


# ------------------------------------------------- seconds interval
def _ui_dur_to_seconds(v, default=None):
    """'0.30' → 30 s, '5' → 5 min, '90s' → 90 s. In this tool the value is
    minutes; a fractional value is read as a mm.ss style seconds amount
    (0.30 = 30 s, 1.30 = 1 min 30 s), matching the user's request."""
    s = str(v).strip().lower().replace(',', '.')
    if not s:
        return default
    unit = None
    if s.endswith('s') and not s.endswith('ms'):
        unit, s = 'sec', s[:-1].strip()
    elif s.endswith('m') or s.endswith('min'):
        unit, s = 'min', s.rstrip('min').strip()
    try:
        f = float(s)
    except Exception:
        return default
    if unit == 'sec':
        return max(1, int(round(f)))
    if unit == 'min':
        return max(1, int(round(f * 60)))
    if f == int(f):                       # whole number → minutes (5 → 300 s)
        return max(1, int(f) * 60)
    whole = int(f)                        # fraction → mm.ss (0.30 → 30 s)
    frac = round((f - whole) * 100)
    if frac >= 60:                        # e.g. 0.90 → 90 s
        return max(1, whole * 60 + frac)
    return max(1, whole * 60 + frac)


_UI_SECS = {'min': None, 'max': None}     # seconds chosen for the current run


_ui_orig_run_automation_v9 = FacebookMultiPosterApp.run_automation


def _ui_run_automation_v9(self, group_urls, interval_min, slots, publications, target_type='groupe',
                          interval_max=None, group_mode='rotation', *a, **kw):
    """Read the Min/Max fields directly so decimals like 0.30 (= 30 s) work.
    The app multiplies its interval by 60, so we hand it a value in *minutes*
    (possibly fractional) that the wait turns back into the right seconds."""
    try:
        smin = _ui_dur_to_seconds(self.interval_var.get(), None)
        smax = _ui_dur_to_seconds(self.interval_max_var.get(), smin)
        if smin is not None:
            if smax is None or smax < smin:
                smax = smin
            _UI_SECS['min'], _UI_SECS['max'] = smin, smax
            # v7 "irregular delays" for ZIP widened the range already; keep it
            interval_min = smin / 60.0
            interval_max = smax / 60.0
            self.log('⏱️ Temps entre publications : %s à %s.'
                     % (_ui_fmt_dur(smin), _ui_fmt_dur(smax)))
    except Exception:
        pass
    return _ui_orig_run_automation_v9(self, group_urls, interval_min, slots, publications,
                                      target_type, interval_max, group_mode, *a, **kw)


def _ui_fmt_dur(secs):
    secs = int(secs)
    if secs < 60:
        return '%d s' % secs
    if secs % 60 == 0:
        return '%d min' % (secs // 60)
    return '%d min %02d s' % (secs // 60, secs % 60)


FacebookMultiPosterApp.run_automation = _ui_run_automation_v9

# start_posting parses int(interval) and would reject "0.30"; pre-validate
# with the seconds parser so a decimal no longer shows the "entier" error
_ui_orig_start_posting_v9 = FacebookMultiPosterApp.start_posting


def _ui_start_posting_v9(self, *a, **kw):
    try:
        if _ui_dur_to_seconds(self.interval_var.get(), None) is None:
            messagebox.showerror(_TR('Erreur'), _TR("Le temps minimum est invalide (ex : 0.30 = 30 s, 5 = 5 min)."))
            return None
        # feed start_posting's own int() parse a safe integer; the real
        # (possibly fractional) timing is applied in run_automation
        self._ui_int_backup = (self.interval_var.get(), self.interval_max_var.get())
        self._ui_int_backup_t = time.time()
        self._ui_int_backup_t = time.time()
        smin = _ui_dur_to_seconds(self.interval_var.get(), 60)
        smax = _ui_dur_to_seconds(self.interval_max_var.get(), smin)
        self.interval_var.set(str(max(1, int(round(smin / 60.0)))))
        self.interval_max_var.set(str(max(1, int(round(max(smax, smin) / 60.0)))))
    except Exception:
        pass

    def restore():
        try:
            b = getattr(self, '_ui_int_backup', None)
            if b:
                self.interval_var.set(b[0])
                self.interval_max_var.set(b[1])
        except Exception:
            pass
    try:
        r = _ui_orig_start_posting_v9(self, *a, **kw)
    finally:
        try:
            self.root.after(1500, restore)
        except Exception:
            restore()
    return r


FacebookMultiPosterApp.start_posting = _ui_start_posting_v9


