# >>> UI v10 — every setting saved on close & restored on start ·
#     connected accounts come back automatically · clear ZIP messages
# ======================================================================
_UI_SET_SKIP = ('_progress_var', 'group_url_var', 'csv_path_var', 'csv_path_var_input')
_UI_SET_LOCK = _ui_threading.Lock()


def _ui_settings_path():
    return os.path.join(SESSION_BASE, 'ui_settings.json')


def _ui_proxy_line(p):
    try:
        srv = str(p.get('server') or '').strip()
        if not srv:
            return ''
        if p.get('username'):
            scheme, rest = (srv.split('://', 1) + [''])[:2] if '://' in srv else ('http', srv)
            return '%s://%s:%s@%s' % (scheme, p.get('username'), p.get('password') or '', rest)
        return srv
    except Exception:
        return ''


def _ui_settings_collect(self):
    import tkinter as _tk
    d = {'version': 1, 'vars': {}, 'texts': {}, 'lists': {}, 'accounts': {}, 'cm_sel': {},
         'theme': _CURRENT_THEME[0]}
    back = getattr(self, '_ui_int_backup', None)
    recent = back and (time.time() - getattr(self, '_ui_int_backup_t', 0) < 5)
    for name, v in list(vars(self).items()):
        try:
            if isinstance(v, _tk.Variable):
                if (name.startswith('_ui_') or name in _UI_SET_SKIP
                        or 'progress' in name or 'status' in name):
                    continue
                d['vars'][name] = v.get()
            elif isinstance(v, _tk.Text) and 'log' not in name.lower():
                d['texts'][name] = v.get('1.0', 'end-1c')
        except Exception:
            pass
    if recent:
        d['vars']['interval_var'], d['vars']['interval_max_var'] = back
    zr = _ui_zip_root()
    d['lists'] = {
        'group_urls_list': list(getattr(self, 'group_urls_list', []) or []),
        'csv_paths_list': [p for p in (getattr(self, 'csv_paths_list', []) or [])
                           if not os.path.normcase(os.path.abspath(p)).startswith(zr + os.sep)],
        'schedule_slots': [dict(x) for x in (getattr(self, 'schedule_slots', []) or [])
                           if isinstance(x, dict)],
        'proxies': [l for l in (_ui_proxy_line(p) for p in (getattr(self, 'proxys_list', []) or [])) if l],
    }
    try:
        with self._accounts_lock:
            items = [(sid, dict(a)) for sid, a in self.accounts.items()]
    except Exception:
        items = list((getattr(self, 'accounts', {}) or {}).items())
    conn = [sid for sid, a in items if a.get('connected')]
    pend = getattr(self, '_ui_reconnect_pending', None) or set()
    if pend and time.time() < getattr(self, '_ui_reconnect_until', 0):
        conn = sorted(set(conn) | set(pend))
    d['accounts'] = {'connected': conn,
                     'selected': [sid for sid, a in items if a.get('selected')],
                     'post_active': {str(sid): bool(a.get('post_active')) for sid, a in items}}
    try:
        d['cm_sel'] = {str(sid): bool(v.get()) for sid, v in (getattr(self, '_cm_slot_vars', {}) or {}).items()}
    except Exception:
        pass
    try:
        if getattr(self, '_standalone', False):
            top = self.root.winfo_toplevel()
            d['zoomed'] = (str(top.state()) == 'zoomed')
            if not d['zoomed'] and str(top.state()) == 'normal':
                d['geometry'] = top.geometry()
    except Exception:
        pass
    return d


def _ui_settings_save(self, force=False):
    import json
    try:
        d = _ui_settings_collect(self)
        txt = json.dumps(d, ensure_ascii=False, indent=1, sort_keys=True)
    except Exception:
        return False
    if not force and txt == getattr(self, '_ui_settings_last', None):
        return True
    with _UI_SET_LOCK:
        try:
            os.makedirs(SESSION_BASE, exist_ok=True)
            tmp = _ui_settings_path() + '.tmp'
            with open(tmp, 'w', encoding='utf-8') as f:
                f.write(txt)
            os.replace(tmp, _ui_settings_path())
            self._ui_settings_last = txt
            return True
        except Exception:
            return False


def _ui_settings_restore(self):
    """Bring back every saved setting; lists go through the app's own buttons."""
    import json
    import tkinter as _tk
    try:
        with open(_ui_settings_path(), encoding='utf-8') as f:
            d = json.load(f)
    except Exception:
        return False
    for name, val in (d.get('vars') or {}).items():
        v = getattr(self, name, None)
        if isinstance(v, _tk.Variable):
            try:
                v.set(val)
            except Exception:
                pass
    for name, txt in (d.get('texts') or {}).items():
        w = getattr(self, name, None)
        if isinstance(w, _tk.Text):
            try:
                st = str(w.cget('state'))
                if st == 'disabled':
                    w.configure(state='normal')
                w.delete('1.0', 'end')
                w.insert('1.0', txt)
                if st == 'disabled':
                    w.configure(state='disabled')
            except Exception:
                pass
    L = d.get('lists') or {}
    try:
        urls = [u for u in (L.get('group_urls_list') or []) if u]
        if urls and urls != list(self.group_urls_list):
            _ui_apply_urls(self, urls)
    except Exception:
        pass
    try:
        csvs = [p for p in (L.get('csv_paths_list') or []) if os.path.isfile(p)]
        if csvs and csvs != list(self.csv_paths_list):
            _ui_apply_csv(self, csvs)
    except Exception:
        pass
    try:
        slots = L.get('schedule_slots') or []
        have = [(x.get('start'), x.get('end')) for x in (self.schedule_slots or []) if isinstance(x, dict)]
        add = _ui_find(self._sections.get('horaires'),
                       lambda w: w.winfo_class() == 'Button' and getattr(w, '_i18n_src', None) == '+ Ajouter')
        if add is not None:
            keep = (self._sched_start_var.get(), self._sched_end_var.get())
            for x in slots:
                if (x.get('start'), x.get('end')) in have:
                    continue
                self._sched_start_var.set(x.get('start', ''))
                self._sched_end_var.set(x.get('end', ''))
                _ui_invoke(add)
            self._sched_start_var.set(keep[0])
            self._sched_end_var.set(keep[1])
    except Exception:
        pass
    try:
        prox = L.get('proxies') or []
        if prox and not (getattr(self, 'proxys_list', []) or []):
            imp = _ui_find(self._sections.get('campagne'),
                           lambda w: w.winfo_class() == 'Button'
                           and 'Importer TXT' in str(getattr(w, '_i18n_src', '') or ''))
            if imp is not None:
                tmp = os.path.join(SESSION_BASE, 'ui_proxies_restore.txt')
                with open(tmp, 'w', encoding='utf-8') as f:
                    f.write('\n'.join(prox))
                orig = filedialog.askopenfilename
                try:
                    filedialog.askopenfilename = lambda *a, **k: tmp
                    _ui_invoke(imp)
                finally:
                    filedialog.askopenfilename = orig
                pv = (d.get('vars') or {}).get('proxy_enabled_var')
                if pv is not None:
                    self.proxy_enabled_var.set(bool(pv))
    except Exception:
        pass
    acc = d.get('accounts') or {}
    try:
        sel = set(int(s) for s in (acc.get('selected') or []))
        for sid, a in self.accounts.items():
            a['selected'] = sid in sel
            try:
                self.update_account_ui(sid)
            except Exception:
                pass
    except Exception:
        pass
    self._ui_pending_post_active = {int(k): bool(v) for k, v in (acc.get('post_active') or {}).items()}
    self._ui_pending_cm_sel = {int(k): bool(v) for k, v in (d.get('cm_sel') or {}).items()}
    try:
        if d.get('theme') in ('light', 'dark') and d['theme'] != _CURRENT_THEME[0]:
            self.toggle_theme()
    except Exception:
        pass
    try:
        if getattr(self, '_standalone', False):
            top = self.root.winfo_toplevel()
            if d.get('geometry'):
                top.geometry(d['geometry'])
            if d.get('zoomed'):
                try:
                    top.state('zoomed')
                except Exception:
                    pass
    except Exception:
        pass
    # accounts that were connected come back on their own (instant cookie
    # check of each saved browser profile, exactly like "Connect selection")
    try:
        sids = [int(s) for s in (acc.get('connected') or []) if int(s) in self.accounts]
        self._ui_reconnect_pending = set(sids)
        self._ui_reconnect_until = time.time() + 90
        if sids:
            def _go():
                try:
                    self.log('🔄 Reconnexion automatique de %d compte(s) (sessions enregistrées)…' % len(sids))
                    self._start_thread(self._check_sessions_sequential, (sids,), name='auto-reconnect')
                except Exception:
                    pass
            self.root.after(1200, _go)
    except Exception:
        pass
    return True


def _ui_apply_pending(self):
    """Once accounts are back online, re-apply their saved POST switch and
    their saved selection in 'Commenting accounts'."""
    pend = getattr(self, '_ui_reconnect_pending', None)
    if pend:
        try:
            alive = any(t.name == 'auto-reconnect' and t.is_alive() for t in _ui_threading.enumerate())
        except Exception:
            alive = True
        if not alive and time.time() > getattr(self, '_ui_reconnect_until', 0) - 88:
            self._ui_reconnect_pending = set()
    pa = getattr(self, '_ui_pending_post_active', None)
    if pa:
        for sid in list(pa):
            a = self.accounts.get(sid)
            if a and a.get('connected') and not a.get('connecting'):
                a['post_active'] = pa.pop(sid)
                try:
                    self.update_account_ui(sid)
                except Exception:
                    pass
    cs = getattr(self, '_ui_pending_cm_sel', None)
    if cs:
        for sid, v in list((getattr(self, '_cm_slot_vars', {}) or {}).items()):
            if sid in cs:
                try:
                    v.set(cs.pop(sid))
                except Exception:
                    pass


