def _ui_zip_publications_raw(self):
    out = []
    for _zp, csvp, _n in list(getattr(self, '_ui_zip_items', []) or []):
        for p in _ui_read_zip_csv(csvp):
            if p['image'] and not os.path.isfile(p['image']):
                continue
            out.append(p)
    return out


def _ui_zip_forget(keys):
    import json
    with _UI_ZIPMEM_LOCK:
        mem = _ui_zip_memory() - set(keys)
        try:
            with open(_ui_zip_mem_path(), 'w', encoding='utf-8') as f:
                json.dump(sorted(mem), f)
        except Exception:
            pass


_ui_orig_start_posting_v10 = FacebookMultiPosterApp.start_posting


def _ui_start_posting_v10(self, *a, **kw):
    """ZIP method: never show the misleading "CSV/XLSX" error. If every ZIP
    deal was already posted (anti-duplicate memory), ask to post them again."""
    if not getattr(self, 'is_running', False) and not getattr(self, '_sc_running', False):
        if _ui_source(self) == 'zip' and (getattr(self, '_ui_zip_items', []) or []):
            raw = _ui_zip_publications_raw(self)
            if not raw:
                messagebox.showerror(_TR('Erreur'), _TR('Les images du fichier ZIP sont introuvables — importez le ZIP à nouveau.'))
                return None
            if _UI_ZIPOPT['dedup']:
                mem = _ui_zip_memory()
                keys = [_ui_zip_key(p) for p in raw]
                if all(k in mem for k in keys):
                    msg = '%s\n\n%s' % (_TR('Toutes les publications de vos fichiers ZIP ont déjà été postées (mémoire anti-doublon).'),
                                        _TR('Voulez-vous les publier à nouveau ?'))
                    if messagebox.askyesno(_TR('Mémoire anti-doublon'), msg):
                        _ui_zip_forget(keys)
                        self.log('♻️ ZIP : mémoire anti-doublon vidée pour %d publication(s).' % len(keys))
                    else:
                        return None
    return _ui_orig_start_posting_v10(self, *a, **kw)


FacebookMultiPosterApp.start_posting = _ui_start_posting_v10


