# ======================================================================
# >>> UI v11 — per-account PROXY column in Facebook Accounts
#     switch ON/OFF · green = working · red = not working · grey = not used
# ======================================================================
_UI_ACC_PROXY = {}          # sid -> {'enabled': bool, 'proxy': str}   (read by workers)
_UI_ACC_PSTAT = {}          # sid -> (state, ms, message)  state: ok|bad|checking
_UI_PX_LOCK = _ui_threading.Lock()
_UI_PX_TARGET = ('www.facebook.com', 443)
_UI_PX_TLS = True           # also finish a TLS handshake with Facebook through the tunnel
_UI_PX_TIMEOUT = 10


def _ui_px_path():
    return os.path.join(SESSION_BASE, 'account_proxies.json')


def _ui_px_load():
    import json
    try:
        with open(_ui_px_path(), encoding='utf-8') as f:
            d = json.load(f) or {}
        out = {}
        for k, v in d.items():
            if isinstance(v, dict):
                out[int(k)] = {'enabled': bool(v.get('enabled')), 'proxy': str(v.get('proxy') or '')}
        return out
    except Exception:
        return {}


def _ui_px_save():
    import json
    with _UI_PX_LOCK:
        data = {str(k): dict(v) for k, v in _UI_ACC_PROXY.items() if v.get('proxy') or v.get('enabled')}
    try:
        os.makedirs(SESSION_BASE, exist_ok=True)
        tmp = _ui_px_path() + '.tmp'
        with open(tmp, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
        os.replace(tmp, _ui_px_path())
    except Exception:
        pass


def _ui_px_parse(s):
    """ip:port · ip:port:user:pass · user:pass@ip:port · scheme://[user:pass@]ip:port
    (schemes: http, https, socks5, socks5h). Returns dict or None."""
    s = (s or '').strip()
    if not s:
        return None
    scheme = 'http'
    m = re.match(r'^(https?|socks5h?)://(.+)$', s, re.I)
    if m:
        scheme, s = m.group(1).lower(), m.group(2)
    s = s.rstrip('/')
    user = pwd = None
    if '@' in s:
        cred, hostport = s.rsplit('@', 1)
        user, _, pwd = cred.partition(':')
    else:
        parts = s.split(':')
        if len(parts) == 4:
            hostport = parts[0] + ':' + parts[1]
            user, pwd = parts[2], parts[3]
        elif len(parts) == 2:
            hostport = s
        else:
            return None
    host, _, port = hostport.rpartition(':')
    host = host.strip('[]')
    if not host or not port.isdigit() or not (0 < int(port) < 65536):
        return None
    if not re.match(r'^[A-Za-z0-9.\-_]+$', host):
        return None
    return {'scheme': scheme, 'host': host, 'port': int(port), 'user': user or None, 'pwd': pwd or None}


def _ui_px_for_playwright(p):
    sch = 'socks5' if p['scheme'].startswith('socks5') else p['scheme']
    d = {'server': '%s://%s:%d' % (sch, p['host'], p['port'])}
    if p.get('user'):
        d['username'] = p['user']
        d['password'] = p.get('pwd') or ''
    return d


def _ui_px_probe(p, target=None, timeout=None, tls=None):
    """Open a real tunnel to Facebook through the proxy. (ok, ms, message)"""
    import socket
    import struct
    import base64
    th, tp = target or _UI_PX_TARGET
    timeout = timeout or _UI_PX_TIMEOUT
    tls = _UI_PX_TLS if tls is None else tls
    if p['scheme'].startswith('socks5') and p.get('user'):
        return (False, 0, 'SOCKS5 + login is not supported by Chrome — use an HTTP proxy '
                          'or a SOCKS5 proxy without login (IP allow-list).')
    t0 = time.time()
    try:
        s = socket.create_connection((p['host'], p['port']), timeout=timeout)
    except Exception as e:
        return (False, 0, 'cannot reach the proxy (%s)' % (e.__class__.__name__,))
    try:
        s.settimeout(timeout)
        if p['scheme'].startswith('socks5'):
            s.sendall(b'\x05\x01\x00')
            r = s.recv(2)
            if len(r) < 2 or r[0] != 5 or r[1] != 0:
                return (False, 0, 'not a SOCKS5 proxy (or it requires a login)')
            hb = th.encode('idna')
            s.sendall(b'\x05\x01\x00\x03' + bytes([len(hb)]) + hb + struct.pack('>H', tp))
            rep = s.recv(10)
            if len(rep) < 2 or rep[1] != 0:
                return (False, 0, 'the proxy refused the connection to Facebook')
        else:
            req = 'CONNECT %s:%d HTTP/1.1\r\nHost: %s:%d\r\n' % (th, tp, th, tp)
            if p.get('user'):
                tok = base64.b64encode(('%s:%s' % (p['user'], p.get('pwd') or '')).encode('utf-8')).decode()
                req += 'Proxy-Authorization: Basic %s\r\n' % tok
            s.sendall((req + '\r\n').encode('latin-1'))
            resp = b''
            while b'\r\n\r\n' not in resp and len(resp) < 8192:
                chunk = s.recv(2048)
                if not chunk:
                    break
                resp += chunk
            line = resp.split(b'\r\n', 1)[0].decode('latin-1', 'replace').strip()
            if not re.match(r'^HTTP/\d(\.\d)?\s+200\b', line):
                if ' 407' in line:
                    return (False, 0, 'wrong proxy username or password (407)')
                return (False, 0, 'the proxy answered: %s' % (line[:60] or 'nothing'))
        if tls:
            import ssl
            ctx = ssl.create_default_context()
            ss = ctx.wrap_socket(s, server_hostname=th)
            try:
                ss.do_handshake()
            finally:
                try:
                    ss.close()
                except Exception:
                    pass
        return (True, int((time.time() - t0) * 1000), 'OK')
    except Exception as e:
        return (False, 0, '%s' % (str(e)[:80] or e.__class__.__name__))
    finally:
        try:
            s.close()
        except Exception:
            pass


def _ui_px_test(sid):
    """Background test of one account's proxy (never touches Tk)."""
    ap = _UI_ACC_PROXY.get(sid) or {}
    p = _ui_px_parse(ap.get('proxy'))
    if p is None:
        _UI_ACC_PSTAT[sid] = ('bad', 0, 'invalid format') if ap.get('proxy') else ('', 0, '')
        return
    _UI_ACC_PSTAT[sid] = ('checking', 0, '')

    def run():
        ok, ms, msg = _ui_px_probe(p)
        cur = _ui_px_parse((_UI_ACC_PROXY.get(sid) or {}).get('proxy'))
        if cur == p:                                     # still the same proxy?
            _UI_ACC_PSTAT[sid] = ('ok' if ok else 'bad', ms, msg)
    _ui_threading.Thread(target=run, daemon=True, name='proxy-test-%s' % sid).start()


def _ui_px_state(sid):
    ap = _UI_ACC_PROXY.get(sid) or {}
    if not ap.get('enabled') or not ap.get('proxy'):
        return 'off'
    return (_UI_ACC_PSTAT.get(sid) or ('checking',))[0] or 'checking'


def _ui_px_show(txt):
    p = _ui_px_parse(txt)
    if p is None:
        return (txt or '').strip()
    return '%s:%d' % (p['host'], p['port'])


# ------------------------------------------- column: zones + drawing
_UI_PX_COLORS = {
    'ok': ('#bbf7d0', '#14532d'), 'bad': ('#fecaca', '#991b1b'),
    'checking': ('#fde68a', '#78350f'), 'off': (None, None)}

_ui_orig_row_zones = FacebookMultiPosterApp._row_zones


def _ui_row_zones(self, W, *a, **kw):
    """Same columns as before, plus a Proxy column carved from the right of the
    (flexible) account-name column. Post-as / Status are trimmed a little to
    make room; their longest content still fits."""
    W2, z = _ui_orig_row_zones(self, W, *a, **kw)
    try:
        x = W2 - 6
        for name, w in (('act2', 90), ('act1', 58), ('page', 96), ('post', 56), ('stat', 92)):
            z[name] = (x - w, x)
            x -= w + 1
        n1, n2 = z['name'][0], max(150, x - 10)
        avail = n2 - n1
        pw = min(150, avail - 84)                         # keep ~10 chars of name
        if pw >= 110:
            z['proxy'] = (n2 - pw, n2)
        elif avail - 60 >= 56:
            pw = 56
            z['proxy'] = (n2 - pw, n2)                    # compact: switch + dot
        else:
            z['name'] = (n1, n2)
            return (W2, z)
        z['name'] = (n1, n2 - pw - 6)
    except Exception:
        pass
    return (W2, z)


FacebookMultiPosterApp._row_zones = _ui_row_zones


def _ui_px_switch_img(w, on):
    return _ui_photo(w, ('pxsw', on), lambda: _ui_render_switch(on, 38, 16, _UI_SWITCH_ON, _UI_SWITCH_OFF))


def _ui_px_globe_img(w):
    def make():
        S = 13
        cv = _UICanvas(S, S)
        col = _ui_hex(C['text3'])
        c = S / 2.0
        cv.paint(_sd_ring(c, c, c - 0.9, c - 0.9, 0.55), col)
        cv.paint(_sd_ring(c, c, (c - 0.9) * 0.45, c - 0.9, 0.5), col)
        cv.paint(_sd_capsule(1.2, c, S - 1.2, c, 0.5), col)
        return cv.png()
    return _ui_photo(w, ('pxglobe', C['text3']), make)


_UI_PX_FONTS = {}


def _ui_px_measure(w, fnt):
    """Exact pixel width of text in this font (cached per Tk interpreter)."""
    import tkinter.font as _tkf
    key = (w.tk, fnt, _UI_ZOOM[0])
    f = _UI_PX_FONTS.get(key)
    if f is None:
        f = _tkf.Font(root=w, family=fnt[0], size=_ui_scaled([fnt[0], fnt[1]], _UI_ZOOM[0])[1])
        _UI_PX_FONTS[key] = f
    return f.measure


def _ui_px_draw_row(app, cv, sid, z, mid, o_ct, o_ci):
    """Drawn inside the row's own redraw, right after the account name."""
    x1, x2 = z['proxy']
    ap = _UI_ACC_PROXY.get(sid) or {}
    o_ci(cv, x1, mid, image=_ui_px_switch_img(cv, bool(ap.get('enabled'))), anchor='w')
    st = _ui_px_state(sid)
    bx1 = x1 + 42
    bg, fg = _UI_PX_COLORS.get(st, (None, None))
    if bg is None:
        bg, fg = C['surface3'], C['text3']
    bw = x2 - bx1
    if bw >= 50:
        img = _ui_photo(cv, ('pxbox', bw, bg), lambda: _ui_render_button(bw, 20, 5, bg))
        o_ci(cv, bx1, mid, image=img, anchor='w')
        txt = _ui_px_show(ap.get('proxy')) or '+ Proxy'
        fnt = ('Consolas', 8)
        room = bw - 12
        meas = _ui_px_measure(cv, fnt)
        if meas(txt) > room and ':' in txt:
            txt = txt.rsplit(':', 1)[0]                   # IP only when the port won't fit
        while len(txt) > 3 and meas(txt) > room:
            txt = txt[:-2] + '…'
        o_ct(cv, bx1 + 6, mid, text=txt, anchor='w', font=fnt, fill=fg)
    else:
        dot = _ui_photo(cv, ('pxdot', bg), lambda: _ui_render_button(12, 12, 6, bg))
        o_ci(cv, bx1 + 2, mid, image=dot, anchor='w')


def _ui_install_proxy_hook():
    """Draw the proxy cell whenever a row draws its account name."""
    import tkinter as _tk
    if getattr(_tk.Canvas, '_ui_px_hooked', False):
        return
    prev_ct = _tk.Canvas.create_text
    base_ct = getattr(_tk.Canvas, '_ui_base_create_text', None)

    def create_text(self, *a, **kw):
        r = prev_ct(self, *a, **kw)
        try:
            if kw.get('anchor') == 'w' and 'Semibold' in str(kw.get('font', '')):
                app = globals().get('_CURRENT_APP')
                cvs = getattr(app, 'account_canvases', None) if app is not None else None
                if cvs:
                    sid = next((s for s, c in cvs.items() if c is self), None)
                    if sid is not None:
                        co = _ui_flat(a)
                        _W, z = app._row_zones(self.winfo_width())
                        if 'proxy' in z and len(co) >= 2 and abs(float(co[0]) - z['name'][0]) < 1:
                            _ui_px_draw_row(app, self, sid, z, float(co[1]),
                                            lambda cv, *aa, **kk: prev_ct(cv, *aa, **kk),
                                            lambda cv, *aa, **kk: _tk.Canvas.create_image(cv, *aa, **kk))
        except Exception:
            pass
        return r
    _tk.Canvas.create_text = create_text
    _tk.Canvas._ui_px_hooked = True
    _tk.Canvas._ui_base_create_text = base_ct or prev_ct


_ui_install_proxy_hook()

