def _ui13_raise(w):
    """Raise a widget (Canvas.lift would raise canvas items instead)."""
    try:
        w.tk.call('raise', w._w)
    except Exception:
        pass


def _ui13_is_dark():
    return _CURRENT_THEME[0] == 'dark'


def _ui13_rgb(t):
    return '#%02x%02x%02x' % tuple(max(0, min(255, int(round(v)))) for v in t)


def _ui13_tint(col, t, base=None):
    return _ui13_rgb(_ui_mix(_ui_hex(base or _SB['bg']), _ui_hex(col), t))


def _ui13_key(col):
    """Palette key of a colour (current theme first), or None."""
    if not isinstance(col, str) or not col.startswith('#'):
        return None
    c = col.lower()
    cur = C_DARK if _ui13_is_dark() else C_LIGHT
    oth = C_LIGHT if cur is C_DARK else C_DARK
    for d in (cur, oth):
        for k, v in d.items():
            if v == c:
                return k
    return None


# ------------------------------------------------ switches (plain pills)
def _ui13_render_toggle(on, W, H, on_col, off_col, gap=0, rtl=False):
    cv = _UICanvas(W + gap, H)
    ox = gap if rtl else 0
    r = H / 2.0
    cy = H / 2.0
    cv.paint(_sd_capsule(ox + r, cy, ox + W - r, cy, r - 0.5), _ui_hex(on_col if on else off_col))
    R = r - 2.2
    kx = (ox + W - r) if on else (ox + r)
    cv.paint(_sd_circle(kx, cy + 0.7, R), (15, 23, 42), 0.22)
    cv.paint(_sd_circle(kx, cy, R), (255, 255, 255))
    return cv.png()


def _ui_switch_img(w, on):
    z = _UI_ZOOM[0]
    H = max(12, int(round(16 * z)))
    W = int(round(H * 1.8))
    gap = int(round(8 * z))
    off = '#475569' if _ui13_is_dark() else _UI_SWITCH_OFF
    return _ui_photo(w, ('sw13', on, W, H, gap, _UI_SWITCH_ON, off),
                     lambda: _ui13_render_toggle(on, W, H, _UI_SWITCH_ON, off, gap=gap))


def _ui13_render_pill(W, H, r, fill, border=None, shadow=False):
    cv = _UICanvas(W, H)
    yb = H - (2 if shadow else 0)
    if shadow:
        cv.paint(_sd_rbox(0.5, 1.5, W - 0.5, H - 0.2, r), (15, 23, 42), 0.10)
    if border:
        cv.paint(_sd_rbox(0.5, 0.5, W - 0.5, yb - 0.5, r), _ui_hex(border))
        cv.paint(_sd_rbox(1.5, 1.5, W - 1.5, yb - 1.5, max(1.0, r - 1)), _ui_hex(fill))
    else:
        cv.paint(_sd_rbox(0.5, 0.5, W - 0.5, yb - 0.5, r), _ui_hex(fill))
    return cv.png()


def _ui13_pill_img(w, W, H, r, fill, border=None, shadow=False):
    return _ui_photo(w, ('pill13', W, H, r, fill, border, shadow),
                     lambda: _ui13_render_pill(W, H, r, fill, border, shadow))


# ------------------------------------------------------ colour guards
def _ui13_guard(w, fix):
    """Instance-level configure/config filter: every colour the app (or the
    theme walk) pushes into this widget is translated by `fix`."""
    if getattr(w, '_ui13_fix', None) is fix:
        return
    cls_conf = type(w).configure

    def configure(cnf=None, **kw):
        if isinstance(cnf, str):
            return cls_conf(w, cnf)
        if cnf is None and not kw:
            return cls_conf(w)
        if isinstance(cnf, dict):
            kw = dict(cnf, **kw)
        try:
            kw = fix(kw)
        except Exception:
            pass
        return cls_conf(w, **kw)
    w.configure = configure
    w.config = configure
    w._ui13_fix = fix


_SB_BG_MAP = {'surface': 'bg', 'bg': 'bg', 'surface2': 'hover', 'surface3': 'hover',
              'glass_tile': 'bg', 'glass_shine': 'bg', 'g_ind_3': 'active', 'g_ind_1': 'active',
              'border': 'line', 'border2': 'line', 'glass_edge': 'line'}
_SB_FG_MAP = {'text': 'white', 'text2': 'text', 'text3': 'muted', 'accent': 'white',
              'accent2': 'white', 'accent_lt': 'pill_fg', 'success': 'green', 'success2': 'green',
              'g_grn_1': 'green', 'g_grn_2': 'green', 'danger': 'rose', 'warning': 'amber',
              'bg': 'white', 'surface': 'white'}


def _ui13_sb_fix(kw):
    for opt in ('bg', 'background', 'activebackground', 'highlightbackground',
                'highlightcolor', 'selectcolor'):
        k = _ui13_key(kw.get(opt))
        if k is not None:
            kw[opt] = _SB[_SB_BG_MAP.get(k, 'bg')]
    for opt in ('fg', 'foreground', 'activeforeground'):
        k = _ui13_key(kw.get(opt))
        if k is not None:
            kw[opt] = _SB[_SB_FG_MAP.get(k, 'text')]
    return kw


def _ui13_guard_tree(root_w, fix):
    for w in _ui_walk(root_w):
        try:
            _ui13_guard(w, fix)
        except Exception:
            pass


# ------------------------------------------------------------ sidebar
def _ui13_sidebar_of(self):
    try:
        return self.start_btn.master.master.master       # sb_btn_f > action_bot > sidebar
    except Exception:
        return None


def _ui13_btn_style(role, key):
    """(fill, text) of a sidebar action button for a given drawn state."""
    dim = (_SB['dim'], _SB['dim_text'])
    if role == 'start':
        if key == 'surface2':
            return dim
        return ('#3b7cf5' if key == 'accent2' else '#2563eb', _SB['white'])
    if key == 'surface2':
        base = {'stop': '#f43f5e', 'force': '#f59e0b'}.get(role)
        if base:
            return (_ui13_tint(base, 0.07), _ui13_tint(base, 0.42))
        return dim
    hover = key in ('warning2', 'danger2', 'success2', 'accent2')
    if key in ('success', 'success2'):
        return (_ui13_tint('#10b981', 0.30 if hover else 0.19), '#6ee7b7')
    if role == 'stop':
        return (_ui13_tint('#f43f5e', 0.28 if hover else 0.17), '#fda4af')
    return (_ui13_tint('#f59e0b', 0.28 if hover else 0.17), '#fcd34d')


def _ui13_skin_sb_canvas(cv, role):
    if getattr(cv, '_ui13_role', None) == role:
        return
    o_poly = type(cv).create_polygon
    o_text = type(cv).create_text

    def create_polygon(*a, **kw):
        try:
            fill, txt = _ui13_btn_style(role, _ui13_key(kw.get('fill')))
            kw['fill'] = fill
            cv._ui13_txt = txt
        except Exception:
            pass
        return o_poly(cv, *a, **kw)

    def create_text(*a, **kw):
        try:
            if getattr(cv, '_ui13_txt', None):
                kw['fill'] = cv._ui13_txt
        except Exception:
            pass
        return o_text(cv, *a, **kw)
    cv.create_polygon = create_polygon
    cv.create_text = create_text
    cv._ui13_role = role
    _ui13_guard(cv, _ui13_sb_fix)
    _ui_raw_conf(cv, bg=_SB['bg'])
    fn = getattr(cv, '_draw_fn', None)
    if callable(fn):
        try:
            fn('idle')
        except Exception:
            pass


def _ui13_brand(self, sidebar):
    import tkinter as _tk
    if getattr(self, '_ui13_brand_box', None) is not None:
        return
    first = (sidebar.pack_slaves() or [None])[0]
    box = _tk.Frame(sidebar, bg=_SB['bg'], height=58)
    kw = {'side': 'top', 'fill': 'x'}
    if first is not None:
        kw['before'] = first
    box.pack(**kw)
    box.pack_propagate(False)
    inner = _tk.Frame(box, bg=_SB['bg'])
    inner.pack(side='left', padx=16)
    img = getattr(self, '_logo_tb_photo', None)
    if img is not None:
        lg = _tk.Label(inner, image=img, bg=_SB['bg'], bd=0)
    else:
        lg = _tk.Canvas(inner, width=32, height=32, bg=_SB['bg'], highlightthickness=0)
        try:
            lg.create_image(0, 0, anchor='nw', image=_ui_photo(
                lg, ('logo13', 32), lambda: _ui_render_button(32, 32, 8, '#3b82f6', '#10b981')))
            lg.create_text(16, 16, text='\u25B6', fill='white', font=(_F13, 11, 'bold'))
        except Exception:
            pass
    lg.pack(side='left')
    txt = _tk.Frame(inner, bg=_SB['bg'])
    txt.pack(side='left', padx=(10, 0))
    t1 = _tk.Label(txt, text='AutoPoster Pro', font=(_F13, 11, 'bold'), bg=_SB['bg'], fg=_SB['white'])
    t1.pack(anchor='w')
    try:
        ver = str(APP_VERSION)
    except Exception:
        ver = ''
    if ver:
        t2 = _tk.Label(txt, text=' v%s ' % ver, font=(_F13, 8, 'bold'), bg=_SB['pill_bg'],
                       fg=_SB['pill_fg'], padx=2, pady=0)
        t2._i18n_src = None
        t2.pack(anchor='w', pady=(2, 0))
    _tk.Frame(box, bg=_SB['line'], height=1).place(relx=0, rely=1.0, relwidth=1, anchor='sw')
    self._ui13_brand_box = box


def _ui13_style_nav(self):
    """Sidebar tab rows: navy rows, blue bar + lighter fill on the active one."""
    btns = getattr(self, '_tab_btns', None) or {}
    for key, (lbl, bar) in btns.items():
        try:
            item = lbl.master
            _ui13_guard(item, _ui13_sb_fix)
            _ui13_guard(lbl, _ui13_sb_fix)
            _ui13_guard(bar, _ui13_sb_fix)
            item.pack_configure(padx=(10, 10), pady=1)
            _ui_raw_conf(lbl, padx=12, pady=8)
            lbl.bind('<Enter>', lambda e, w=lbl, k=key: (getattr(self, '_current_tab', '') != k)
                     and _ui_raw_conf(w, bg=_SB['hover'], fg=_SB['white']))
            lbl.bind('<Leave>', lambda e, w=lbl, k=key: (getattr(self, '_current_tab', '') != k)
                     and _ui_raw_conf(w, bg=_SB['bg'], fg=_SB['text']))
        except Exception:
            pass


def _ui13_style_sidebar(self):
    import tkinter as _tk
    from tkinter import ttk as _ttk
    sidebar = _ui13_sidebar_of(self)
    if sidebar is None:
        return
    self._ui13_sidebar = sidebar
    _ui_raw_conf(sidebar, bg=_SB['bg'])
    _ui13_brand(self, sidebar)
    for w in _ui_walk(sidebar):
        try:
            cls = w.winfo_class()
            if cls in ('Frame', 'Label', 'Canvas', 'Button'):
                opts = {}
                bgk = _ui13_key(w.cget('bg'))
                if bgk is not None:
                    opts['bg'] = _SB[_SB_BG_MAP.get(bgk, 'bg')]
                if cls in ('Label', 'Button'):
                    fgk = _ui13_key(w.cget('fg'))
                    if fgk is not None:
                        opts['fg'] = _SB[_SB_FG_MAP.get(fgk, 'text')]
                if opts:
                    _ui_raw_conf(w, **opts)
            _ui13_guard(w, _ui13_sb_fix)
        except Exception:
            pass
    # NAVIGATION caption, separators
    try:
        nav_top = self._tab_btns['config'][0].master.master
        _ui_raw_conf(nav_top, pady=0)
        nav_top.pack_configure(pady=(14, 4))
        for ch in nav_top.pack_slaves():
            if ch.winfo_class() == 'Label':
                _ui_raw_conf(ch, fg=_SB['muted'], bg=_SB['bg'])
                ch.configure(font=(_F13, 8, 'bold'))
                ch.pack_configure(padx=20, pady=(0, 6))
                break
    except Exception:
        pass
    for ch in sidebar.pack_slaves():
        try:
            if ch.winfo_class() == 'Frame' and int(ch.cget('height')) == 1:
                _ui_raw_conf(ch, bg=_SB['line'])
                ch.pack_configure(padx=16, pady=(8, 4))
        except Exception:
            pass
    _ui13_style_nav(self)
    # progress
    try:
        _ttk.Style().configure('FB.Horizontal.TProgressbar', troughcolor=_SB['trough'],
                               background='#3d84f7', bordercolor=_SB['trough'],
                               lightcolor='#3d84f7', darkcolor='#3d84f7', thickness=5)
    except Exception:
        pass
    # action buttons
    for attr, role in (('start_btn', 'start'), ('pause_btn', 'pause'),
                       ('stop_btn', 'stop'), ('force_stop_btn', 'force')):
        cv = getattr(self, attr, None)
        if cv is not None:
            _ui13_skin_sb_canvas(cv, role)
    try:
        self.start_btn.pack_configure(pady=(0, 7))
        self.pause_btn.pack_configure(pady=(0, 7))
    except Exception:
        pass
    # links
    for i, cv in enumerate(getattr(self, '_ui_links', []) or []):
        _ui13_restyle_link(self, cv, i)
    # right-hand separator between sidebar and content
    try:
        for ch in sidebar.master.pack_slaves():
            if ch is not sidebar and ch.winfo_class() == 'Frame' and int(ch.cget('width')) == 1:
                _ui13_guard(ch, _ui13_sb_fix)
                _ui_raw_conf(ch, bg=_SB['line'])
                break
    except Exception:
        pass


_UI13_LINK_COLS = (('#2563eb', '#4f46e5', '#3b82f6', '#6366f1'),
                   ('#059669', '#0d9488', '#10b981', '#14b8a6'))


def _ui13_restyle_link(self, cv, i):
    W, H = 190, 38
    cols = _UI13_LINK_COLS[min(i, len(_UI13_LINK_COLS) - 1)]
    src = None
    for s, url, icon in _UI_LINKS:
        if url == getattr(cv, '_ui_url', None):
            src, ic = s, icon
    if src is None:
        return

    def draw(state='idle', cv=cv, src=src, ic=ic):
        try:
            cv.delete('all')
            top, bot = (cols[2], cols[3]) if state == 'hover' else (cols[0], cols[1])
            img = _ui_photo(cv, ('link13', W, H, top, bot),
                            lambda: _ui_render_button(W, H, 10, top, bot))
            cv.create_image(0, 0, anchor='nw', image=img)
            cv.create_text(W // 2, H // 2, text='%s  %s' % (ic, _TR(src)),
                           font=(_F13, 10, 'bold'), fill='white')
        except Exception:
            pass
    _ui13_guard(cv, _ui13_sb_fix)
    _ui_raw_conf(cv, bg=_SB['bg'], height=H + 2)
    cv.bind('<Enter>', lambda e, d=draw: d('hover'))
    cv.bind('<Leave>', lambda e, d=draw: d('idle'))
    cv._ui_draw = draw
    try:
        cv.pack_configure(pady=(0, 7))
    except Exception:
        pass
    draw()


# running-task cards: navy versions of the v6 helpers (called by name)
def _ui_task_card(self, key, title):
    import tkinter as _tk
    box = self._ui_tasks_box
    card = _tk.Frame(box, bg=_SB['card'], highlightthickness=1, highlightbackground=_SB['card_line'],
                     highlightcolor=_SB['card_line'], padx=10, pady=8)
    card.pack(fill='x', pady=(0, 8))
    hdr = _tk.Frame(card, bg=_SB['card'])
    hdr.pack(fill='x')
    _tk.Label(hdr, text=title, font=(_F13, 9, 'bold'), bg=_SB['card'], fg='#93c5fd',
              anchor='w').pack(side='left', fill='x', expand=True)
    x = _tk.Label(hdr, text='\u2715', font=(_F13, 9, 'bold'), bg=_SB['card'], fg=_SB['muted'],
                  cursor='hand2')
    x._i18n_src = None
    x.bind('<Button-1>', lambda e, k=key: _ui_task_dismiss(self, k))
    st = _tk.Label(card, text='', font=(_F13, 8), bg=_SB['card'], fg=_SB['text'], anchor='w')
    st._i18n_src = None
    st.pack(fill='x', pady=(2, 6))
    btns = _tk.Frame(card, bg=_SB['card'])
    btns.pack(fill='x')
    for w in (card, hdr, st, btns, x):
        _ui13_guard(w, _ui13_sb_fix)
    return {'card': card, 'x': x, 'status': st, 'btns': btns, 'state': None, 't0': time.time()}


def _ui_tasks_update(self):
    if not hasattr(self, '_ui_tasks_box'):
        return
    for key, title, running_fn, stop_fn, start_fn, pause_fn in self._ui_tasks_list:
        try:
            run = bool(running_fn())
        except Exception:
            run = False
        t = self._ui_tasks.get(key)
        if run:
            if t is None:
                t = self._ui_tasks[key] = _ui_task_card(self, key, title)
            if t['state'] != 'run':
                t['state'] = 'run'
                t['t0'] = time.time()
                t['x'].pack_forget()
                _ui_raw_conf(t['card'], highlightbackground=_SB['card_line'])
                _ui_task_buttons(self, t, [('\u23F8 Pause', pause_fn, '#d97706'),
                                           ('\u25A0 Arr\u00eater', stop_fn, '#e11d48')])
            secs = int(time.time() - t['t0'])
            _ui_raw_conf(t['status'], text='%s  %02d:%02d' % (_TR('En cours\u2026'), secs // 60, secs % 60),
                         fg=_SB['text'])
        elif t is not None and t['state'] == 'run':
            t['state'] = 'done'
            t['x'].pack(side='right')
            _ui_raw_conf(t['card'], highlightbackground='#10b981')
            _ui_raw_conf(t['status'], text=_TR('\u2713 Termin\u00e9 !'), fg=_SB['green'])
            _ui_task_buttons(self, t, [('\u25B6 Relancer', start_fn, '#059669')])
            try:
                self.root.bell()
            except Exception:
                pass



# ------------------------------------------------------ window chrome
def _ui13_dbg():
    try:
        if os.environ.get('UI13_DEBUG'):
            import traceback
            traceback.print_exc()
    except Exception:
        pass


def _ui13_chrome(self):
    """Full-height sidebar: title bar + status bar move into a new right
    column next to the sidebar (pack in_=, nothing re-created)."""
    import tkinter as _tk
    if getattr(self, '_ui13_right', None) is not None:
        return True
    try:
        root = self.root
        titlebar = self._theme_btn_lbl.master.master
        statusbar = self._sb_conn.master
        main_pane = self._main_pane_ref
        canvas = self._body_canvas
    except Exception:
        return False
    kids = root.pack_slaves()
    if titlebar not in kids or statusbar not in kids or main_pane not in kids:
        return False

    def thin(w):
        try:
            return w.winfo_class() == 'Frame' and int(str(w.cget('height')) or 0) in (1, 2, 3)
        except Exception:
            return False
    ti = kids.index(titlebar)
    top_lines = [w for w in kids[:ti] if thin(w)]
    tb_line = kids[ti + 1] if (ti + 1 < len(kids) and thin(kids[ti + 1])) else None
    sb_line = None
    for w in kids:
        if w is tb_line or w in top_lines or not thin(w):
            continue
        try:
            if w.pack_info().get('side') == 'bottom':
                sb_line = w
        except Exception:
            pass
    vsb = None
    for w in main_pane.pack_slaves():
        if w.winfo_class() == 'TScrollbar':
            vsb = w
    right = _tk.Frame(main_pane, bg=C['bg'])
    for w in top_lines:
        w.pack_forget()
    canvas.pack_forget()
    if vsb is not None:
        vsb.pack_forget()
    right.pack(side='left', fill='both', expand=True)
    titlebar.pack_forget()
    titlebar.pack(in_=right, side='top', fill='x')
    if tb_line is not None:
        tb_line.pack_forget()
        tb_line.pack(in_=right, side='top', fill='x')
    statusbar.pack_forget()
    statusbar.pack(in_=right, side='bottom', fill='x')
    if sb_line is not None:
        sb_line.pack_forget()
        sb_line.pack(in_=right, side='bottom', fill='x')
    canvas.pack(in_=right, side='left', fill='both', expand=True)
    for w in (titlebar, tb_line, statusbar, sb_line, canvas, vsb):
        if w is not None:
            try:
                _ui13_raise(w)
            except Exception:
                pass
    for w in root.place_slaves():          # resize edges + grip stay on top
        try:
            _ui13_raise(w)
        except Exception:
            pass
    self._ui13_right = right
    self._ui13_vsb = vsb
    self._ui13_vsb_on = False
    self._ui13_titlebar = titlebar
    self._ui13_statusbar = statusbar
    self._ui13_lines = (tb_line, sb_line)
    return True


def _ui13_vsb_show(self, need):
    vsb = getattr(self, '_ui13_vsb', None)
    if vsb is None:
        return
    try:
        if need and not self._ui13_vsb_on:
            vsb.place(in_=self._body_canvas, relx=1.0, x=-1, y=2, relheight=1.0, height=-4, anchor='ne')
            _ui13_raise(vsb)
            self._ui13_vsb_on = True
        elif not need and self._ui13_vsb_on:
            vsb.place_forget()
            self._ui13_vsb_on = False
    except Exception:
        pass


# ------------------------------------------------------ top-bar tabs
_UI13_TABS = (('config', 'Configuration', '\u2699'), ('auto', 'Mode automatique', '\u26A1'),
              ('journal', 'Journal', '\u25A4'))


def _ui13_tabs_draw(self):
    import tkinter.font as _tkf
    cv = getattr(self, '_ui13_tabs_cv', None)
    if cv is None:
        return
    try:
        z = _UI_ZOOM[0]
        size = max(8, int(round(9 * z)))
        fb = _tkf.Font(root=cv, family=_F13, size=size, weight='bold')
        cur = getattr(self, '_current_tab', 'config')
        hov = getattr(self, '_ui13_tab_hover', None)
        H = int(round(34 * z))
        pad = max(3, int(round(4 * z)))
        segs, x = [], pad
        btns = getattr(self, '_tab_btns', None) or {}
        for key, src, icon in _UI13_TABS:
            name = _TR(src)
            try:
                txt = str(btns[key][0].cget('text')).strip()
                if txt.startswith(icon):
                    txt = txt[len(icon):].strip()
                name = txt or name
            except Exception:
                pass
            label = '%s  %s' % (icon, name)
            w = fb.measure(label) + int(round(30 * z))
            segs.append((key, x, w, label))
            x += w
        W = x + pad
        dark = _ui13_is_dark()
        _ui_raw_conf(cv, width=W, height=H, bg=C['surface'])
        cv.delete('all')
        cv.create_image(0, 0, anchor='nw', image=_ui13_pill_img(
            cv, W, H, int(round(10 * z)), C['surface3'], border=C['border']))
        for key, x0, w, label in segs:
            active = (key == cur)
            if active:
                cv.create_image(x0, pad, anchor='nw', image=_ui13_pill_img(
                    cv, w, H - 2 * pad, int(round(8 * z)), C['border2'] if dark else C['surface'],
                    border=None if dark else C['border'], shadow=not dark))
            col = C['text'] if (active or key == hov) else C['text2']
            cv.create_text(x0 + w // 2, H // 2 - (1 if (active and not dark) else 0), text=label,
                           font=(_F13, size, 'bold') if active else (_F13, size), fill=col)
        self._ui13_tab_segs = segs
    except Exception:
        _ui13_dbg()


def _ui13_tab_at(self, x):
    for key, x0, w, _l in getattr(self, '_ui13_tab_segs', ()) or ():
        if x0 <= x < x0 + w:
            return key
    return None


def _ui13_tabs_click(self, x):
    k = _ui13_tab_at(self, x)
    if k:
        try:
            self._show_tab(k)
        except Exception:
            _ui13_dbg()


def _ui13_tabs_hover(self, x):
    k = None if x is None else _ui13_tab_at(self, x)
    if k != getattr(self, '_ui13_tab_hover', None):
        self._ui13_tab_hover = k
        _ui13_tabs_draw(self)


def _ui13_topbar(self):
    import tkinter as _tk
    tb = getattr(self, '_ui13_titlebar', None)
    if tb is None or getattr(self, '_ui13_tabs_cv', None) is not None:
        return
    try:
        tr = self._theme_btn_lbl.master
    except Exception:
        return
    _ui_raw_conf(tb, height=46)
    for ch in tb.pack_slaves():
        if ch is not tr:
            ch.pack_forget()                        # brand moved to the sidebar
    cv = _tk.Canvas(tb, height=34, width=300, bg=C['surface'], highlightthickness=0, cursor='hand2')
    cv.pack(side='left', padx=(14, 0))
    self._ui13_tabs_cv = cv
    self._ui13_tab_hover = None
    cv.bind('<Button-1>', lambda e: _ui13_tabs_click(self, e.x))
    cv.bind('<Motion>', lambda e: _ui13_tabs_hover(self, e.x))
    cv.bind('<Leave>', lambda e: _ui13_tabs_hover(self, None))
    for ch in tr.pack_slaves():
        try:
            if ch.winfo_class() == 'Label' and '\u25cf' in str(ch.cget('text')):
                self._ui13_sd = ch
                ch.pack_configure(pady=11, padx=(0, 8))
                break
        except Exception:
            pass
    zb = getattr(self, '_ui_zoom_box', None)
    if zb is not None:
        try:
            zb.pack_configure(pady=11)
        except Exception:
            pass
        for b in zb.winfo_children():
            b.bind('<Enter>', lambda e, w=b: _ui_raw_conf(w, bg=C['surface3']))
            b.bind('<Leave>', lambda e, w=b: _ui_raw_conf(w, bg=C['surface2']))
    lb = getattr(self, '_ui_lang_box', None)
    if lb is not None:
        try:
            lb.pack_configure(pady=11)
        except Exception:
            pass
        for code, b in (getattr(self, '_lang_btns', {}) or {}).items():
            b.bind('<Enter>', lambda e, w=b, c=code: (_LANG[0] != c) and _ui_raw_conf(w, bg=C['surface3']))
            b.bind('<Leave>', lambda e, w=b, c=code: (_LANG[0] != c) and _ui_raw_conf(w, bg=C['surface2']))
    _ui13_colors_topbar(self)
    _ui13_tabs_draw(self)


def _ui13_lang_colors(self):
    lb = getattr(self, '_ui_lang_box', None)
    if lb is not None:
        _ui_raw_conf(lb, bg=C['surface2'], highlightbackground=C['border'], highlightcolor=C['border'])
    for code, b in (getattr(self, '_lang_btns', {}) or {}).items():
        on = (code == _LANG[0])
        try:
            _ui_raw_conf(b, bg=(C['accent'] if on else C['surface2']), fg=('#ffffff' if on else C['text2']))
        except Exception:
            pass


def _ui13_colors_topbar(self):
    dark = _ui13_is_dark()
    sd = getattr(self, '_ui13_sd', None)
    if sd is not None:
        _ui_raw_conf(sd, bg=C['g_grn_3'], fg=C['success'], padx=10, pady=3, highlightthickness=1,
                     highlightbackground=('#0e4a3a' if dark else '#a7f3d0'),
                     highlightcolor=('#0e4a3a' if dark else '#a7f3d0'))
        for ref in getattr(self, '_blink_refs', []) or []:
            if ref.get('w') is sd:
                ref['on'], ref['off'] = C['success'], C['g_grn_2']
    zb = getattr(self, '_ui_zoom_box', None)
    if zb is not None:
        _ui_raw_conf(zb, bg=C['surface2'], highlightbackground=C['border'], highlightcolor=C['border'])
        for b in zb.winfo_children():
            try:
                _ui_raw_conf(b, bg=C['surface2'], fg=C['text2'])
            except Exception:
                pass
    _ui13_lang_colors(self)
    for ln in getattr(self, '_ui13_lines', ()) or ():
        if ln is not None:
            _ui_raw_conf(ln, bg=C['border'])


# --------------------------------------------------------------- cards
_UI13_ICON = {'comptes': '\u25A6', 'horaires': '\u25F7', 'collecte': '\u26A1', 'rejoindre': '\u2295',
              'liker': '\u2661', 'commenter': '\u270E', 'journal': '\u25A4',
              'cfg': '\u2699', 'br': '\u25E7', 'tor': '\u25C8', 'wm': '\u25E9'}


def _ui13_title(tf, icon=None, fg=None, ic=None):
    import tkinter as _tk
    bg = tf.cget('bg') if getattr(tf, '_ui13_keepbg', False) else C['surface']
    _ui_raw_conf(tf, bg=bg)
    lab = None
    for k in list(tf.pack_slaves()):
        cls = k.winfo_class()
        if cls == 'Frame':
            k.pack_forget()                          # the old accent rules
        elif cls == 'Label' and k is not getattr(tf, '_ui13_icon', None):
            lab = k
    if lab is not None:
        _ui_raw_conf(lab, bg=bg, fg=fg or C['text'])
        try:
            lab.configure(font=(_F13, 10, 'bold'))
        except Exception:
            pass
    if icon and lab is not None and getattr(tf, '_ui13_icon', None) is None:
        il = _tk.Label(tf, text=icon, bg=bg, fg=ic or C['accent'], font=(_F13, 10))
        il._i18n_src = None
        il.pack(side='left', before=lab, padx=(0, 7))
        tf._ui13_icon = il
    tf._ui13_lab = lab
    tf._ui13_noflow = True
    return lab


def _ui13_card_look(w):
    _ui_raw_conf(w, bg=C['surface'], highlightthickness=1, highlightbackground=C['border'],
                 highlightcolor=C['border'])


def _ui13_section_card(self, name):
    S = self._sections.get(name)
    if S is None or getattr(S, '_ui13_card', False):
        return
    kids = S.pack_slaves()
    if not kids:
        return
    _ui13_card_look(S)
    tf = kids[0]
    _ui13_title(tf, _UI13_ICON.get(name))
    tf.pack_configure(padx=14, pady=(9, 4))
    for card in kids[1:]:
        if card.winfo_class() == 'Frame':
            _ui_raw_conf(card, highlightthickness=0)
            try:
                card.pack_configure(padx=2, pady=(0, 4))
            except Exception:
                pass
    S._ui13_card = True
    self._ui13_cards.append(S)


def _ui13_overlay_title(p, t):
    """Title on top of a grid panel: row 0 grows, its widgets sit at its bottom."""
    try:
        p.update_idletasks()
        r0 = [s for s in p.grid_slaves() if int(s.grid_info()['row']) == 0]
        h0 = max([s.winfo_reqheight() for s in r0] or [0])
        p.rowconfigure(0, minsize=h0 + t.winfo_reqheight() + 8)
        for s in r0:
            st = s.grid_info().get('sticky') or ''
            if 's' not in st:
                s.grid_configure(sticky=st + 's')
        t.place_forget()                           # drop the v12 absolute width/height
        t.place(in_=p, x=0, y=0, relwidth=1.0)
    except Exception:
        _ui13_dbg()


def _ui13_tight_grid(frame, top=6, bottom=2):
    for s in frame.grid_slaves():
        try:
            p0, p1 = _ui_pad2(s.grid_info().get('pady', 0))
            n0, n1 = (min(p0, top), min(p1, bottom))
            if (n0, n1) != (p0, p1):
                s.grid_configure(pady=(n0, n1))
        except Exception:
            pass


def _ui_br_arrange(self, two):                         # v13: row 0 holds the card title
    c3 = getattr(self, '_ui_cfg3', None) or {}
    cols = c3.get('br_cols')
    if not cols or c3.get('br_two13') == two:
        return
    p_br = c3['blocks']['br'][1]
    left, right = cols
    base = 1 if getattr(p_br, '_ui13_card', False) else 0
    if two:
        left.grid(row=base, column=0, columnspan=1, sticky='nwe', padx=(0, 18), pady=0)
        right.grid(row=base, column=1, columnspan=1, sticky='nwe', padx=0, pady=0)
        p_br.columnconfigure(0, weight=1, uniform='ui_br')
        p_br.columnconfigure(1, weight=1, uniform='ui_br')
    else:
        left.grid(row=base, column=0, columnspan=2, sticky='nwe', padx=0, pady=0)
        right.grid(row=base + 1, column=0, columnspan=2, sticky='nwe', padx=0, pady=(8, 0))
        p_br.columnconfigure(0, weight=1, uniform='')
        p_br.columnconfigure(1, weight=0, uniform='')
    c3['br_two13'] = two


def _ui13_blocks(self):
    c3 = getattr(self, '_ui_cfg3', None)
    if not c3:
        return
    for name, (t, p) in list(c3['blocks'].items()):
        if getattr(p, '_ui13_card', False):
            continue
        try:
            _ui13_title(t, _UI13_ICON.get(name))
            if name == 'wm':
                inner = next((c for c in p.pack_slaves() if c is not t), None)
                kw = dict(in_=p, side='top', fill='x', padx=14, pady=(11, 4))
                if inner is not None:
                    kw['before'] = inner
                    _ui_raw_conf(inner, padx=14, pady=0)
                    inner.pack_configure(pady=(0, 11))
                t.pack(**kw)
            else:
                _ui_raw_conf(p, padx=14, pady=11)
                if name == 'cfg':
                    _ui13_cfg_header(self, p, t)
                elif name == 'br':
                    p._ui13_card = True
                    c3['br_two13'] = None
                    _ui_br_arrange(self, True)
                    t.grid(in_=p, row=0, column=0, columnspan=2, sticky='we', pady=(0, 8))
                else:
                    _ui13_overlay_title(p, t)
            _ui13_raise(t)
            _ui13_card_look(p)
            p._ui13_card = True
            self._ui13_cards.append(p)
        except Exception:
            _ui13_dbg()
    for name in ('cfg', 'tor'):
        try:
            _ui13_tight_grid(c3['blocks'][name][1])
        except Exception:
            pass
    for col in c3.get('br_cols') or ():
        _ui13_tight_grid(col)
    c3['br_two13'] = None


def _ui13_cfg_header(self, p, t):
    """'Configuration' title on the left, Target [Group | FB Page] on the right."""
    tl = next((s for s in p.grid_slaves() if getattr(s, '_i18n_src', None) == 'Cible'), None)
    ok = False
    try:
        if tl is not None and int(tl.grid_info()['row']) == 0:
            r1 = [s for s in p.grid_slaves() if int(s.grid_info()['row']) == 1]
            if len(r1) == 1:
                rad = r1[0]
                tl.grid_configure(row=0, column=0, columnspan=1, sticky='w', padx=0, pady=(0, 2))
                rad.grid_configure(row=0, column=1, columnspan=1, sticky='e', padx=0, pady=(0, 2))
                p.columnconfigure(0, weight=1)
                p.columnconfigure(1, weight=0)
                _ui13_overlay_title(p, t)
                ok = True
    except Exception:
        _ui13_dbg()
    if not ok:
        _ui13_overlay_title(p, t)


def _ui13_wm_compact(self):
    """Watermark: settings on the left, the 3×3 position pad on the right."""
    import tkinter as _tk
    c3 = getattr(self, '_ui_cfg3', None)
    if not c3:
        return
    t, card = c3['blocks']['wm']
    inner = next((c for c in card.pack_slaves() if c is not t), None)
    if inner is None or getattr(inner, '_ui13_wm', False):
        return
    by_row = {}
    for s in inner.grid_slaves():
        try:
            by_row[int(s.grid_info()['row'])] = s
        except Exception:
            pass
    if not all(r in by_row for r in range(8)):
        return
    for r in range(6):
        by_row[r].grid_configure(column=0, columnspan=1)
    by_row[6].grid_configure(row=0, column=1, columnspan=1, sticky='nw', padx=(14, 0), pady=(0, 3))
    by_row[7].grid_configure(row=1, column=1, rowspan=5, columnspan=1, sticky='nw', padx=(14, 0), pady=0)
    inner.columnconfigure(0, weight=1)
    inner.columnconfigure(1, weight=0)
    pos = by_row[7]
    kids = pos.pack_slaves()
    for k in kids:
        try:
            k.pack_configure(side='top', anchor='w')
        except Exception:
            pass
    for k in kids:
        try:
            if k.winfo_class() == 'Label':
                _ui_raw_conf(k, wraplength=96, justify='left', fg=C['text3'])
                k.configure(font=(_F13, 8))
                k.pack_configure(pady=(4, 0))
            elif k.winfo_class() == 'Frame':
                for b in k.grid_slaves():
                    _ui_raw_conf(b, width=2, padx=1, pady=0)
                    b.configure(font=(_F13, 9))
        except Exception:
            pass
    for e in _ui_walk(by_row[3]):
        try:
            if e.winfo_class() == 'Entry':
                _ui_raw_conf(e, width=8)
        except Exception:
            pass
    sr = by_row[5]
    parts = sr.pack_slaves()
    if len(parts) == 6:
        l1 = _tk.Frame(sr, bg=C['surface'])
        l2 = _tk.Frame(sr, bg=C['surface'])
        for p in parts:
            p.pack_forget()
        for p in parts[:3]:
            p.pack(in_=l1, side='left')
        for p in parts[3:]:
            p.pack(in_=l2, side='left')
        l1.pack(side='top', anchor='w')
        l2.pack(side='top', anchor='w', pady=(3, 0))
        for p in parts:
            _ui13_raise(p)
    _ui13_tight_grid(inner, top=5, bottom=2)
    inner._ui13_wm = True


def _ui13_accounts_card(self):
    A = self._sections.get('comptes')
    af = getattr(self, 'accounts_frame', None)
    if A is None or af is None or getattr(A, '_ui13_card', False):
        return
    card = af.master
    kids = A.pack_slaves()
    tf = kids[0] if (kids and kids[0] is not card) else None
    _ui13_card_look(A)
    _ui_raw_conf(card, highlightthickness=0)
    card.pack_configure(padx=1, pady=1)
    parts = card.pack_slaves()
    hdr = parts[0] if parts else None
    if hdr is not None:
        _ui_raw_conf(hdr, padx=14, pady=9)
        if tf is not None:
            _ui13_title(tf, _UI13_ICON['comptes'])
            tf.pack_forget()
            first = (hdr.pack_slaves() or [None])[0]
            kw = dict(in_=hdr, side='left', padx=(0, 8))
            if first is not None:
                kw['before'] = first
            tf.pack(**kw)
            _ui13_raise(tf)
        for ch in hdr.pack_slaves():
            try:
                if ch is tf:
                    continue
                if ch is getattr(self, '_acc_count_lbl', None):
                    _ui_raw_conf(ch, bg=C['g_grn_3'], fg=C['success'], padx=8, pady=1)
                    ch.configure(font=(_F13, 8, 'bold'))
                elif ch.winfo_class() == 'Label':
                    _ui_raw_conf(ch, fg=C['text3'])
                    ch.configure(font=(_F13, 9))
            except Exception:
                pass
    if len(parts) >= 2:
        ctrl = parts[1]
        _ui_raw_conf(ctrl, padx=12, pady=6)
        try:
            leg = ctrl.pack_slaves()[0]
            for ch in leg.pack_slaves():
                info = ch.pack_info()
                if ch.winfo_class() == 'Label':
                    ch.configure(font=(_F13, 8))
                elif ch.winfo_class() == 'Frame' and info.get('side') == 'right':
                    ch.pack_configure(padx=(0, 8))
                    for w in ch.winfo_children():
                        cls = w.winfo_class()
                        if cls == 'Spinbox':
                            _ui_raw_conf(w, width=3)
                        elif cls == 'Button':
                            _ui_raw_conf(w, padx=8)
                        elif cls == 'Label':
                            w.configure(font=(_F13, 8))
            for w in _ui_walk(leg):
                if w.winfo_class() == 'Label' and str(w.master) != str(leg):
                    continue
        except Exception:
            _ui13_dbg()
        for ch in ctrl.pack_slaves():
            try:
                p0, p1 = _ui_pad2(ch.pack_info().get('pady', 0))
                ch.pack_configure(pady=(min(p0, 4), min(p1, 6)))
            except Exception:
                pass
        for b in _ui_walk(ctrl):
            try:
                if b.winfo_class() == 'Button':
                    _ui_raw_conf(b, pady=3, padx=min(8, _ui_int(b, 'padx')))
            except Exception:
                pass
    for w in parts[2:]:
        try:
            if w is af:
                continue
            if w.winfo_class() == 'Frame':
                w.pack_configure(padx=14)
            elif w.winfo_class() == 'Canvas':
                w.pack_configure(pady=(4, 0))
        except Exception:
            pass
    A._ui13_card = True
    self._ui13_cards.append(A)


# ------------------------------------------- accounts: internal scroll
def _ui13_wheel_handler(fn):
    def h(e, d=None):
        try:
            if int(getattr(e, 'state', 0) or 0) & 0x4:      # Ctrl+wheel = zoom
                return None
        except Exception:
            pass
        if d is None:
            d = -1 if (getattr(e, 'delta', 0) or 0) > 0 else 1
        return fn(d)
    return h


def _ui13_bind_wheel(root_w, fn):
    h = _ui13_wheel_handler(fn)
    for w in _ui_walk(root_w):
        if getattr(w, '_ui13_wh', None) is fn:
            continue
        try:
            w.bind('<MouseWheel>', h, add='+')
            w.bind('<Button-4>', lambda e, h=h: h(e, -1), add='+')
            w.bind('<Button-5>', lambda e, h=h: h(e, 1), add='+')
            w._ui13_wh = fn
        except Exception:
            pass


def _ui13_acc_top(self):
    try:
        hc = self._acc_head_cv
        return int(hc.winfo_y() + hc.winfo_height() + 4)
    except Exception:
        return 0


def _ui13_acc_min_h(self):
    try:
        card = self.accounts_frame.master
        h = 0
        for w in card.pack_slaves():
            if w is self.accounts_frame:
                continue
            p0, p1 = _ui_pad2(w.pack_info().get('pady', 0))
            h += w.winfo_reqheight() + p0 + p1
        return h + int(2.5 * (int(getattr(self, 'ROW_H', 34)) + 2)) + 12
    except Exception:
        return 300


def _ui13_acc_scroll(self, on):
    from tkinter import ttk as _ttk
    import tkinter as _tk
    af = getattr(self, 'accounts_frame', None)
    if af is None:
        return
    card = af.master
    if on and not getattr(self, '_ui13_acc_on', False):
        af.pack_forget()
        card.pack_configure(fill='both', expand=True)
        if getattr(self, '_ui13_acc_sb', None) is None:
            self._ui13_acc_sb = _ttk.Scrollbar(card, orient='vertical', style='FB.Vertical.TScrollbar',
                                               command=lambda *a: _ui13_acc_yview(self, *a))
            self._ui13_acc_cover = _tk.Frame(card, bg=C['surface'])
            af.bind('<Configure>', lambda e: _ui13_acc_soon(self), add='+')
        self._ui13_acc_on = True
        self._ui13_acc_off = getattr(self, '_ui13_acc_off', 0)
    elif not on and getattr(self, '_ui13_acc_on', False):
        self._ui13_acc_on = False
        for w in (af, getattr(self, '_ui13_acc_sb', None), getattr(self, '_ui13_acc_cover', None)):
            try:
                w.place_forget()
            except Exception:
                pass
        card.pack_configure(fill='x', expand=False)
        af.pack(fill='x')
        return
    _ui13_acc_place(self)


def _ui13_acc_soon(self):
    if getattr(self, '_ui13_acc_job', None):
        return
    def run():
        self._ui13_acc_job = None
        _ui13_acc_place(self)
    try:
        self._ui13_acc_job = self.root.after(30, run)
    except Exception:
        self._ui13_acc_job = None


def _ui13_acc_place(self):
    if not getattr(self, '_ui13_acc_on', False):
        return
    try:
        af = self.accounts_frame
        card = af.master
        card.update_idletasks()
        top = _ui13_acc_top(self)
        view = max(1, card.winfo_height() - top - 2)
        total = max(1, af.winfo_reqheight())
        mx = max(0, total - view)
        off = max(0, min(int(getattr(self, '_ui13_acc_off', 0)), mx))
        self._ui13_acc_off = off
        sbw = 10 if mx > 0 else 0
        af.place(in_=card, x=0, y=top - off, relwidth=1.0, width=-sbw, height=total)
        cover = self._ui13_acc_cover
        _ui_raw_conf(cover, bg=C['surface'])
        cover.place(in_=card, x=0, y=0, relwidth=1.0, height=top)
        _ui13_raise(cover)
        for w in card.pack_slaves():
            _ui13_raise(w)
        sb = self._ui13_acc_sb
        if mx > 0:
            sb.place(in_=card, relx=1.0, x=-1, y=top, height=view, anchor='ne')
            _ui13_raise(sb)
            sb.set(off / float(total), (off + view) / float(total))
        else:
            sb.place_forget()
        _ui13_bind_wheel(af, lambda d: _ui13_acc_wheel(self, d))
    except Exception:
        _ui13_dbg()


def _ui13_acc_wheel(self, d):
    if getattr(self, '_ui13_acc_on', False):
        self._ui13_acc_off = int(getattr(self, '_ui13_acc_off', 0)) + d * (int(getattr(self, 'ROW_H', 34)) + 2) * 2
        _ui13_acc_place(self)
        return 'break'
    return None


def _ui13_acc_yview(self, *a):
    try:
        af = self.accounts_frame
        total = max(1, af.winfo_reqheight())
        view = max(1, af.master.winfo_height() - _ui13_acc_top(self))
        if a and a[0] == 'moveto':
            self._ui13_acc_off = int(float(a[1]) * total)
        elif a and a[0] == 'scroll':
            n = int(a[1])
            step = (int(getattr(self, 'ROW_H', 34)) + 2) if (len(a) < 3 or a[2] == 'units') else view
            self._ui13_acc_off = int(getattr(self, '_ui13_acc_off', 0)) + n * step
        _ui13_acc_place(self)
    except Exception:
        _ui13_dbg()


# ------------------------------------------------------------ layouts
_TAB_LAYOUT['config'] = {'kind': 'config13', 'sections': ['campagne', 'horaires', 'comptes']}
_TAB_LAYOUT['auto'] = {'kind': 'auto13', 'sections': ['collecte', 'commenter', 'rejoindre', 'liker']}
_TAB_LAYOUT['journal'] = {'kind': 'log13', 'sections': ['journal']}
_UI13_M, _UI13_G, _UI13_TWO = 10, 10, 900


def _ui13_boxes(self, tab):
    if tab == 'config' and getattr(self, '_ui_cfg3', None):
        b = self._ui_cfg3['blocks']
        return [b['cfg'][1], b['br'][1], b['tor'][1], b['wm'][1],
                self._sections['horaires'], self._sections['comptes']]
    return [fr for _n, fr in _ui_sections_of(self, tab)]


def _ui13_layout_config(self, spec, body_w, body_h):
    S = self._sections['campagne']
    H = self._sections['horaires']
    A = self._sections['comptes']
    b = self._ui_cfg3['blocks']
    p_cfg, p_br, p_tor, p_wm = b['cfg'][1], b['br'][1], b['tor'][1], b['wm'][1]
    m, g = _UI13_M, _UI13_G
    S.place(x=0, y=0, width=body_w, height=max(10, body_h))
    if body_w >= _UI13_TWO:
        lw = max(330, min(440, int((body_w - 2 * m - g) * 0.345)))
        rx = m + lw + g
        rw = body_w - rx - m
        _ui_br_arrange(self, rw >= 560)
        wa = int((rw - g) * 0.42)                  # [Tor over Watermark] | [Working Hours]
        wb = rw - g - wa
        xa, xb = rx, rx + wa + g
        # Right column, top -> bottom: Facebook Accounts, Browser settings,
        # then [Tor over Watermark | Working Hours].  The accounts panel now
        # sits at the TOP, next to the Configuration panel (see site.png).
        p_cfg.place(x=m, y=m, width=lw, height='')
        p_br.place(x=rx, y=0, width=rw, height='')
        p_tor.place(x=xa, y=0, width=wa, height='')
        p_wm.place(x=xa, y=0, width=wa, height='')
        H.place(x=xb, y=0, width=wb, height='')
        _ui13_acc_scroll(self, True)
        A.place(x=rx, y=m, width=rw, height=300)
        _ui_fit_boxes(self, [p_cfg, p_br, p_tor, H, p_wm, A])
        cfg_h = p_cfg.winfo_reqheight()
        br_h = p_br.winfo_reqheight()
        tor_h, wm_h = p_tor.winfo_reqheight(), p_wm.winfo_reqheight()
        row_h = max(tor_h + g + wm_h, H.winfo_reqheight())
        acc_min = max(_ui13_acc_min_h(self), 260)
        right_fixed = br_h + row_h + 2 * g            # everything below accounts
        total = max(body_h, cfg_h + 2 * m, acc_min + right_fixed + 2 * m)
        acc_h = total - 2 * m - right_fixed           # accounts fills the top
        y_br = m + acc_h + g
        y_row = y_br + br_h + g
        p_cfg.place(x=m, y=m, width=lw, height=total - 2 * m)
        A.place(x=rx, y=m, width=rw, height=acc_h)
        p_br.place(x=rx, y=y_br, width=rw, height=br_h)
        p_tor.place(x=xa, y=y_row, width=wa, height=tor_h)
        p_wm.place(x=xa, y=y_row + tor_h + g, width=wa, height=row_h - tor_h - g)
        H.place(x=xb, y=y_row, width=wb, height=row_h)
        self._ui_two_cols = True
    else:
        _ui13_acc_scroll(self, False)
        _ui_br_arrange(self, False)
        w = body_w - 2 * m
        S.place(x=m, y=0, width=w, height=max(10, body_h))     # one column, same x for all
        inner = (p_cfg, p_br, p_tor, p_wm)
        order = [p_cfg, A, p_br, p_tor, H, p_wm]     # accounts right under Configuration
        for w_ in order:
            w_.place(x=(0 if w_ in inner else m), y=0, width=w, height='')
        _ui_fit_boxes(self, order)
        y = m
        for w_ in order:
            w_.place(x=(0 if w_ in inner else m), y=y, width=w, height='')
            y += w_.winfo_reqheight() + g
        total = y
        self._ui_two_cols = False
    if self._ui_two_cols:
        S.place(x=0, y=0, width=body_w, height=max(10, total))
    else:
        S.place(x=m, y=0, width=body_w - 2 * m, height=max(10, total))
    for w_ in (H, A):
        try:
            _ui13_raise(w_)
        except Exception:
            pass
    for t_, _p in b.values():                      # card titles above their cards
        _ui13_raise(t_)
    _ui13_acc_place(self)
    return total


def _ui13_stretch(fr):
    for c in fr.pack_slaves():
        try:
            if c.winfo_class() == 'Frame' and c is not fr.pack_slaves()[0]:
                c.pack_configure(fill='both', expand=True)
        except Exception:
            pass


def _ui13_layout_auto(self, spec, body_w, body_h):
    secs = dict(_ui_sections_of(self, 'auto'))
    col, com = secs.get('collecte'), secs.get('commenter')
    stack = [secs[n] for n in ('rejoindre', 'liker', 'nettoyage') if secs.get(n) is not None]
    m, g = _UI13_M, _UI13_G
    for fr in secs.values():
        _ui13_stretch(fr)
    if body_w >= _UI13_TWO and col is not None and com is not None and stack:
        avail = body_w - 2 * m - 2 * g
        w1 = int(avail * 0.90 / 3.0)
        w2 = int(avail * 1.10 / 3.0)
        w3 = avail - w1 - w2
        x1, x2, x3 = m, m + w1 + g, m + w1 + g + w2 + g
        col.place(x=x1, y=m, width=w1, height='')
        com.place(x=x2, y=m, width=w2, height='')
        for fr in stack:
            fr.place(x=x3, y=m, width=w3, height='')
        _ui_fit_boxes(self, [col, com] + stack)
        hs = [fr.winfo_reqheight() for fr in stack]
        need = sum(hs) + g * (len(hs) - 1)
        full = max(col.winfo_reqheight(), com.winfo_reqheight(), need, body_h - 2 * m)
        extra = full - need
        y = m
        for i, (fr, h) in enumerate(zip(stack, hs)):
            add = extra // len(hs) if i < len(hs) - 1 else extra - (extra // len(hs)) * (len(hs) - 1)
            fr.place(x=x3, y=y, width=w3, height=h + add)
            y += h + add + g
        col.place(x=x1, y=m, width=w1, height=full)
        com.place(x=x2, y=m, width=w2, height=full)
        self._ui_two_cols = True
        return full + 2 * m
    w = body_w - 2 * m
    order = [x for x in [col, com] + stack if x is not None]
    for fr in order:
        fr.place(x=m, y=0, width=w, height='')
    _ui_fit_boxes(self, order)
    y = m
    for fr in order:
        fr.place(x=m, y=y, width=w, height='')
        y += fr.winfo_reqheight() + g
    self._ui_two_cols = False
    return y


def _ui13_layout_log(self, spec, body_w, body_h):
    J = self._sections['journal']
    ov = _ui13_overview(self)
    m, g = _UI13_M, _UI13_G
    if body_w >= _UI13_TWO:
        ow = int((body_w - 2 * m - g) * 0.64)
        jw = body_w - 2 * m - g - ow
        ov.place(x=m, y=m, width=ow, height=body_h - 2 * m)
        J.place(x=m + ow + g, y=m, width=jw, height=body_h - 2 * m)
        total = body_h
    else:
        oh = max(260, int(body_h * 0.5))
        ov.place(x=m, y=m, width=body_w - 2 * m, height=oh)
        J.place(x=m, y=m + oh + g, width=body_w - 2 * m, height=max(240, body_h - oh - 2 * m - g))
        total = m + oh + g + max(240, body_h - oh - 2 * m - g) + m
    for w_ in (ov, J):
        try:
            _ui13_raise(w_)
        except Exception:
            pass
    _ui13_ov_refresh(self)
    return total


_ui13_prev_layout_grid = FacebookMultiPosterApp._layout_grid


def _ui13_layout_grid(self, tab, force=True):
    spec = _TAB_LAYOUT.get(tab) or {}
    kind = spec.get('kind')
    if kind not in ('config13', 'auto13', 'log13', 'shorts15', 'freeid15') or \
            (kind == 'config13' and not getattr(self, '_ui_cfg3', None)) or \
            not getattr(self, '_ui13_done', False):
        if kind in ('log13', 'shorts15', 'freeid15'):
            return False
        if kind in ('config13', 'auto13'):
            old = {'config13': {'kind': 'config3', 'sections': ['campagne', 'horaires', 'comptes'],
                                'right_share': 0.60, 'right_min': 700, 'left_min': 380, 'mid_share': 0.5},
                   'auto13': {'kind': 'rows', 'sections': ['collecte', 'commenter', 'rejoindre', 'liker'],
                              'rows': [('collecte', 'commenter'), ('rejoindre', 'liker')],
                              'ratio': 0.5, 'min': (440, 420)}}[kind]
            _TAB_LAYOUT[tab] = old
            try:
                return _ui13_prev_layout_grid(self, tab, force)
            finally:
                _TAB_LAYOUT[tab] = spec
        return _ui13_prev_layout_grid(self, tab, force)
    if not hasattr(self, '_ui_wrapped'):
        self._ui_wrapped, self._ui_flows = set(), set()
    try:
        body_w = int(self._body_canvas.winfo_width())
        body_h = int(self._body_canvas.winfo_height())
    except Exception:
        body_w = body_h = 0
    if body_w < 300 or body_h < 150:
        for _n, fr in _ui_sections_of(self, tab):
            fr.place(x=0, y=0, width=1000)
        return True
    boxes = _ui13_boxes(self, tab)
    sig = (tab, body_w, body_h, _UI_ZOOM[0], _LANG[0], _CURRENT_THEME[0],
           tuple(bx.winfo_reqheight() for bx in boxes))
    if not force and sig == getattr(self, '_ui_layout_sig', None):
        return True
    _ui_reset_responsive(self)
    try:
        if kind == 'config13':
            total = _ui13_layout_config(self, spec, body_w, body_h)
        elif kind == 'auto13':
            total = _ui13_layout_auto(self, spec, body_w, body_h)
        elif kind == 'shorts15':
            total = _ui15_layout_shorts(self, spec, body_w, body_h)
        elif kind == 'freeid15':
            total = _ui15_layout_freeid(self, spec, body_w, body_h)
        else:
            total = _ui13_layout_log(self, spec, body_w, body_h)
    except Exception:
        _ui13_dbg()
        total = body_h
    total = max(int(total), body_h)
    self._set_body_height(total)
    _ui13_vsb_show(self, total > body_h + 1)
    try:
        self.root.update_idletasks()
    except Exception:
        pass
    self._ui_layout_sig = (tab, body_w, body_h, _UI_ZOOM[0], _LANG[0], _CURRENT_THEME[0],
                           tuple(bx.winfo_reqheight() for bx in boxes))
    return True


FacebookMultiPosterApp._layout_grid = _ui13_layout_grid

_ui13_prev_hide_all = FacebookMultiPosterApp._hide_all_sections


def _ui13_hide_all_sections(self):
    _ui13_prev_hide_all(self)
    ov = getattr(self, '_ui13_ov', None)
    if ov is not None:
        try:
            ov.place_forget()
        except Exception:
            pass


