_LOGC = {'card': '#0c1628', 'line': '#1b2740', 'box': '#0a1322', 'btn': '#16223a', 'text': '#cbd5e1',
         'title': '#f1f5f9', 'muted': '#8391a7', 'live_bg': '#0f3b31', 'live_fg': '#6ee7b7'}
