for _k13, _v13 in _UI13_NEW_TR.items():
    _TRAW.setdefault(_k13, _v13)
_UI13_REV = {}


def _ui13_src(en):
    """French source key of an English UI string (so _TR translates it)."""
    if not _UI13_REV:
        for k, v in _TRAW.items():
            try:
                if v and v[0]:
                    _UI13_REV.setdefault(str(v[0]).strip(), k)
            except Exception:
                pass
    s = _UI13_REV.get(en)
    if s is not None:
        return s
    for suf in (':', ' :'):
        s = _UI13_REV.get(en + suf)
        if s is not None:
            k = s.rstrip(' :\uff1a')
            if k not in _TRAW:
                try:
                    _TRAW[k] = tuple((x or '').rstrip(' :\uff1a') for x in _TRAW[s])
                except Exception:
                    return s
            _UI13_REV[en] = k
            return k
    return en


