def _ui13_var(self, name):
    v = getattr(self, name, None)
    try:
        return v.get() if v is not None else None
    except Exception:
        return None


def _ui13_radio_text(self, name):
    v = getattr(self, name, None)
    if v is None:
        return '\u2014'
    try:
        val = str(v.get())
    except Exception:
        return '\u2014'
    cache = getattr(self, '_ui13_radios', None)
    if cache is None:
        cache = {}
        for w in _ui_walk(self.root):
            try:
                if w.winfo_class() == 'Radiobutton':
                    cache.setdefault(str(w.cget('variable')), {})[str(w.cget('value'))] = w
            except Exception:
                pass
        self._ui13_radios = cache
    w = cache.get(str(v), {}).get(val)
    if w is None:
        return val
    try:
        return str(w.cget('text')).strip().rstrip(':').strip() or val
    except Exception:
        return val


_UI13_TEXTS = {'sc': '_sc_text', 'cm_url': '_cm_text', 'cm_txt': '_cm_comments', 'jg': '_jg_text'}


def _ui13_text_lines(self, kind):
    import tkinter as _tk
    la = getattr(self, 'log_area', None)
    pick = getattr(self, _UI13_TEXTS.get(kind, '-'), None)
    if not isinstance(pick, _tk.Text):
        pick = None
    for n, w in ([] if pick is not None else list(vars(self).items())):
        if not isinstance(w, _tk.Text) or w is la:
            continue
        ln = n.lower()
        if kind == 'sc' and 'sc' in ln and any(k in ln for k in ('group', 'url', 'src', 'watch', 'source')):
            pick = w
        elif kind == 'cm_url' and 'cm' in ln and any(k in ln for k in ('url', 'group')):
            pick = w
        elif kind == 'cm_txt' and 'cm' in ln and any(k in ln for k in ('comment', 'txt', 'text', 'msg')) \
                and not any(k in ln for k in ('url', 'group')):
            pick = w
        elif kind == 'jg' and any(k in ln for k in ('jg', 'join', 'rejoin')):
            pick = w
        if pick is not None:
            break
    if pick is None:
        return None
    try:
        return sum(1 for l in pick.get('1.0', 'end-1c').splitlines() if l.strip())
    except Exception:
        return None


def _ui13_ov_value(self, spec):
    kind = spec[0]
    V = lambda n: _ui13_var(self, n)
    if kind == 'bool':
        return (bool(V(spec[1])), '')
    if kind == 'boolx':
        return (bool(V(spec[1])), '%s%s' % (V(spec[2]), spec[3]))
    if kind == 'var':
        x = V(spec[1])
        return (None, ('%s%s' % (x, spec[2])) if x not in (None, '') else '\u2014')
    if kind == 'radio':
        return (None, _ui13_radio_text(self, spec[1]))
    if kind == 'count':
        lst = list(getattr(self, spec[1], None) or [])
        if spec[1] == 'csv_paths_list':
            try:
                zr = _ui_zip_root()
                lst = [p for p in lst if not os.path.normcase(os.path.abspath(p)).startswith(zr + os.sep)]
            except Exception:
                pass
        return (None, str(len(lst)))
    if kind == 'file':
        x = str(V(spec[1]) or '').strip()
        return (None, os.path.basename(x.replace('\\', '/')) or '\u2014')
    if kind == 'text':
        n = _ui13_text_lines(self, spec[1])
        return (None, '\u2014' if n is None else str(n))
    if kind == 'cycle':
        return (None, '%s Img \u00b7 %s BG \u00b7 %s Txt' % (V('cycle_img_var'), V('cycle_bg_var'), V('cycle_txt_var')))
    if kind == 'anon':
        return (bool(V('anon_enabled_var')), '%s / %s' % (V('anon_ratio_a_var'), V('anon_ratio_n_var')))
    if kind == 'sched':
        sl = [x for x in (getattr(self, 'schedule_slots', []) or []) if isinstance(x, dict)]
        if not sl:
            return (None, _TR(_ui13_src('No schedule \u2014 continuous')))
        out = []
        for x in sl[:3]:
            vals = [str(v) for v in x.values() if isinstance(v, str) and ':' in v]
            out.append('\u2013'.join(vals[:2]) if vals else '?')
        return (None, ', '.join(out) + (' \u2026' if len(sl) > 3 else ''))
    if kind == 'wmsize':
        return (None, '%s%% \u00b7 %s%%' % (V('watermark_size_var'), V('watermark_opacity_var')))
    if kind == 'wmpos':
        p = str(V('watermark_position_var') or '')
        return (None, _UI13_WMPOS.get(p, p or '\u2014'))
    accs = getattr(self, 'accounts', {}) or {}
    if kind == 'accn':
        return (None, str(len(accs)))
    if kind == 'accc':
        return (None, str(sum(1 for a in list(accs.values()) if a.get('connected'))))
    if kind == 'accp':
        try:
            return (None, str(sum(1 for v in list(_UI_ACC_PROXY.values()) if v.get('enabled'))))
        except Exception:
            return (None, '0')
    if kind == 'cmsel':
        try:
            return (None, str(sum(1 for v in (getattr(self, '_cm_slot_vars', {}) or {}).values() if v.get())))
        except Exception:
            return (None, '\u2014')
    return (None, '\u2014')


def _ui13_ov_card(self, parent, title_en, icon, rows):
    import tkinter as _tk
    card = _tk.Frame(parent, bg=C['surface'], highlightthickness=1, highlightbackground=C['border'],
                     highlightcolor=C['border'])
    card.pack(fill='x', pady=(0, 9))
    self._ui13_cards.append(card)
    hd = _tk.Frame(card, bg=C['surface'])
    hd.pack(fill='x', padx=10, pady=(6, 4))
    il = _tk.Label(hd, text=icon, bg=C['surface'], fg=C['accent'], font=(_F13, 9))
    il._i18n_src = None
    il.pack(side='left', padx=(0, 5))
    _tk.Label(hd, text=_ui13_src(title_en), bg=C['surface'], fg=C['text'], font=(_F13, 9, 'bold'),
              anchor='w', justify='left', wraplength=190).pack(side='left', fill='x')
    _tk.Frame(card, bg=C['border'], height=1).pack(fill='x')
    body = _tk.Frame(card, bg=C['surface'])
    body.pack(fill='x', padx=10, pady=(4, 6))
    body.columnconfigure(0, weight=1)
    for r, (en, spec) in enumerate(rows):
        k = _tk.Label(body, text=_ui13_src(en), bg=C['surface'], fg=C['text2'], font=(_F13, 8),
                      anchor='w', justify='left', wraplength=122)
        k.grid(row=r, column=0, sticky='w', pady=0)
        vf = _tk.Frame(body, bg=C['surface'])
        vf.grid(row=r, column=1, sticky='e', padx=(6, 0))
        badge = _tk.Label(vf, text='', font=(_F13, 7, 'bold'), padx=4, pady=0, bg=C['surface3'], fg=C['text3'])
        badge._i18n_src = None
        val = _tk.Label(vf, text='', bg=C['surface'], fg=C['text'], font=(_F13, 8, 'bold'), anchor='e',
                        justify='right', wraplength=92)
        val._i18n_src = None
        self._ui13_ov_rows.append((spec, badge, val))


def _ui13_ov_region(ov):
    try:
        ov.configure(scrollregion=(0, 0, ov.winfo_width(), ov._ui13_inner.winfo_reqheight()))
    except Exception:
        pass


def _ui13_ov_wheel(self, d):
    ov = getattr(self, '_ui13_ov', None)
    if ov is None:
        return None
    try:
        a, b = ov.yview()
        if b - a < 0.999:
            ov.yview_scroll(d * 2, 'units')
    except Exception:
        pass
    return 'break'


def _ui13_overview(self):
    import tkinter as _tk
    ov = getattr(self, '_ui13_ov', None)
    if ov is not None:
        return ov
    ov = _tk.Canvas(self._body_root, bg=C['bg'], highlightthickness=0, bd=0)
    inner = _tk.Frame(ov, bg=C['bg'])
    win = ov.create_window(0, 0, anchor='nw', window=inner)
    ov._ui13_inner, ov._ui13_win = inner, win
    self._ui13_ov = ov
    self._ui13_ov_rows = []
    if not hasattr(self, '_ui13_cards'):
        self._ui13_cards = []
    for si, (sec_src, icon, cards) in enumerate((('Configuration', '\u2699', _UI13_OV_CONF),
                                                  ('Mode automatique', '\u26A1', _UI13_OV_AUTO))):
        hdr = _tk.Frame(inner, bg=C['bg'])
        hdr.pack(fill='x', padx=2, pady=((0 if si == 0 else 6), 6))
        il = _tk.Label(hdr, text=icon, bg=C['bg'], fg=C['accent'], font=(_F13, 10))
        il._i18n_src = None
        il.pack(side='left', padx=(0, 6))
        _tk.Label(hdr, text=sec_src, bg=C['bg'], fg=C['text'], font=(_F13, 10, 'bold')).pack(side='left')
        _tk.Label(hdr, text='r\u00e9glages actuels', bg=C['bg'], fg=C['text3'],
                  font=(_F13, 8)).pack(side='left', padx=(8, 0), pady=(2, 0))
        grid = _tk.Frame(inner, bg=C['bg'])
        grid.pack(fill='x')
        cols = []
        for c in range(3):
            f = _tk.Frame(grid, bg=C['bg'])
            f.grid(row=0, column=c, sticky='nwe', padx=((0 if c == 0 else 5), (0 if c == 2 else 5)))
            grid.columnconfigure(c, weight=1, uniform='ov13')
            cols.append([f, 0])
        for title_en, cicon, rows in cards:
            tgt = min(cols, key=lambda cc: cc[1])
            _ui13_ov_card(self, tgt[0], title_en, cicon, rows)
            tgt[1] += len(rows) + 2
    ov.bind('<Configure>', lambda e: (ov.itemconfigure(win, width=e.width), _ui13_ov_region(ov)))
    inner.bind('<Configure>', lambda e: _ui13_ov_region(ov))
    _ui13_bind_wheel(ov, lambda d: _ui13_ov_wheel(self, d))
    _ui13_ov_refresh(self)
    return ov


def _ui13_ov_refresh(self):
    for spec, badge, val in getattr(self, '_ui13_ov_rows', []) or []:
        try:
            on, txt = _ui13_ov_value(self, spec)
            if on is None:
                if badge.winfo_manager():
                    badge.pack_forget()
            else:
                _ui_raw_conf(badge, text=_TR('ON' if on else 'OFF'),
                             bg=(C['success_d'] if on else C['surface3']),
                             fg=(C['success'] if on else C['text3']))
                if not badge.winfo_manager():
                    badge.pack(side='left')
            txt = str(txt or '')
            if txt:
                _ui_raw_conf(val, text=txt, bg=C['surface'], fg=C['text'])
                if not val.winfo_manager():
                    val.pack(side='left', padx=((5 if on is not None else 0), 0))
            elif val.winfo_manager():
                val.pack_forget()
        except Exception:
            pass


# ------------------------------------------------------------ polish
def _ui13_theme_fix(kw):
    """Colours captured by hover handlers at start-up follow the current theme."""
    cur = C_DARK if _ui13_is_dark() else C_LIGHT
    oth = C_LIGHT if cur is C_DARK else C_DARK
    curv = set(cur.values())
    for opt in ('bg', 'background', 'fg', 'foreground', 'activebackground', 'activeforeground'):
        v = kw.get(opt)
        if isinstance(v, str) and v.startswith('#'):
            c = v.lower()
            if c not in curv:
                for k, ov in oth.items():
                    if ov == c:
                        kw[opt] = cur[k]
                        break
    return kw


def _ui13_compact(self):
    for name, S in list((self._sections or {}).items()):
        if name == 'journal':
            continue
        for w in _ui_walk(S):
            try:
                cls = w.winfo_class()
                if cls == 'Entry':
                    if int(str(w.cget('bd'))) > 5:
                        _ui_raw_conf(w, bd=5)
                elif cls == 'Spinbox':
                    if int(str(w.cget('bd'))) > 4:
                        _ui_raw_conf(w, bd=4)
                elif cls == 'Button':
                    if int(str(w.cget('pady'))) > 4:
                        _ui_raw_conf(w, pady=4)
                    if getattr(w, '_ui13_fix', None) is None:
                        _ui13_guard(w, _ui13_theme_fix)
                elif cls == 'Radiobutton' and getattr(w, '_ui_skin', None) == 'chip':
                    _ui_raw_conf(w, pady=2, padx=8)
                elif cls == 'Checkbutton' and getattr(w, '_ui_skin', None) == 'switch':
                    _ui_raw_conf(w, pady=1)
            except Exception:
                pass
    for name in ('horaires', 'collecte', 'commenter', 'rejoindre', 'liker'):
        S = self._sections.get(name)
        if S is None:
            continue
        for w in _ui_walk(S):
            try:
                if w.winfo_class() == 'Frame' and w.grid_slaves():
                    _ui13_tight_grid(w, top=8, bottom=3)
            except Exception:
                pass


_UI13_PX_LIGHT = {'ok': ('#d1fae5', '#065f46'), 'bad': ('#ffe4e6', '#9f1239'),
                  'checking': ('#fef3c7', '#92400e')}
_UI13_PX_DARK = {'ok': ('#0b3b2e', '#6ee7b7'), 'bad': ('#3f1520', '#fda4af'),
                 'checking': ('#3a2a0c', '#fcd34d')}


def _ui13_theme_misc(self):
    """Theme-aware proxy pills and disabled/readonly input colours."""
    _UI_PX_COLORS.update(_UI13_PX_DARK if _ui13_is_dark() else _UI13_PX_LIGHT)
    for name, S in list((self._sections or {}).items()):
        if name == 'journal':
            continue
        for w in _ui_walk(S):
            try:
                if w.winfo_class() in ('Entry', 'Spinbox'):
                    _ui_raw_conf(w, disabledbackground=C['surface3'], disabledforeground=C['text3'],
                                 readonlybackground=C['surface2'])
            except Exception:
                pass


def _ui13_sections(self):
    for name in ('horaires', 'collecte', 'commenter', 'rejoindre', 'liker'):
        try:
            _ui13_section_card(self, name)
        except Exception:
            _ui13_dbg()


def _ui13_default_size(self):
    """Once: open at the compact 1440×960 size of the redesign (capped to the screen)."""
    if not getattr(self, '_standalone', False):
        return
    try:
        flag = os.path.join(SESSION_BASE, 'ui13_layout.flag')
        if os.path.exists(flag):
            return
        top = self.root.winfo_toplevel()
        if str(top.state()) == 'normal':
            sw, sh = top.winfo_screenwidth(), top.winfo_screenheight()
            W, H = min(1440, sw - 40), min(960, sh - 80)
            top.geometry('%dx%d+%d+%d' % (W, H, max(0, (sw - W) // 2), max(0, (sh - H) // 3)))
        with open(flag, 'w') as fh:
            fh.write('1')
    except Exception:
        pass


# ------------------------------------------------------------- wiring
def _ui13_progress_style(self):
    from tkinter import ttk as _ttk
    names = set(['FB.Horizontal.TProgressbar'])
    sb = getattr(self, '_ui13_sidebar', None)
    if sb is not None:
        for w in _ui_walk(sb):
            try:
                if w.winfo_class() == 'TProgressbar':
                    names.add(str(w.cget('style')) or 'Horizontal.TProgressbar')
            except Exception:
                pass
    st = _ttk.Style()
    for n in names:
        try:
            st.configure(n, troughcolor=_SB['trough'], background='#3d84f7', bordercolor=_SB['trough'],
                         lightcolor='#3d84f7', darkcolor='#3d84f7', thickness=5, borderwidth=0,
                         troughrelief='flat', relief='flat')
        except Exception:
            pass


def _ui13_highlight_tabs(self):
    btns = getattr(self, '_tab_btns', None) or {}
    cur = getattr(self, '_current_tab', 'config')
    for key, pair in btns.items():
        lbl, bar = pair
        on = (key == cur)
        try:
            _ui_raw_conf(lbl, bg=(_SB['active'] if on else _SB['bg']), fg=(_SB['white'] if on else _SB['text']))
            lbl.configure(font=(_F13, 10, 'bold') if on else (_F13, 10))
            _ui_raw_conf(bar, bg=(_SB['bar'] if on else _SB['bg']))
        except Exception:
            pass
    _ui13_tabs_draw(self)


FacebookMultiPosterApp._highlight_tabs = _ui13_highlight_tabs


def _ui13_finish(self):
    if getattr(self, '_ui13_done', False):
        return
    self._ui13_cards = []
    for fn in (_ui13_chrome, _ui13_topbar, _ui13_style_sidebar, _ui_reset_responsive, _ui13_blocks,
               _ui13_wm_compact, _ui13_sections, _ui13_accounts_card, _ui13_style_journal, _ui13_compact,
               _ui13_theme_misc):
        try:
            fn(self)
        except Exception:
            _ui13_dbg()
