# =====================================================================
# v14 — human typing (no accidental tags, pasted links), comment always
#        on the post just published, theme capsule, collapsible
#        Watermark, ZIP timers, Delete Post & Decline
# =====================================================================
import threading as _ui14_threading
import unicodedata as _ui14_ud

_UI14_TLS = _ui14_threading.local()          # sid of the account typing in this thread
_UI14_OPT = {'human': True}                  # read by worker threads (Tk var -> dict)

_UI14_URL_RX = re.compile(r'(?:https?://|www\.)[^\s<>"\'\u00ab\u00bb]+', re.I)
_UI14_NEAR = {
    'q': 'wa', 'w': 'qeas', 'e': 'wrsd', 'r': 'etdf', 't': 'ryfg', 'y': 'tugh', 'u': 'yihj',
    'i': 'uojk', 'o': 'ipkl', 'p': 'ol', 'a': 'qwsz', 's': 'awedxz', 'd': 'serfcx', 'f': 'drtgvc',
    'g': 'ftyhbv', 'h': 'gyujnb', 'j': 'huikmn', 'k': 'jiolm', 'l': 'kop', 'z': 'asx', 'x': 'zsdc',
    'c': 'xdfv', 'v': 'cfgb', 'b': 'vghn', 'n': 'bhjm', 'm': 'njk'}

# A mention / hashtag suggestion list is open (Facebook's tag popup)
_UI14_TA_JS = r"""() => {
  const vis = e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; };
  for (const lb of document.querySelectorAll('[role="listbox"]')) {
    if (vis(lb) && lb.querySelector('[role="option"]')) return true;
  }
  return false;
}"""

# Paste the link as ONE block through a synthetic paste event (no OS clipboard:
# several browsers post in parallel and must never swap their links)
_UI14_PASTE_JS = r"""(t) => {
  let el = document.activeElement;
  if (el && !el.isContentEditable) el = el.closest && el.closest('[contenteditable="true"]');
  if (!el) return -1;
  const before = (el.innerText || '').length;
  try {
    const dt = new DataTransfer();
    dt.setData('text/plain', t);
    el.dispatchEvent(new ClipboardEvent('paste', {clipboardData: dt, bubbles: true, cancelable: true}));
  } catch (e) { return -2; }
  return before;
}"""

_UI14_TEXT_JS = r"""(el) => {
  let mention = false;
  for (const a of el.querySelectorAll('a, [data-lexical-mention], [data-mention], [data-mention-id]')) {
    if (a.matches('[data-lexical-mention], [data-mention], [data-mention-id]')) { mention = true; break; }
    const tx = (a.innerText || '').trim();
    if (tx && !/^(https?:\/\/|www\.)/i.test(tx) && tx[0] !== '#') { mention = true; break; }
  }
  return {text: el.innerText || '', mention: mention};
}"""

_UI14_KEEP_EDIT_JS = r"""() => {
  const W = ['continue editing', 'keep editing', 'continuer la modification', 'continuer \u00e0 modifier',
             'reprendre la modification', 'seguir editando', 'continuar editando',
             '\u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u062a\u0639\u062f\u064a\u0644',
             '\u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u062a\u062d\u0631\u064a\u0631'];
  for (const d of document.querySelectorAll('[role="dialog"], [aria-modal="true"]')) {
    for (const b of d.querySelectorAll('[role="button"], button')) {
      const t = (b.innerText || '').trim().toLowerCase();
      if (W.includes(t)) { b.click(); return true; }
    }
  }
  return false;
}"""


def _ui14_tokens(texte):
    """[('txt'|'url'|'nl', piece)] — links are pasted, never typed."""
    out, pos = [], 0
    for m in _UI14_URL_RX.finditer(texte):
        url = m.group(0).rstrip('.,;:!?)]}\'"')
        if not url:
            continue
        if m.start() > pos:
            out.append(('txt', texte[pos:m.start()]))
        out.append(('url', url))
        pos = m.start() + len(url)
    if pos < len(texte):
        out.append(('txt', texte[pos:]))
    res = []
    for kind, s in out:
        if kind == 'url':
            res.append((kind, s))
            continue
        for i, ln in enumerate(s.split('\n')):
            if i:
                res.append(('nl', '\n'))
            if ln:
                res.append(('txt', ln))
    return res


def _ui14_delay(n):
    """ms per key: slow at first, then faster (ease-out), with jitter."""
    k = min(1.0, n / 80.0)
    base = 175.0 + (40.0 - 175.0) * (1.0 - (1.0 - k) ** 2)
    return max(16, int(base * random.uniform(0.72, 1.32)))


def _ui14_wrong(ch):
    near = _UI14_NEAR.get(ch.lower())
    if not near:
        return None
    w = random.choice(near)
    return w.upper() if ch.isupper() else w


def _ui14_type_chars(page, s, n):
    if not s:
        return
    if n < 30:                                   # the slow start: key by key
        for j, ch in enumerate(s):
            page.keyboard.type(ch)
            page.wait_for_timeout(_ui14_delay(n + j))
    else:
        page.keyboard.type(s, delay=_ui14_delay(n))


def _ui14_type_word(page, word, n, typo=None):
    if typo is None:
        _ui14_type_chars(page, word, n)
        return
    i = typo
    wrong = _ui14_wrong(word[i])
    if wrong is None:
        _ui14_type_chars(page, word, n)
        return
    _ui14_type_chars(page, word[:i], n)
    extra = word[i + 1] if (i + 1 < len(word) and random.random() < 0.45) else ''
    _ui14_type_chars(page, wrong + extra, n + i)
    page.wait_for_timeout(random.randint(240, 560))            # notices the mistake
    for _ in range(1 + len(extra)):
        page.keyboard.press('Backspace')
        page.wait_for_timeout(random.randint(70, 140))
    page.wait_for_timeout(random.randint(90, 220))
    _ui14_type_chars(page, word[i:], n + i)


def _ui14_ta_open(page):
    try:
        return bool(page.evaluate(_UI14_TA_JS))
    except Exception:
        return False


def _ui14_close_ta(page, tb):
    """Close Facebook's tag popup without choosing anyone (Escape), keeping
    the composer open."""
    for _ in range(3):
        if not _ui14_ta_open(page):
            return True
        try:
            page.keyboard.press('Escape')
        except Exception:
            return False
        page.wait_for_timeout(200)
        try:
            alive = tb.is_visible()
        except Exception:
            alive = False
        if not alive:
            try:
                page.evaluate(_UI14_KEEP_EDIT_JS)
                page.wait_for_timeout(300)
                tb.click(timeout=3000)
                page.keyboard.press('Control+End')
            except Exception:
                pass
    return not _ui14_ta_open(page)


def _ui14_editor_len(tb):
    try:
        return int(tb.evaluate('el => (el.innerText || "").length'))
    except Exception:
        return -1


def _ui14_paste(page, tb, url):
    before = -1
    try:
        before = int(page.evaluate(_UI14_PASTE_JS, url))
    except Exception:
        before = -1
    if before >= 0:
        page.wait_for_timeout(150)
        if _ui14_editor_len(tb) >= before + len(url) - 2:
            return True
    try:
        page.keyboard.insert_text(url)          # still one block, never key by key
        return True
    except Exception:
        return False


def _ui14_human_type(self, page, tb, texte):
    sid = getattr(_UI14_TLS, 'sid', None)
    last = [time.time()]

    def beat():
        if sid is not None and time.time() - last[0] > 4:
            last[0] = time.time()
            try:
                self._wd_beat(sid, 'saisie du texte', 4)
            except Exception:
                pass
    texte = texte.replace('\r\n', '\n').replace('\r', '\n')
    n = 0
    typos_left = min(3, 1 + len(texte) // 140)
    next_typo = random.randint(18, 45)
    page.wait_for_timeout(random.randint(350, 800))            # "thinking" before typing
    for kind, s in _ui14_tokens(texte):
        beat()
        if getattr(self, '_closing', False):
            raise Exception('fermeture')
        if kind == 'url':
            _ui14_close_ta(page, tb)
            if n:
                page.wait_for_timeout(random.randint(180, 420))
            if not _ui14_paste(page, tb, s):
                raise Exception('link paste failed')
            page.wait_for_timeout(random.randint(400, 900))    # link preview loads
            n += len(s)
        elif kind == 'nl':
            page.wait_for_timeout(random.randint(260, 520))
            _ui14_close_ta(page, tb)                           # Enter would pick a name
            page.keyboard.press('Enter')
            page.wait_for_timeout(random.randint(250, 650))
            n += 1
        else:
            for piece in re.findall(r'\s+|\S+', s):
                beat()
                if piece.isspace():
                    page.keyboard.type(piece, delay=_ui14_delay(n))
                    n += len(piece)
                    page.wait_for_timeout(random.randint(30, 140))
                    continue
                typo = None
                spots = [i for i in range(1, len(piece) - 1)
                         if piece[i].isalpha() and piece[i].lower() in _UI14_NEAR]
                if typos_left > 0 and n >= next_typo and len(piece) >= 4 and spots \
                        and random.random() < 0.5:
                    typo = random.choice(spots)
                    typos_left -= 1
                    next_typo = n + random.randint(45, 120)
                _ui14_type_word(page, piece, n, typo)
                n += len(piece)
                if piece[-1:] in '.!?':
                    page.wait_for_timeout(random.randint(220, 600))
                if piece[:1].isupper() or piece[:1] in '@#':
                    if _ui14_ta_open(page):
                        _ui14_close_ta(page, tb)
    page.wait_for_timeout(450)                                 # a late popup, if any
    _ui14_close_ta(page, tb)
    return True


def _ui14_norm_text(s):
    return re.sub(r'\s+', ' ', _ui14_ud.normalize('NFC', s or '')).strip()


def _ui14_check_text(page, tb, texte):
    try:
        got = tb.evaluate(_UI14_TEXT_JS) or {}
    except Exception as e:
        return False, 'text not readable (%s)' % e
    if got.get('mention'):
        return False, 'a tag/mention was inserted'
    a, b = _ui14_norm_text(got.get('text')), _ui14_norm_text(texte)
    if a == b:
        return True, ''
    import difflib
    r = difflib.SequenceMatcher(None, a, b).ratio()
    if r >= 0.985:
        return True, ''
    return False, 'typed text differs (%.0f%% identical)' % (r * 100)


_ui14_prev_type_text = FacebookMultiPosterApp._type_text


def _ui14_type_text(self, page, texte):
    """Human-like typing of the description: slow start then faster,
    occasional typo corrected, links pasted in one go, tag popup closed."""
    if not texte or not _UI14_OPT.get('human', True):
        return _ui14_prev_type_text(self, page, texte)
    self.log('  \u2192 Text (%d chars, human typing)\u2026' % len(texte))
    scope, kind = self._wait_for_composer(page, timeout_ms=10000)
    if scope is None:
        raise Exception("Compositeur introuvable \u2014 saisie annulee (refus d'ecrire hors du compositeur)")
    tb = scope.locator('div[role="textbox"], [contenteditable="true"]').first if kind == 'dialog' else scope
    if self._est_zone_commentaire(tb):
        raise Exception("Zone de commentaire detectee \u2014 saisie annulee (le compositeur n'etait pas ouvert)")
    try:
        if tb.count() == 0:
            raise Exception('vide')
    except Exception:
        raise Exception('Zone de texte du compositeur introuvable')
    tb.click(timeout=5000)
    page.wait_for_timeout(500)
    tb.focus()
    try:
        page.keyboard.press('Control+A')
        page.keyboard.press('Backspace')
        _ui14_human_type(self, page, tb, texte)
        ok, why = _ui14_check_text(page, tb, texte)
        if ok:
            self.log('  \u2192 Text typed (human rhythm, links pasted, no tag).')
            return
        self.log('  \u26a0\ufe0f Typing check: %s \u2014 text re-inserted as plain text.' % why)
    except Exception as e:
        if 'fermeture' in str(e):
            raise
        self.log('  \u26a0\ufe0f Human typing interrupted (%s) \u2014 direct insertion.' % e)
    _ui14_prev_type_text(self, page, texte)       # the proven insertion as safety net
    _ui14_close_ta(page, tb)


FacebookMultiPosterApp._type_text = _ui14_type_text

_ui14_prev_publish = FacebookMultiPosterApp._publish_post


def _ui14_publish_post(self, page, task_url, task, sid, post_num, target_type, *a, **kw):
    _UI14_TLS.sid = sid                            # lets the typing keep the watchdog fed
    try:
        return _ui14_prev_publish(self, page, task_url, task, sid, post_num, target_type, *a, **kw)
    finally:
        _UI14_TLS.sid = None


FacebookMultiPosterApp._publish_post = _ui14_publish_post


# ------------------------------------------ comment: verified target post
_UI14_VERIFY_JS = r"""(args) => {
  const norm = s => (s || '').normalize('NFC').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '');
  const needle = args.needle || '';
  const isCommentArt = (a) => {
    if (!a) return false;
    if (a.parentElement && a.parentElement.closest('[role="article"]')) return true;
    const lab = (a.getAttribute('aria-label') || '').toLowerCase();
    return /comment|coment|\u062a\u0639\u0644\u064a\u0642|reply|r\u00e9pon|respuest/.test(lab);
  };
  const inComment = (el) => isCommentArt(el.closest('[role="article"]'));
  const MSG = '[data-ad-rendering-role="story_message"], [data-ad-comet-preview="message"], [data-ad-preview="message"]';
  const dlg = Array.from(document.querySelectorAll('div[role="dialog"]')).filter(d => {
    const r = d.getBoundingClientRect(); return r.width > 300 && r.height > 200; });
  const scope = dlg.length ? dlg[dlg.length - 1] : (document.querySelector('[role="main"]') || document.body);
  const msgs = Array.from(scope.querySelectorAll(MSG)).filter(e => !inComment(e) && (e.innerText || '').trim());
  const head = (document.body.innerText || '').slice(0, 3000);
  const unavailable = /content isn.t available|contenu n.est pas disponible|contenido no est\u00e1 disponible|\u063a\u064a\u0631 \u0645\u062a\u0627\u062d/i.test(head);
  if (!msgs.length) return {msgs: 0, mine: false, dialog: dlg.length > 0, unavailable: unavailable};
  const first = norm(msgs[0].innerText);
  return {msgs: msgs.length, mine: !!needle && first.includes(needle), dialog: dlg.length > 0,
          unavailable: unavailable, first: first.slice(0, 40)};
}"""


def _ui14_needle(info):
    return _ui_norm(_ui14_ud.normalize('NFC', (info or {}).get('texte') or ''))[:32]


def _ui14_verify_post_page(page, needle, info, timeout=8.0):
    """(True, '') only when the page shows ONE post view whose post text is
    ours. Polls a few seconds (a fresh post can render late)."""
    deadline = time.time() + timeout
    why = 'not checked'
    perma = (info or {}).get('permalink') or ''
    pid = re.search(r'/posts/(\d+)', perma)
    while True:
        try:
            url = page.url or ''
        except Exception:
            url = ''
        try:
            res = page.evaluate(_UI14_VERIFY_JS, {'needle': needle}) or {}
        except Exception:
            res = {}
        post_view = bool(_UI_PERMA_RX.search(url)) or bool(res.get('dialog'))
        if res.get('unavailable'):
            why = 'the post is not available at its address (pending approval?)'
        elif not post_view:
            why = 'Facebook opened another page (%s)' % (url.split('?')[0][-60:] or '?')
        elif needle:
            if res.get('mine'):
                return True, ''
            if res.get('msgs', 0) == 0:
                try:
                    if _ui_dom_locate(page, needle)[0]:
                        return True, ''
                except Exception:
                    pass
                why = 'no post text on the page yet'
            else:
                why = 'the post on this page has another text ("%s\u2026")' % (res.get('first') or '')[:24]
        else:                                     # no text: the address must be the captured one
            if pid and pid.group(1) in url:
                return True, ''
            why = 'post without text cannot be verified here'
        if time.time() >= deadline:
            return False, why
        try:
            page.wait_for_timeout(700)
        except Exception:
            time.sleep(0.7)


def _ui14_verify_or_clean(page, needle, info):
    """Verify; if the address carries tracking parameters, retry the clean
    post address once (Facebook shows the same post there)."""
    ok, why = _ui14_verify_post_page(page, needle, info)
    if ok:
        return ok, why
    try:
        url = page.url or ''
    except Exception:
        return ok, why
    base = url.split('?')[0]
    if '?' in url and re.search(r'/(?:posts|permalink)/\d+', base):
        try:
            page.goto(base, wait_until='domcontentloaded', timeout=30000)
            return _ui14_verify_post_page(page, needle, info)
        except Exception:
            pass
    return ok, why


_ui14_prev_goto_own_post = _ui_goto_own_post


def _ui_goto_own_post(app, page, info, sid):
    """v14: open the post just published AND prove it is that post before any
    comment is written (the captured link is checked, never trusted blindly)."""
    needle = _ui14_needle(info)
    captured = bool(info.get('permalink'))
    st = _ui14_prev_goto_own_post(app, page, info, sid)
    if st == 'ok':
        ok, why = _ui14_verify_or_clean(page, needle, info)
        if ok:
            app.log('  \u2713 Verified: this is the post just published \u2014 adding the comment here.')
            return 'ok'
        app.log('  \u26a0\ufe0f Opened post is not the one just published (%s).' % why)
        if captured and needle:
            info['bad_permalink'] = info.get('permalink')
            info['permalink'] = None
            app.log('  \u2192 Searching the group for the post by its text\u2026')
            try:
                st = _ui14_prev_goto_own_post(app, page, info, sid)
            except Exception:
                st = 'notfound'
            if st == 'ok':
                ok, why = _ui14_verify_or_clean(page, needle, info)
                if ok:
                    app.log('  \u2713 Verified: post found by its text \u2014 adding the comment here.')
                    return 'ok'
                app.log('  \u26a0\ufe0f Still not our post (%s).' % why)
    return 'notfound'



# ---------------------------------------------- theme: capsule switch
def _ui14_pill(d, box, fill):
    x0, y0, x1, y1 = box
    r = (y1 - y0) / 2.0
    if x1 - x0 <= 2 * r:
        d.ellipse((x0, y0, x1, y1), fill=fill)
        return
    d.rectangle((x0 + r, y0, x1 - r, y1), fill=fill)
    d.ellipse((x0, y0, x0 + 2 * r, y1), fill=fill)
    d.ellipse((x1 - 2 * r, y0, x1, y1), fill=fill)


def _ui14_capsule(self, dark=None):
    """Rounded capsule switch: sun on the left (light) / moon on the right (dark)."""
    import math
    from PIL import Image, ImageDraw, ImageTk
    if dark is None:
        dark = _ui13_is_dark()
    z = _UI_ZOOM[0]
    key = (bool(dark), round(z, 2))
    cache = getattr(self, '_ui14_caps', None)
    if cache is None:
        cache = self._ui14_caps = {}
    if key in cache:
        return cache[key]
    W, H = max(30, int(round(50 * z))), max(16, int(round(26 * z)))
    S = 4
    w, h = W * S, H * S
    im = Image.new('RGBA', (w, h), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    _ui14_pill(d, (0, 0, w - 1, h - 1), '#334155' if dark else '#e3e9f6')           # halo
    ins = int(2.2 * S)
    tr = (ins, ins, w - 1 - ins, h - 1 - ins)
    th = tr[3] - tr[1]
    _ui14_pill(d, tr, '#33437c' if dark else '#fcd34d')                              # track
    bw, bh = max(S * 2, int(th * 0.13)), int(th * 0.48)
    cy = (tr[1] + tr[3]) // 2
    bx = tr[0] + int((tr[2] - tr[0]) * (0.28 if dark else 0.58))
    for k in (0, 1):                                                                  # grip bars
        x = bx + k * int(bw * 2.3)
        _ui14_pill(d, (x, cy - bh // 2, x + bw, cy + bh // 2), '#4a5a9a' if dark else '#f5a524')
    kd = th - 2 * S
    kx = (tr[2] - S - kd) if dark else (tr[0] + S)
    ky = cy - kd // 2
    box = (kx, ky, kx + kd, ky + kd)
    d.ellipse(box, fill=('#5b78b8' if dark else '#45bdf5'))                           # knob
    d.pieslice(box, -90, 90, fill=('#4c5d9c' if dark else '#2fa3e6'))
    ccx, ccy = kx + kd / 2.0, ky + kd / 2.0
    if dark:                                                                          # moon
        mr = kd * 0.30
        mask = Image.new('L', (w, h), 0)
        md = ImageDraw.Draw(mask)
        md.ellipse((ccx - mr, ccy - mr, ccx + mr, ccy + mr), fill=255)
        off = mr * 0.62
        md.ellipse((ccx - mr + off, ccy - mr - off * 0.55, ccx + mr + off, ccy + mr - off * 0.55), fill=0)
        im.paste(Image.new('RGBA', (w, h), '#e8eefc'), (0, 0), mask)
    else:                                                                             # sun
        pr, rr = kd * 0.11, kd * 0.25
        for i in range(8):
            a = i * math.pi / 4.0
            px, py = ccx + math.cos(a) * rr, ccy + math.sin(a) * rr
            d.ellipse((px - pr, py - pr, px + pr, py + pr), fill='#fde047')
        cr = kd * 0.15
        d.ellipse((ccx - cr, ccy - cr, ccx + cr, ccy + cr), fill='#f59e0b')
    im = im.resize((W, H), Image.LANCZOS)
    ph = ImageTk.PhotoImage(im, master=self.root)
    cache[key] = ph
    return ph


def _ui14_theme_toggle_ui(self):
    lbl = getattr(self, '_theme_btn_lbl', None)
    if lbl is None:
        return
    lbl._i18n_src = None
    _ui_raw_conf(lbl, image=_ui14_capsule(self), text='', padx=6, pady=0, bd=0, compound='center')

    def fix(kw):
        if 'text' in kw:                           # toggle_theme sets a glyph: show the capsule
            kw.pop('text', None)
            kw['image'] = _ui14_capsule(self)
        return kw
    _ui13_guard(lbl, fix)
    lbl.bind('<Enter>', lambda e: None)
    lbl.bind('<Leave>', lambda e: None)
    self._ui14_theme_lbl = lbl


def _ui14_capsule_refresh(self):
    lbl = getattr(self, '_ui14_theme_lbl', None)
    if lbl is not None:
        try:
            _ui_raw_conf(lbl, image=_ui14_capsule(self), bg=C['surface'])
        except Exception:
            pass


# ------------------------------------ Tor & Watermark: collapsible cards
def _ui14_chevron(self, title, state_fn, on_click):
    import tkinter as _tk
    ic = _tk.Label(title, bg=C['surface'], cursor='hand2', bd=0)
    ic._i18n_src = None
    ic.pack(side='right')
    _ui_add_icon(self, ic, 'dropdown', 30, state_fn)
    try:
        _ui_raw_conf(ic, image=_ui_icon(ic, 'dropdown', 30, bool(state_fn())))
    except Exception:
        pass
    for w in [ic, title] + [c for c in title.pack_slaves() if c is not ic]:
        try:
            w.bind('<Button-1>', lambda e: on_click(), add='+')
            w.configure(cursor='hand2')
        except Exception:
            pass
    return ic


def _ui14_card_chevrons(self):
    c3 = getattr(self, '_ui_cfg3', None)
    if not c3:
        return
    tor = c3.get('tor')
    t_tor, p_tor = c3['blocks']['tor']
    if tor and not getattr(t_tor, '_ui14_chev', False):
        ic = _ui14_chevron(self, t_tor, lambda: bool(c3['tor']['open']), lambda: self._ui_tor_toggle())
        try:
            tor['icon'].pack_forget()
        except Exception:
            pass
        tor['icon'] = ic                         # _ui_tor_toggle now updates this arrow
        t_tor._ui14_chev = True
        _ui13_overlay_title(p_tor, t_tor)        # title row a little taller now
        _ui13_raise(t_tor)
    t_wm, p_wm = c3['blocks']['wm']
    if getattr(p_wm, '_ui14_wm', False):
        return
    inner = next((c for c in p_wm.pack_slaves() if c is not t_wm), None)
    if inner is None:
        return
    info = inner.pack_info()
    st = {'open': True, 'inner': inner, 'pack': info, 'title': t_wm}
    c3['wm'] = st
    st['icon'] = _ui14_chevron(self, t_wm, lambda: bool(c3['wm']['open']), lambda: _ui14_wm_toggle(self))
    p_wm._ui14_wm = True
    _ui14_wm_toggle(self, False)                 # collapsed by default, like Tor


def _ui14_wm_toggle(self, open_=None):
    c3 = getattr(self, '_ui_cfg3', None) or {}
    st = c3.get('wm')
    if not st:
        return
    new = (not st['open']) if open_ is None else bool(open_)
    st['open'] = new
    inner, t = st['inner'], st['title']
    try:
        if new:
            opts = {k: v for k, v in st['pack'].items() if k != 'in'}
            inner.pack(in_=st['pack'].get('in'), **opts)
            t.pack_configure(pady=(11, 4))
        else:
            inner.pack_forget()
            t.pack_configure(pady=(11, 11))
    except Exception:
        _ui13_dbg()
    try:
        _ui_raw_conf(st['icon'], image=_ui_icon(st['icon'], 'dropdown', 30, new))
    except Exception:
        pass
    try:
        self._ui_request_relayout(force=True)
    except Exception:
        pass


FacebookMultiPosterApp._ui14_wm_toggle = _ui14_wm_toggle


# ------------------------------------------------ human typing switch
def _ui14_clone(ref, parent, **over):
    """New widget styled exactly like `ref` (same class, fonts, images, skin)."""
    opts = {}
    for k in ('font', 'bg', 'fg', 'activebackground', 'activeforeground', 'selectcolor', 'relief', 'bd',
              'highlightthickness', 'highlightbackground', 'highlightcolor', 'cursor', 'indicatoron',
              'image', 'selectimage', 'compound', 'padx', 'pady', 'anchor', 'justify', 'offrelief',
              'overrelief', 'disabledforeground', 'insertbackground', 'buttonbackground', 'width'):
        try:
            v = ref.cget(k)
        except Exception:
            continue
        if k == 'width' and 'width' not in over:
            continue
        opts[k] = v
    opts.update(over)
    w = type(ref)(parent, **opts)
    for a in ('_ui_skin',):
        if hasattr(ref, a):
            setattr(w, a, getattr(ref, a))
    return w


def _ui14_find(root, pred):
    for w in _ui_walk(root):
        try:
            if pred(w):
                return w
        except Exception:
            pass
    return None


def _ui14_typing_toggle(self):
    import tkinter as _tk
    c3 = getattr(self, '_ui_cfg3', None)
    if not c3 or getattr(self, '_ui14_typing_var', None) is not None:
        return
    L = c3['br_cols'][0]
    sw_ref = _ui14_find(L, lambda w: w.winfo_class() == 'Checkbutton' and getattr(w, '_ui_skin', None) == 'switch')
    rows = [int(s.grid_info()['row']) for s in L.grid_slaves()]
    tl_ref = None
    for s in L.grid_slaves():
        if s.winfo_class() == 'Label' and 'bold' in str(s.cget('font')):
            tl_ref = s
            break
    if sw_ref is None or tl_ref is None:
        return
    r = (max(rows) + 1) if rows else 0
    self._ui14_typing_var = _tk.BooleanVar(value=True)
    gi = tl_ref.grid_info()
    lab = _tk.Label(L, text='Frappe humaine', font=tl_ref.cget('font'), bg=tl_ref.cget('bg'),
                    fg=tl_ref.cget('fg'))
    lab.grid(row=r, column=0, columnspan=int(gi.get('columnspan', 1)), sticky='w', pady=(6, 2))
    sw = _ui14_clone(sw_ref, L, text='D\u00e9but lent, fautes corrig\u00e9es, liens coll\u00e9s',
                     variable=self._ui14_typing_var, onvalue=True, offvalue=False)
    sw.grid(row=r + 1, column=0, columnspan=int(gi.get('columnspan', 1)), sticky='w')

    def sync(*_a):
        try:
            _UI14_OPT['human'] = bool(self._ui14_typing_var.get())
        except Exception:
            pass
    self._ui14_typing_var.trace_add('write', sync)
    sync()


# ------------------------------------------------------------ ZIP timers
_UI14_TIMERS = {}
_UI14_TIMERS_LOCK = _ui14_threading.Lock()


def _ui14_timers_path():
    return os.path.join(SESSION_BASE, 'zip_timers.json')


def _ui14_timers_load():
    import json
    try:
        with open(_ui14_timers_path(), encoding='utf-8') as f:
            d = json.load(f)
    except Exception:
        d = {}
    with _UI14_TIMERS_LOCK:
        _UI14_TIMERS.clear()
        _UI14_TIMERS.update({k: v for k, v in (d or {}).items() if isinstance(v, dict)})


def _ui14_timers_save():
    import json
    try:
        with _UI14_TIMERS_LOCK:
            data = json.dumps(_UI14_TIMERS, ensure_ascii=False, indent=1)
        p = _ui14_timers_path()
        tmp = p + '.tmp'
        with open(tmp, 'w', encoding='utf-8') as f:
            f.write(data)
        os.replace(tmp, p)
    except Exception:
        pass


def _ui14_tkey(zp):
    return os.path.normcase(os.path.abspath(zp or ''))


def _ui14_parse_time(s):
    m = re.match(r'^\s*(\d{1,2})\s*[:hH.]\s*(\d{2})\s*$', s or '')
    if not m:
        return None
    hh, mm = int(m.group(1)), int(m.group(2))
    if hh > 23 or mm > 59:
        return None
    return '%02d:%02d' % (hh, mm)


def _ui14_parse_date(s):
    from datetime import datetime as _dt
    s = (s or '').strip()
    for fmt in ('%Y-%m-%d', '%d/%m/%Y', '%d-%m-%Y', '%Y/%m/%d'):
        try:
            return _dt.strptime(s, fmt).strftime('%Y-%m-%d')
        except Exception:
            pass
    return None


def _ui14_window(t):
    """(start, end|None) datetimes of a timer, None if invalid."""
    from datetime import datetime as _dt, timedelta as _td
    if not t:
        return None
    try:
        start = _dt.strptime('%s %s' % (t['date'], t['start']), '%Y-%m-%d %H:%M')
    except Exception:
        return None
    end = None
    if t.get('end'):
        try:
            end = _dt.strptime('%s %s' % (t['date'], t['end']), '%Y-%m-%d %H:%M')
            if end <= start:
                end += _td(days=1)                  # e.g. 22:00 -> 01:00
        except Exception:
            end = None
    return start, end


def _ui14_tstate(t, now=None):
    from datetime import datetime as _dt
    w = _ui14_window(t)
    if w is None:
        return 'none'
    now = now or _dt.now()
    start, end = w
    if now < start:
        return 'wait'
    if end is None or now < end:
        return 'active'
    return 'done'


def _ui14_tlabel(t, now=None):
    from datetime import datetime as _dt, timedelta as _td
    w = _ui14_window(t)
    if w is None:
        return '?'
    start, end = w
    now = now or _dt.now()
    if start.date() == now.date():
        day = ''
    elif start.date() == (now + _td(days=1)).date():
        day = _TR('Demain') + ' '
    else:
        day = start.strftime('%d/%m') + ' '
    s = day + start.strftime('%H:%M')
    if end is not None:
        s += ' \u2192 ' + end.strftime('%H:%M')
    return s


def _ui14_zip_timer_widgets(self):
    import tkinter as _tk
    lf = getattr(self, '_ui_zip_list', None)
    if lf is None:
        return
    rows = [w for w in lf.winfo_children() if w.winfo_class() == 'Frame']
    items = list(getattr(self, '_ui_zip_items', []) or [])
    F = _F13
    for row, it in zip(rows, items):
        zp = it[0]
        t = _UI14_TIMERS.get(_ui14_tkey(zp))
        if t and _ui14_window(t):
            st = _ui14_tstate(t)
            col = {'wait': C['accent'], 'active': C['success'], 'done': C['text3']}.get(st, C['accent'])
            mark = {'wait': '\u23f0 ', 'active': '\u25cf ', 'done': '\u2713 '}.get(st, '')
            chip = _tk.Label(row, text=mark + _ui14_tlabel(t), font=(F, 8, 'bold'), bg=C['surface'], fg=col,
                             padx=6, pady=1, cursor='hand2', highlightthickness=1,
                             highlightbackground=col, highlightcolor=col)
            chip._i18n_src = None
        else:
            chip = _tk.Label(row, text='+ Ajouter une heure', font=(F, 8, 'bold'), bg=C['accent'],
                             fg='#ffffff', padx=6, pady=1, cursor='hand2')
        chip.pack(side='right', padx=(4, 4))
        chip.bind('<Button-1>', lambda e, z=zp: _ui14_timer_edit(self, z))
        chip._ui14_timer = True


_ui14_prev_zip_render = _ui_zip_render


def _ui_zip_render(self):
    _ui14_prev_zip_render(self)
    try:
        _ui14_zip_timer_widgets(self)
    except Exception:
        _ui13_dbg()


if getattr(FacebookMultiPosterApp, '_ui_zip_render', None) is _ui14_prev_zip_render:
    FacebookMultiPosterApp._ui_zip_render = _ui_zip_render

_ui14_prev_zip_remove = _ui_zip_remove


def _ui_zip_remove(self, zp):
    r = _ui14_prev_zip_remove(self, zp)
    try:
        still = any(_ui14_tkey(it[0]) == _ui14_tkey(zp) for it in (getattr(self, '_ui_zip_items', []) or []))
        if not still and _ui14_tkey(zp) in _UI14_TIMERS:
            with _UI14_TIMERS_LOCK:
                _UI14_TIMERS.pop(_ui14_tkey(zp), None)
            _ui14_timers_save()
    except Exception:
        pass
    return r


def _ui14_timer_set(self, zp, date, start, end=''):
    """Validated save; returns an error text or ''."""
    d = _ui14_parse_date(date)
    s = _ui14_parse_time(start)
    e = _ui14_parse_time(end) if (end or '').strip() else ''
    if not d or not s or e is None:
        return _TR('Date ou heure invalide (AAAA-MM-JJ, HH:MM).')
    t = {'date': d, 'start': s, 'end': e or '', 'name': os.path.basename(zp)}
    with _UI14_TIMERS_LOCK:
        _UI14_TIMERS[_ui14_tkey(zp)] = t
    _ui14_timers_save()
    try:
        self.log('\u23f0 ZIP timer set: %s \u2014 %s' % (os.path.basename(zp), _ui14_tlabel(t)))
    except Exception:
        pass
    return ''


def _ui14_timer_clear(self, zp):
    with _UI14_TIMERS_LOCK:
        _UI14_TIMERS.pop(_ui14_tkey(zp), None)
    _ui14_timers_save()
    try:
        self.log('\u23f0 ZIP timer removed: %s' % os.path.basename(zp))
    except Exception:
        pass


def _ui14_timer_edit(self, zp):
    """Small editor: date + start (+ optional end); Save / Remove / Cancel."""
    import tkinter as _tk
    from datetime import datetime as _dt, timedelta as _td
    key = _ui14_tkey(zp)
    t = dict(_UI14_TIMERS.get(key) or {})
    now = _dt.now()
    if not t:
        nxt = now + _td(minutes=15)
        t = {'date': nxt.strftime('%Y-%m-%d'), 'start': nxt.strftime('%H:00' if nxt.minute < 5 else '%H:%M'),
             'end': ''}
    host = self.root.winfo_toplevel()
    top = _tk.Toplevel(host)
    top.withdraw()
    top.title(_TR('Minuterie ZIP'))
    top.configure(bg=C['surface'])
    top.resizable(False, False)
    self._ui14_timer_win = top
    F = _F13
    frm = _tk.Frame(top, bg=C['surface'], padx=18, pady=14)
    frm.pack(fill='both', expand=True)
    hd = _tk.Label(frm, text='\u23f0  ' + os.path.basename(zp), font=(F, 10, 'bold'), bg=C['surface'],
                   fg=C['text'])
    hd._i18n_src = None
    hd.grid(row=0, column=0, columnspan=4, sticky='w', pady=(0, 10))

    def entry(val, w):
        e = _tk.Entry(frm, width=w, font=(F, 10), bg=C['surface2'], fg=C['text'], relief='flat', bd=5,
                      insertbackground=C['accent'], highlightthickness=1, highlightbackground=C['border'],
                      highlightcolor=C['accent'])
        e.insert(0, val)
        return e
    _tk.Label(frm, text='Date', font=(F, 9, 'bold'), bg=C['surface'], fg=C['text2']).grid(
        row=1, column=0, sticky='w')
    e_date = entry(t.get('date', ''), 12)
    e_date.grid(row=1, column=1, sticky='w', padx=(8, 6), pady=3)

    def setday(k):
        e_date.delete(0, 'end')
        e_date.insert(0, (now + _td(days=k)).strftime('%Y-%m-%d'))
    for i, (txt, k) in enumerate((("Aujourd'hui", 0), ('Demain', 1))):
        b = _tk.Button(frm, text=txt, font=(F, 8), bg=C['surface3'], fg=C['text2'], relief='flat', bd=0,
                       padx=8, pady=2, cursor='hand2', command=lambda k=k: setday(k))
        b.grid(row=1, column=2 + i, sticky='w', padx=(0, 4))
    _tk.Label(frm, text='D\u00e9but', font=(F, 9, 'bold'), bg=C['surface'], fg=C['text2']).grid(
        row=2, column=0, sticky='w')
    e_start = entry(t.get('start', ''), 7)
    e_start.grid(row=2, column=1, sticky='w', padx=(8, 6), pady=3)
    _tk.Label(frm, text='Fin (facultatif)', font=(F, 9, 'bold'), bg=C['surface'], fg=C['text2']).grid(
        row=3, column=0, sticky='w')
    e_end = entry(t.get('end', ''), 7)
    e_end.grid(row=3, column=1, sticky='w', padx=(8, 6), pady=3)
    _tk.Label(frm, text='La publication de ce ZIP d\u00e9marre automatiquement \u00e0 cette heure '
                        "et s'arr\u00eate \u00e0 l'heure de fin.",
              font=(F, 8), bg=C['surface'], fg=C['text3'], wraplength=300, justify='left').grid(
        row=4, column=0, columnspan=4, sticky='w', pady=(6, 2))
    err = _tk.Label(frm, text='', font=(F, 8, 'bold'), bg=C['surface'], fg=C['danger'])
    err._i18n_src = None
    err.grid(row=5, column=0, columnspan=4, sticky='w')
    bar = _tk.Frame(frm, bg=C['surface'])
    bar.grid(row=6, column=0, columnspan=4, sticky='we', pady=(10, 0))

    def close():
        try:
            top.grab_release()
        except Exception:
            pass
        top.destroy()
        self._ui14_timer_win = None

    def save():
        msg = _ui14_timer_set(self, zp, e_date.get(), e_start.get(), e_end.get())
        if msg:
            _ui_raw_conf(err, text=msg)
            return
        close()
        _ui_zip_render(self)

    def remove():
        _ui14_timer_clear(self, zp)
        close()
        _ui_zip_render(self)
    _tk.Button(bar, text='Enregistrer', font=(F, 9, 'bold'), bg=C['accent'], fg='#ffffff', relief='flat',
               bd=0, padx=14, pady=5, cursor='hand2', command=save).pack(side='left')
    if key in _UI14_TIMERS:
        _tk.Button(bar, text='Supprimer la minuterie', font=(F, 9), bg=C['surface'], fg=C['danger'],
                   relief='flat', bd=0, padx=10, pady=5, cursor='hand2', command=remove).pack(side='left',
                                                                                              padx=(8, 0))
    _tk.Button(bar, text='Annuler', font=(F, 9), bg=C['surface3'], fg=C['text2'], relief='flat', bd=0,
               padx=12, pady=5, cursor='hand2', command=close).pack(side='right')
    top.protocol('WM_DELETE_WINDOW', close)
    top.bind('<Return>', lambda e: save())
    top.bind('<Escape>', lambda e: close())
    try:
        top.update_idletasks()
        x = host.winfo_rootx() + max(0, (host.winfo_width() - top.winfo_reqwidth()) // 2)
        y = host.winfo_rooty() + max(0, (host.winfo_height() - top.winfo_reqheight()) // 3)
        top.geometry('+%d+%d' % (x, y))
        top.deiconify()
        top.transient(host)
        top.lift()
        top.grab_set()
        e_start.focus_set()
    except Exception:
        top.deiconify()
    return top


def _ui14_timer_step(self, now=None):
    """Start posting when a ZIP's time comes; stop when its window ends."""
    from datetime import datetime as _dt
    items = list(getattr(self, '_ui_zip_items', []) or [])
    if not items:
        return
    now = now or _dt.now()
    changed = False
    running = bool(getattr(self, 'is_running', False))
    try:
        zip_on = bool(self._ui_src_zip_var.get())
    except Exception:
        zip_on = True
    active = []
    for zp, _c, _n in items:
        key = _ui14_tkey(zp)
        t = _UI14_TIMERS.get(key)
        if not t:
            continue
        st = _ui14_tstate(t, now)
        name = os.path.basename(zp)
        if st == 'active':
            active.append(key)
            if t.get('fired'):
                continue
            if not zip_on:
                t['fired'] = True
                changed = True
                self.log('\u23f0 ZIP timer %s reached, but the ZIP source is off \u2014 not started.' % name)
            elif not running:
                t['fired'] = True
                changed = True
                self._ui14_timer_run = key
                self.log('\u23f0 ZIP timer: %s \u2014 starting posting now (%s).' % (name, _ui14_tlabel(t, now)))
                try:
                    self.start_posting()
                except Exception as e:
                    self.log('\u26a0\ufe0f ZIP timer: posting could not start (%s).' % e)
                running = bool(getattr(self, 'is_running', False))
        elif st == 'done' and not t.get('ended'):
            t['ended'] = True
            changed = True
            if running and getattr(self, '_ui14_timer_run', None) == key:
                self.log('\u23f0 ZIP timer: %s \u2014 end of its window (%s), stopping posting.'
                         % (name, t.get('end')))
                self._ui14_timer_run = None
                if not active:
                    try:
                        self.stop_posting()
                    except Exception:
                        pass
    if changed:
        _ui14_timers_save()
    sig = tuple(_ui14_tstate(_UI14_TIMERS.get(_ui14_tkey(it[0])), now) for it in items)
    if sig != getattr(self, '_ui14_timer_sig', None):
        self._ui14_timer_sig = sig
        try:
            _ui_zip_render(self)
        except Exception:
            pass


def _ui14_timer_tick(self):
    if getattr(self, '_closing', False):
        return
    try:
        _ui14_timer_step(self)
    except Exception:
        _ui13_dbg()
    try:
        self._ui14_timer_job = self.root.after(15000, lambda: _ui14_timer_tick(self))
    except Exception:
        pass


def _ui14_zip_timers_init(self):
    _ui14_timers_load()
    try:
        _ui_zip_render(self)
    except Exception:
        pass
    try:
        self._ui14_timer_job = self.root.after(3000, lambda: _ui14_timer_tick(self))
    except Exception:
        pass


def _ui14_held(self, now=None):
    """ZIP items whose timer keeps them out of posting right now."""
    out = []
    for it in list(getattr(self, '_ui_zip_items', []) or []):
        t = _UI14_TIMERS.get(_ui14_tkey(it[0]))
        if t and _ui14_tstate(t, now) in ('wait', 'done'):
            out.append((it, t))
    return out


_ui14_prev_zip_pubs = _ui_zip_publications


def _ui_zip_publications(self):
    """Scheduled ZIPs only feed posting inside their time window."""
    items = list(getattr(self, '_ui_zip_items', []) or [])
    held = _ui14_held(self)
    if not held:
        return _ui14_prev_zip_pubs(self)
    hk = set(_ui14_tkey(it[0]) for it, _t in held)
    for it, t in held:
        st = _ui14_tstate(t)
        if st == 'wait':
            self.log('\u23f0 ZIP %s is scheduled for %s \u2014 held until then.'
                     % (os.path.basename(it[0]), _ui14_tlabel(t)))
        else:
            self.log('\u23f0 ZIP %s: its time window has ended (%s) \u2014 not posted.'
                     % (os.path.basename(it[0]), _ui14_tlabel(t)))
    self._ui_zip_items = [it for it in items if _ui14_tkey(it[0]) not in hk]
    try:
        return _ui14_prev_zip_pubs(self)
    finally:
        self._ui_zip_items = items


_ui14_prev_start_posting = FacebookMultiPosterApp.start_posting


def _ui14_start_posting(self):
    """If every ZIP is scheduled for later (and no CSV source), say so."""
    try:
        items = list(getattr(self, '_ui_zip_items', []) or [])
        zip_on = bool(getattr(self, '_ui_src_zip_var', None) is not None and self._ui_src_zip_var.get())
        csv_on = bool(getattr(self, '_ui_src_csv_var', None) is not None and self._ui_src_csv_var.get())
        held = _ui14_held(self)
        if (not getattr(self, 'is_running', False)) and zip_on and not csv_on and items \
                and len(held) == len(items):
            waits = sorted((_ui14_window(t)[0], t) for _it, t in held if _ui14_tstate(t) == 'wait')
            if waits:
                msg = _TR('Tous les fichiers ZIP sont programm\u00e9s \u2014 la publication d\u00e9marrera '
                          'automatiquement :') + ' ' + _ui14_tlabel(waits[0][1])
            else:
                msg = _TR('Les plages horaires de tous les fichiers ZIP sont termin\u00e9es.')
            self.log('\u23f0 ' + msg)
            messagebox.showinfo('AutoPoster Pro', msg)
            return
    except Exception:
        _ui13_dbg()
    return _ui14_prev_start_posting(self)


FacebookMultiPosterApp.start_posting = _ui14_start_posting



# ------------------------------------------ Delete Post & Decline: engine
# Strategies ported from Delete_Decline.js (Group Manager): post "Actions" menu
# (never comment / reaction / video menus), multilingual Delete item, confirm
# dialog, wait until the post is really gone; Decline + its confirm popup.
_UI14_DD_JS = r"""(() => {
  if (window.__apdd) return true;
  const STRONG = ['delete post','remove post','move to trash','move to recycle bin','supprimer la publication',
    'eliminar publicación','excluir publicação','beitrag löschen','elimina post','حذف المنشور'];
  const DEL = ['delete','remove','supprimer','eliminar','excluir','löschen','elimina','verwijderen','sil','usuń',
    'xóa','حذف','удалить','מחק'];
  const CONF = ['delete','confirm','yes','ok','remove','move','supprimer','confirmer','oui','eliminar','sí','löschen',
    'ja','excluir','sim','elimina','sì','verwijderen','sil','evet','да','حذف','نعم','تأكيد','כן','decline',
    'refuser','rechazar','recusar','ablehnen','rifiuta','reddet','odrzuć','رفض','отклонить','từ chối','tolak',
    'weigeren'];
  const DECL = ['decline','refuser','rechazar','recusar','ablehnen','rifiuta','reddet','odrzuć','رفض','отклонить',
    'từ chối','tolak','weigeren'];
  const BAD = ['comment','reply','react','like','share','hide or report','report','emoji','sticker','gif','video',
    'edit history','notification','commentaire','répondre','partager','réagir','signaler','تعليق','comentar'];
  const GOOD = ['actions for this post','action options','more options','more','options',
    'actions pour cette publication',"plus d'options",'acciones para esta publicación','más opciones',
    'إجراءات لهذا المنشور','المزيد من الخيارات'];
  const VIDEO = ['quality','caption','subtitle','playback speed','speed','picture-in-picture','miniplayer',
    'mini player','loop','autoplay'];
  const vis = e => { if (!e) return false; const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; };
  const low = e => ((e && (e.innerText || e.textContent)) || '').replace(/\s+/g, ' ').trim().toLowerCase();
  const aria = e => ((e && e.getAttribute && e.getAttribute('aria-label')) || '').toLowerCase().trim();
  const inComment = el => { let n = el, d = 0; while (n && d < 12) {
      if (/comment|reply|commentaire|réponse|comentario|تعليق/.test(aria(n))) return true;
      n = n.parentElement; d++; } return false; };
  const POST = 'div[role="article"], div[aria-posinset], div[data-pagelet^="FeedUnit"], div[data-pagelet^="GroupFeed"]';
  const posts = () => {
    const all = Array.from(document.querySelectorAll(POST)).filter(p => vis(p) &&
      p.getBoundingClientRect().height >= 80 && !inComment(p) &&
      !(p.parentElement && p.parentElement.closest('[role="article"]')));
    const set = new Set(all);
    const out = all.filter(p => { let a = p.parentElement; while (a) { if (set.has(a)) return false; a = a.parentElement; } return true; });
    out.sort((a, b) => a.getBoundingClientRect().top - b.getBoundingClientRect().top);
    return out;
  };
  const badBtn = b => {
    const l = aria(b);
    if (GOOD.some(g => l === g) || l.startsWith('actions for this post')) return false;
    if (l && BAD.some(w => l.includes(w))) return true;
    let n = b.parentElement, h = 0;
    while (n && h < 8) { const al = aria(n); if (al.includes('video player') || al.includes('video controls')) return true;
      n = n.parentElement; h++; }
    return false;
  };
  const nested = (b, post) => { let n = b.parentElement; while (n && n !== post) {
      if (n.getAttribute && n.getAttribute('role') === 'article') return true; n = n.parentElement; } return false; };
  const menuIn = post => {
    let fb = null;
    for (const b of post.querySelectorAll('[role="button"][aria-haspopup="menu"], [role="button"][aria-label], [aria-haspopup="menu"]')) {
      if (!vis(b) || nested(b, post) || badBtn(b)) continue;
      const l = aria(b);
      if (GOOD.some(g => l === g || l.startsWith(g + ' ')) || l.startsWith('actions for this post')) return b;
      if (!fb && b.getAttribute('aria-haspopup') === 'menu') fb = b;
    }
    return fb;
  };
  const mark = (el, attr) => {
    document.querySelectorAll('[' + attr + ']').forEach(e => e.removeAttribute(attr));
    if (!el) return false;
    el.setAttribute(attr, '1');
    try { el.scrollIntoView({block: 'center', behavior: 'instant'}); } catch (e) { try { el.scrollIntoView(); } catch (e2) {} }
    return true;
  };
  const sig = p => { const a = p.querySelector('h2 a, h3 a, h4 a, strong a, span a[role="link"]');
    return (a ? low(a) : '') + '|' + low(p).slice(0, 90); };
  window.__apdd = {
    nextPost() {
      for (const p of posts()) {
        if (p.hasAttribute('data-apdd-skip')) continue;
        const m = menuIn(p);
        if (!m) continue;
        mark(p, 'data-apdd-post'); mark(m, 'data-apdd-menu');
        window.__apddSig = sig(p); window.__apddCount = posts().length;
        return true;
      }
      return false;
    },
    skip() { const p = document.querySelector('[data-apdd-post]'); if (p) p.setAttribute('data-apdd-skip', '1'); return true; },
    clear() { ['data-apdd-ok', 'data-apdd-item'].forEach(a =>
      document.querySelectorAll('[' + a + ']').forEach(e => e.removeAttribute(a))); return true; },
    menuOpen() { for (const m of document.querySelectorAll('[role="menu"]'))
      if (vis(m) && m.querySelector('[role="menuitem"]')) return true; return false; },
    videoMenu() { let v = 0, o = 0; for (const n of document.querySelectorAll('[role="menu"] [role="menuitem"]')) {
      const t = low(n); if (!t || t.length > 40) continue; if (VIDEO.some(w => t === w || t.includes(w))) v++; else o++; }
      return v >= 1 && v >= o; },
    menuItems() { return Array.from(document.querySelectorAll('[role="menu"] [role="menuitem"]')).filter(vis)
      .map(low).filter(t => t && t.length < 60).slice(0, 8); },
    deleteItem() {
      const items = Array.from(document.querySelectorAll('[role="menu"] [role="menuitem"], [role="menuitem"]'))
        .filter(vis).map(it => [it, low(it)])
        .filter(x => x[1] && x[1].length <= 60 && !/comment|commentaire|comentario|تعليق/.test(x[1]));
      for (const [it, t] of items) if (STRONG.some(w => t === w || t.startsWith(w))) return mark(it, 'data-apdd-item');
      for (const [it, t] of items) {
        if (/tag|identification|etiqueta|markierung|إشارة/.test(t)) continue;
        if (DEL.some(w => t === w || t.startsWith(w + ' '))) return mark(it, 'data-apdd-item');
      }
      return false;
    },
    confirm() {
      const ds = Array.from(document.querySelectorAll('[role="dialog"], [aria-modal="true"]')).filter(vis).reverse();
      for (const d of ds) {
        const btns = Array.from(d.querySelectorAll('[role="button"], button'))
          .filter(b => vis(b) && b.getAttribute('aria-disabled') !== 'true');
        for (const b of btns) { const t = low(b), l = aria(b); if (CONF.some(w => t === w || l === w)) return mark(b, 'data-apdd-ok'); }
        for (const b of btns) { const t = low(b); if (t && t.length < 25 && CONF.some(w => t.startsWith(w + ' '))) return mark(b, 'data-apdd-ok'); }
      }
      return false;
    },
    hasOk() { return !!document.querySelector('[data-apdd-ok]'); },
    removed() {
      const p = document.querySelector('[data-apdd-post]');
      if (!p || !document.contains(p)) return true;
      if (p.getBoundingClientRect().height < 40) return true;
      const cs = getComputedStyle(p);
      if (p.offsetParent === null || cs.display === 'none' || cs.visibility === 'hidden' ||
          p.getAttribute('aria-hidden') === 'true') return true;
      const ps = posts();
      if (ps.length && ps.indexOf(p) === -1) return true;
      if (typeof window.__apddCount === 'number' && ps.length < window.__apddCount) return true;
      if (window.__apddSig && ps.length && !ps.some(q => sig(q) === window.__apddSig)) return true;
      return false;
    },
    declineBtn() {
      const cands = [];
      for (const b of document.querySelectorAll('[role="button"], button')) {
        if (!vis(b) || b.hasAttribute('data-apdd-done') || b.getAttribute('aria-disabled') === 'true') continue;
        if (b.closest('[role="dialog"], [aria-modal="true"]')) continue;
        const t = low(b), l = aria(b);
        if (DECL.some(w => t === w || l === w)) cands.push(b);
      }
      if (!cands.length) {
        for (const s of document.querySelectorAll('span')) {
          if (!vis(s) || !DECL.includes(low(s))) continue;
          let c = s, p = s.parentElement;
          for (let i = 0; i < 5 && p; i++) { if (p.getAttribute('role') === 'button') { c = p; break; } p = p.parentElement; }
          if (!c.hasAttribute('data-apdd-done') && !c.closest('[role="dialog"]')) cands.push(c);
        }
      }
      cands.sort((a, b) => a.getBoundingClientRect().top - b.getBoundingClientRect().top);
      return cands.length ? mark(cands[0], 'data-apdd-dec') : false;
    },
    declineGone() { const b = document.querySelector('[data-apdd-dec]');
      return !b || !document.contains(b) || !vis(b) || b.getAttribute('aria-disabled') === 'true'; },
    doneDecline() { const b = document.querySelector('[data-apdd-dec]');
      if (b) { b.setAttribute('data-apdd-done', '1'); b.removeAttribute('data-apdd-dec'); } return true; },
    scroll(px) { window.scrollBy(0, px); return Math.round(window.scrollY); }
  };
  return true;
})()"""

_UI14_DD_SPEEDS = {      # same profiles as the userscript (ms)
    'turbo': {'act': (300, 800), 'cycle': (800, 1500), 'menu': (600, 1000), 'confirm': (500, 900), 'del': (700, 1200)},
    'fast': {'act': (400, 1000), 'cycle': (1000, 2000), 'menu': (800, 1300), 'confirm': (600, 1100), 'del': (900, 1500)},
    'normal': {'act': (600, 1500), 'cycle': (1500, 3000), 'menu': (1000, 1800), 'confirm': (800, 1400), 'del': (1200, 2200)},
    'safe': {'act': (1000, 2500), 'cycle': (2500, 5000), 'menu': (1500, 2500), 'confirm': (1200, 2000), 'del': (2000, 3500)},
}


def _ui14_dd_on(self):
    return bool(getattr(self, '_ui14_dd_running', False)) and not getattr(self, '_closing', False)


def _ui14_dd_eval(pg, expr, *args):
    try:
        pg.evaluate(_UI14_DD_JS)
        return pg.evaluate(expr, *args) if args else pg.evaluate(expr)
    except Exception:
        return None


def _ui14_dd_wait(self, pg, expr, timeout):
    end = time.time() + timeout
    while True:
        if not _ui14_dd_on(self):
            return False
        if _ui14_dd_eval(pg, expr):
            return True
        if time.time() >= end:
            return False
        time.sleep(0.12)


def _ui14_dd_pause(self, rng, k=1.0):
    ms = random.randint(int(rng[0] * k), int(rng[1] * k))
    end = time.time() + ms / 1000.0
    while _ui14_dd_on(self) and time.time() < end:
        time.sleep(min(0.2, max(0.0, end - time.time())))


def _ui14_dd_click(pg, sel):
    try:
        loc = pg.locator(sel).first
        if loc.count() == 0:
            return False
        try:
            loc.scroll_into_view_if_needed(timeout=2000)
        except Exception:
            pass
        loc.click(timeout=4000)
        return True
    except Exception:
        try:
            return bool(pg.evaluate("(s) => { const e = document.querySelector(s); if (!e) return false; "
                                    "e.click(); return true; }", sel))
        except Exception:
            return False


def _ui14_dd_escape(pg):
    try:
        pg.keyboard.press('Escape')
        pg.wait_for_timeout(250)
    except Exception:
        pass


def _ui14_dd_open(self, pg, url):
    try:
        pg.goto(url, wait_until='domcontentloaded', timeout=30000)
    except Exception as e:
        self.log('   \u26a0\ufe0f Cannot open %s (%s)' % (url, str(e)[:80]))
        return False
    try:
        pg.wait_for_selector('[role="main"], [role="feed"], div[role="article"]', timeout=10000)
    except Exception:
        pass
    _ui14_dd_pause(self, (1800, 2600))
    _ui14_dd_eval(pg, '() => true')
    return True


def _ui14_dd_delete_one(self, pg, sp):
    _ui14_dd_eval(pg, '() => window.__apdd.clear()')
    if not _ui14_dd_click(pg, '[data-apdd-menu="1"]'):
        return 'menu click failed'
    if not _ui14_dd_wait(self, pg, '() => window.__apdd.menuOpen()', 2.5):
        if not _ui14_dd_click(pg, '[data-apdd-menu="1"]') or \
                not _ui14_dd_wait(self, pg, '() => window.__apdd.menuOpen()', 2.0):
            return 'menu did not open'
    if _ui14_dd_eval(pg, '() => window.__apdd.videoMenu()'):
        _ui14_dd_escape(pg)
        return 'video menu'
    _ui14_dd_pause(self, sp['menu'], 0.4)
    if not _ui14_dd_wait(self, pg, '() => window.__apdd.deleteItem()', 3.5):
        items = _ui14_dd_eval(pg, '() => window.__apdd.menuItems()') or []
        _ui14_dd_escape(pg)
        return 'no Delete in the menu' + ((' (' + ' | '.join(items[:5]) + ')') if items else '')
    if not _ui14_dd_click(pg, '[data-apdd-item="1"]'):
        _ui14_dd_escape(pg)
        return 'Delete click failed'
    if _ui14_dd_wait(self, pg, '() => window.__apdd.confirm() || window.__apdd.removed()', 3.5):
        if _ui14_dd_eval(pg, '() => window.__apdd.hasOk()'):
            _ui14_dd_pause(self, sp['confirm'], 0.4)
            _ui14_dd_click(pg, '[data-apdd-ok="1"]')
    if _ui14_dd_wait(self, pg, '() => window.__apdd.removed()', max(3.0, sp['del'][1] / 1000.0 + 1.5)):
        return 'ok'
    return 'the post is still there'


def _ui14_dd_delete_group(self, pg, origin, gid, sid, sp, mx):
    self.log("   \u2296 Group %s \u2014 deleting this account's posts\u2026" % gid)
    if not _ui14_dd_open(self, pg, '%s/groups/%s/my_posted_content' % (origin, gid)):
        return 0
    done = fails = idle = 0
    while _ui14_dd_on(self):
        if mx and done >= mx:
            break
        try:
            self._wd_beat(sid, 'suppression %d' % (done + 1), 4)
        except Exception:
            pass
        if not _ui14_dd_eval(pg, '() => window.__apdd.nextPost()'):
            if idle >= 3:
                break
            _ui14_dd_eval(pg, '(px) => window.__apdd.scroll(px)', 900)
            _ui14_dd_pause(self, (1100, 1700))
            idle += 1
            continue
        idle = 0
        _ui14_dd_pause(self, sp['act'], 0.5)
        res = _ui14_dd_delete_one(self, pg, sp)
        if res == 'ok':
            done += 1
            self._ui14_dd_stats['del'] += 1
            self.log('   \u2713 Post deleted (%d)' % done)
        else:
            fails += 1
            self._ui14_dd_stats['fail'] += 1
            _ui14_dd_eval(pg, '() => window.__apdd.skip()')
            self.log('   \u26a0\ufe0f Post not deleted: %s \u2014 skipped.' % res)
            if fails >= 6 and done == 0:
                self.log('   \u26a0\ufe0f Nothing could be deleted in this group \u2014 moving on.')
                break
        _ui14_dd_pause(self, sp['cycle'])
    if done == 0 and fails == 0 and _ui14_dd_on(self):
        self.log('   \u2139\ufe0f No posts of this account in this group.')
    return done


def _ui14_dd_decline_group(self, pg, origin, gid, sid, sp, mx):
    self.log('   \u2296 Group %s \u2014 declining pending posts\u2026' % gid)
    if not _ui14_dd_open(self, pg, '%s/groups/%s/pending_posts' % (origin, gid)):
        return 0
    done = fails = idle = 0
    while _ui14_dd_on(self):
        if mx and done >= mx:
            break
        try:
            self._wd_beat(sid, 'refus %d' % (done + 1), 4)
        except Exception:
            pass
        if not _ui14_dd_eval(pg, '() => window.__apdd.declineBtn()'):
            if idle >= 2:
                break
            _ui14_dd_eval(pg, '(px) => window.__apdd.scroll(px)', 600 if idle == 0 else 1000)
            _ui14_dd_pause(self, (800, 1200))
            idle += 1
            continue
        idle = 0
        _ui14_dd_pause(self, sp['act'], 0.5)
        if not _ui14_dd_click(pg, '[data-apdd-dec="1"]'):
            _ui14_dd_eval(pg, '() => window.__apdd.doneDecline()')
            fails += 1
            continue
        _ui14_dd_eval(pg, '() => window.__apdd.clear()')
        if _ui14_dd_wait(self, pg, '() => window.__apdd.confirm() || window.__apdd.declineGone()', 2.5):
            if _ui14_dd_eval(pg, '() => window.__apdd.hasOk()'):
                _ui14_dd_pause(self, sp['confirm'], 0.4)
                _ui14_dd_click(pg, '[data-apdd-ok="1"]')
        if _ui14_dd_wait(self, pg, '() => window.__apdd.declineGone()', 4.0):
            done += 1
            self._ui14_dd_stats['dec'] += 1
            self.log('   \u2713 Pending post declined (%d)' % done)
        else:
            _ui14_dd_eval(pg, '() => window.__apdd.doneDecline()')
            fails += 1
            self._ui14_dd_stats['fail'] += 1
            if fails >= 6 and done == 0:
                break
        _ui14_dd_pause(self, sp['cycle'], 0.6)
    if done == 0 and _ui14_dd_on(self):
        self.log('   \u2139\ufe0f No pending posts to decline here (or this account is not an admin of the group).')
    return done


def _ui14_dd_worker(self, slots, urls, opts):
    sp = _UI14_DD_SPEEDS.get(opts.get('speed'), _UI14_DD_SPEEDS['normal'])
    self._ui14_dd_stats = {'del': 0, 'dec': 0, 'fail': 0}
    acts = [a for a, on in (('delete my posts', opts.get('delete')), ('decline pending posts', opts.get('decline')))
            if on]
    self.log('\u2296 Delete Post & Decline \u2014 %d account(s) \u00d7 %d group(s) \u00b7 %s \u00b7 speed: %s'
             % (len(slots), len(urls), ' + '.join(acts), opts.get('speed')))
    try:
        self._wd_start()
    except Exception:
        pass
    first = True
    try:
        for sid in slots:
            if not _ui14_dd_on(self):
                break
            acc = self.accounts.get(sid)
            if not acc or not acc.get('connected'):
                continue
            if not first:
                try:
                    self._renew_tor_circuit()
                except Exception:
                    pass
            first = False
            label = acc.get('custom_name') or acc.get('name') or 'Compte %02d' % sid
            self.log('\u2500\u2500\u2500 %s' % label)
            try:
                with sync_playwright() as pw:
                    try:
                        self._wd_beat(sid, 'ouverture du navigateur', 4)
                    except Exception:
                        pass
                    ctx = self._launch_ctx(pw, acc['user_data_dir'], sid=sid)
                    try:
                        pg = ctx.new_page()
                        for url in urls:
                            if not _ui14_dd_on(self):
                                break
                            origin, gid = _ui_origin_gid(url)
                            if not gid:
                                self.log('   \u26a0\ufe0f Not a group address \u2014 skipped: %s' % url)
                                continue
                            if opts.get('decline'):
                                _ui14_dd_decline_group(self, pg, origin, gid, sid, sp, opts.get('max', 0))
                            if opts.get('delete') and _ui14_dd_on(self):
                                _ui14_dd_delete_group(self, pg, origin, gid, sid, sp, opts.get('max', 0))
                    finally:
                        try:
                            ctx.close()
                        except Exception:
                            pass
                try:
                    self._wd_clear(sid)
                except Exception:
                    pass
            except Exception as e:
                self.log('   \u274c %s: %s' % (label, str(e)[:160]))
    finally:
        st = self._ui14_dd_stats
        stopped = not getattr(self, '_ui14_dd_running', False)
        self._ui14_dd_running = False
        self.log('\u2296 Delete Post & Decline %s \u2014 %d post(s) deleted \u00b7 %d pending post(s) declined%s.'
                 % ('stopped' if stopped else 'finished', st['del'], st['dec'],
                    (' \u00b7 %d skipped' % st['fail']) if st['fail'] else ''))


# ------------------------------------------ Delete Post & Decline: panel
def _ui14_dd_accounts(self):
    cb = getattr(self, '_dd_account_cb', None)
    if cb is None:
        return
    vals = [_TR('Tous les comptes connect\u00e9s')]
    for sid, a in sorted((getattr(self, 'accounts', {}) or {}).items()):
        if a.get('connected'):
            vals.append('%02d \u2014 %s' % (sid, a.get('custom_name') or a.get('name') or 'Compte %02d' % sid))
    try:
        cb.configure(values=vals)
        if not re.match(r'^\s*\d+\s*\u2014', str(self._dd_account_var.get() or '')):
            self._dd_account_var.set(vals[0])
    except Exception:
        pass


def _ui14_dd_slots(self):
    val = str(self._dd_account_var.get() or '')
    m = re.match(r'^\s*(\d+)\s*\u2014', val)
    accs = getattr(self, 'accounts', {}) or {}
    if m:
        sid = int(m.group(1))
        return [sid] if (sid in accs and accs[sid].get('connected')) else []
    return [sid for sid, a in sorted(accs.items()) if a.get('connected')]


def _ui14_dd_import(self):
    try:
        path = filedialog.askopenfilename(title=_TR('Importer URLs depuis TXT'),
                                          filetypes=[('TXT', '*.txt'), ('*', '*.*')])
    except Exception:
        path = ''
    if not path:
        return
    try:
        with open(path, encoding='utf-8', errors='ignore') as f:
            lines = [l.strip() for l in f if l.strip() and 'facebook.com' in l.lower()]
        self._dd_text.delete('1.0', 'end')
        self._dd_text.insert('end', '\n'.join(lines))
    except Exception as ex:
        messagebox.showerror(_TR('Erreur'), str(ex))


def _ui14_dd_start(self):
    if getattr(self, '_ui14_dd_running', False):
        return
    raw = self._dd_text.get('1.0', 'end').strip()
    urls = [l.strip() for l in raw.splitlines() if l.strip().startswith(('http://', 'https://'))]
    if not urls:
        messagebox.showerror(_TR('Erreur'), _TR('Aucune URL valide d\u00e9tect\u00e9e.'))
        return
    dele, decl = bool(self._dd_del_var.get()), bool(self._dd_dec_var.get())
    if not (dele or decl):
        messagebox.showwarning('AutoPoster Pro', _TR('Choisissez au moins une action : supprimer mes '
                                                     'publications ou refuser les publications en attente.'))
        return
    slots = _ui14_dd_slots(self)
    if not slots:
        messagebox.showerror(_TR('Erreur'), _TR('Aucun compte connect\u00e9.'))
        return
    if dele and not messagebox.askyesno('AutoPoster Pro', _TR(
            'Supprimer les publications de %d compte(s) dans %d groupe(s) ? Cette action est d\u00e9finitive.')
            % (len(slots), len(urls))):
        return
    try:
        mx = max(0, int(self._dd_max_var.get() or 0))
    except Exception:
        mx = 0
    opts = {'delete': dele, 'decline': decl, 'speed': str(self._dd_speed_var.get() or 'normal'), 'max': mx}
    self._ui14_dd_stats = {'del': 0, 'dec': 0, 'fail': 0}
    self._ui14_dd_running = True
    th = _ui14_threading.Thread(target=_ui14_dd_worker, args=(self, slots, urls, opts), daemon=True)
    self._ui14_dd_thread = th
    th.start()
    _ui14_dd_poll(self)


def _ui14_dd_stop(self):
    if getattr(self, '_ui14_dd_running', False):
        self._ui14_dd_running = False
        self.log('\u2296 Delete Post & Decline \u2014 stopping\u2026')


def _ui14_dd_poll(self):
    run = bool(getattr(self, '_ui14_dd_running', False))
    th = getattr(self, '_ui14_dd_thread', None)
    alive = bool(th is not None and th.is_alive())
    st = getattr(self, '_ui14_dd_stats', None) or {}
    lbl = getattr(self, '_dd_status_lbl', None)
    if lbl is not None:
        counts = _TR('%d supprim\u00e9(s) \u00b7 %d refus\u00e9(s)') % (st.get('del', 0), st.get('dec', 0))
        txt = (_TR('En cours\u2026') + '  ' + counts) if (run or alive) else (
            (_TR('Arr\u00eat\u00e9.') + '  ' + counts) if st else _TR('Arr\u00eat\u00e9.'))
        try:
            _ui_raw_conf(lbl, text=txt, fg=(C['success'] if (run or alive) else C['text3']))
        except Exception:
            pass
    if run or alive:
        try:
            self.root.after(700, lambda: _ui14_dd_poll(self))
        except Exception:
            pass


_UI14_DD_SPEED_NAMES = (('safe', 'S\u00fbr'), ('normal', 'Normal'), ('fast', 'Rapide'), ('turbo', 'Turbo'))


def _ui14_dd_speed_pick(self):
    disp = str(self._dd_speed_disp.get() or '')
    for k, n in _UI14_DD_SPEED_NAMES:
        if disp in (_TR(n), n):
            if self._dd_speed_var.get() != k:
                self._dd_speed_var.set(k)
            return


def _ui14_dd_speed_sync(self):
    cb = getattr(self, '_dd_speed_cb', None)
    k = str(self._dd_speed_var.get() or 'normal')
    try:
        if cb is not None:
            cb.configure(values=[_TR(n) for _k, n in _UI14_DD_SPEED_NAMES])
        for kk, n in _UI14_DD_SPEED_NAMES:
            if kk == k and self._dd_speed_disp.get() != _TR(n):
                self._dd_speed_disp.set(_TR(n))
    except Exception:
        pass


