def _ui14_ov_patch():
    global _UI13_OV_CONF, _UI13_OV_AUTO
    conf = []
    for title, icon, rows in _UI13_OV_CONF:
        if title == 'Browser Settings':
            rows = tuple(rows) + (('Human typing', ('bool', '_ui14_typing_var')),)
        elif title == 'ZIP file':
            rows = tuple(rows) + (('Timers', ('ztimers',)),)
        conf.append((title, icon, rows))
    _UI13_OV_CONF = tuple(conf)
    _UI13_OV_AUTO = tuple(_UI13_OV_AUTO) + (('Delete Post & Decline', '\u2296', (
        ('Group URLs', ('text', 'dd')),
        ('Delete my posts', ('bool', '_dd_del_var')),
        ('Decline pending posts', ('bool', '_dd_dec_var')),
        ('Account', ('var', '_dd_account_var', '')),
        ('Speed', ('var', '_dd_speed_disp', '')),
        ('Max per group (0 = all)', ('var', '_dd_max_var', '')))),)


_ui14_ov_patch()
_ui14_prev_ov_value = _ui13_ov_value


def _ui13_ov_value(self, spec):
    if spec and spec[0] == 'ztimers':
        ts = [_UI14_TIMERS.get(_ui14_tkey(it[0])) for it in (getattr(self, '_ui_zip_items', []) or [])]
        ts = [t for t in ts if t and _ui14_window(t)]
        waits = sorted((_ui14_window(t)[0], t) for t in ts if _ui14_tstate(t) == 'wait')
        if waits:
            return (None, '%d \u00b7 %s' % (len(ts), _ui14_tlabel(waits[0][1])))
        return (None, str(len(ts)))
    return _ui14_prev_ov_value(self, spec)


# --------------------------------------------------------------- wiring
_ui14_prev_finish = _ui13_finish


def _ui13_finish(self):
    _ui14_prev_finish(self)
    if getattr(self, '_ui14_done', False):
        return
    for fn in (_ui14_theme_toggle_ui, _ui14_card_chevrons, _ui14_typing_toggle, _ui14_build_cleaner,
               _ui14_zip_timers_init):
        try:
            fn(self)
        except Exception:
            _ui13_dbg()
    self._ui14_done = True
    try:
        self._ui_layout_sig = None
        self._show_tab(getattr(self, '_current_tab', None) or 'config')
    except Exception:
        _ui13_dbg()


_ui14_prev_set_language = FacebookMultiPosterApp._set_language


def _ui14_set_language(self, lang):
    r = _ui14_prev_set_language(self, lang)
    if getattr(self, '_ui14_done', False):
        for fn in (_ui14_dd_accounts, _ui14_dd_speed_sync, _ui14_dd_poll):
            try:
                fn(self)
            except Exception:
                pass
        try:
            _ui_zip_render(self)
        except Exception:
            pass
    return r


FacebookMultiPosterApp._set_language = _ui14_set_language
_ui14_prev_recolor = FacebookMultiPosterApp._ui_recolor


def _ui14_recolor(self):
    _ui14_prev_recolor(self)
    if not getattr(self, '_ui14_done', False):
        return
    _ui14_capsule_refresh(self)
    try:
        _ui_zip_render(self)
    except Exception:
        pass


FacebookMultiPosterApp._ui_recolor = _ui14_recolor
_ui14_prev_set_zoom = FacebookMultiPosterApp._ui_set_zoom


def _ui14_set_zoom(self, z, save=True):
    r = _ui14_prev_set_zoom(self, z, save)
    if getattr(self, '_ui14_done', False):
        _ui14_capsule_refresh(self)
    return r


FacebookMultiPosterApp._ui_set_zoom = _ui14_set_zoom



