def _sv_even(v):
    v = int(v)
    return max(2, v - (v % 2))


def _sv_num(v, default, lo=None, hi=None, cast=float):
    try:
        x = cast(str(v).strip().replace(',', '.'))
    except Exception:
        x = cast(default)
    if lo is not None:
        x = max(lo, x)
    if hi is not None:
        x = min(hi, x)
    return x


def _sv_frac(s):
    try:
        if '/' in str(s):
            a, b = str(s).split('/', 1)
            return float(a) / float(b) if float(b) else 0.0
        return float(s)
    except Exception:
        return 0.0


def _sv_kind(path):
    e = os.path.splitext(path or '')[1].lower()
    if e in _SV_VIDEO_EXTS:
        return 'video'
    if e in _SV_IMAGE_EXTS:
        return 'image'
    if e in _SV_AUDIO_EXTS:
        return 'audio'
    return ''


def _sv_natkey(s):
    return [int(t) if t.isdigit() else t.lower() for t in re.split(r'(\d+)', str(s))]


# -------------------------------------------------------- ffmpeg discovery
def _sv_dirs():
    out = []
    try:
        if getattr(sys, 'frozen', False):
            out.append(os.path.dirname(os.path.abspath(sys.executable)))
    except Exception:
        pass
    for p in (globals().get('__file__'), sys.argv[0] if sys.argv else None):
        if p:
            d = os.path.dirname(os.path.abspath(p))
            if d not in out:
                out.append(d)
    return out


def _sv_find(name, custom=''):
    exe = name + ('.exe' if os.name == 'nt' else '')
    cands = []
    c = (custom or '').strip().strip('"')
    if c:
        if os.path.isdir(c):
            cands += [os.path.join(c, exe), os.path.join(c, 'bin', exe)]
        else:
            d = os.path.dirname(c)
            if os.path.basename(c).lower().startswith(name):
                cands.append(c)
            cands.append(os.path.join(d, exe))
    for base in _sv_dirs():
        for sub in ('', 'tools', 'bin', 'ffmpeg', os.path.join('ffmpeg', 'bin')):
            cands.append(os.path.join(base, sub, exe))
    w = _sv_shutil.which(name)
    if w:
        cands.append(w)
    for p in cands:
        try:
            if p and os.path.isfile(p):
                return p
        except Exception:
            pass
    return None


def _sv_popen_kw():
    if os.name == 'nt':
        return {'creationflags': 0x08000000}          # CREATE_NO_WINDOW: no console flashes
    return {}


def _sv_run(cmd, timeout=30):
    try:
        r = _sv_sp.run(cmd, stdout=_sv_sp.PIPE, stderr=_sv_sp.PIPE, timeout=timeout, **_sv_popen_kw())
        return r.returncode, r.stdout.decode('utf-8', 'replace'), r.stderr.decode('utf-8', 'replace')
    except Exception as e:
        return -1, '', str(e)


_SV_CAPS = {}


def _sv_caps(ff):
    if not ff:
        return {'filters': set(), 'encoders': set(), 'version': '', 'major': 0}
    if ff in _SV_CAPS:
        return _SV_CAPS[ff]
    filters, encs = set(), set()
    rc, out, _e = _sv_run([ff, '-hide_banner', '-filters'], 25)
    for line in out.splitlines():
        parts = line.split()
        if len(parts) >= 3 and re.match(r'^[TSC.A-Z|]{2,4}$', parts[0]):
            filters.add(parts[1])
    rc, out, _e = _sv_run([ff, '-hide_banner', '-encoders'], 25)
    for line in out.splitlines():
        parts = line.split()
        if len(parts) >= 2 and parts[0].startswith('V'):
            encs.add(parts[1])
    rc, out, _e = _sv_run([ff, '-version'], 15)
    first = (out.splitlines() or [''])[0]
    m = re.search(r'version\s+n?(\d+)\.', first)
    major = int(m.group(1)) if m else (99 if 'version N-' in first or 'git' in first else 0)
    _SV_CAPS[ff] = {'filters': filters, 'encoders': encs, 'version': first, 'major': major}
    return _SV_CAPS[ff]


def _sv_env(custom='', caps=True):
    ff = _sv_find('ffmpeg', custom)
    return {'ffmpeg': ff, 'ffprobe': _sv_find('ffprobe', custom), 'ffplay': _sv_find('ffplay', custom),
            'caps': _sv_caps(ff) if caps else {}}


_SV_PROBES = {}


def _sv_probe(ffprobe, path):
    try:
        key = (path, os.path.getmtime(path), os.path.getsize(path))
    except Exception:
        key = (path, 0, 0)
    if key in _SV_PROBES:
        return _SV_PROBES[key]
    info = {'dur': 0.0, 'w': 0, 'h': 0, 'fps': 0.0, 'audio': False, 'video': False}
    if ffprobe and path:
        rc, out, _e = _sv_run([ffprobe, '-v', 'error', '-print_format', 'json', '-show_format', '-show_streams',
                               path], 30)
        if rc == 0:
            try:
                d = _sv_json.loads(out or '{}')
            except Exception:
                d = {}
            try:
                info['dur'] = float((d.get('format') or {}).get('duration') or 0)
            except Exception:
                pass
            for st in d.get('streams') or []:
                ct = st.get('codec_type')
                if ct == 'video' and not info['video']:
                    if (st.get('disposition') or {}).get('attached_pic'):
                        continue
                    w, h = int(st.get('width') or 0), int(st.get('height') or 0)
                    rot = 0
                    try:
                        rot = int(float((st.get('tags') or {}).get('rotate') or 0))
                    except Exception:
                        pass
                    for sd in st.get('side_data_list') or []:
                        if 'rotation' in sd:
                            try:
                                rot = int(float(sd.get('rotation') or 0))
                            except Exception:
                                pass
                    if abs(rot) % 180 == 90:
                        w, h = h, w
                    info.update(video=True, w=w, h=h,
                                fps=_sv_frac(st.get('avg_frame_rate') or st.get('r_frame_rate') or '0'))
                    if not info['dur']:
                        try:
                            info['dur'] = float(st.get('duration') or 0)
                        except Exception:
                            pass
                elif ct == 'audio':
                    info['audio'] = True
    _SV_PROBES[key] = info
    return info


# ------------------------------------------------------- encoder (Shorts)
_SV_ENC_OK = {}


def _sv_encoder_works(ff, enc):
    key = (ff, enc)
    if key not in _SV_ENC_OK:
        rc, _o, _e = _sv_run([ff, '-hide_banner', '-loglevel', 'error', '-f', 'lavfi', '-t', '0.5', '-i',
                              'color=c=black:s=256x256:r=30', '-c:v', enc, '-pix_fmt', 'yuv420p', '-f', 'null', '-'],
                             25)
        _SV_ENC_OK[key] = (rc == 0)
    return _SV_ENC_OK[key]


def _sv_pick_encoder(env, want):
    ff = env['ffmpeg']
    pref = ['h264_nvenc', 'h264_qsv', 'h264_amf', 'h264_videotoolbox', 'libx264'] if want in ('', 'auto') \
        else [want, 'libx264']
    encs = env['caps'].get('encoders') or set()
    for e in pref:
        if e != 'libx264' and e not in encs:
            continue
        if _sv_encoder_works(ff, e):
            return e
    return 'libx264'


def _sv_enc_flags(enc, crf, preset, W, H):
    if enc == 'libx264':
        return ['-c:v', 'libx264', '-preset', preset or 'medium', '-crf', str(int(crf))]
    if enc == 'h264_nvenc':
        return ['-c:v', enc, '-preset', 'p4', '-rc', 'vbr', '-cq', str(max(15, min(35, int(crf)))), '-b:v', '0']
    if enc == 'h264_qsv':
        return ['-c:v', enc, '-global_quality', str(int(crf))]
    return ['-c:v', enc, '-b:v', '8M' if W * H >= 1500000 else '5M']


# --------------------------------------------------- planning (3 scripts)
def _sv_pattern(text):
    patt = []
    for p in [x.strip() for x in (text or '').split(',') if x.strip()]:
        m = re.match(r'^(\d+(?:\.\d+)?)\s*[x*]\s*(\d+)$', p, re.I)
        if m:
            patt.extend([float(m.group(1))] * int(m.group(2)))
        else:
            try:
                patt.append(float(p))
            except Exception:
                pass
    patt = [x for x in patt if x > 0]
    return patt or [5, 4, 3, 3] + [1] * 11


def _sv_montage(durs, cfg, rng):
    """Rapid Zoom 'Videos' mode: random sub-clips following the pattern."""
    total = max(1.0, float(cfg['target']))
    patt = _sv_pattern(cfg['pattern'])
    segs, t, k, margin = [], 0.0, 0, 0.05
    while t + 0.25 < total and len(segs) < 600:
        d = patt[k % len(patt)]
        if t + d > total:
            d = max(0.25, total - t)
        if not segs and cfg['first_zero']:
            vi, st = 0, 0.0
            if durs[0] and d > durs[0]:
                d = max(0.25, durs[0] - margin)
        else:
            cands = [i for i, x in enumerate(durs) if x and x > d + margin]
            if cands:
                vi = rng.choice(cands)
            else:
                vi = rng.randrange(len(durs))
                if durs[vi] and d > durs[vi]:
                    d = max(0.25, durs[vi] - margin)
            vd = durs[vi]
            st = rng.uniform(0.0, max(0.0, vd - d - margin)) if (vd and vd > d + margin) else 0.0
        segs.append((vi, max(0.0, st), max(0.25, float(d))))
        t += segs[-1][2]
        k += 1
    return segs


def _sv_split(dur, cfg, rng):
    """Shorts Creator: cut a long video into Shorts (first part always kept)."""
    L = max(1.0, float(cfg['seg_len']))
    mx = max(1, int(cfg['seg_max']))
    jit = max(0.0, float(cfg['jitter']))
    out = []
    n = min(mx, int(_sv_math.ceil(dur / L))) if dur > 0 else 1
    for i in range(n):
        st = i * L
        if dur > 0 and st >= dur:
            break
        d = min(L, dur - st) if dur > 0 else L
        if i > 0 and d < (L * 0.5 if L < 30 else max(15.0, L * 0.5)):
            break                                       # leftover too short for a Short
        if jit > 0 and dur > 0:
            st = max(0.0, min(max(0.0, dur - 1.0), st + rng.uniform(-jit, jit)))
            d = min(d, dur - st)
        if d >= 0.5:
            out.append((st, d))
    return out


def _sv_unique(path):
    if not os.path.exists(path):
        return path
    base, ext = os.path.splitext(path)
    n = 2
    while os.path.exists('%s_%d%s' % (base, n, ext)):
        n += 1
    return '%s_%d%s' % (base, n, ext)


def _sv_plan(cfg, env, rng, preview=False, log=None):
    """Jobs to render: [{'kind', 'label', 'out', 'main_dur', ...}]."""
    log = log or (lambda m: None)
    files = [f for f in cfg['files'] if f and os.path.isfile(f)]
    vids = [f for f in files if _sv_kind(f) == 'video']
    imgs = [f for f in files if _sv_kind(f) == 'image']
    W, H = cfg['w'], cfg['h']
    out_dir = cfg['out_dir']
    ts = time.strftime('%Y%m%d_%H%M%S')
    fp = env.get('ffprobe')
    jobs = []
    mode = cfg['mode']
    if mode == 'slideshow':
        if not imgs:
            raise ValueError('images')
        d = max(0.2, float(cfg['img_dur']))
        items = imgs
        if preview:
            items = imgs[:max(1, int(_sv_math.ceil(5.0 / d)))]
        jobs.append({'kind': 'slideshow', 'items': items, 'img_dur': d, 'main_dur': d * len(items),
                     'label': 'Photo slideshow (%d images)' % len(items),
                     'name': 'Slideshow_%dx%d_%s' % (W, H, ts)})
    elif mode == 'montage':
        if not vids:
            raise ValueError('videos')
        pr = [_sv_probe(fp, v) for v in vids]
        c2 = dict(cfg)
        if preview:
            c2['target'] = min(5.0, float(cfg['target']))
        segs = _sv_montage([p['dur'] for p in pr], c2, rng)
        segs = [(vids[vi], st, d, pr[vi]['audio']) for vi, st, d in segs]
        jobs.append({'kind': 'montage', 'segs': segs, 'main_dur': sum(s[2] for s in segs),
                     'label': 'Rapid Zoom montage (%d clips from %d videos)' % (len(segs), len(vids)),
                     'name': 'RapidZoom_%dx%d_%s' % (W, H, ts)})
    else:
        if not vids:
            raise ValueError('videos')
        for v in vids:
            p = _sv_probe(fp, v)
            stem = re.sub(r'[<>:"/\\|?*]+', '_', os.path.splitext(os.path.basename(v))[0])
            if mode == 'split':
                parts = _sv_split(p['dur'], cfg, rng)
                for j, (st, d) in enumerate(parts, 1):
                    jobs.append({'kind': 'clip', 'src': v, 'start': st, 'dur': d, 'has_a': p['audio'],
                                 'main_dur': d, 'label': '%s \u2014 part %d/%d' % (os.path.basename(v), j, len(parts)),
                                 'name': '%s_short%02d' % (stem, j)})
            else:
                lim = float(cfg['each_max'] or 0)
                d = p['dur'] if p['dur'] > 0 else 60.0
                if lim > 0:
                    d = min(d, lim)
                jobs.append({'kind': 'clip', 'src': v, 'start': 0.0, 'dur': d, 'has_a': p['audio'],
                             'main_dur': d, 'label': os.path.basename(v), 'name': '%s_short' % stem})
            if preview and jobs:
                break
    if preview:
        jobs = jobs[:1]
        for j in jobs:
            if j['kind'] == 'clip':
                j['dur'] = j['main_dur'] = min(j['main_dur'], 5.0)
    hooks = [h for h in cfg['hooks'] if h and os.path.isfile(h) and _sv_kind(h) == 'video']
    songs = [s for s in cfg['songs'] if s and os.path.isfile(s) and _sv_kind(s) in ('audio', 'video')]
    if cfg['h_on'] and not hooks:
        log('\u26a0\ufe0f Hook video is ON but no hook file was added \u2014 no hook.')
    if cfg['a_mode'] in ('music', 'mix') and not songs:
        log('\u26a0\ufe0f No song added \u2014 keeping the original sound.')
    for j in jobs:
        if cfg['h_on'] and hooks:
            h = rng.choice(hooks)
            hp = _sv_probe(fp, h)
            hd = hp['dur'] if hp['dur'] > 0 else 3.0
            if float(cfg['h_max'] or 0) > 0:
                hd = min(hd, float(cfg['h_max']))
            if preview:
                hd = min(hd, 2.5)
            j.update(hook=h, hook_dur=max(0.5, hd), hook_a=hp['audio'])
        if cfg['a_mode'] in ('music', 'mix') and songs:
            j['song'] = rng.choice(songs)
        j['out'] = _sv_unique(os.path.join(out_dir, j['name'] + ('_preview' if preview else '') + '.mp4'))
    return jobs


# ----------------------------------------------------- filter-graph parts
def _sv_zoom(cfg, frames, rng):
    """Rapid Zoom expressions (Zoom In / Out / Pulse / Random / None + pan)."""
    style = cfg['zoom']
    zmin, zmax = float(cfg['zmin']), float(cfg['zmax'])
    if style == 'Random':
        style = rng.choice(['Zoom In', 'Zoom Out', 'Pulse'])
        zm = rng.uniform(min(zmin, zmax), max(zmin, zmax))
    elif style == 'None':
        zm = 1.0
    else:
        zm = zmax
    zm = max(1.0, zm)
    n = max(1, frames - 1)
    if style == 'Zoom In':
        z = 'min(%.6f,1.0+on*%.10f)' % (zm, (zm - 1.0) / n)
    elif style == 'Zoom Out':
        z = 'max(1.0,%.6f-on*%.10f)' % (zm, (zm - 1.0) / n)
    elif style == 'Pulse':
        mid = frames // 2
        up = (zm - 1.0) / max(1, mid)
        down = (zm - 1.0) / max(1, (frames - 1 - mid) or 1)
        z = 'if(lte(on,%d),1.0+on*%.10f,max(1.0,%.6f-(on-%d)*%.10f))' % (mid, up, zm, mid, down)
    else:
        z = '1.0'
    pan = cfg['pan']
    if pan == 'Random':
        pan = rng.choice(['None', 'Left->Right', 'Right->Left', 'Top->Bottom', 'Bottom->Top'])
    cx, cy = '(iw-iw/zoom)/2', '(ih-ih/zoom)/2'
    if pan == 'Left->Right':
        x, y = '(iw-iw/zoom)*on/%d' % n, cy
    elif pan == 'Right->Left':
        x, y = '(iw-iw/zoom)*(1-on/%d)' % n, cy
    elif pan == 'Top->Bottom':
        x, y = cx, '(ih-ih/zoom)*on/%d' % n
    elif pan == 'Bottom->Top':
        x, y = cx, '(ih-ih/zoom)*(1-on/%d)' % n
    else:
        x, y = cx, cy
    return z, x, y, zm, style


def _sv_crop_aspect(a):
    a = '%.6f' % a
    return ("crop=w='if(gte(iw/ih,{a}),ih*{a},iw)':h='if(gte(iw/ih,{a}),ih,iw/{a})':"
            "x='if(gte(iw/ih,{a}),(iw-ih*{a})/2,0)':y='if(gte(iw/ih,{a}),0,(ih-iw/{a})/2)'").format(a=a)


def _sv_frame_chain(src, out, dur, cfg, tw, th, fps, rng):
    """One visual clip -> tw x th: crop (+rapid zoom), blurred background
    (+stroke, slow zoom) or fit with bars."""
    frames = max(1, int(round(dur * fps)))
    head = '[%s]fps=%d,setpts=PTS-STARTPTS' % (src, fps)
    tail = ',setsar=1,format=yuv420p,trim=duration=%.6f,setpts=PTS-STARTPTS[%s]' % (dur, out)
    mode = cfg['frame']
    if mode == 'blur':
        brightness = -min(0.9, max(0.0, float(cfg['bg_dim'])))
        sat = max(0.0, float(cfg['bg_sat']))
        sigma = max(0.0, float(cfg['bg_sigma']))
        qw, qh = _sv_even(tw // 4), _sv_even(th // 4)
        if cfg['bg_zoom']:
            zb = 1.0 + max(0.0, float(cfg['bg_rate'])) * dur
            inc = (zb - 1.0) / max(1, frames - 1)
            bg = ("scale=%d:%d:force_original_aspect_ratio=increase,crop=%d:%d,zoompan=z='min(%.6f,1.0+on*%.10f)'"
                  ":x='(iw-iw/zoom)/2':y='(ih-ih/zoom)/2':d=1:s=%dx%d:fps=%d"
                  % (_sv_even(qw * zb + 2), _sv_even(qh * zb + 2), _sv_even(qw * zb + 2), _sv_even(qh * zb + 2),
                     zb, inc, qw, qh, fps))
        else:
            bg = 'scale=%d:%d:force_original_aspect_ratio=increase,crop=%d:%d' % (qw, qh, qw, qh)
        bg += ',gblur=sigma=%.3f:steps=2,scale=%d:%d,eq=brightness=%.3f:saturation=%.3f' % (
            max(0.5, sigma / 4.0), tw, th, brightness, sat)
        b = int(max(0, int(cfg['stroke_px']))) if cfg['stroke'] else 0
        b = max(0, min(b, (tw - 16) // 2, (th - 16) // 2))
        col = 'white' if str(cfg['stroke_col']).lower().startswith('w') else 'black'
        if b > 0:
            fg = 'scale=%d:%d:force_original_aspect_ratio=decrease,setsar=1,pad=iw+%d:ih+%d:%d:%d:color=%s' % (
                tw - 2 * b, th - 2 * b, 2 * b, 2 * b, b, b, col)
        else:
            fg = 'scale=%d:%d:force_original_aspect_ratio=decrease,setsar=1' % (tw, th)
        return ('%s,split=2[%sb][%sf];[%sb]%s,setsar=1,format=yuv420p[%sB];[%sf]%s[%sF];'
                '[%sB][%sF]overlay=x=(main_w-overlay_w)/2:y=(main_h-overlay_h)/2:shortest=1%s'
                % (head, out, out, out, bg, out, out, fg, out, out, out, tail))
    if mode == 'fit':
        return head + ',scale=%d:%d:force_original_aspect_ratio=decrease,pad=%d:%d:(ow-iw)/2:(oh-ih)/2:color=black' \
            % (tw, th, tw, th) + tail
    z, x, y, zm, style = _sv_zoom(cfg, frames, rng)
    chain = head + ',' + _sv_crop_aspect(tw / float(th))
    if style == 'None' or zm <= 1.0001:
        chain += ',scale=%d:%d' % (tw, th)
    else:
        chain += ",scale=%d:%d,zoompan=z='%s':x='%s':y='%s':d=1:s=%dx%d:fps=%d" % (
            _sv_even(_sv_math.ceil(tw * zm) + 1), _sv_even(_sv_math.ceil(th * zm) + 1), z, x, y, tw, th, fps)
    return chain + tail


def _sv_stack_geo(cfg, W, H):
    sm = max(0, int(cfg['side_m']))
    tm = max(0, int(cfg['top_m']))
    bm = max(0, int(cfg['bot_m']))
    gap = max(0, int(cfg['gap']))
    aw = _sv_even(max(16, W - 2 * sm))
    ah = _sv_even(max(16, int((H - tm - bm - 2 * gap) / 3)))
    return {'aw': aw, 'ah': ah, 'top': (sm, tm), 'mid': (sm, tm + ah + gap), 'bot': (sm, tm + 2 * (ah + gap))}


def _sv_logo(fc, add, cfg, pre, D, fps, geo, panel, env, label):
    path = cfg[pre + 'path']
    img = _sv_kind(path) == 'image'
    i = add(path, ['-loop', '1', '-framerate', str(fps)] if img else ['-stream_loop', '-1'])
    aw, ah = geo['aw'], geo['ah']
    mw = max(2, int(aw * float(cfg[pre + 'w']) / 100.0))
    mh = max(2, int(ah * float(cfg[pre + 'h']) / 100.0))
    ch = '[%d:v]fps=%d,scale=%d:%d:force_original_aspect_ratio=decrease,format=rgba' % (i, fps, mw, mh)
    flt = env['caps'].get('filters') or set()
    if cfg[pre + 'key']:
        kf = 'colorkey' if 'colorkey' in flt else ('chromakey' if 'chromakey' in flt else None)
        if kf:
            ch += ',%s=%s:%.3f:%.3f' % (kf, _sv_hex(cfg[pre + 'kc']), max(0.0, min(1.0, float(cfg[pre + 'sim']))),
                                        max(0.0, min(1.0, float(cfg[pre + 'bl']))))
    fi, fo = max(0.0, float(cfg[pre + 'fi'])), max(0.0, float(cfg[pre + 'fo']))
    if fi > 0:
        ch += ',fade=t=in:st=0:d=%.3f:alpha=1' % fi
    if fo > 0:
        ch += ',fade=t=out:st=%.3f:d=%.3f:alpha=1' % (max(0.0, D - fo), fo)
    op = int(cfg[pre + 'op'])
    if op < 100:
        ch += ',colorchannelmixer=aa=%.3f' % max(0.0, min(1.0, op / 100.0))
    ch += ',trim=duration=%.3f,setpts=PTS-STARTPTS[%s]' % (D, label)
    fc.append(ch)
    px, py = geo[panel]
    return ('%d+(%d-overlay_w)/2' % (px, aw), '%d+(%d-overlay_h)/2+%d' % (py, ah, int(cfg[pre + 'y'])))


def _sv_hex(c):
    s = str(c or '').strip()
    if s.lower().startswith('0x'):
        s = s[2:]
    s = s.lstrip('#')
    try:
        int(s, 16)
        if len(s) == 6:
            return '0x' + s.upper()
    except Exception:
        pass
    return '0x00FF00'


def _sv_stack(fc, add, cfg, W, H, fps, mv, D, geo, env):
    """Shorts Creator triple stack: top video | main (stroke) | bottom video,
    each with an optional (green-screen) logo."""
    aw, ah = geo['aw'], geo['ah']
    fc.append('color=c=black:s=%dx%d:r=%d,trim=duration=%.3f,format=yuv420p[stbg]' % (W, H, fps, D))
    state = {'cur': 'stbg', 'n': 0}

    def over(lab, x, y):
        state['n'] += 1
        new = 'st%d' % state['n']
        fc.append("[%s][%s]overlay=x='%s':y='%s':eof_action=repeat:shortest=0[%s]" % (state['cur'], lab, x, y, new))
        state['cur'] = new

    def panel(path, lab):
        img = _sv_kind(path) == 'image'
        i = add(path, ['-loop', '1', '-framerate', str(fps)] if img else ['-stream_loop', '-1'])
        fc.append('[%d:v]fps=%d,scale=%d:%d:force_original_aspect_ratio=increase,crop=%d:%d,setsar=1,'
                  'format=yuv420p,trim=duration=%.3f,setpts=PTS-STARTPTS[%s]' % (i, fps, aw, ah, aw, ah, D, lab))
    top = cfg['top_video'] if cfg['top_video'] and os.path.isfile(cfg['top_video']) else ''
    bot = cfg['bot_video'] if cfg['bot_video'] and os.path.isfile(cfg['bot_video']) else ''
    if top:
        panel(top, 'sttop')
        over('sttop', geo['top'][0], geo['top'][1])
    if cfg['tl_path'] and os.path.isfile(cfg['tl_path']):
        x, y = _sv_logo(fc, add, cfg, 'tl_', D, fps, geo, 'top', env, 'stlt')
        over('stlt', x, y)
    s = max(0, int(cfg['st_px']))
    col = 'white' if str(cfg['st_col']).lower().startswith('w') else 'black'
    if s > 0:
        fc.append('[%s]pad=iw+%d:ih+%d:%d:%d:color=%s[stmain]' % (mv, 2 * s, 2 * s, s, s, col))
        over('stmain', geo['mid'][0] - s, geo['mid'][1] - s)
    else:
        over(mv, geo['mid'][0], geo['mid'][1])
    if bot:
        panel(bot, 'stbot')
        over('stbot', geo['bot'][0], geo['bot'][1])
    if cfg['bl_path'] and os.path.isfile(cfg['bl_path']):
        x, y = _sv_logo(fc, add, cfg, 'bl_', D, fps, geo, 'bot', env, 'stlb')
        over('stlb', x, y)
    return state['cur']


def _sv_glitch(src, out, H, cfg, rng, fps):
    """Pixel Line Glitch: green core line + side glow (+ flowing rainbow),
    jitter, soft blur and pulse-gated flicker inside the time window."""
    w_main = max(1, int(cfg['g_th']))
    w_bleed = max(0, int(cfg['g_bleed']))
    a_main = min(1.0, max(0.05, float(cfg['g_a'])))
    a_bleed = min(1.0, max(0.0, float(cfg['g_ba'])))
    blur = max(0.0, float(cfg['g_blur']))
    rb = float(cfg['g_rb'])
    jamp, jfreq = float(cfg['g_jamp']), float(cfg['g_jfreq'])
    fr, fd = max(0.1, float(cfg['g_flr'])), min(1.0, max(0.05, float(cfg['g_fld'])))
    ph_l, ph_r, ph_f = rng.uniform(0, 1), rng.uniform(0, 1), rng.uniform(0, 1)
    jph = round(rng.uniform(0, 6.2831), 4)
    s0 = max(0.0, float(cfg['g_start']))
    gd = max(0.0, float(cfg['g_dur']))
    s1 = s0 + gd if gd > 0 else 1e9
    rain = (cfg['g_col'] == 'Green+Rainbow')
    pos = {'Left': 'main_w*0.1', 'Right': 'main_w*0.9'}.get(cfg['g_pos'], 'main_w/2')
    p = []

    def side(lab, phase):
        if w_bleed <= 0:
            return 'color=c=black@0.0:s=1x64:r=%d,format=rgba[%s]' % (fps, lab)
        c = 'color=c=0x00FF00@%.3f:s=%dx64:r=%d,format=rgba' % (a_bleed, w_bleed, fps)
        if rain:
            c += ',hue=h=360*%.4f*(t+%.4f):s=1' % (rb, phase)
        return c + '[%s]' % lab
    p.append(side('%sL' % out, ph_l))
    p.append('color=c=0x00FF00@%.3f:s=%dx64:r=%d,format=rgba[%sC]' % (a_main, w_main, fps, out))
    p.append(side('%sR' % out, ph_r))
    p.append('[%sL][%sC]hstack=inputs=2[%sLC]' % (out, out, out))
    p.append('[%sLC][%sR]hstack=inputs=2[%sS]' % (out, out, out))
    small = '%sS' % out
    if blur > 0:
        p.append('[%sS]gblur=sigma=%.3f[%sSB]' % (out, blur, out))
        small = '%sSB' % out
    p.append('[%s]scale=w=iw:h=%d[%sStripe]' % (small, int(H), out))
    x = '(%s)-overlay_w/2+(%.3f)*sin(2*PI*%.3f*t+%.4f)' % (pos, jamp, jfreq, jph)
    en = 'between(t,%.3f,%.3f)*lt(mod(t*%.3f+%.4f,1),%.3f)' % (s0, s1, fr, ph_f, fd)
    p.append("[%s][%sStripe]overlay=x='%s':y=0:eval=frame:shortest=1:format=auto:enable='%s'[%s]"
             % (src, out, x, en, out))
    return ';'.join(p)


# ------------------------------------------------- keywords & metadata
def _sv_keywords(raw):
    toks = []
    for part in (raw or '').replace(',', '\n').splitlines():
        for s in part.split():
            s = s.strip()
            if s:
                toks.append(s if s.startswith('#') else '#' + s)
    seen, out = set(), []
    for t in toks:
        if t.lower() not in seen:
            seen.add(t.lower())
            out.append(t)
    return out[:1000]


def _sv_genre(keywords):
    kws = [k.lower().lstrip('#') for k in keywords]
    if not kws:
        return '', 'PG'
    best, top = 'General', 0
    for g, terms in _SV_GENRES.items():
        n = sum(1 for t in terms if any(t in k for k in kws))
        if n > top:
            best, top = g.capitalize(), n
    rating = 'PG'
    if best.lower() in _SV_RATING['safe']:
        rating = 'G' if best.lower() == 'education' else 'PG'
    elif best.lower() in _SV_RATING['caution']:
        rating = 'PG-13'
    return best, rating


def _sv_tc(t):
    t = max(0.0, float(t))
    ms = int(round((t - int(t)) * 1000))
    s = int(t)
    if ms >= 1000:
        s, ms = s + 1, 0
    return '%02d:%02d:%02d,%03d' % (s // 3600, (s % 3600) // 60, s % 60, ms)


def _sv_srt(path, keywords, start, end):
    lines, steps = [], max(1, int(_sv_math.ceil(end - start)))
    for i in range(steps):
        a, b = start + i, min(start + i + 1, end)
        lines += [str(i + 1), '%s --> %s' % (_sv_tc(a), _sv_tc(b)), keywords[i % len(keywords)], '']
    with open(path, 'w', encoding='utf-8') as f:
        f.write('\n'.join(lines).strip() + '\n')
    return path


def _sv_meta(cfg, job, keywords):
    pairs = []
    if not keywords:
        return pairs
    if cfg['kw_meta']:
        hl, cl = '', []
        for k in keywords:
            if len((hl + ' ' + k).strip()) > 900:
                break
            hl = (hl + ' ' + k).strip()
        tot = 0
        for k in keywords:
            plain = k.lstrip('#')
            if tot + len(plain) + 2 > 900:
                break
            cl.append(plain)
            tot += len(plain) + 2
        pairs += [('comment', hl), ('description', ', '.join(cl)), ('keywords', ', '.join(cl))]
    if cfg['kw_rich']:
        genre, rating = _sv_genre(keywords)
        if cfg['rating'] not in ('', 'Auto'):
            rating = cfg['rating']
        base = os.path.splitext(os.path.basename(job['out']))[0].replace('_', ' ').title()
        tags = []
        for k in keywords[:20]:
            c = k.lstrip('#')
            tags.append(c)
        desc = 'Short created with AutoPoster Pro Edit Shorts Video Tool on %s. Tags: %s' % (
            time.strftime('%Y-%m-%d'), ', '.join(tags[:10]))
        pairs += [('title', base), ('description', desc), ('genre', genre or 'Entertainment'),
                  ('rating', rating), ('tags', ', '.join(tags[:30])), ('category', genre or 'Entertainment'),
                  ('date', time.strftime('%Y-%m-%d')), ('year', time.strftime('%Y'))]
    return pairs


# ---------------------------------------------------------- job command
def _sv_main_audio(fc, add, cfg, job, ma, D):
    mode = cfg['a_mode']
    song = job.get('song')
    if mode in ('music', 'mix') and not song:
        mode = 'original'
    if mode in ('original', 'mix') and not ma:
        mode = 'music' if song else 'silent'
    if ma and mode in ('silent', 'music'):
        fc.append('[%s]anullsink' % ma)                  # original sound not used
    if mode == 'silent':
        fc.append('anullsrc=r=48000:cl=stereo,atrim=0:%.3f,asetpts=PTS-STARTPTS[mau]' % D)
        return 'mau'
    ov = max(0.0, float(cfg['o_vol']))
    if mode == 'original':
        if abs(ov - 1.0) > 1e-3:
            fc.append('[%s]volume=%.3f[mau]' % (ma, ov))
            return 'mau'
        return ma
    si = add(song, ['-stream_loop', '-1'])
    m = '[%d:a]%s,atrim=0:%.3f,asetpts=PTS-STARTPTS' % (si, _SV_AFMT, D)
    mv = max(0.0, float(cfg['m_vol']))
    if abs(mv - 1.0) > 1e-3:
        m += ',volume=%.3f' % mv
    fi, fo = max(0.0, float(cfg['m_fi'])), max(0.0, float(cfg['m_fo']))
    if fi > 0:
        m += ',afade=t=in:st=0:d=%.3f' % min(fi, D)
    if fo > 0:
        m += ',afade=t=out:st=%.3f:d=%.3f' % (max(0.0, D - fo), min(fo, D))
    fc.append(m + '[mus]')
    if mode == 'music':
        return 'mus'
    fc.append('[%s]volume=%.3f[mor];[mor][mus]amix=inputs=2:duration=first:dropout_transition=0,volume=2[mau]'
              % (ma, ov))
    return 'mau'


def _sv_build(job, cfg, env, rng, tmpdir):
    """(cmd, temp_files, total_seconds) for one Short."""
    W, H, fps = cfg['w'], cfg['h'], cfg['fps']
    inputs, fc, tmp = [], [], []

    def add(path, pre=None):
        inputs.append((list(pre or []), path))
        return len(inputs) - 1
    stack = (cfg['frame'] == 'stack')
    geo = _sv_stack_geo(cfg, W, H) if stack else None
    tw, th = (geo['aw'], geo['ah']) if stack else (W, H)
    fcfg = dict(cfg, frame='crop') if stack else cfg
    vparts, aparts = [], []
    kind = job['kind']
    if kind == 'slideshow':
        d = job['img_dur']
        for k, img in enumerate(job['items']):
            i = add(img, ['-loop', '1', '-framerate', str(fps), '-t', '%.3f' % d])
            fc.append(_sv_frame_chain('%d:v' % i, 'sv%d' % k, d, fcfg, tw, th, fps, rng))
            vparts.append('sv%d' % k)
    elif kind == 'montage':
        for k, (path, st, d, has_a) in enumerate(job['segs']):
            i = add(path, ['-ss', '%.3f' % st, '-t', '%.3f' % d])
            fc.append(_sv_frame_chain('%d:v' % i, 'sv%d' % k, d, fcfg, tw, th, fps, rng))
            vparts.append('sv%d' % k)
            if has_a:
                fc.append('[%d:a]%s,apad,atrim=0:%.3f,asetpts=PTS-STARTPTS[sa%d]' % (i, _SV_AFMT, d, k))
            else:
                fc.append('anullsrc=r=48000:cl=stereo,atrim=0:%.3f,asetpts=PTS-STARTPTS[sa%d]' % (d, k))
            aparts.append('sa%d' % k)
    else:
        pre = ['-ss', '%.3f' % job['start'], '-t', '%.3f' % job['dur']] if job['start'] > 0 \
            else ['-t', '%.3f' % job['dur']]
        i = add(job['src'], pre)
        fc.append(_sv_frame_chain('%d:v' % i, 'sv0', job['dur'], fcfg, tw, th, fps, rng))
        vparts.append('sv0')
        if job.get('has_a'):
            fc.append('[%d:a]%s,apad,atrim=0:%.3f,asetpts=PTS-STARTPTS[sa0]' % (i, _SV_AFMT, job['dur']))
            aparts.append('sa0')
    D = float(job['main_dur'])
    if len(vparts) > 1:
        fc.append(''.join('[%s]' % p for p in vparts) + 'concat=n=%d:v=1:a=0[mv0]' % len(vparts))
        mv = 'mv0'
    else:
        mv = vparts[0]
    ma = None
    if len(aparts) > 1:
        fc.append(''.join('[%s]' % p for p in aparts) + 'concat=n=%d:v=0:a=1[ma0]' % len(aparts))
        ma = 'ma0'
    elif aparts:
        ma = aparts[0]
    if stack:
        mv = _sv_stack(fc, add, cfg, W, H, fps, mv, D, geo, env)
    if cfg['g_on']:
        fc.append(_sv_glitch(mv, 'gl', H, cfg, rng, fps))
        mv = 'gl'
    au = _sv_main_audio(fc, add, cfg, job, ma, D)
    total, main_start = D, 0.0
    if job.get('hook'):
        hd = float(job['hook_dur'])
        hi = add(job['hook'], ['-t', '%.3f' % hd])
        hcfg = dict(cfg, frame=('crop' if stack else cfg['frame']), zoom='None', pan='None')
        fc.append(_sv_frame_chain('%d:v' % hi, 'hk', hd, hcfg, W, H, fps, rng))
        norm = 'settb=AVTB,fps=%d,format=yuv420p,setsar=1' % fps
        fc.append('[hk]%s[hkn]' % norm)
        fc.append('[%s]%s[mvn]' % (mv, norm))
        if job.get('hook_a'):
            fc.append('[%d:a]%s,apad,atrim=0:%.3f,asetpts=PTS-STARTPTS[hka]' % (hi, _SV_AFMT, hd))
        else:
            fc.append('anullsrc=r=48000:cl=stereo,atrim=0:%.3f,asetpts=PTS-STARTPTS[hka]' % hd)
        xd = min(max(0.0, float(cfg['xd'])), hd * 0.9, D * 0.9)
        flt = env['caps'].get('filters') or set()
        if xd >= 0.1 and 'xfade' in flt:
            off = max(0.0, hd - xd)
            xf = cfg['xf'] if cfg['xf'] in _SV_XFADES else 'circleopen'
            fc.append('[hkn][mvn]xfade=transition=%s:duration=%.3f:offset=%.3f[vx]' % (xf, xd, off))
            fc.append('[hka][%s]acrossfade=d=%.3f:c1=tri:c2=tri[ax]' % (au, xd))
            total, main_start = hd + D - xd, off
        else:
            fc.append('[hkn][mvn]concat=n=2:v=1:a=0[vx]')
            fc.append('[hka][%s]concat=n=2:v=0:a=1[ax]' % au)
            total, main_start = hd + D, hd
        mv, au = 'vx', 'ax'
    fc.append('[%s]format=yuv420p[vout]' % mv)
    fc.append('[%s]atrim=0:%.3f,asetpts=PTS-STARTPTS[aout]' % (au, total))
    ff = env['ffmpeg']
    cmd = [ff, '-hide_banner', '-nostats', '-loglevel', 'error', '-y']
    for pre, path in inputs:
        cmd += pre + ['-i', path]
    kws = _sv_keywords(cfg['kw_text'])
    sub_idx = None
    if kws and cfg['kw_subs']:
        st = main_start if cfg['kw_scope'] == 'main' else 0.0
        if total > st:
            srt = os.path.join(tmpdir, 'kw_%d.srt' % int(time.time() * 1000))
            _sv_srt(srt, kws, st, total)
            tmp.append(srt)
            cmd += ['-i', srt]
            sub_idx = len(inputs)
    graph = ';'.join(fc)
    if len(graph) + sum(len(a) for a in cmd) < 24000:
        cmd += ['-filter_complex', graph]
    else:
        gp = os.path.join(tmpdir, 'graph_%d.txt' % int(time.time() * 1000))
        with open(gp, 'w', encoding='utf-8') as f:
            f.write(graph)
        tmp.append(gp)
        cmd += (['-/filter_complex', gp] if env['caps'].get('major', 0) >= 7 else ['-filter_complex_script', gp])
    cmd += ['-map', '[vout]', '-map', '[aout]']
    if sub_idx is not None:
        cmd += ['-map', '%d:s:0' % sub_idx, '-c:s', 'mov_text', '-disposition:s:0', '0',
                '-metadata:s:s:0', 'title=Keywords', '-metadata:s:s:0', 'handler_name=Keywords',
                '-metadata:s:s:0', 'language=und']
    enc = env.get('enc') or 'libx264'
    cmd += _sv_enc_flags(enc, cfg['crf'], cfg['preset'], W, H)
    cmd += ['-pix_fmt', 'yuv420p', '-r', str(fps), '-c:a', 'aac', '-b:a', cfg['abr'] or '192k', '-ar', '48000',
            '-movflags', '+faststart+use_metadata_tags', '-t', '%.3f' % total]
    for k, v in _sv_meta(cfg, job, kws):
        cmd += ['-metadata', '%s=%s' % (k, v)]
    cmd += ['-progress', 'pipe:1', job['out']]
    return cmd, tmp, total


# ----------------------------------------------------------------- runner
def _sv_suspend(proc, on):
    if proc is None:
        return False
    try:
        import psutil as _ps
        p = _ps.Process(proc.pid)
        p.suspend() if on else p.resume()
        return True
    except Exception:
        pass
    if os.name == 'nt':
        try:
            import ctypes
            h = ctypes.windll.kernel32.OpenProcess(0x0800, False, proc.pid)      # PROCESS_SUSPEND_RESUME
            if h:
                (ctypes.windll.ntdll.NtSuspendProcess if on else ctypes.windll.ntdll.NtResumeProcess)(h)
                ctypes.windll.kernel32.CloseHandle(h)
                return True
        except Exception:
            pass
        return False
    try:
        os.kill(proc.pid, _sv_signal.SIGSTOP if on else _sv_signal.SIGCONT)
        return True
    except Exception:
        return False


class _SVRunner(object):
    """Runs the jobs in a worker thread (no Tk calls there); the tab polls it."""

    def __init__(self, log):
        self.log = log
        self.jobs = []
        self.state = 'idle'          # idle | running | paused
        self.stop_req = None         # None | 'stop' | 'force'
        self.proc = None
        self.cur = -1
        self.pct = 0.0
        self.total = 0.0
        self.t0 = 0.0
        self.thread = None
        self.preview = False
        self.done_ok = 0
        self.last_out = None
        self.enc = ''
        self.error = None
        self._q_sent = False

    def busy(self):
        return self.state in ('running', 'paused') or (self.thread is not None and self.thread.is_alive())

    def start(self, cfg, env, jobs=None, preview=False):
        self.jobs, self.preview, self.done_ok = jobs, preview, 0
        self.error = None
        self.stop_req, self.cur, self.pct, self.last_out = None, -1, 0.0, None
        self.state = 'running'
        self.thread = _sv_threading.Thread(target=self._work, args=(cfg, env), daemon=True)
        self.thread.start()

    def pause(self):
        if self.state == 'running':
            self.state = 'paused'
            _sv_suspend(self.proc, True)
            return True
        return False

    def resume(self):
        if self.state == 'paused':
            _sv_suspend(self.proc, False)
            self.state = 'running'
            return True
        return False

    def stop(self):
        """Finish the current Short cleanly (FFmpeg 'q') and start no other."""
        if not self.busy():
            return
        self.stop_req = self.stop_req or 'stop'
        if self.state == 'paused':
            self.resume()
        p = self.proc
        if p is not None and not self._q_sent:
            try:
                p.stdin.write(b'q')
                p.stdin.flush()
                self._q_sent = True
            except Exception:
                pass

    def force(self):
        """Kill FFmpeg now; the unfinished file is deleted."""
        if not self.busy():
            return
        self.stop_req = 'force'
        p = self.proc
        if p is not None:
            try:
                p.kill()
            except Exception:
                pass
            if self.state == 'paused':
                _sv_suspend(p, False)
        self.state = 'running'

    def _exec(self, cmd, total):
        errf = _sv_tempfile.TemporaryFile()
        try:
            p = _sv_sp.Popen(cmd, stdin=_sv_sp.PIPE, stdout=_sv_sp.PIPE, stderr=errf, **_sv_popen_kw())
        except Exception as e:
            return -1, str(e)
        self.proc, self._q_sent = p, False
        try:
            for raw in iter(p.stdout.readline, b''):
                line = raw.decode('utf-8', 'replace').strip()
                if line.startswith('out_time_us=') or line.startswith('out_time_ms='):
                    try:
                        v = int(line.split('=', 1)[1]) / 1e6
                        if total > 0:
                            self.pct = max(0.0, min(1.0, v / total))
                    except Exception:
                        pass
                if self.stop_req == 'force':
                    try:
                        p.kill()
                    except Exception:
                        pass
                    break
            rc = p.wait()
        finally:
            self.proc = None
        try:
            errf.seek(0)
            err = errf.read().decode('utf-8', 'replace')
        except Exception:
            err = ''
        finally:
            errf.close()
        return rc, err

    def _work(self, cfg, env):
        tmpdir = _sv_tempfile.mkdtemp(prefix='apshorts_')
        rng = random.Random()
        try:
            if not env.get('caps'):
                env['caps'] = _sv_caps(env.get('ffmpeg'))
            if self.jobs is None:                      # planning off the UI thread
                try:
                    self.jobs = _sv_plan(cfg, env, rng, preview=self.preview, log=self.log)
                except ValueError as e:
                    self.error, self.jobs = str(e), []
                    return
                if not self.jobs:
                    self.error = 'empty'
                    return
            env['enc'] = self.enc = _sv_pick_encoder(env, cfg['enc'])
            self.log('\U0001f3ac Edit Shorts Video Tool \u2014 %d video(s) to render \u00b7 encoder: %s'
                     % (len(self.jobs), self.enc))
            for i, job in enumerate(self.jobs):
                if self.stop_req:
                    job['status'] = 'skipped'
                    continue
                while self.state == 'paused' and not self.stop_req:
                    time.sleep(0.2)
                self.cur, self.pct, self.t0 = i, 0.0, time.time()
                job['status'] = 'running'
                try:
                    cmd, tmp, total = _sv_build(job, cfg, env, rng, tmpdir)
                except Exception as e:
                    job['status'], job['err'] = 'failed', str(e)
                    self.log('   \u274c %s: %s' % (job['label'], e))
                    continue
                self.total = total
                self.log('   \u25b6 %s \u2192 %s (%.1fs)' % (job['label'], os.path.basename(job['out']), total))
                rc, err = self._exec(cmd, total)
                if rc != 0 and env['caps'].get('major', 0) >= 7 and '-/filter_complex' in cmd \
                        and ('nrecognized option' in err or 'not found' in err):
                    k = cmd.index('-/filter_complex')
                    cmd[k] = '-filter_complex_script'
                    rc, err = self._exec(cmd, total)
                for t in tmp:
                    try:
                        os.remove(t)
                    except Exception:
                        pass
                out = job['out']
                size = os.path.getsize(out) if os.path.isfile(out) else 0
                if self.stop_req == 'force':
                    job['status'] = 'cancelled'
                    try:
                        if os.path.isfile(out):
                            os.remove(out)
                    except Exception:
                        pass
                    self.log('   \u26a1 Forced stop \u2014 unfinished file removed.')
                    break
                if rc == 0 and size > 1024:
                    job['status'] = 'stopped' if self.stop_req == 'stop' else 'done'
                    job['size'] = size
                    self.done_ok += 1
                    self.last_out = out
                    self.pct = 1.0
                    self.log('   \u2713 %s (%.1f MB)%s' % (os.path.basename(out), size / 1048576.0,
                                                          ' \u2014 stopped early' if job['status'] == 'stopped' else ''))
                else:
                    job['status'] = 'failed'
                    tail = (err or '').strip()[-1500:]
                    job['err'] = tail
                    self.log('   \u274c FFmpeg failed (code %s) for %s%s' % (rc, job['label'],
                                                                            (':\n' + tail) if tail else ''))
                    try:
                        os.makedirs(os.path.join(cfg['out_dir'], '_logs'), exist_ok=True)
                        with open(os.path.join(cfg['out_dir'], '_logs', 'ffmpeg_last_error.txt'), 'w',
                                  encoding='utf-8') as f:
                            f.write(' '.join(cmd) + '\n\n' + (err or ''))
                    except Exception:
                        pass
                    try:
                        if os.path.isfile(out):
                            os.remove(out)
                    except Exception:
                        pass
        except Exception as e:
            self.log('   \u274c Edit Shorts Video Tool: %s' % e)
        finally:
            try:
                _sv_shutil.rmtree(tmpdir, ignore_errors=True)
            except Exception:
                pass
            self.state = 'idle'
            self.proc = None
            n = len(self.jobs or [])
            if self.error:
                return
            self.log('\U0001f3ac Edit Shorts Video Tool %s \u2014 %d/%d video(s) created.'
                     % ('stopped' if self.stop_req else 'finished', self.done_ok, n))



