# ------------------------------------------------ widgets like the app's
class _SVB(object):
    """Builds controls cloned from the app's own widgets (same look, same
    theme handling)."""

    def __init__(self, app):
        self.app = app
        self.entries = []
        S = app._sections
        src = lambda w: str(getattr(w, '_i18n_src', '') or '')
        R, CM, CO, CP = (S.get(n) for n in ('rejoindre', 'commenter', 'collecte', 'campagne'))
        f = _ui14_find
        self.refs = {
            'switch': f(CM, lambda w: w.winfo_class() == 'Checkbutton' and getattr(w, '_ui_skin', None) == 'switch')
            if CM else None,
            'chip': f(CP, lambda w: w.winfo_class() == 'Radiobutton' and getattr(w, '_ui_skin', None) == 'chip')
            if CP else None,
            'spin': f(R, lambda w: w.winfo_class() == 'Spinbox') if R else None,
            'mini': f(R, lambda w: w.winfo_class() == 'Button' and src(w).startswith('\U0001f4c2')) if R else None,
            'go': f(R, lambda w: w.winfo_class() == 'Button' and src(w).startswith('\u25b6')) if R else None,
            'stop': f(R, lambda w: w.winfo_class() == 'Button' and src(w).startswith('\u25a0')) if R else None,
            'combo': f(CO, lambda w: w.winfo_class() == 'TCombobox') if CO else None,
        }

    def lbl(self, parent, text, bold=False, fg=None, size=9, **kw):
        import tkinter as _tk
        return _tk.Label(parent, text=text, font=(_F13, size, 'bold') if bold else (_F13, size), bg=C['surface'],
                         fg=fg or (C['text'] if bold else C['text2']), anchor='w', justify='left', **kw)

    def row(self, parent, pady=(6, 0)):
        import tkinter as _tk
        r = _tk.Frame(parent, bg=C['surface'])
        r.pack(fill='x', pady=pady)
        return r

    def holder(self, parent):
        import tkinter as _tk
        h = _tk.Frame(parent, bg=C['surface'])
        h.pack(fill='x')
        return h

    def entry(self, parent, var, width=8):
        import tkinter as _tk
        e = _tk.Entry(parent, textvariable=var, width=width, font=(_F13, 9), bg=C['surface2'], fg=C['text'],
                      relief='flat', bd=4, highlightthickness=1, highlightbackground=C['border'],
                      highlightcolor=C['accent'], insertbackground=C['accent'])
        self.entries.append(e)
        return e

    def spin(self, parent, var, lo, hi, inc=1, width=5):
        import tkinter as _tk
        kw = dict(from_=lo, to=hi, increment=inc, textvariable=var, width=width)
        ref = self.refs['spin']
        return _ui14_clone(ref, parent, **kw) if ref is not None else _tk.Spinbox(parent, font=(_F13, 9), **kw)

    def switch(self, parent, text, var):
        import tkinter as _tk
        ref = self.refs['switch']
        if ref is not None:
            return _ui14_clone(ref, parent, text=text, variable=var)
        return _tk.Checkbutton(parent, text=text, variable=var, bg=C['surface'], fg=C['text'], font=(_F13, 9),
                               selectcolor=C['surface'], activebackground=C['surface'], bd=0, highlightthickness=0)

    def chips(self, parent, var, options):
        import tkinter as _tk
        ref, out = self.refs['chip'], []
        for val, text in options:
            if ref is not None:
                c = _ui14_clone(ref, parent, text=text, variable=var, value=val)
            else:
                c = _tk.Radiobutton(parent, text=text, variable=var, value=val, bg=C['surface'], fg=C['text'],
                                    font=(_F13, 9), selectcolor=C['surface'])
            c.pack(side='left', padx=(0, 5))
            out.append(c)
        return out

    def combo(self, parent, var, values, width=10):
        from tkinter import ttk as _ttk
        cb = _ttk.Combobox(parent, textvariable=var, values=list(values), state='readonly', width=width,
                           font=(_F13, 9))
        ref = self.refs['combo']
        if ref is not None:
            try:
                cb.configure(style=ref.cget('style') or 'TCombobox')
            except Exception:
                pass
        return cb

    def btn(self, parent, text, cmd, kind='mini'):
        import tkinter as _tk
        ref = self.refs.get({'mini': 'mini', 'force': 'mini', 'stop': 'stop'}.get(kind, 'go'))
        over = {'text': text, 'command': cmd}
        if kind == 'accent':
            over.update(bg=C['accent'], activebackground=C['accent'])
        elif kind == 'warn':
            w = C.get('warning', '#f59e0b')
            over.update(bg=w, activebackground=w, fg='#ffffff')
        elif kind == 'force':
            over.update(bg=C['danger_d'], fg=C['danger'], activebackground=C['danger_d'])
        if ref is not None:
            return _ui14_clone(ref, parent, **over)
        base = {'mini': (C['surface2'], C['text2']), 'stop': (C['danger'], '#ffffff')}.get(kind, (C['success'], '#ffffff'))
        return _tk.Button(parent, relief='flat', bd=0, padx=10, pady=4, font=(_F13, 9, 'bold'), cursor='hand2',
                          **dict({'bg': base[0], 'fg': base[1]}, **over))

    def text(self, parent, height=3):
        import tkinter as _tk
        from tkinter import scrolledtext as _st
        fr = _tk.Frame(parent, bg=C['border'], padx=1, pady=1)
        fr.pack(fill='x', pady=(4, 0))
        t = _st.ScrolledText(fr, height=height, font=('Consolas', 9), bg=C['surface2'], fg=C['text'],
                             insertbackground=C['accent'], relief='flat', bd=4, wrap='none')
        t.pack(fill='x')
        return t

    def sep(self, parent):
        import tkinter as _tk
        _tk.Frame(parent, bg=C['border2'], height=1).pack(fill='x', pady=(10, 4))

    def pair(self, parent, text, widget_fn, pad=(0, 10)):
        """'Label: [widget]' inline, packed left."""
        self.lbl(parent, text).pack(side='left')
        w = widget_fn(parent)
        w.pack(side='left', padx=(5, pad[1]))
        return w


# --------------------------------------------------- file lists (+ DnD)
def _sv_lines(t):
    try:
        raw = t.get('1.0', 'end')
    except Exception:
        return []
    return [l.strip().strip('"') for l in raw.splitlines() if l.strip()]


def _sv_add_paths(app, attr, paths, kinds):
    t = getattr(app, attr, None)
    if t is None:
        return 0
    cur = _sv_lines(t)
    seen = set(os.path.normcase(p) for p in cur)
    new = []

    def take(p):
        if os.path.isfile(p) and _sv_kind(p) in kinds and os.path.normcase(p) not in seen:
            seen.add(os.path.normcase(p))
            new.append(p)
    for p in paths:
        p = (p or '').strip().strip('{}').strip('"')
        if os.path.isdir(p):
            for n in sorted(os.listdir(p), key=_sv_natkey):
                take(os.path.join(p, n))
        elif p:
            take(p)
    if new:
        t.delete('1.0', 'end')
        t.insert('1.0', '\n'.join(cur + new))
    _sv_counts(app)
    return len(new)


def _sv_types(kinds):
    out = []
    if 'video' in kinds:
        out.append((_TR('Vid\u00e9os'), ' '.join('*' + e for e in _SV_VIDEO_EXTS)))
    if 'image' in kinds:
        out.append((_TR('Images'), ' '.join('*' + e for e in _SV_IMAGE_EXTS)))
    if 'audio' in kinds:
        out.append((_TR('Audio'), ' '.join('*' + e for e in _SV_AUDIO_EXTS)))
    return out + [('*', '*.*')]


def _sv_pick_files(app, attr, kinds):
    try:
        ps = filedialog.askopenfilenames(filetypes=_sv_types(kinds))
    except Exception:
        ps = ()
    if ps:
        _sv_add_paths(app, attr, list(ps), kinds)


def _sv_pick_folder(app, attr, kinds):
    try:
        d = filedialog.askdirectory()
    except Exception:
        d = ''
    if d:
        _sv_add_paths(app, attr, [d], kinds)


def _sv_clear(app, attr):
    t = getattr(app, attr, None)
    if t is not None:
        t.delete('1.0', 'end')
    _sv_counts(app)


def _sv_dnd(app, widget, attr, kinds):
    try:
        widget.drop_target_register(DND_FILES)

        def on_drop(ev):
            _sv_add_paths(app, attr, list(app.root.tk.splitlist(ev.data)), kinds)
        widget.dnd_bind('<<Drop>>', on_drop)
        return True
    except Exception:
        return False


def _sv_filelist(b, parent, attr, title, kinds, height=3, hint=False):
    app = b.app
    b.lbl(parent, title, bold=True).pack(fill='x', pady=(6, 0))
    r = b.row(parent, (4, 0))
    b.btn(r, '+ Fichiers', lambda: _sv_pick_files(app, attr, kinds)).pack(side='left')
    b.btn(r, '+ Dossier', lambda: _sv_pick_folder(app, attr, kinds)).pack(side='left', padx=(5, 0))
    b.btn(r, 'Vider', lambda: _sv_clear(app, attr)).pack(side='left', padx=(5, 0))
    t = b.text(parent, height)
    setattr(app, attr, t)
    t.bind('<KeyRelease>', lambda e: _sv_counts(app), add='+')
    _sv_dnd(app, t, attr, kinds)
    if hint:
        import tkinter as _tk
        dz = _tk.Label(parent, text='\U0001f4c2 Glissez-d\u00e9posez vos fichiers ici', font=(_F13, 8),
                       bg=C['g_ind_3'], fg=C['text2'], pady=4)
        dz.pack(fill='x', pady=(4, 0))
        _sv_dnd(app, dz, attr, kinds)
    return t


def _sv_counts(app):
    lbl = getattr(app, '_sv_count_lbl', None)
    if lbl is None:
        return
    fs = _sv_lines(getattr(app, '_sv_files_text', None))
    nv = sum(1 for f in fs if _sv_kind(f) == 'video')
    ni = sum(1 for f in fs if _sv_kind(f) == 'image')
    try:
        _ui_raw_conf(lbl, text=_TR('%d vid\u00e9o(s) \u00b7 %d image(s)') % (nv, ni))
    except Exception:
        pass


def _sv_pick_one(var, kinds):
    try:
        p = filedialog.askopenfilename(filetypes=_sv_types(kinds))
    except Exception:
        p = ''
    if p:
        var.set(p)


def _sv_file_row(b, parent, title, var, kinds):
    b.lbl(parent, title).pack(fill='x', pady=(6, 0))
    r = b.row(parent, (3, 0))
    e = b.entry(r, var, 24)
    e.pack(side='left', fill='x', expand=True)
    b.btn(r, 'Parcourir', lambda: _sv_pick_one(var, kinds)).pack(side='left', padx=(5, 0))
    return e


# ------------------------------------------------------------ the cards
def _sv_section(app, name, title):
    import tkinter as _tk
    S = _tk.Frame(app._body_root, bg=C['surface'])
    tf = _tk.Frame(S, bg=C['surface'])
    tf.pack(fill='x')
    _tk.Label(tf, text=title, font=(_F13, 10, 'bold'), bg=C['surface'], fg=C['text']).pack(side='left')
    body = _tk.Frame(S, bg=C['surface'], padx=12, pady=4)
    body.pack(fill='both', expand=True)
    app._sections[name] = S
    return body


def _sv_vars(app):
    import tkinter as _tk
    D = _SV_DEFAULTS
    V = {}

    def sv(k, v):
        V[k] = _tk.StringVar(value=str(v))

    def bv(k, v):
        V[k] = _tk.BooleanVar(value=bool(v))
    for k in ('mode', 'frame', 'orient', 'zoom', 'pan', 'stroke_col', 'st_col', 'g_pos', 'g_col', 'xf', 'a_mode',
              'kw_scope', 'rating', 'enc', 'preset', 'abr', 'pattern', 'top_video', 'bot_video', 'tl_path', 'bl_path',
              'tl_kc', 'bl_kc', 'out_dir', 'ffmpeg_path'):
        sv(k, D[k])
    for k in ('target', 'img_dur', 'seg_len', 'seg_max', 'jitter', 'each_max', 'fps', 'zmin', 'zmax', 'bg_sigma',
              'bg_dim', 'bg_sat', 'bg_rate', 'stroke_px', 'side_m', 'top_m', 'bot_m', 'gap', 'st_px',
              'tl_w', 'tl_h', 'tl_op', 'tl_fi', 'tl_fo', 'tl_y', 'tl_sim', 'tl_bl',
              'bl_w', 'bl_h', 'bl_op', 'bl_fi', 'bl_fo', 'bl_y', 'bl_sim', 'bl_bl',
              'g_start', 'g_dur', 'g_th', 'g_bleed', 'g_a', 'g_ba', 'g_blur', 'g_jamp', 'g_jfreq', 'g_rb',
              'g_flr', 'g_fld', 'xd', 'h_max', 'm_vol', 'm_fi', 'm_fo', 'o_vol', 'crf'):
        sv(k, D[k])
    for k in ('first_zero', 'bg_zoom', 'stroke', 'tl_key', 'bl_key', 'g_on', 'h_on', 'kw_subs', 'kw_meta',
              'kw_rich', 'open_done'):
        bv(k, D[k])
    V['res'] = _tk.StringVar(value='%dx%d' % (D['w'], D['h']))
    V['out_dir'].set(os.path.join(_sv_dirs()[0] if _sv_dirs() else os.getcwd(), '_shorts_output'))
    for k, v in V.items():
        setattr(app, '_sv_%s_var' % k, v)                 # saved/restored with the app's settings
    app._sv_V = V
    return V


