    b.pair(r, 'Dur\u00e9e (s, 0 = fin) :', lambda p: b.spin(p, V['g_dur'], 0, 900, 0.5, 4))
    ah = b.row(g)
    tog = b.lbl(ah, '\u25b8  R\u00e9glages avanc\u00e9s', fg=C['accent'], cursor='hand2')
