    items = (('\u00c9paisseur ligne (px)', 'g_th', 1, 12, 1), ('\u00c9paisseur halo (px)', 'g_bleed', 0, 12, 1),
             ('Opacit\u00e9 ligne', 'g_a', 0.05, 1, 0.05), ('Opacit\u00e9 halo', 'g_ba', 0, 1, 0.05),
             ('Flou', 'g_blur', 0, 10, 0.1), ('Tremblement (px)', 'g_jamp', 0, 20, 0.1),
             ('Tremblement (Hz)', 'g_jfreq', 0, 30, 0.1), ('Arc-en-ciel (tours/s)', 'g_rb', 0, 5, 0.05),
             ('Scintillement (Hz)', 'g_flr', 0.1, 60, 0.5), ('Cycle scintillement', 'g_fld', 0.05, 1, 0.05))
    for i, (t, k, lo, hi, inc) in enumerate(items):
        b.lbl(adv, t, size=8).grid(row=i // 2, column=(i % 2) * 2, sticky='w', pady=2, padx=(0, 4))
        b.spin(adv, V[k], lo, hi, inc, 5).grid(row=i // 2, column=(i % 2) * 2 + 1, sticky='w', pady=2, padx=(0, 10))

    def toggle(e=None):
        open_ = not adv.winfo_manager()
        if open_:
            adv.pack(fill='x', pady=(4, 0))
        else:
            adv.pack_forget()
        _ui_raw_conf(tog, text=('\u25be  ' if open_ else '\u25b8  ') + _TR('R\u00e9glages avanc\u00e9s'))
        try:
            app._ui_request_relayout(force=True)
        except Exception:
            pass
    tog._i18n_src = None
    _ui_raw_conf(tog, text='\u25b8  ' + _TR('R\u00e9glages avanc\u00e9s'))
    tog.bind('<Button-1>', toggle)
    app._sv_adv_toggle = toggle
    app._sv_adv_lbl = tog
    app._sv_glitch_frame = g
    b.sep(body)
    b.switch(b.row(body, (0, 0)), "Vid\u00e9o d'accroche au d\u00e9but", V['h_on']).pack(side='left')
    h2 = b.holder(body)
    hk = _tk.Frame(h2, bg=C['surface'])
    _sv_filelist(b, hk, '_sv_hooks_text', 'Accroches (une au hasard par Short) :', ('video',), height=2)
    r = b.row(hk)
