    b.pair(r, 'Dur\u00e9e fondu (s) :', lambda p: b.spin(p, V['xd'], 0.1, 5, 0.1, 4))
    b.pair(b.row(hk, (4, 0)), 'Accroche max (s, 0 = enti\u00e8re) :', lambda p: b.spin(p, V['h_max'], 0, 120, 0.5, 4))
    app._sv_hook_frame = hk


