def _sv_pstyle():
    from tkinter import ttk as _ttk
    try:
        _ttk.Style().configure('SV.Horizontal.TProgressbar', troughcolor=C['surface3'], background=C['accent'],
                               bordercolor=C['surface3'], lightcolor=C['accent'], darkcolor=C['accent'], thickness=8)
    except Exception:
        pass



# ------------------------------------------------------------ handlers
_SV_HINTS = {
    'montage': "Clips al\u00e9atoires de toutes les vid\u00e9os selon le motif, jusqu'\u00e0 la dur\u00e9e totale.",
    'slideshow': "Chaque image avec un zoom rapide, dans l'ordre de la liste.",
    'split': 'Chaque longue vid\u00e9o est d\u00e9coup\u00e9e en plusieurs Shorts.',
    'each': 'Chaque vid\u00e9o devient un Short avec les effets choisis.',
}
_SV_ICONS = {'running': '\u23f3', 'done': '\u2713', 'stopped': '\u25a0', 'failed': '\u2715', 'cancelled': '\u26a1',
             'skipped': '\u2013'}


def _sv_pick_dir(var):
    try:
        d = filedialog.askdirectory()
    except Exception:
        d = ''
    if d:
        var.set(d)


def _sv_open_path(path, folder=False):
    try:
        if folder:
            os.makedirs(path, exist_ok=True)
        if os.name == 'nt':
            os.startfile(path)
        elif sys.platform == 'darwin':
            _sv_sp.Popen(['open', path])
        else:
            _sv_sp.Popen(['xdg-open', path], stdout=_sv_sp.DEVNULL, stderr=_sv_sp.DEVNULL)
    except Exception:
        pass


def _sv_play(app, path, env):
    fp = (env or {}).get('ffplay')
    try:
        if fp:
            _sv_sp.Popen([fp, '-autoexit', '-loglevel', 'error', '-window_title', 'AutoPoster Pro \u2014 Preview', path],
                         stdout=_sv_sp.DEVNULL, stderr=_sv_sp.DEVNULL, **_sv_popen_kw())
            return
    except Exception:
        pass
    _sv_open_path(path)


def _sv_pick_ffmpeg(app):
    try:
        p = filedialog.askopenfilename(filetypes=[('ffmpeg', 'ffmpeg*'), ('*', '*.*')])
    except Exception:
        p = ''
    if p:
        app._sv_ffmpeg_path_var.set(p)
        _sv_ff_status(app)


def _sv_ff_status(app):
    lbl = getattr(app, '_sv_ff_lbl', None)
    if lbl is None:
        return
    ff = _sv_find('ffmpeg', app._sv_ffmpeg_path_var.get())
    if ff:
        d = os.path.dirname(ff)
        short = d if len(d) <= 34 else '\u2026' + d[-33:]
        _ui_raw_conf(lbl, text='\u2713 ' + short, fg=C['success'])
    else:
        _ui_raw_conf(lbl, text=_TR('FFmpeg introuvable \u2014 choisissez ffmpeg.exe'), fg=C['danger'])


def _sv_genre_soon(app):
    job = getattr(app, '_sv_genre_job', None)
    if job:
        try:
            app.root.after_cancel(job)
        except Exception:
            pass
    app._sv_genre_job = app.root.after(700, lambda: _sv_genre_update(app))


def _sv_genre_update(app):
    app._sv_genre_job = None
    try:
        kws = _sv_keywords(app._sv_kw_text.get('1.0', 'end'))
        if kws:
            g, r = _sv_genre(kws)
            _ui_raw_conf(app._sv_genre_lbl, text=_TR('Genre : %s \u00b7 %s (auto)') % (g, r))
        else:
            _ui_raw_conf(app._sv_genre_lbl, text='')
    except Exception:
        pass


def _sv_show(frame, on):
    try:
        if on and not frame.winfo_manager():
            frame.pack(fill='x')
        elif not on and frame.winfo_manager():
            frame.pack_forget()
    except Exception:
        pass


def _sv_refresh_ui(app, relayout=True):
    V = getattr(app, '_sv_V', None)
    if V is None:
        return
    mode = V['mode'].get()
    for k, f in app._sv_mode_frames.items():
        _sv_show(f, k == mode)
    _ui_raw_conf(app._sv_hint_lbl, text=_TR(_SV_HINTS.get(mode, '')))
    _sv_show(app._sv_blur_frame, V['frame'].get() == 'blur')
    _sv_show(app._sv_glitch_frame, bool(V['g_on'].get()))
    _sv_show(app._sv_hook_frame, bool(V['h_on'].get()))
    am = V['a_mode'].get()
    _sv_show(app._sv_music_frame, am in ('music', 'mix'))
    _sv_show(app._sv_orig_frame, am in ('original', 'mix'))
    _sv_counts(app)
    _sv_genre_update(app)
    _sv_ff_status(app)
    if relayout and getattr(app, '_current_tab', '') == 'shorts':
        try:
            app._ui_layout_sig = None
            app._ui_request_relayout(force=True)
        except Exception:
            pass


def _sv_cfg(app):
    V = app._sv_V
    c = dict(_SV_DEFAULTS)
    for k in ('mode', 'frame', 'zoom', 'pan', 'stroke_col', 'st_col', 'g_pos', 'g_col', 'xf', 'a_mode', 'kw_scope',
              'rating', 'enc', 'preset', 'abr', 'pattern', 'top_video', 'bot_video', 'tl_path', 'bl_path', 'tl_kc',
              'bl_kc', 'out_dir', 'ffmpeg_path'):
        c[k] = str(V[k].get() or '').strip().strip('"')
    fl = {'target': (1, 3600), 'img_dur': (0.2, 60), 'seg_len': (1, 3600), 'jitter': (0, 600), 'each_max': (0, 36000),
          'zmin': (1.0, 4.0), 'zmax': (1.0, 4.0), 'bg_sigma': (0, 400), 'bg_dim': (0, 0.9), 'bg_sat': (0, 4),
          'bg_rate': (0, 1), 'tl_fi': (0, 600), 'tl_fo': (0, 600), 'bl_fi': (0, 600), 'bl_fo': (0, 600),
          'tl_sim': (0, 1), 'tl_bl': (0, 1), 'bl_sim': (0, 1), 'bl_bl': (0, 1), 'g_start': (0, 36000),
          'g_dur': (0, 36000), 'g_a': (0.05, 1), 'g_ba': (0, 1), 'g_blur': (0, 20), 'g_jamp': (0, 50),
          'g_jfreq': (0, 60), 'g_rb': (0, 10), 'g_flr': (0.1, 120), 'g_fld': (0.05, 1), 'xd': (0.1, 10),
          'h_max': (0, 3600), 'm_vol': (0, 5), 'm_fi': (0, 600), 'm_fo': (0, 600), 'o_vol': (0, 5)}
    for k, (lo, hi) in fl.items():
        c[k] = _sv_num(V[k].get(), _SV_DEFAULTS[k], lo, hi)
    it = {'seg_max': (1, 500), 'fps': (10, 60), 'stroke_px': (0, 200), 'side_m': (0, 800), 'top_m': (0, 800),
          'bot_m': (0, 800), 'gap': (0, 800), 'st_px': (0, 100), 'tl_w': (1, 100), 'tl_h': (1, 100),
          'tl_op': (0, 100), 'tl_y': (-2000, 2000), 'bl_w': (1, 100), 'bl_h': (1, 100), 'bl_op': (0, 100),
          'bl_y': (-2000, 2000), 'g_th': (1, 50), 'g_bleed': (0, 50), 'crf': (0, 51)}
    for k, (lo, hi) in it.items():
        c[k] = _sv_num(V[k].get(), _SV_DEFAULTS[k], lo, hi, cast=lambda x: int(float(x)))
    for k in ('first_zero', 'bg_zoom', 'stroke', 'tl_key', 'bl_key', 'g_on', 'h_on', 'kw_subs', 'kw_meta', 'kw_rich',
              'open_done'):
        c[k] = bool(V[k].get())
    m = re.match(r'^\s*(\d+)\s*[x\u00d7]\s*(\d+)\s*$', str(V['res'].get()))
    if m:
        c['w'], c['h'] = _sv_even(int(m.group(1))), _sv_even(int(m.group(2)))
    c['files'] = _sv_lines(getattr(app, '_sv_files_text', None))
    c['hooks'] = _sv_lines(getattr(app, '_sv_hooks_text', None))
    c['songs'] = _sv_lines(getattr(app, '_sv_songs_text', None))
    try:
        c['kw_text'] = app._sv_kw_text.get('1.0', 'end')
    except Exception:
        c['kw_text'] = ''
    if not c['out_dir']:
        c['out_dir'] = os.path.join(_sv_dirs()[0] if _sv_dirs() else os.getcwd(), '_shorts_output')
    return c


def _sv_start(app, preview=False):
    r = app._sv_runner
    if r.busy():
        return
    c = _sv_cfg(app)
    if not c['files']:
        messagebox.showwarning('AutoPoster Pro', _TR("Ajoutez d'abord des vid\u00e9os ou des images."))
        return
    env = _sv_env(c['ffmpeg_path'], caps=False)
    if not env['ffmpeg'] or (c['mode'] != 'slideshow' and not env['ffprobe']):
        _sv_ff_status(app)
        messagebox.showerror('AutoPoster Pro', _TR('FFmpeg introuvable \u2014 choisissez ffmpeg.exe'))
        return
    if preview:
        c['out_dir'] = os.path.join(_sv_tempfile.gettempdir(), 'autoposter_shorts_preview')
        c['open_done'] = False
    try:
        os.makedirs(c['out_dir'], exist_ok=True)
    except Exception as e:
        messagebox.showerror('AutoPoster Pro', str(e))
        return
    app._sv_last = {'cfg': c, 'env': env, 'preview': preview, 'done': False}
    app._sv_jobs_sig = None
    r.start(c, env, None, preview)
    _sv_set_buttons(app)
    _sv_poll(app)


def _sv_pause(app):
    r = app._sv_runner
    if r.state == 'paused':
        r.resume()
    elif r.busy():
        r.pause()
    _sv_set_buttons(app)


def _sv_stop(app):
    app._sv_runner.stop()
    _sv_set_buttons(app)


def _sv_force(app):
    app._sv_runner.force()
    _sv_set_buttons(app)


def _sv_set_buttons(app):
    r = getattr(app, '_sv_runner', None)
    if r is None:
        return
    busy = r.busy()
    for w, on in ((app._sv_btn_go, not busy), (app._sv_btn_prev, not busy), (app._sv_btn_pause, busy),
                  (app._sv_btn_stop, busy), (app._sv_btn_force, busy)):
        try:
            _ui_raw_conf(w, state=('normal' if on else 'disabled'))
        except Exception:
            pass
    try:
        _ui_raw_conf(app._sv_btn_pause, text=_TR('\u25b6 Reprendre') if r.state == 'paused'
                     else _TR('\u275a\u275a Pause'))
    except Exception:
        pass


def _sv_fmt_t(s):
    s = max(0, int(s))
    return '%d:%02d' % (s // 60, s % 60)


def _sv_jobs_refresh(app):
    r = app._sv_runner
    lines = []
    for j in (r.jobs or []):
        st = j.get('status')
        extra = ''
        if st == 'running':
            extra = ' \u2014 %d%%' % int(r.pct * 100)
        elif st in ('done', 'stopped'):
            extra = ' \u2014 %.1f MB' % (j.get('size', 0) / 1048576.0)
        elif st == 'failed':
            extra = ' \u2014 FFmpeg error (see Log)'
        lines.append('%s %s  \u2192  %s%s' % (_SV_ICONS.get(st, '\u2022'), j['label'], os.path.basename(j['out']), extra))
    txt = '\n'.join(lines)
    if txt == getattr(app, '_sv_jobs_sig', None):
        return
    app._sv_jobs_sig = txt
    t = app._sv_jobs_txt
    try:
        t.configure(state='normal')
        t.delete('1.0', 'end')
        t.insert('1.0', txt)
        if 0 <= r.cur < len(r.jobs or []):
            t.see('%d.0' % (r.cur + 1))
        t.configure(state='disabled')
    except Exception:
        pass


def _sv_poll(app):
    job = getattr(app, '_sv_poll_job', None)
    if job:
        try:
            app.root.after_cancel(job)
        except Exception:
            pass
    app._sv_poll_job = None
    r = app._sv_runner
    busy = r.busy()
    jobs = r.jobs or []
    n = len(jobs)
    overall = 0.0
    if busy:
        if r.jobs is None:
            txt = _TR('Pr\u00e9paration\u2026')
        else:
            i = max(0, r.cur)
            overall = ((i + r.pct) / float(n) * 100.0) if n else 0.0
            txt = _TR('T\u00e2che %d/%d \u00b7 %d%%') % (min(n, i + 1), n, int(r.pct * 100))
            if r.state == 'paused':
                txt = _TR('En pause') + ' \u00b7 ' + txt
            elif r.pct > 0.03 and r.t0:
                el = time.time() - r.t0
                txt += ' \u00b7 ~%s' % _sv_fmt_t(el * (1.0 - r.pct) / r.pct)
    else:
        last = getattr(app, '_sv_last', None) or {}
        if r.error:
            txt = ''
        elif n:
            overall = 100.0 if not r.stop_req else overall
            txt = (_TR('Arr\u00eat\u00e9 : %d/%d vid\u00e9o(s) cr\u00e9\u00e9e(s).') if r.stop_req
                   else _TR('Termin\u00e9 : %d/%d vid\u00e9o(s) cr\u00e9\u00e9e(s).')) % (r.done_ok, n)
        else:
            txt = _TR('Pr\u00eat.')
    try:
        app._sv_pbar.configure(value=overall)
        _ui_raw_conf(app._sv_status, text=txt, fg=(C['success'] if (not busy and r.done_ok) else C['text2']))
    except Exception:
        pass
    _sv_jobs_refresh(app)
    _sv_set_buttons(app)
    if busy:
        app._sv_poll_job = app.root.after(400, lambda: _sv_poll(app))
        return
    last = getattr(app, '_sv_last', None)
    if last and not last.get('done'):
        last['done'] = True
        if r.error:
            msg = {'videos': 'Ce mode a besoin de vid\u00e9os.', 'images': "Ce mode a besoin d'images."}.get(
                r.error, 'Aucune vid\u00e9o \u00e0 cr\u00e9er.')
            messagebox.showwarning('AutoPoster Pro', _TR(msg))
        elif last.get('preview') and r.last_out:
            _sv_play(app, r.last_out, last.get('env'))
        elif last['cfg'].get('open_done') and r.done_ok:
            _sv_open_path(last['cfg']['out_dir'], True)


# -------------------------------------------------------------- layout
def _ui15_layout_shorts(self, spec, body_w, body_h):
    secs = dict(_ui_sections_of(self, 'shorts'))
    m, g = _UI13_M, _UI13_G
    stack_on = (self._sv_V['frame'].get() == 'stack')
    # "Triple stack & logos" is now its OWN separate panel/column, shown only
    # when the "Triple stack" framing is selected (see tripe_stack.png). It is
    # no longer stacked underneath the "Frame & rapid zoom" card.
    if stack_on:
        cols = [['sv_src', 'sv_run'], ['sv_look'], ['sv_stack'], ['sv_fx', 'sv_audio']]
    else:
        cols = [['sv_src', 'sv_run'], ['sv_look'], ['sv_fx', 'sv_audio']]
    cols = [[n for n in c if n in secs] for c in cols]
    cols = [c for c in cols if c]
    if not stack_on and 'sv_stack' in secs:
        secs['sv_stack'].place_forget()
    for fr in secs.values():
        _ui13_stretch(fr)
    if body_w >= _UI13_TWO:
        ncol = max(1, len(cols))
        avail = body_w - 2 * m - (ncol - 1) * g
        base = avail // ncol
        ws = [base] * (ncol - 1) + [avail - base * (ncol - 1)]
        xs = [m + sum(ws[:i]) + i * g for i in range(ncol)]
        placed = []
        for ci, names in enumerate(cols):
            for n in names:
                secs[n].place(x=xs[ci], y=m, width=ws[ci], height='')
                placed.append(secs[n])
        _ui_fit_boxes(self, placed)
        need = [sum(secs[n].winfo_reqheight() for n in names) + g * (len(names) - 1) for names in cols if names]
        full = max(need + [body_h - 2 * m])
        for ci, names in enumerate(cols):
            y = m
            for k, n in enumerate(names):
                h = secs[n].winfo_reqheight()
                if k == len(names) - 1:
                    h = max(h, full - (y - m))            # last card of a column reaches the bottom
                secs[n].place(x=xs[ci], y=y, width=ws[ci], height=h)
                y += h + g
        self._ui_two_cols = True
        return full + 2 * m
    order = [n for n in ('sv_src', 'sv_look', 'sv_stack', 'sv_fx', 'sv_audio', 'sv_run')
             if n in secs and (n != 'sv_stack' or stack_on)]
    w = body_w - 2 * m
    for n in order:
        secs[n].place(x=m, y=0, width=w, height='')
    _ui_fit_boxes(self, [secs[n] for n in order])
    y = m
    for n in order:
        secs[n].place(x=m, y=y, width=w, height='')
        y += secs[n].winfo_reqheight() + g
    self._ui_two_cols = False
    return y


# ------------------------------------------------------------- building
def _sv_build_tab(app):
    if 'sv_src' in (app._sections or {}):
        return
    V = _sv_vars(app)
    b = _SVB(app)
    app._svb = b
    _sv_card_source(app, b, V)
    _sv_card_run(app, b, V)
    _sv_card_look(app, b, V)
    _sv_card_stack(app, b, V)
    _sv_card_fx(app, b, V)
    _sv_card_audio(app, b, V)
    app._sv_entries = b.entries
    app._sv_runner = _SVRunner(app.log)
    _TAB_SECTIONS['shorts'] = list(_SV_SECS)
    for n in _SV_SECS:
        _SECTION_TAB[n] = 'shorts'
    _TAB_LAYOUT['shorts'] = {'kind': 'shorts15', 'sections': list(_SV_SECS)}
    for n in _SV_SECS:
        _ui13_section_card(app, n)
        for w in _ui_walk(app._sections[n]):
            try:
                if w.winfo_class() == 'Button' and getattr(w, '_ui13_fix', None) is None:
                    _ui13_guard(w, _ui13_theme_fix)
            except Exception:
                pass
    try:
        _ui13_theme_misc(app)
    except Exception:
        pass
    for k in ('mode', 'frame', 'g_on', 'h_on', 'a_mode'):
        V[k].trace_add('write', lambda *a: _sv_refresh_ui(app))
    V['orient'].trace_add('write', lambda *a: _sv_on_orient(app))
    V['ffmpeg_path'].trace_add('write', lambda *a: _sv_ff_status(app))
    _sv_refresh_ui(app, relayout=False)
    _sv_set_buttons(app)
    _ui_raw_conf(app._sv_status, text=_TR('Pr\u00eat.'))


_ui15_prev_finish = _ui13_finish


