def _sv_shutdown(self):
    r = getattr(self, '_sv_runner', None)
    if r is not None and r.busy():
        try:
            r.force()                                   # never leave FFmpeg running
        except Exception:
            pass


for _nm15 in ('teardown', '_close_app'):
    _fn15 = getattr(FacebookMultiPosterApp, _nm15, None)
    if callable(_fn15):
        def _mk15(prev):
            def wrapper(self, *a, **kw):
                _sv_shutdown(self)
                return prev(self, *a, **kw)
            return wrapper
        setattr(FacebookMultiPosterApp, _nm15, _mk15(_fn15))



class SplashScreen:
    def __init__(self, root, callback):
        self.root = root
        self.callback = callback
        self._step = 0
        sw = root.winfo_screenwidth()
        sh = root.winfo_screenheight()
        W, H = (480, 280)
        x = (sw - W) // 2
        y = (sh - H) // 2
        self.top = tk.Toplevel(root)
        self.top.overrideredirect(True)
        self.top.geometry(f'{W}x{H}+{x}+{y}')
        self.top.configure(bg=C['bg'])
        self.top.lift()
        F = 'Segoe UI'
        tk.Frame(self.top, bg=C['accent'], height=2).pack(fill=tk.X)
        body = tk.Frame(self.top, bg=C['bg'])
        body.pack(fill=tk.BOTH, expand=True, padx=2, pady=2)
        tk.Frame(body, bg=C['bg'], height=20).pack()
        try:
            _logo_sp = PILImage.open(LOGO_PATH).convert('RGBA').resize((120, 120), PILImage.LANCZOS)
            self._logo_sp_photo = _ITk2.PhotoImage(_logo_sp)
            tk.Label(body, image=self._logo_sp_photo, bg=C['bg']).pack()
        except Exception:
            pass
        tk.Frame(body, bg=C['bg'], height=10).pack()
        tk.Label(body, text='AutoPoster Pro', font=(F, 16, 'bold'), bg=C['bg'], fg=C['text']).pack()
        tk.Label(body, text='Initialisation…', font=(F, 9), bg=C['bg'], fg=C['text2']).pack(pady=(4, 0))
        tk.Frame(body, bg=C['bg'], height=22).pack()
        bar_outer = tk.Frame(body, bg=C['surface2'], height=4)
        bar_outer.pack(fill=tk.X, padx=50)
        bar_outer.pack_propagate(False)
        self._bar = tk.Frame(bar_outer, bg=C['accent'], height=4, width=0)
        self._bar.place(x=0, y=0, height=4, width=0)
        self._bar_total = 380
        tk.Frame(body, bg=C['bg'], height=6).pack()
        self._status_lbl = tk.Label(body, text='Chargement des modules…', font=(F, 9), bg=C['bg'], fg=C['text3'])
        self._status_lbl.pack()
        tk.Frame(self.top, bg=C['accent'], height=2).pack(side=tk.BOTTOM, fill=tk.X)
        self._animate()
    def _animate(self):
        steps = [(20, 'Chargement des modules…'), (45, 'Initialisation…'), (70, 'Préparation de l\'interface…'), (100, 'Prêt !')]
        if self._step < len(steps):
            pct, msg = steps[self._step]
            w = int(self._bar_total * pct / 100)
            self._bar.place(x=0, y=0, height=4, width=w)
            self._status_lbl.config(text=msg)
            self._step += 1
            delay = 320 if self._step < len(steps) else 500
            self.top.after(delay, self._animate)
        else:
            self.top.after(200, self._finish)
    def _finish(self):
        self.top.destroy()
        self.callback()


# ======================================================================
# Host TAB module API  (build / on_show / on_hide / teardown)
# ======================================================================
# The host application embeds this module by calling build(parent, ctx).
# build() MUST NOT create a second Tk root, call mainloop(), or sys.exit().

class _HostMessagebox(object):
    """Drop-in stand-in for tkinter.messagebox used across this module.

    In host TAB mode, routine info/warning/error dialogs are sent to the
    host log panel and a non-modal toast instead of a focus-stealing popup
    (spec §5).  In standalone mode the real dialogs are used.  Genuine
    confirmations (askyesno / askokcancel) stay modal in both modes -- they
    need a yes/no answer and are short-lived, user-initiated gates.
    """

    def _emit(self, kind, title, message):
        app = _CURRENT_APP
        if app is not None and not getattr(app, '_standalone', True):
            try:
                app._notify(title, message, kind)
                return
            except Exception:
                pass
        fn = {'info': _real_messagebox.showinfo,
              'warn': _real_messagebox.showwarning,
              'error': _real_messagebox.showerror}.get(kind, _real_messagebox.showinfo)
        try:
            fn(title, message)
        except Exception:
            pass

    def showinfo(self, title='', message='', **kw):
        self._emit('info', title, message)

    def showwarning(self, title='', message='', **kw):
        self._emit('warn', title, message)

    def showerror(self, title='', message='', **kw):
        self._emit('error', title, message)

    def askyesno(self, title='', message='', **kw):
        try:
            return bool(_real_messagebox.askyesno(title, message, **kw))
        except Exception:
            return False

    def askokcancel(self, title='', message='', **kw):
        try:
            return bool(_real_messagebox.askokcancel(title, message, **kw))
        except Exception:
            return False

    def askquestion(self, title='', message='', **kw):
        try:
            return _real_messagebox.askquestion(title, message, **kw)
        except Exception:
            return 'no'


messagebox = _HostMessagebox()   # every messagebox.* call below is routed


_APP = None            # the live FacebookMultiPosterApp instance (TAB mode)
_TAB_FRAME = None      # the container frame returned by build()


def _apply_ctx_paths(ctx):
    """Confine every disk write to the per-tab work folder the host provides
    (ctx['paths']['work']) — the only location this module may write to
    (spec §5/§6).  Older key names are accepted as fallbacks.  All of the
    app's data (Chrome profiles, histories, scraped media, temp files) then
    lives under that folder because they are all derived from SESSION_BASE."""
    try:
        paths = (ctx or {}).get('paths') or {}
        base = (paths.get('work') or paths.get('session_base')
                or paths.get('data_root') or (ctx or {}).get('session_base'))
        if base:
            _set_session_base(base)
            try:
                os.makedirs(SESSION_BASE, exist_ok=True)
            except Exception:
                pass
    except Exception:
        pass


def _luma(hexcol):
    """Rough perceived brightness (0..1) of a #rrggbb colour."""
    try:
        h = str(hexcol).lstrip('#')
        r, g, b = (int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16))
        return (0.299 * r + 0.587 * g + 0.114 * b) / 255.0
    except Exception:
        return 0.0


def _apply_ctx_style(ctx):
    """Seed the app palette from the host theme tokens (ctx['style']) so the
    tab follows the tool's light/dark switch and accent colour (spec §4).

    The host defines only a handful of base tokens; the app's own derived and
    gradient tokens are kept from the matching built-in theme, so the tab still
    looks like itself while its background / text / accent match the host.
    """
    global C, _CURRENT_THEME
    try:
        st = (ctx or {}).get('style') or {}
        if not st:
            return
        base_bg = st.get('BG', '') or st.get('bg', '')
        dark = _luma(base_bg) < 0.5 if base_bg else True
        pal = dict(C_DARK if dark else C_LIGHT)
        _CURRENT_THEME[0] = 'dark' if dark else 'light'

        def put(key, *tokens):
            for tok in tokens:
                v = st.get(tok)
                if v:
                    pal[key] = v
                    return
        put('bg', 'BG', 'bg')
        put('surface', 'BG_CARD', 'surface')
        put('surface2', 'BG_CARD_2', 'surface2')
        put('surface3', 'BG_CARD_2', 'surface3')
        put('border', 'BORDER', 'border')
        put('border2', 'BORDER', 'border2')
        put('text', 'FG', 'text')
        put('text2', 'FG_MUTED', 'text2')
        put('text3', 'FG_MUTED', 'text3')
        put('accent', 'ACCENT', 'accent')
        put('accent2', 'ACCENT', 'accent2')
        put('accent_lt', 'ACCENT', 'accent_lt')
        put('purple', 'ACCENT')
        put('success', 'GREEN', 'success')
        put('success2', 'GREEN', 'success2')
        put('danger', 'DANGER', 'danger')
        put('danger2', 'DANGER', 'danger2')
        put('info', 'ACCENT')
        # keep the same dict object so every widget/method sees the update
        C.clear()
        C.update(pal)
    except Exception:
        pass


def build(parent, ctx=None):
    """Host entry point (spec §2).

    Wrapped per spec §7: if construction fails, the error is logged to the
    host and re-raised so the host can show an inline error inside the tab
    without taking down the rest of the tool.  Returns quickly and never
    blocks; all slow work happens on worker threads.
    """
    try:
        return _build_impl(parent, ctx)
    except Exception as exc:
        try:
            log = ctx.get('log') if isinstance(ctx, dict) else None
            if callable(log):
                log('[autoposter] build failed: %r' % (exc,))
            else:
                traceback.print_exc()
        except Exception:
            traceback.print_exc()
        raise


def _build_impl(parent, ctx):
    """Actual construction, guarded by build()."""
    global _APP, _TAB_FRAME
    ctx = ctx if isinstance(ctx, dict) else {}

    # Writes -> host work folder; palette -> host theme tokens (§4/§6).
    _apply_ctx_paths(ctx)
    _apply_ctx_style(ctx)

    # Optional DPI scaling hint from the host (§3: sizes are logical px).
    try:
        scale = ctx.get('scale')
        top = parent.winfo_toplevel()
        if scale:
            top.tk.call('tk', 'scaling', float(scale))
    except Exception:
        pass

    # Container frame; everything is built inside it (§3: never our own window).
    frame = _AppFrame(parent)
    _TAB_FRAME = frame           # set early so teardown() can clean a partial build
    try:
        frame.pack(fill=tk.BOTH, expand=True)
    except Exception:
        pass

    app = FacebookMultiPosterApp(frame, ctx=ctx, standalone=False)
    frame._autoposter_app = app
    _APP = app

    # Tee the app's own log into the host log panel (§6) without breaking the
    # in-tab log area.
    host_log = ctx.get('log')
    if callable(host_log):
        _orig_log = app.log

        def _tee_log(message, _orig=_orig_log, _host=host_log):
            try:
                _orig(message)
            finally:
                try:
                    _host(str(message))
                except Exception:
                    pass
        app.log = _tee_log

    return frame

def on_show(*args, **kwargs):
    """Called by the host when the tab becomes visible."""
    app = _APP
    if app is None:
        return
    try:
        app._bind_wheel()
    except Exception:
        pass
    try:
        app._draw_accounts_header()
    except Exception:
        pass


def on_hide(*args, **kwargs):
    """Called by the host when the tab is hidden (work continues in the
    background; we only detach the mouse-wheel binding from the host)."""
    app = _APP
    if app is None:
        return
    try:
        app._unbind_wheel()
    except Exception:
        pass


def teardown(*args, **kwargs):
    """Called by the host when the tab is closed. Stops worker threads,
    cancels Tk jobs and kills any browser we launched."""
    global _APP, _TAB_FRAME
    app = _APP
    if app is not None:
        try:
            app.teardown()
        except Exception:
            traceback.print_exc()
    frame = _TAB_FRAME
    if frame is not None:
        try:
            frame.destroy()
        except Exception:
            pass
    _APP = None
    _TAB_FRAME = None


# ======================================================================
# Diagnostics  (python autoV2_FIXED.py --diagnose)
# ======================================================================

def _diagnose():
    """Print an environment / capability report. Needs no Facebook creds."""
    line = '=' * 62
    print(line)
    print(' AutoPoster Pro - diagnostic')
    print(line)
    print(' Python      :', sys.version.replace('\n', ' '))
    print(' Platform    :', platform.platform())
    print(' Executable  :', sys.executable)
    print(' Session base:', SESSION_BASE)
    print(' Media dir   :', SC_MEDIA_DIR)
    print(line)

    # tkinter
    try:
        import tkinter as _tk
        print(' tkinter     : OK (Tcl/Tk %s)' % _tk.TkVersion)
    except Exception as e:
        print(' tkinter     : MISSING (%s)' % e)

    # Playwright
    if sync_playwright is None:
        print(' Playwright  : NOT INSTALLED - run: pip install playwright==1.35.0'
              ' then: %s' % PLAYWRIGHT_INSTALL_CMD)
    else:
        ver = '?'
        try:
            from playwright._repo_version import version as ver
        except Exception:
            try:
                import pkg_resources
                ver = pkg_resources.get_distribution('playwright').version
            except Exception:
                pass
        print(' Playwright  : installed (v%s)' % ver)
        try:
            installed, detail = _chromium_status()
        except Exception as e:
            installed, detail = False, 'status check failed: %s' % e
        if installed:
            print(' Chromium    : OK (%s)' % detail)
        else:
            print(' Chromium    : NOT FOUND - run: %s' % PLAYWRIGHT_INSTALL_CMD)
            if detail:
                print('               (%s)' % detail)

    # openpyxl
    if openpyxl is None:
        print(' openpyxl    : NOT INSTALLED (%s)' % OPENPYXL_PIP_CMD)
    else:
        print(' openpyxl    : OK (v%s)' % getattr(openpyxl, '__version__', '?'))

    # optional libs
    print(' Pillow      :', 'OK' if PILImage is not None else 'missing (images limited)')
    print(' psutil      :', 'OK' if psutil is not None else 'missing (fallback used)')
    print(' tkinterdnd2 :', 'OK' if TkinterDnD is not None else 'missing (drag&drop off)')

    if _IMPORT_ERRORS:
        print(line)
        print(' Import warnings:')
        for name, err in _IMPORT_ERRORS.items():
            print('   - %s: %s' % (name, err))

    # TAB API surface
    print(line)
    print(' TAB_META    :', TAB_META)
    for fn in ('build', 'on_show', 'on_hide', 'teardown'):
        print('   %-9s : %s' % (fn, 'present' if callable(globals().get(fn)) else 'MISSING'))

    # Method count of the main class (sanity check of the reconstruction)
    try:
        methods = [m for m in dir(FacebookMultiPosterApp) if not m.startswith('__')]
        print(' App methods :', len(methods))
    except Exception as e:
        print(' App methods : error (%s)' % e)
    print(line)
    print(' Diagnostic complete.')
    print(line)


# ======================================================================
# Standalone entry point  (python autoV2_FIXED.py)
# ======================================================================

def _standalone_main():
    """Open the real AutoPoster GUI in its own window."""
    _apply_dpi_awareness()

    if TkinterDnD is not None:
        try:
            root = _AppDnDTk()
        except Exception:
            root = _AppTk()
    else:
        root = _AppTk()

    _apply_tk_scaling(root)

    # Offer the Playwright/Chromium installer only if Chromium is missing.
    # _boot is also the installer's on_done(success) callback: the app opens
    # either way (without Chromium, browser actions show a clear error).
    def _boot(*_args):
        try:
            root.deiconify()
        except Exception:
            pass
        try:
            app = FacebookMultiPosterApp(root, ctx=None, standalone=True)
        except Exception:
            traceback.print_exc()
            try:
                messagebox.showerror('AutoPoster Pro',
                                     "Erreur au demarrage :\n\n%s" % traceback.format_exc())
            except Exception:
                pass
            try:
                root.destroy()
            except Exception:
                pass
            return

        # Close handling: the window uses a custom title bar (overrideredirect),
        # so route both the WM protocol and Ctrl-Q to a clean shutdown.
        def _on_close():
            try:
                app.teardown()
            finally:
                try:
                    root.destroy()
                except Exception:
                    pass
        try:
            root.protocol('WM_DELETE_WINDOW', _on_close)
        except Exception:
            pass
        try:
            root.bind_all('<Control-q>', lambda e: _on_close())
        except Exception:
            pass

    if sync_playwright is not None and not _chromium_is_installed():
        # Show the installer window first; boot the app when the user is done.
        # The (still empty) root stays hidden meanwhile; _boot reveals it.
        try:
            root.withdraw()
            install_playwright_with_ui(root, on_done=_boot, modal=False)
        except Exception:
            traceback.print_exc()
            _boot()
    else:
        _boot()

    try:
        root.mainloop()
    except KeyboardInterrupt:
        try:
            if _APP is not None:
                _APP.teardown()
        except Exception:
            pass


def main():
    # Safe no-op when not frozen; prevents a subprocess fork-bomb in a
    # PyInstaller/py2exe build on Windows (the original did this too).
    try:
        multiprocessing.freeze_support()
    except Exception:
        pass
    if '--diagnose' in sys.argv[1:] or '--diagnostic' in sys.argv[1:]:
        _diagnose()
        return
    try:
        _standalone_main()
    except Exception:
        traceback.print_exc()
        # Never exit silently: surface the failure and keep a non-zero code.
        sys.exit(1)




