    card.create_text(190, 120, text=grouped, fill="#ffffff", font=("Courier", 19, "bold"), anchor="center")
    card.create_text(22, 155, text="CARD HOLDER", fill=accent, font=("Helvetica", 7), anchor="w")
    card.create_text(240, 155, text="EXPIRES", fill=accent, font=("Helvetica", 7), anchor="w")
    card.create_text(310, 155, text="CVV", fill=accent, font=("Helvetica", 7), anchor="w")
