# -------------------------------------------------------------------- layout
def _ui15_layout_freeid(self, spec, body_w, body_h):
    secs = dict(_ui_sections_of(self, 'freeid'))
    m, g = _UI13_M, _UI13_G
    cols = [['fid_gen'], ['fid_person'], ['fid_finance']]
    cols = [[n for n in c if n in secs] for c in cols]
    cols = [c for c in cols if c]
    for fr in secs.values():
        _ui13_stretch(fr)
    if body_w >= _UI13_TWO:
        ncol = max(1, len(cols))
        avail = body_w - 2 * m - (ncol - 1) * g
        base = avail // ncol
        ws = [base] * (ncol - 1) + [avail - base * (ncol - 1)]
        xs = [m + sum(ws[:i]) + i * g for i in range(ncol)]
        placed = []
        for ci, names in enumerate(cols):
            for n in names:
                secs[n].place(x=xs[ci], y=m, width=ws[ci], height='')
                placed.append(secs[n])
        _ui_fit_boxes(self, placed)
        need = [sum(secs[n].winfo_reqheight() for n in names) + g * (len(names) - 1)
                for names in cols if names]
        full = max(need + [body_h - 2 * m])
        for ci, names in enumerate(cols):
            y = m
            for k, n in enumerate(names):
                h = secs[n].winfo_reqheight()
                if k == len(names) - 1:
                    h = max(h, full - (y - m))
                secs[n].place(x=xs[ci], y=y, width=ws[ci], height=h)
                y += h + g
        self._ui_two_cols = True
        return full + 2 * m
    order = [n for c in cols for n in c]
    w = body_w - 2 * m
    for n in order:
        secs[n].place(x=m, y=0, width=w, height='')
    _ui_fit_boxes(self, [secs[n] for n in order])
    y = m
    for n in order:
        secs[n].place(x=m, y=y, width=w, height='')
        y += secs[n].winfo_reqheight() + g
    self._ui_two_cols = False
    return y


